y = np.linspace(0, L, N, endpoint=False)
z = np.linspace(0, L, N, endpoint=False)
X, Y, Z = np.meshgrid(x, y, z, indexing='ij')
dx = L / N
dt = 0.008
steps = 150
nu = 5e-4  # Physically valid Reynolds number

# Initial Condition: Strong Vortex Tube with 3D Asymmetric Perturbation
r = np.sqrt((X - L/2)**2 + (Y - L/2)**2)
# Primary Z-axis vortex (Tornado)
omega0_z = 20.0 * np.exp(-10.0 * r**2)
# 3D Perturbation: Sinusoidal Z-dependence breaks symmetry and forces stretching
omega0_x = 3.0 * np.sin(2 * Z) * np.exp(-10.0 * r**2)
omega0_y = 3.0 * np.cos(2 * Z) * np.exp(-10.0 * r**2)

# ------------------------------------------------------------
# 2. Spectral Helpers
# ------------------------------------------------------------
kx = 2 * np.pi * fftfreq(N, d=L/N)
ky = 2 * np.pi * fftfreq(N, d=L/N)
kz = 2 * np.pi * fftfreq(N, d=L/N)
KX, KY, KZ = np.meshgrid(kx, ky, kz, indexing='ij')
K2 = KX**2 + KY**2 + KZ**2
K2[0, 0, 0] = 1.0

def get_velocity(w_hat):
    psi_x = w_hat[0] / K2; psi_y = w_hat[1] / K2; psi_z = w_hat[2] / K2
    u = np.real(ifftn(1j * KY * psi_z - 1j * KZ * psi_y))
    v = np.real(ifftn(1j * KZ * psi_x - 1j * KX * psi_z))
    w = np.real(ifftn(1j * KX * psi_y - 1j * KY * psi_x))
    return u, v, w

# ------------------------------------------------------------
# 3. Run Simulations & Store History
# ------------------------------------------------------------
def run_classical(w0, steps, dt, nu):
    wx, wy, wz = w0[0].copy(), w0[1].copy(), w0[2].copy()
    hist = []
    blowup_step = -1

    for t in range(steps):
        mag = np.sqrt(wx**2 + wy**2 + wz**2)
        hist.append(mag.copy())

        if np.any(np.isnan(mag)) or np.any(np.isinf(mag)):
            blowup_step = t
            while len(hist) < steps: hist.append(hist[-1])
            break

        w_hat = [fftn(wx), fftn(wy), fftn(wz)]
        u, v, w = get_velocity(w_hat)

        cx = v * wz - w * wy; cy = w * wx - u * wz; cz = u * wy - v * wx
        Nx = np.real(ifftn(1j * (KY * fftn(cz) - KZ * fftn(cy))))
        Ny = np.real(ifftn(1j * (KZ * fftn(cx) - KX * fftn(cz))))
        Nz = np.real(ifftn(1j * (KX * fftn(cy) - KY * fftn(cx))))

        wx = wx - dt * Nx + dt * nu * np.real(ifftn(-K2 * w_hat[0]))
        wy = wy - dt * Ny + dt * nu * np.real(ifftn(-K2 * w_hat[1]))
        wz = wz - dt * Nz + dt * nu * np.real(ifftn(-K2 * w_hat[2]))

    return hist, blowup_step

def run_nth_math(w0, steps, dt, nu):
    kx_m, ky_m, kz_m = w0[0].copy(), w0[1].copy(), w0[2].copy()
    px, py, pz = np.zeros_like(kx_m), np.zeros_like(ky_m), np.zeros_like(kz_m)
    hist_k, hist_p = [], []
    T_CRIT = 60.0

    for t in range(steps):
        hist_k.append(np.sqrt(kx_m**2 + ky_m**2 + kz_m**2).copy())
        hist_p.append(np.sqrt(px**2 + py**2 + pz**2).copy())

        w_hat = [fftn(kx_m), fftn(ky_m), fftn(kz_m)]
        u, v, w = get_velocity(w_hat)

        cx = v * kz_m - w * ky_m; cy = w * kx_m - u * kz_m; cz = u * ky_m - v * kx_m
        Nx = np.real(ifftn(1j * (KY * fftn(cz) - KZ * fftn(cy))))
        Ny = np.real(ifftn(1j * (KZ * fftn(cx) - KX * fftn(cz))))
        Nz = np.real(ifftn(1j * (KX * fftn(cy) - KY * fftn(cx))))

        tension = np.sqrt(Nx**2 + Ny**2 + Nz**2)
        mask = tension > T_CRIT

        if np.any(mask):
            excess = tension - T_CRIT
            px[mask] += dt * excess[mask] * (Nx[mask]/tension[mask]) * 0.1
            py[mask] += dt * excess[mask] * (Ny[mask]/tension[mask]) * 0.1
            pz[mask] += dt * excess[mask] * (Nz[mask]/tension[mask]) * 0.1
            Nx = np.where(mask, Nx / tension * T_CRIT, Nx)
            Ny = np.where(mask, Ny / tension * T_CRIT, Ny)
            Nz = np.where(mask, Nz / tension * T_CRIT, Nz)

        kx_m = kx_m - dt * Nx + dt * nu * np.real(ifftn(-K2 * w_hat[0]))
        ky_m = ky_m - dt * Ny + dt * nu * np.real(ifftn(-K2 * w_hat[1]))
        kz_m = kz_m - dt * Nz + dt * nu * np.real(ifftn(-K2 * w_hat[2]))

        np.nan_to_num(kx_m, copy=False, nan=0.0, posinf=T_CRIT, neginf=-T_CRIT)
        np.nan_to_num(ky_m, copy=False, nan=0.0, posinf=T_CRIT, neginf=-T_CRIT)
        np.nan_to_num(kz_m, copy=False, nan=0.0, posinf=T_CRIT, neginf=-T_CRIT)

    return hist_k, hist_p

print("Running Organic Simulations (Vortex Stretching)...")
class_hist, class_blow = run_classical([omega0_x, omega0_y, omega0_z], steps, dt, nu)
nth_k_hist, nth_p_hist = run_nth_math([omega0_x, omega0_y, omega0_z], steps, dt, nu)

