kz = 2 * np.pi * fftfreq(N, d=L/N)
KX, KY, KZ = np.meshgrid(kx, ky, kz, indexing='ij')
K2 = KX**2 + KY**2 + KZ**2
K2[0, 0, 0] = 1.0

def get_velocity(w_hat):
    psi_x = w_hat[0] / K2; psi_y = w_hat[1] / K2; psi_z = w_hat[2] / K2
    u = np.real(ifftn(1j * KY * psi_z - 1j * KZ * psi_y))
    v = np.real(ifftn(1j * KZ * psi_x - 1j * KX * psi_z))
    w = np.real(ifftn(1j * KX * psi_y - 1j * KY * psi_x))
    return u, v, w

# ------------------------------------------------------------
# 3. Run Simulations & Store History
# ------------------------------------------------------------
def run_classical(w0, steps, dt, nu):
    wx, wy, wz = w0[0].copy(), w0[1].copy(), w0[2].copy()
    hist = []
    blowup_step = -1

    for t in range(steps):
        mag = np.sqrt(wx**2 + wy**2 + wz**2)
        hist.append(mag.copy())

        if np.any(np.isnan(mag)) or np.any(np.isinf(mag)) or np.max(mag) > 1e6:
            blowup_step = t
            while len(hist) < steps: hist.append(hist[-1])
            break

        w_hat = [fftn(wx), fftn(wy), fftn(wz)]
        u, v, w = get_velocity(w_hat)

        cx = v * wz - w * wy; cy = w * wx - u * wz; cz = u * wy - v * wx
        Nx = np.real(ifftn(1j * (KY * fftn(cz) - KZ * fftn(cy))))
        Ny = np.real(ifftn(1j * (KZ * fftn(cx) - KX * fftn(cz))))
        Nz = np.real(ifftn(1j * (KX * fftn(cy) - KY * fftn(cx))))

        wx = wx - dt * Nx
        wy = wy - dt * Ny
        wz = wz - dt * Nz

    return hist, blowup_step

def run_nth_math(w0, steps, dt, nu):
    kx_m, ky_m, kz_m = w0[0].copy(), w0[1].copy(), w0[2].copy()
    px, py, pz = np.zeros_like(kx_m), np.zeros_like(ky_m), np.zeros_like(kz_m)
    hist_k, hist_p = [], []
    T_CRIT = 100.0  # Omega-Selector boundary

    for t in range(steps):
        hist_k.append(np.sqrt(kx_m**2 + ky_m**2 + kz_m**2).copy())
        hist_p.append(np.sqrt(px**2 + py**2 + pz**2).copy())

        w_hat = [fftn(kx_m), fftn(ky_m), fftn(kz_m)]
        u, v, w = get_velocity(w_hat)

        cx = v * kz_m - w * ky_m; cy = w * kx_m - u * kz_m; cz = u * ky_m - v * kx_m
        Nx = np.real(ifftn(1j * (KY * fftn(cz) - KZ * fftn(cy))))
        Ny = np.real(ifftn(1j * (KZ * fftn(cx) - KX * fftn(cz))))
        Nz = np.real(ifftn(1j * (KX * fftn(cy) - KY * fftn(cx))))

        tension = np.sqrt(Nx**2 + Ny**2 + Nz**2)
        mask = tension > T_CRIT

        if np.any(mask):
            excess = tension - T_CRIT
            px[mask] += dt * excess[mask] * (Nx[mask]/tension[mask]) * 0.1
            py[mask] += dt * excess[mask] * (Ny[mask]/tension[mask]) * 0.1
            pz[mask] += dt * excess[mask] * (Nz[mask]/tension[mask]) * 0.1
            Nx = np.where(mask, Nx / tension * T_CRIT, Nx)
            Ny = np.where(mask, Ny / tension * T_CRIT, Ny)
            Nz = np.where(mask, Nz / tension * T_CRIT, Nz)

        kx_m = kx_m - dt * Nx
        ky_m = ky_m - dt * Ny
        kz_m = kz_m - dt * Nz

        np.nan_to_num(kx_m, copy=False, nan=0.0, posinf=T_CRIT, neginf=-T_CRIT)
        np.nan_to_num(ky_m, copy=False, nan=0.0, posinf=T_CRIT, neginf=-T_CRIT)
        np.nan_to_num(kz_m, copy=False, nan=0.0, posinf=T_CRIT, neginf=-T_CRIT)

    return hist_k, hist_p

print("Running Organic Inviscid Euler Simulation (Classical)...")
class_hist, class_blow = run_classical([omega0_x, omega0_y, omega0_z], max_steps, dt, nu)

if class_blow != -1: print(f"Classical organically crashed at step {class_blow} (Time = {class_blow*dt:.3f})")
else: print("Classical survived.")

print("Running Nth Math Topology Simulation...")
nth_k_hist, nth_p_hist = run_nth_math([omega0_x, omega0_y, omega0_z], max_steps, dt, nu)
print("Nth Math completed. Global existence maintained.")

# ------------------------------------------------------------
# 4. Playable Animation (Frame Skipping for Size)
# ------------------------------------------------------------
fig = plt.figure(figsize=(16, 6))
ax1 = fig.add_subplot(131, projection='3d')
ax2 = fig.add_subplot(132, projection='3d')
ax3 = fig.add_subplot(133, projection='3d')

init_mag = np.sqrt(omega0_x**2 + omega0_y**2 + omega0_z**2)
threshold = np.max(init_mag) * 0.3
p_threshold = 0.5

skip = 3 # Skip frames to reduce animation size
frames = range(0, max_steps, skip)
Xs, Ys, Zs = X[::2, ::2, ::2], Y[::2, ::2, ::2], Z[::2, ::2, ::2]

def update(frame_idx):
    frame = frames[frame_idx]
    ax1.clear(); ax2.clear(); ax3.clear()

    mag_c = class_hist[frame][::2, ::2, ::2]
    mask = mag_c > threshold
    if np.any(mask): ax1.scatter(Xs[mask], Ys[mask], Zs[mask], c=mag_c[mask], cmap='inferno', alpha=0.6)
    ax1.set_title(f"Classical Euler\n(Step {frame}, t={frame*dt:.2f})")
    ax1.set_xlim(0,L); ax1.set_ylim(0,L); ax1.set_zlim(0,L)

    mag_k = nth_k_hist[frame][::2, ::2, ::2]
    mask = mag_k > threshold
    if np.any(mask): ax2.scatter(Xs[mask], Ys[mask], Zs[mask], c=mag_k[mask], cmap='viridis', alpha=0.6)
    ax2.set_title(f"Nth Math Mag (k)\n(Stable)")
    ax2.set_xlim(0,L); ax2.set_ylim(0,L); ax2.set_zlim(0,L)

    mag_p = nth_p_hist[frame][::2, ::2, ::2]
    mask = mag_p > p_threshold
    if np.any(mask): ax3.scatter(Xs[mask], Ys[mask], Zs[mask], c=mag_p[mask], cmap='plasma', alpha=0.6)
    ax3.set_title(f"Nth Math Phase (p)\n(Omega Absorption)")
    ax3.set_xlim(0,L); ax3.set_ylim(0,L); ax3.set_zlim(0,L)

    plt.tight_layout()

ani = FuncAnimation(fig, update, frames=len(list(frames)), interval=80, blit=False)
plt.close()
HTML(ani.to_jshtml())

"""OpenAI 6-Astra Style Trajectory Replication

This cell advects massless tracer particles using the stable Nth Math velocity field. It produces a playable animation showing the particles spiraling inward and stretching axially, colored by speed (Orange = fast, Teal = slow).
"""

# ============================================================
# NTH MATH — OpenAI 6-ASTRA STYLE TRAJECTORY VISUALIZATION
# Local Incompressible Motion & Axial Stretching
# ============================================================

import numpy as np
import matplotlib.pyplot as plt
from scipy.fft import fftn, ifftn, fftfreq
from scipy.interpolate import RegularGridInterpolator
from mpl_toolkits.mplot3d import Axes3D
from matplotlib.animation import FuncAnimation
from IPython.display import HTML

# ------------------------------------------------------------
# 1. Setup
# ------------------------------------------------------------
N = 32
L = 2 * np.pi
x = np.linspace(0, L, N, endpoint=False)
y = np.linspace(0, L, N, endpoint=False)
z = np.linspace(0, L, N, endpoint=False)
X, Y, Z = np.meshgrid(x, y, z, indexing='ij')
dt = 0.01
steps = 100
nu = 1e-4

r = np.sqrt((X - L/2)**2 + (Y - L/2)**2)
omega0_x = -10.0 * (Y - L/2) * np.exp(-5.0 * r**2)
omega0_y = 10.0 * (X - L/2) * np.exp(-5.0 * r**2)
omega0_z = 2.0 * np.sin(2 * Z) * np.exp(-5.0 * r**2)

kx = 2 * np.pi * fftfreq(N, d=L/N); ky = 2 * np.pi * fftfreq(N, d=L/N); kz = 2 * np.pi * fftfreq(N, d=L/N)
KX, KY, KZ = np.meshgrid(kx, ky, kz, indexing='ij')
K2 = KX**2 + KY**2 + KZ**2; K2[0,0,0] = 1.0

def get_velocity(w_hat):
    psi_x = w_hat[0] / K2; psi_y = w_hat[1] / K2; psi_z = w_hat[2] / K2
    u = np.real(ifftn(1j * KY * psi_z - 1j * KZ * psi_y))
    v = np.real(ifftn(1j * KZ * psi_x - 1j * KX * psi_z))
    w = np.real(ifftn(1j * KX * psi_y - 1j * KY * psi_x))
    return u, v, w

# ------------------------------------------------------------
# 2. Run Nth Math & Store Velocity Fields
# ------------------------------------------------------------
print("Generating Nth Math Velocity Field History...")
kx_m, ky_m, kz_m = omega0_x.copy(), omega0_y.copy(), omega0_z.copy()
px, py, pz = np.zeros_like(kx_m), np.zeros_like(kx_m), np.zeros_like(kx_m)
vel_history = []
T_CRIT = 60.0

for t in range(steps):
    w_hat = [fftn(kx_m), fftn(ky_m), fftn(kz_m)]
    u, v, w = get_velocity(w_hat)
    vel_history.append([u, v, w])

    cx = v * kz_m - w * ky_m; cy = w * kx_m - u * kz_m; cz = u * ky_m - v * kx_m
    Nx = np.real(ifftn(1j * (KY * fftn(cz) - KZ * fftn(cy))))
    Ny = np.real(ifftn(1j * (KZ * fftn(cx) - KX * fftn(cz))))
    Nz = np.real(ifftn(1j * (KX * fftn(cy) - KY * fftn(cx))))

    tension = np.sqrt(Nx**2 + Ny**2 + Nz**2)
    mask = tension > T_CRIT
    if np.any(mask):
        excess = tension - T_CRIT
        px[mask] += dt * excess[mask] * (Nx[mask]/tension[mask]) * 0.1
        py[mask] += dt * excess[mask] * (Ny[mask]/tension[mask]) * 0.1
        pz[mask] += dt * excess[mask] * (Nz[mask]/tension[mask]) * 0.1
        Nx = np.where(mask, Nx / tension * T_CRIT, Nx)
        Ny = np.where(mask, Ny / tension * T_CRIT, Ny)
        Nz = np.where(mask, Nz / tension * T_CRIT, Nz)

    kx_m = kx_m - dt * Nx + dt * nu * np.real(ifftn(-K2 * w_hat[0]))
    ky_m = ky_m - dt * Ny + dt * nu * np.real(ifftn(-K2 * w_hat[1]))
    kz_m = kz_m - dt * Nz + dt * nu * np.real(ifftn(-K2 * w_hat[2]))
    np.nan_to_num(kx_m, copy=False, nan=0.0, posinf=T_CRIT, neginf=-T_CRIT)
    np.nan_to_num(ky_m, copy=False, nan=0.0, posinf=T_CRIT, neginf=-T_CRIT)
    np.nan_to_num(kz_m, copy=False, nan=0.0, posinf=T_CRIT, neginf=-T_CRIT)

# ------------------------------------------------------------
# 3. Particle Advection
# ------------------------------------------------------------
n_particles = 300
# Start particles in a ring around the vortex
angles = np.random.uniform(0, 2*np.pi, n_particles)
radii = np.random.uniform(0.5, 1.0, n_particles)
pos = np.zeros((steps, n_particles, 3))
pos[0, :, 0] = L/2 + radii * np.cos(angles)
pos[0, :, 1] = L/2 + radii * np.sin(angles)
pos[0, :, 2] = np.random.uniform(L*0.4, L*0.6, n_particles)

print("Advecting Particles...")
for t in range(1, steps):
    u, v, w = vel_history[t-1]
    # Interpolate velocity to particle positions
    interp_u = RegularGridInterpolator((x, y, z), u, bounds_error=False, fill_value=0)
    interp_v = RegularGridInterpolator((x, y, z), v, bounds_error=False, fill_value=0)
    interp_w = RegularGridInterpolator((x, y, z), w, bounds_error=False, fill_value=0)

    pts = pos[t-1]
    vel_u = interp_u(pts); vel_v = interp_v(pts); vel_w = interp_w(pts)

    # Update positions
    pos[t, :, 0] = pts[:, 0] + dt * vel_u
    pos[t, :, 1] = pts[:, 1] + dt * vel_v
    pos[t, :, 2] = pts[:, 2] + dt * vel_w

    # Wrap boundaries (cyclic topology)
    pos[t] = pos[t] % L

# ------------------------------------------------------------
# 4. Playable 3D Trajectory Animation
# ------------------------------------------------------------
fig = plt.figure(figsize=(10, 8))
ax = fig.add_subplot(111, projection='3d')

def update_particles(frame):
    ax.clear()
    # Calculate speed for coloring (Orange = fast, Teal = slow)
    if frame > 0:
        diff = pos[frame] - pos[frame-1]
        speeds = np.sqrt(diff[:, 0]**2 + diff[:, 1]**2 + diff[:, 2]**2) / dt
    else:
        speeds = np.zeros(n_particles)

    # Plot trajectories up to current frame
    for i in range(n_particles):
        ax.plot(pos[:frame+1, i, 0], pos[:frame+1, i, 1], pos[:frame+1, i, 2], color='gray', alpha=0.3, linewidth=0.5)

    # Scatter current positions
    sc = ax.scatter(pos[frame, :, 0], pos[frame, :, 1], pos[frame, :, 2], c=speeds, cmap='plasma', s=20)

    ax.set_title(f"Nth Math Fluid Trajectories (6-Astra Style)\nFrame {frame}")
    ax.set_xlim(0, L); ax.set_ylim(0, L); ax.set_zlim(0, L)
    ax.set_xlabel('X'); ax.set_ylabel('Y'); ax.set_zlabel('Z')

ani = FuncAnimation(fig, update_particles, frames=steps, interval=50, blit=False)
plt.close()

# Add colorbar
fig.colorbar(plt.cm.ScalarMappable(cmap='plasma'), ax=ax, label='Speed (Orange=Fast, Teal=Slow)')
HTML(ani.to_jshtml())

