wall[0, :] = True
wall[0, inlet_y] = False
# Right boundary (Solid except Outlet)
wall[-1, :] = True
wall[-1, outlet_y] = False

# Interior Staggered Walls (Double thickness to obstruct flow heavily)
wall[40:42, 0:35] = True       # Wall 1 (Left to Center)
wall[80:82, 45:80] = True      # Wall 2 (Right to Center)
wall[120:122, 0:35] = True     # Wall 3 (Left to Center)
wall[160:162, 45:80] = True    # Wall 4 (Right to Center)

fluid = ~wall

# ------------------------------------------------------------
