    axs[1, 0].imshow(phase_data, cmap=cmap_phase, origin='lower', extent=[0, Nx, 0, Ny], vmin=0, vmax=2)
    axs[1, 0].set_title(f"Nth Math Phase States\n(0=Real, 1=Intermed, 2=Omega)", color='white')

    # Plot 4: Conceptual Phase Space (Bottom Right)
