# ============================================================
# NTH MATH 3D TORNADO GENESIS — APPROACH A: ORTHOGONAL SLICES
# Finite Difference Upwind Solver (Fixed Shapes & Triggered Omega)
# ============================================================
import numpy as np
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation
from IPython.display import HTML, display
import warnings
warnings.filterwarnings("ignore")

plt.style.use('dark_background')
plt.rcParams['animation.embed_limit'] = 150

# ------------------------------------------------------------
# 1. Grid & Physical Parameters
# ------------------------------------------------------------
Nx, Ny, Nz = 40, 40, 20
Lx, Ly, Lz = 4000.0, 4000.0, 1600.0
dx, dy, dz = Lx/Nx, Ly/Ny, Lz/Nz
dt = 0.2
steps = 300

nu, alpha = 15.0, 15.0
g, beta = 9.8, 1.0/300.0
T_avg = 25.0
U_surf, V_surf = 0.0, 5.0
U_upper, V_upper = -25.0, 0.0
T_surf, T_upper = 35.0, 15.0

u = np.zeros((Nx, Ny, Nz))
v = np.zeros((Nx, Ny, Nz))
w = np.zeros((Nx, Ny, Nz))
T = np.zeros((Nx, Ny, Nz))

for k in range(Nz):
    z_frac = k / (Nz - 1)
    u[:, :, k] = U_surf * (1 - z_frac) + U_upper * z_frac
    v[:, :, k] = V_surf * (1 - z_frac) + V_upper * z_frac
    T[:, :, k] = T_surf * (1 - z_frac) + T_upper * z_frac

X, Y = np.meshgrid(np.linspace(0, Lx, Nx), np.linspace(0, Ly, Ny), indexing='ij')
r2d = np.sqrt((X - Lx/2)**2 + (Y - Ly/2)**2)
# Increased Hotspot to +25C to drive stronger updraft
T[:, :, 0] += 25.0 * np.exp(-(r2d/500.0)**2)

phase_x = np.zeros((Nx, Ny, Nz))
phase_y = np.zeros((Nx, Ny, Nz))
phase_z = np.zeros((Nx, Ny, Nz))
V_CRIT = 35.0  # Lowered limit so Omega-Selector triggers naturally

def adv(f, u, v, w):
    dudx = np.where(u > 0, (f - np.roll(f, 1, axis=0)) / dx, (np.roll(f, -1, axis=0) - f) / dx)
    dudy = np.where(v > 0, (f - np.roll(f, 1, axis=1)) / dy, (np.roll(f, -1, axis=1) - f) / dy)
    dudz = np.where(w > 0, (f - np.roll(f, 1, axis=2)) / dz, (np.roll(f, -1, axis=2) - f) / dz)
    return u * dudx + v * dudy + w * dudz

def lap(f):
    return (np.roll(f, -1, axis=0) - 2*f + np.roll(f, 1, axis=0))/dx**2 + \
           (np.roll(f, -1, axis=1) - 2*f + np.roll(f, 1, axis=1))/dy**2 + \
           (np.roll(f, -1, axis=2) - 2*f + np.roll(f, 1, axis=2))/dz**2

def step():
    global u, v, w, T, phase_x, phase_y, phase_z
    adv_u = adv(u, u, v, w); lap_u = lap(u)
    adv_v = adv(v, u, v, w); lap_v = lap(v)
    adv_w = adv(w, u, v, w); lap_w = lap(w)
    adv_T = adv(T, u, v, w); lap_T = lap(T)

    buoy = beta * g * (T - T_avg)

    u += dt * (-adv_u + nu * lap_u)
    v += dt * (-adv_v + nu * lap_v)
    w += dt * (-adv_w + nu * lap_w + buoy)
    T += dt * (-adv_T + alpha * lap_T)

    u[0,:,:]=0; u[-1,:,:]=0; u[:,0,:]=0; u[:,-1,:]=0; u[:,:,0]=0; u[:,:,-1]=u[:,:,-2]
    v[0,:,:]=0; v[-1,:,:]=0; v[:,0,:]=0; v[:,-1,:]=0; v[:,:,0]=0; v[:,:,-1]=v[:,:,-2]
    w[0,:,:]=0; w[-1,:,:]=0; w[:,0,:]=0; w[:,-1,:]=0; w[:,:,0]=0; w[:,:,-1]=w[:,:,-2]

    for k in range(Nz):
        z_frac = k / (Nz - 1)
        u_bg = U_surf * (1 - z_frac) + U_upper * z_frac
        v_bg = V_surf * (1 - z_frac) + V_upper * z_frac
        u[:, :, k] = u_bg + (u[:, :, k] - u_bg) * 0.98
        v[:, :, k] = v_bg + (v[:, :, k] - v_bg) * 0.98

    T[:,:,0] = T_surf + 25.0 * np.exp(-(r2d/500.0)**2)
    T[:,:,-1] = T_upper
    T[0,:,:] = T[1,:,:]; T[-1,:,:] = T[-2,:,:]
    T[:,0,:] = T[:,1,:]; T[:,-1,:] = T[:,-2,:]

    speed = np.sqrt(u**2 + v**2 + w**2)
    mask = speed > V_CRIT
    if np.any(mask):
        excess = speed[mask] - V_CRIT
        scale = V_CRIT / speed[mask]
        u_dir = u[mask] / speed[mask]
        v_dir = v[mask] / speed[mask]
        w_dir = w[mask] / speed[mask]
        phase_x[mask] += excess * np.abs(u_dir)
        phase_y[mask] += excess * np.abs(v_dir)
        phase_z[mask] += excess * np.abs(w_dir)
        u[mask] *= scale
        v[mask] *= scale
        w[mask] *= scale

print("Running True 3D Tornado Genesis Simulation...")
history = []
for t in range(steps):
    step()
    if t % 5 == 0:
        mag = np.sqrt(u**2 + v**2 + w**2)
        history.append(mag.copy())
        print(f"Step {t} | Max VEL: {np.max(mag):.2f} m/s | Z-Phase: {np.sum(phase_z**2):.2f} | Y-Phase: {np.sum(phase_y**2):.2f} | X-Phase: {np.sum(phase_x**2):.2f}")

print("Rendering Animation...")
fig = plt.figure(figsize=(10, 8))
ax = fig.add_subplot(111, projection='3d')

# Pre-calculate correct meshgrids for surfaces to avoid shape mismatch
XX, YY = np.meshgrid(np.arange(Nx), np.arange(Ny), indexing='ij')
XX2, ZZ2 = np.meshgrid(np.arange(Nx), np.arange(Nz), indexing='ij')
YY3, ZZ3 = np.meshgrid(np.arange(Ny), np.arange(Nz), indexing='ij')

def update(idx):
    ax.clear()
    mag = history[idx]
    # Removed .T to match meshgrid shapes exactly
    z_slice = mag[:, :, Nz//4]
    y_slice = mag[:, Ny//2, :]
    x_slice = mag[Nx//2, :, :]

    vmax = 40.0
    ax.plot_surface(XX, YY, np.zeros_like(XX), facecolors=plt.cm.jet(z_slice/vmax), alpha=0.6, shade=False)
    ax.plot_surface(XX2, np.zeros_like(XX2), ZZ2, facecolors=plt.cm.jet(y_slice/vmax), alpha=0.6, shade=False)
    ax.plot_surface(np.zeros_like(YY3), YY3, ZZ3, facecolors=plt.cm.jet(x_slice/vmax), alpha=0.6, shade=False)

    ax.set_xlim(0, Nx); ax.set_ylim(0, Ny); ax.set_zlim(0, Nz)
    ax.set_title(f"Tornado Genesis (Slices)\nStep {idx*5} | Max VEL: {np.max(mag):.1f} m/s")
    ax.view_init(elev=25, azim=-50)

ani = FuncAnimation(fig, update, frames=len(history), interval=200, blit=False)
plt.close()
display(HTML(ani.to_jshtml()))

