# %% [markdown]
# ## 2D diagnostics

# %%
def plot_result(result, title):
    fig, ax = plt.subplots(2, 2, figsize=(13, 9))
    ax[0, 0].plot(result.times, result.real_enstrophy, label='Real enstrophy')
    ax[0, 0].plot(result.times, result.phase_enstrophy, label='Phase enstrophy')
    ax[0, 0].plot(result.times, result.real_enstrophy + result.phase_enstrophy,
                  label='Total structural enstrophy', linewidth=2)
    ax[0, 0].set_title(title + ': enstrophy channels')
    ax[0, 0].set_xlabel('time'); ax[0, 0].legend(); ax[0, 0].grid(alpha=0.3)
    ax[0, 1].plot(result.times, result.total_selector_energy)
    ax[0, 1].set_title('Combined selector energy')
    ax[0, 1].set_xlabel('time'); ax[0, 1].grid(alpha=0.3)
    ax[1, 0].semilogy(result.times, np.maximum(result.linear_momentum_error, 1e-18), label='linear')
    ax[1, 0].semilogy(result.times, np.maximum(result.angular_momentum_error, 1e-18), label='angular')
    ax[1, 0].set_title('Momentum bridge relative error')
    ax[1, 0].set_xlabel('time'); ax[1, 0].legend(); ax[1, 0].grid(alpha=0.3)
    ax[1, 1].plot(result.times, result.phase_routes)
    ax[1, 1].set_title('Non-Real phase points')
    ax[1, 1].set_xlabel('time'); ax[1, 1].grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

plot_result(result_2d, '2D Nth selector run')

