def plot_run(res):
    fig, ax = plt.subplots(2, 3, figsize=(16, 8))
    fig.suptitle(res.name, fontsize=11)
    a = ax[0, 0]
    a.plot(res.times, res.Eu, label='Real channel E_u')
    a.plot(res.times, res.Ep, label='Phase channel E_p')
    a.plot(res.times, res.E, 'k-', lw=2, label='Total selector energy')
    a.set_title('Selector energy (discrete sums)')
    a = ax[0, 1]
    a.plot(res.times, res.Zu, label='Real enstrophy Z_u')
    a.plot(res.times, res.Zp, label='Phase enstrophy Z_p')
    a.plot(res.times, res.Z, 'k-', lw=2, label='Total Z')
    a.set_title('Structural enstrophy channels')
    a = ax[0, 2]
    a.plot(res.times, res.max_u, label='max|u|')
    a.plot(res.times, res.max_p, label='max|p|')
    a.plot(res.times, res.max_wu, label='max|vorticity(u)|')
    a.set_title('Blow-up monitor (sup norms)')
    a = ax[1, 0]
    a.plot(res.times, res.div_max)
    a.set_title('Whole-term residual: max |divergence|')
    a = ax[1, 1]
    a.plot(res.times, res.routes)
    a.set_title('Non-Real phase points (Omega routes)')
    a = ax[1, 2]
    a.plot(res.times, res.mom_drift)
    a.set_title('Selector momentum drift (relative)')
    for row in ax:
        for a in row:
            a.set_xlabel('time'); a.grid(alpha=0.3)
    ax[0, 0].legend(); ax[0, 1].legend(); ax[0, 2].legend()
    plt.tight_layout(); plt.show()

def plot_comparison(res_nth, res_cls):
    fig, ax = plt.subplots(1, 3, figsize=(16, 4.4))
    fig.suptitle('High-tension A/B test: Omega active vs classical '
                 'Real-channel-only (identical discretization)', fontsize=11)
    ax[0].plot(res_nth.times, res_nth.Zu, label='Omega active')
    ax[0].plot(res_cls.times, res_cls.Zu, label='classical Real-only')
    ax[0].set_title('Real-channel enstrophy')
    ax[1].plot(res_nth.times, res_nth.max_wu, label='Omega active')
    ax[1].plot(res_cls.times, res_cls.max_wu, label='classical Real-only')
    ax[1].set_title('max |vorticity| of Real channel')
    ax[2].plot(res_nth.times, res_nth.Zp, label='phase Z_p (Omega run)')
    ax[2].plot(res_cls.times, res_cls.Zp, label='phase Z_p (classical)')
    ax[2].set_title('Phase-channel enstrophy')
    for a in ax:
        a.set_xlabel('time'); a.legend(); a.grid(alpha=0.3)
    plt.tight_layout(); plt.show()

def plot_structure(res):
    mid = res.u_final.shape[0] // 2
    umag = np.sqrt(np.sum(res.u_final ** 2, axis=-1))[mid]
    pmag = np.sqrt(np.sum(res.p_final ** 2, axis=-1))[mid]
    tmag = res.tension_final[mid]
    fig, ax = plt.subplots(1, 3, figsize=(15.5, 4.2))
    fig.suptitle(f'{res.label}: final mid-plane structure', fontsize=11)
    for a, F, title in ((ax[0], umag, '|u| (Real channel)'),
                        (ax[1], pmag, '|p| (phase channel)'),
                        (ax[2], tmag, 'structural tension')):
        im = a.imshow(F.T, origin='lower', cmap='viridis')
        a.set_title(title)
        fig.colorbar(im, ax=a)
    plt.tight_layout(); plt.show()

plot_run(result_base)
plot_run(result_stress)
plot_comparison(result_stress, result_classic)
plot_structure(result_stress)

