# SECTION 1 — SELECTOR ARITHMETIC LAYER (the formalism's own rules)
# =============================================================================
P_REAL, P_UNREAL = '1', 'i'

def phase_mul(p, q):
    """Definition 2 phase algebra: 1*1=1, 1*i=i, i*1=i, i*i=i.
    NOTE: this is NOT complex multiplication (i*i = i here). Negation
    never arises from the phase algebra; it lives only in the channel
    arms of the canonical product tuple."""
    return P_REAL if (p == P_REAL and q == P_REAL) else P_UNREAL

def quotient_phase(p, q):
    """Proposition 8: matching phases cancel to real; mismatched give i."""
    return P_REAL if p == q else P_UNREAL

def S(mag, phase=P_REAL):
    return (float(mag), phase)

def s_str(s):
    return f'n_|{s[0]:+.6f},{s[1]}|'

def product_spectrum(m, n):
    """Structural product of dual selectors — canonical tuple (Axiom 9.3):
    (R, U, C1, C2) = (n_|mn,1|, n_|mn,i|, n_|-mn,1|, n_|-mn,i|)."""
    return [S(m*n, P_REAL), S(m*n, P_UNREAL),
            S(-m*n, P_REAL), S(-m*n, P_UNREAL)]

# ---- the user's translation, as constructible spectra -----------------------
def t_spectrum(g):
    """t = n_|g,gi| / {1+g, 1+gi, i+g, i+gi}. Numerator arms (g,1),(g,i);
    denominator arms: four fusion outputs, magnitudes 1+g, phases (1,1,i,i)."""
    num = [(g, P_REAL), (g, P_UNREAL)]
    den = [(1.0+g, P_REAL), (1.0+g, P_REAL),
           (1.0+g, P_UNREAL), (1.0+g, P_UNREAL)]
    return num, den, g / (1.0 + g)

def cs_spectra(t):
    """c = {1-t^2, 1-ti^2, 1-t^2i, 1-ti^2i, i-t^2, ...} over
       {1+t^2, 1+ti^2, 1+t^2i, 1+ti^2i, i+t^2, ...}   and
       s = {2t, 2ti, 2it, 2iti} over the same denominator set.
    The four product arms of t(x)t all carry magnitude t^2 (the canonical
    tuple's signs are channel labels, not arm magnitudes); the dual leads
    {1, i} give eight numerator and eight denominator channels."""
    arms = [(t*t, P_REAL), (t*t, P_UNREAL),
            (t*t, P_UNREAL), (t*t, P_UNREAL)]
    leads = [(1.0, P_REAL), (1.0, P_UNREAL)]
    num_c = [(lm - am, lp) for (lm, lp) in leads for (am, ap) in arms]
    den_c = [(lm + am, lp) for (lm, lp) in leads for (am, ap) in arms]
    num_s = [(2.0*t, ph) for (am, ph) in arms]
    return num_c, den_c, num_s

def collapse_check(num, den, ref):
    """Enumerate every channel quotient and verify the Proposition 8
    corollary: all magnitudes equal the reference ratio."""
    worst = 0.0
    for (nm, nph) in num:
        for (dm, dph) in den:
            worst = max(worst, abs(nm/dm - ref))
    return worst

