    chans = [s_str(S(nm/dm, quotient_phase(nph, dph)))
             for (nm, nph) in num for (dm, dph) in den]
    print('   quotient channels:', ', '.join(chans[:4]) + ', ...')
    w = collapse_check(num, den, t_ref)
