# =============================================================================
# SECTION 1 — SELECTOR ARITHMETIC LAYER (dual-arm notation)
# =============================================================================
P_REAL, P_UNREAL = '1', 'i'

def phase_mul(p, q):
    """Definition 2 phase algebra: 1*1=1, 1*i=i, i*1=i, i*i=i.
    NOT complex multiplication; negation lives only in the C-arms of the
    canonical product tuple."""
    return P_REAL if (p == P_REAL and q == P_REAL) else P_UNREAL

def quotient_phase(p, q):
    """Proposition 8: matching phases cancel to real; mismatched give i."""
    return P_REAL if p == q else P_UNREAL

def S(mag, phase=P_REAL):
    """DUAL selector n_|m, m*phase| (Proposition 8 form): the magnitude
    is carried in BOTH the real arm and the unreal arm. Returns
    (real_arm, unreal_arm, phase) — a symmetric Nth identity."""
    return (float(mag), float(mag), phase)

def dual_str(s):
    m, mu, ph = s
    arm2 = f'{mu:+.6f}i' if ph == P_UNREAL else f'{mu:+.6f}'
    return f'n_|{m:+.6f}, {arm2}|'

def product_spectrum(m, n):
    """Structural product of dual selectors — SYMMETRIC canonical tuple
    (Axiom 9.3 + Part IX), magnitude in both arms:
        R  = n_|+mn, +mn|     real resonance
        U  = n_|+mn, +mni|    unreal resonance (mirror)
        C1 = n_|-mn, -mn|     cross-phase 1
        C2 = n_|-mn, -mni|    cross-phase 2
    Signs (+,+,-,-) per the canonical tuple; phases (1,i,1,i) per the
    four output channels. NOTATION FIX: the earlier print n_|25,i| was
    asymmetric (real arm 25, unreal arm 1)."""
    return [S(m*n, P_REAL), S(m*n, P_UNREAL),
            S(-m*n, P_REAL), S(-m*n, P_UNREAL)]

def t_spectrum(g):
    """t = n_|g,gi| / {1+g, 1+gi, i+g, i+gi} (user translation)."""
    num = [(g, P_REAL), (g, P_UNREAL)]
    den = [(1.0+g, P_REAL), (1.0+g, P_REAL),
           (1.0+g, P_UNREAL), (1.0+g, P_UNREAL)]
    return num, den, g / (1.0 + g)

def cs_spectra(t):
    """c and s selector spectra (user translation)."""
    arms = [(t*t, P_REAL), (t*t, P_UNREAL),
            (t*t, P_UNREAL), (t*t, P_UNREAL)]
    leads = [(1.0, P_REAL), (1.0, P_UNREAL)]
    num_c = [(lm - am, lp) for (lm, lp) in leads for (am, ap) in arms]
    den_c = [(lm + am, lp) for (lm, lp) in leads for (am, ap) in arms]
    num_s = [(2.0*t, ph) for (am, ph) in arms]
    return num_c, den_c, num_s

def collapse_check(num, den, ref):
    """Verify the Proposition 8 corollary across every channel quotient:
    all magnitudes collapse to the reference ratio."""
    worst = 0.0
    for (nm, nph) in num:
        for (dm, dph) in den:
            worst = max(worst, abs(nm/dm - ref))
    return worst

