# =============================================================================
# SECTION 3 — Cyclic grid and fusion stencils
# =============================================================================
def make_grid(n, length=2.0*np.pi):
    assert n >= 4 and (n & (n - 1)) == 0, \
        'grid size must be a power of two (cascade scale closure)'
    x = np.linspace(0.0, length, n, endpoint=False)
    axes = np.meshgrid(x, x, x, indexing='ij')
    return axes, length / n

def dd(f, axis, dx):
    """Centered periodic difference; exact telescoping over the torus."""
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis)) * (0.5/dx)

def grad_vec(u, dx):
    gu = np.empty(u.shape + (3,))
    for i in range(3):
        for j in range(3):
            gu[..., i, j] = dd(u[..., i], j, dx)
    return gu

def curl(u, dx):
    g = grad_vec(u, dx)
    w = np.empty_like(u)
    w[..., 0] = g[..., 2, 1] - g[..., 1, 2]
    w[..., 1] = g[..., 0, 2] - g[..., 2, 0]
    w[..., 2] = g[..., 1, 0] - g[..., 0, 1]
    return w

def div_u(u, dx):
    return (dd(u[..., 0], 0, dx) + dd(u[..., 1], 1, dx)
            + dd(u[..., 2], 2, dx))

def lap_vec(u, dx):
    out = np.empty_like(u)
    inv = 1.0 / (dx*dx)
    for i in range(3):
        f = u[..., i]
        out[..., i] = (-6.0*f + np.roll(f, -1, 0) + np.roll(f, 1, 0)
                       + np.roll(f, -1, 1) + np.roll(f, 1, 1)
                       + np.roll(f, -1, 2) + np.roll(f, 1, 2)) * inv
    return out

def advect_skew(u, dx):
    """Fused structural product (Proposition 7 output-set fusion).
    Exact discrete identity: sum(u.adv) = 0 — zero scalar leakage."""
    out = np.zeros_like(u)
    for i in range(3):
        for j in range(3):
            fi, fj = u[..., i], u[..., j]
            out[..., i] += 0.5 * (dd(fj*fi, j, dx) + fj*dd(fi, j, dx))
    return out

# =============================================================================
# SECTION 4 — Nth Jacobian
# =============================================================================
@dataclass
class JacobianChannels:
    R: np.ndarray; U: np.ndarray; C1: np.ndarray; C2: np.ndarray
    vort: np.ndarray; tension: np.ndarray

def nth_jacobian(u, dx):
    G = grad_vec(u, dx)
    S_ = 0.5 * (G + np.swapaxes(G, -1, -2))
    A_ = 0.5 * (G - np.swapaxes(G, -1, -2))
    C1 = np.sqrt(np.sum(S_*S_, axis=(-2, -1)))
    C2 = np.sqrt(np.sum(A_*A_, axis=(-2, -1)))
    a, b, c = G[..., 0, 0], G[..., 0, 1], G[..., 0, 2]
    d, e, f = G[..., 1, 0], G[..., 1, 1], G[..., 1, 2]
    g, h, i = G[..., 2, 0], G[..., 2, 1], G[..., 2, 2]
    R = a*(e*i - f*h) - b*(d*i - f*g) + c*(d*h - e*g)
    U = np.sqrt(np.sum(G*G, axis=(-2, -1))) - np.abs(R)
    vort = np.stack([G[..., 2, 1] - G[..., 1, 2],
                     G[..., 0, 2] - G[..., 2, 0],
                     G[..., 1, 0] - G[..., 0, 1]], axis=-1)
    return JacobianChannels(R, U, C1, C2, vort, C1 + C2 + np.abs(R))

# =============================================================================
# SECTION 5 — Native trigonometry and initial field
# =============================================================================
def nth_trig(angle, n_steps=128):
    """Nth trigonometric projection operators (Part VII): modular fusion
    fold [Ax 7.3], half-selector by division spectrum [Prop 8], n fusions
    around the unit selector circle [Ax 7.2]. No np.sin / np.cos."""
    a = np.mod(angle, TAU)
    t = a / (2.0 * n_steps)
    dc = (1.0 - t*t) / (1.0 + t*t)
    ds = (2.0 * t) / (1.0 + t*t)
    c = np.ones_like(a)
    s = np.zeros_like(a)
    for _ in range(n_steps):
        c, s = c*dc - s*ds, s*dc + c*ds
    return c, s

def initial_selector_field(axes, amplitude, harmonic):
    x, y, z = axes
    def mode(k):
        cx, sx = nth_trig(k*x)
        cy, sy = nth_trig(k*y)
        cz, sz = nth_trig(k*z)
        return np.stack([sx*cy*cz, -(cx*sy*cz), np.zeros_like(x)], axis=-1)
    return amplitude * (mode(1.0) + harmonic * mode(2.0))

_a = np.linspace(0.0, 2.0*TAU, 1441)
BRIDGE_DEV = 0.0
for _k in (1.0, 2.0):
    _c, _s = nth_trig(_k*_a)
    BRIDGE_DEV = max(BRIDGE_DEV,
                     float(np.max(np.abs(_s - np.sin(_k*_a)))),
                     float(np.max(np.abs(_c - np.cos(_k*_a)))))
print(f'IC bridge deviation vs classical magnitude projection: '
      f'{BRIDGE_DEV:.2e}  (identical IC for every run, so A/B tests exact)')

# =============================================================================
# SECTION 6 — Omega selector: native assembly
# =============================================================================
def angle_selector(g):
    """Omega angle selector — the trans-finite compactifier:
    g in [0, inf) -> t in [0, 1) -> rotation in [0, pi/2)."""
    t = g / (1.0 + g)
    c = (1.0 - t*t) / (1.0 + t*t)
    s = (2.0 * t) / (1.0 + t*t)
    return t, c, s

def unreal_mirror(axis):
    """Axiom 9.0 unreal mirror of the axis selector (antisymmetric
    coupling tensor; M v = axis x v — the quarter-phase partner map)."""
    a1, a2, a3 = (axis[..., 0], axis[..., 1], axis[..., 2])
    M = np.zeros(axis.shape[:-1] + (3, 3))
    M[..., 0, 1] = -a3; M[..., 0, 2] =  a2
    M[..., 1, 0] =  a3; M[..., 1, 2] = -a1
    M[..., 2, 0] = -a2; M[..., 2, 1] =  a1
    return M

def partner(M, d):
    return np.einsum('...ij,...j->...i', M, d)

def sample_collapse_audit(g_field, n=16):
    flat = g_field.ravel()
    flat = flat[flat > 0.0]
    if flat.size == 0:
        return 0.0
    idx = rng.choice(flat.size, size=min(n, flat.size), replace=False)
    worst = 0.0
    for g in flat[idx]:
        num, den, t_ref = t_spectrum(float(g))
        worst = max(worst, collapse_check(num, den, t_ref))
        num_c, den_c, num_s = cs_spectra(t_ref)
        c_ref = (1.0 - t_ref*t_ref)/(1.0 + t_ref*t_ref)
        s_ref = 2.0*t_ref/(1.0 + t_ref*t_ref)
        worst = max(worst, collapse_check(num_c, den_c, c_ref),
                    collapse_check(num_s, den_c, s_ref))
    return worst

def omega_transfer_nth(u, p, jac, dx, threshold, gain):
    """Omega-selector, fully native: m = u (+) p, d = u (-) p, angle from
    the division spectrum, quarter-phase partner from the unreal mirror,
    unit-circle fusion on the transverse arm. Pointwise invariants
    u+p and |u|^2+|p|^2 hold by construction (audited)."""
    excess = np.maximum(jac.tension - threshold, 0.0)
    active = excess > 0.0
    g = gain * excess * dx
    t, c, s = angle_selector(g)

    m = u + p
    d = 0.5 * (u - p)

    rot_dom = jac.C2 > jac.C1
    wn = np.sqrt(np.sum(jac.vort*jac.vort, axis=-1))
    gs = np.stack([dd(jac.C1, a, dx) for a in (0, 1, 2)], axis=-1)
    gn = np.sqrt(np.sum(gs*gs, axis=-1))
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    axis = np.zeros_like(u)
    if use_v.any():
        axis[use_v] = (jac.vort / np.maximum(wn, 1e-30)[..., None])[use_v]
    if use_g.any():
        axis[use_g] = (gs / np.maximum(gn, 1e-30)[..., None])[use_g]

    M = unreal_mirror(axis)
    Pd = partner(M, d)
    d_ax = d + partner(M, Pd)          # d + P(P(d)) = axial projection
    d_tr = d - d_ax
    Ptr = partner(M, d_tr)
    d_new = d_ax + c[..., None]*d_tr + s[..., None]*Ptr

    u_new = 0.5*m + d_new
    p_new = 0.5*m - d_new

    rdom = np.abs(jac.R) > np.maximum(jac.C1, jac.C2)
    phase = np.full(excess.shape, 'Real', dtype='<U6')
    phase[active & rdom] = 'C2'
    phase[active & ~rdom & rot_dom] = 'Unreal'
    phase[active & ~rdom & ~rot_dom] = 'C1'
    routes = int(np.count_nonzero(active))

    aud = {'circle': float(np.max(np.abs(c*c + s*s - 1.0))),
           'g_max': float(np.max(g))}
    if active.any():
        scale = float(np.max(np.sum(d_tr*d_tr, -1) + np.sum(Ptr*Ptr, -1)))
        aud['orth'] = float(np.max(np.abs(np.sum(d_tr*Ptr, -1)))) / max(scale, 1e-300)
        aud['norm'] = float(np.max(np.abs(np.sum(Ptr*Ptr, -1)
                                          - np.sum(d_tr*d_tr, -1)))) / max(scale, 1e-300)
        aud['collapse'] = sample_collapse_audit(g)
    else:
        aud['orth'] = aud['norm'] = aud['collapse'] = 0.0

    err_m = float(np.max(np.abs((u_new + p_new) - (u + p))))
    e0 = float(np.sum(u*u + p*p))
    e1 = float(np.sum(u_new*u_new + p_new*p_new))
    err_e = abs(e1 - e0) / max(abs(e0), 1e-300)
    return u_new, p_new, phase, routes, max(err_m, err_e), aud

# =============================================================================
# SECTION 7 — WHOLE-TERM CASCADE, OPERATOR-EXACT (mod-2 classes)
# =============================================================================
def restrict(F):
    a, b, c = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (a//2, 2, b//2, 2, c//2, 2)
                     ).mean(axis=(-5, -3, -1))

def _interp1(F, axis):
    n = F.shape[axis]
    shp = list(F.shape); shp[axis] = 2*n
    G = np.empty(shp, dtype=F.dtype)
    se = [slice(None)]*F.ndim; se[axis] = slice(0, 2*n, 2)
    G[tuple(se)] = F
    so = [slice(None)]*F.ndim; so[axis] = slice(1, 2*n, 2)
    G[tuple(so)] = 0.5 * (F + np.roll(F, -1, axis=axis))
    return G

def prolong(C):
    F = _interp1(C, C.ndim - 3)
    F = _interp1(F, F.ndim - 2)
    F = _interp1(F, F.ndim - 1)
    return F

def lap_apply(F, dx):
    """Compact 7-point Laplacian on the last three axes (negative
    semi-definite; null space = constants)."""
    inv = 1.0 / (dx*dx)
    s = -6.0 * F
    for a in (F.ndim - 3, F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s * inv

_RBGS_CACHE = {}
def _rb_mask(m):
    if m not in _RBGS_CACHE:
        idx = np.indices((m, m, m))
        red = ((idx[0] + idx[1] + idx[2]) % 2 == 0)
        _RBGS_CACHE[m] = (red, ~red)
    return _RBGS_CACHE[m]

def smooth_gs(phi, f, dx, iters):
    """Red-black Gauss-Seidel for L phi = f (L negative semi-definite,
    diagonal -6/dx^2). Residual form of the EXACT block update:
        phi <- phi - (dx^2/6)(f - L phi)   on red, then on black.
    Each half-sweep solves that color's equations exactly given the other
    color's frozen values. THE SIGN IS THE v5 CONVENTION — v6's rewrite
    had '+' (amplifier: factor 1 + 6c/dx^2 = 2 per half-sweep), which
    the gate caught as NaN at cycle 13. The validate_solver() unit test
    below makes any such error unpassable."""
    c = dx * dx / 6.0
    red, black = _rb_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - lap_apply(phi, dx)
        phi = phi - c * np.where(red, r, 0.0)
        r = f - lap_apply(phi, dx)
        phi = phi - c * np.where(black, r, 0.0)
    return phi

def v_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - f.mean(axis=(-3, -2, -1), keepdims=True)
        return smooth_gs(phi, f, dx, 40)
    phi = smooth_gs(phi, f, dx, 2)
    r = f - lap_apply(phi, dx)
    rc = restrict(r)
    ec = v_cycle(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + prolong(ec)
    return smooth_gs(phi, f, dx, 2)

def split_classes(f):
    """GATHER: decimate a full-grid bundle into its 8 mod-2 parity
    classes (Axiom 0 closure structure). Pure indexing — exact."""
    N = f.shape[-1]
    M = N // 2
    out = np.empty(f.shape[:-3] + (8, M, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                out[..., c, :, :, :] = f[..., a::2, b::2, d::2]
                c += 1
    return out

def merge_classes(g, N):
    """DISPERSE: interleave the 8 class bundles back onto the full grid."""
    f = np.empty(g.shape[:-4] + (N, N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                f[..., a::2, b::2, d::2] = g[..., c, :, :, :]
                c += 1
    return f

def div_bundle(V, dx):
    out = np.zeros(V.shape[:-1])
    for j in range(3):
        out += dd(V[..., j], j + 1, dx)
    return out

def grad_bundle(phi, dx):
    return np.stack([dd(phi, a, dx) for a in (1, 2, 3)], axis=-1)

@dataclass
class ProjStats:
    solves: int = 0; cycles_total: int = 0; cycles_max: int = 0
    worst_resid: float = 0.0

def project_bundle(V, dx, phi=None, tol=1e-9, max_cycles=15, stats=None):
    """Whole-Term projection, OPERATOR-EXACT. The balance
    div(grad phi) = -div V is enforced with the SAME centered stencils
    the physics uses. The wide operator div(grad .) decouples exactly
    along the 8 mod-2 parity classes; on each class it IS the compact
    balance at double spacing H = 2dx. Hence: gather -> resolve (batched
    RBGS cascade per class) -> disperse. Divergence after projection
    equals the recorded solve residual in EVERY mode, including the
    Nyquist band where the v1-v5 bridge removed exactly nothing."""
    f = -div_bundle(V, dx)                       # (C, N, N, N)
    fc = split_classes(f)                        # (C, 8, M, M, M)
    H = 2.0 * dx
    fc = fc - fc.mean(axis=(-3, -2, -1), keepdims=True)
    f0 = np.sqrt(np.sum(fc*fc, axis=(-3, -2, -1)))          # (C, 8)
    live = f0 > 1e-300
    live5 = live[..., None, None, None]
    fc = fc * live5
    if phi is None:
        psic = np.zeros_like(fc)
    else:
        psic = split_classes(phi) * live5
    psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
    cycles, worst = 0, 0.0
    if live.any():
        def rel_resid():
            r = fc - lap_apply(psic, H)
            rn = np.sqrt(np.sum(r*r, axis=(-3, -2, -1)))
            rel = rn / np.maximum(f0, 1e-300)
            return float(np.max(rel[live]))
        worst = rel_resid()
        while worst >= tol and cycles < max_cycles:
            psic = v_cycle(psic, fc, H)
            psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
            cycles += 1
            worst = rel_resid()
    phi_out = merge_classes(psic, V.shape[-3])
    Vp = V + grad_bundle(phi_out, dx)
    if stats is not None and live.any():
        stats.solves += 1
        stats.cycles_total += cycles
        stats.cycles_max = max(stats.cycles_max, cycles)
        stats.worst_resid = max(stats.worst_resid, worst)
    return Vp, phi_out, cycles, worst

def validate_solver(m=16, seed=3):
    """SOLVER UNIT TEST — exact recovery. Constructs f = L(phi_true) for
    a random smooth mean-zero phi_true on a class-sized grid and
    requires the very same v_cycle used by the projection to recover
    phi_true. Categorical: a wrong SIGN diverges (fails); a wrong
    OPERATOR converges to the wrong solution (fails); a wrong SPACING
    converges to the wrong solution (fails). No error of the class that
    failed v4/v6 can pass this test."""
    H = 0.4
    g = np.random.default_rng(seed)
    phi_true = g.standard_normal((m, m, m))
    for _ in range(6):
        for a in (0, 1, 2):
            phi_true = 0.5*phi_true + 0.25*(np.roll(phi_true, -1, axis=a)
                                            + np.roll(phi_true, 1, axis=a))
    phi_true -= phi_true.mean()
    f = lap_apply(phi_true, H)
    phi = np.zeros_like(f)
    for _ in range(30):
        phi = v_cycle(phi, f, H)
        phi -= phi.mean()
        res = float(np.max(np.abs(f - lap_apply(phi, H))))
        if res < 1e-11 * max(1.0, float(np.max(np.abs(f)))):
            break
    err = float(np.max(np.abs(phi - phi_true)))
    scale = max(1.0, float(np.max(np.abs(phi_true))))
    ok = np.isfinite(err) and err < 1e-6 * scale
    print(f'  exact recovery of a known solution: '
          f'|phi - phi_true|/scale = {err/scale:.2e}  (tol 1e-6)  '
          f'-> {"PASS" if ok else "FAIL"}')
    assert ok, ('SOLVER UNIT TEST FAILED — v_cycle cannot recover a known '
                'solution; aborting before any run.')

def validate_projection(n=32, seed=7):
    """BRIDGE GATE. The cascade must prove, BEFORE any physics run:
      (a) delta-Cauchy termination of the solve,
      (b) elimination of the ACTUAL divergence (the v1-v5 failure),
      (c) non-expansiveness (a projection may only remove energy),
      (d) targeted regression on the old bridge's failure bands.
    Failure aborts the cell."""
    axes, dx = make_grid(n)
    g = np.random.default_rng(seed)
    V = g.standard_normal((2, n, n, n, 3))
    for _ in range(6):
        for a in (1, 2, 3):
            V = 0.5*V + 0.25*(np.roll(V, -1, axis=a) + np.roll(V, 1, axis=a))
    E0 = float(np.sum(V*V))
    d0 = float(np.max(np.abs(div_bundle(V, dx))))
    Vp, phi, cycles, resid = project_bundle(V, dx, None, 1e-10, 25)
    E1 = float(np.sum(Vp*Vp))
    d1 = float(np.max(np.abs(div_bundle(Vp, dx))))
    ok_a = np.isfinite(resid) and resid < 1e-8
    ok_b = np.isfinite(d1) and d1 <= max(1e-9, 1e-6*d0)
    ok_c = np.isfinite(E1) and E1 <= E0*(1.0 + 1e-6)
    print(f'  random smooth bundle ({cycles} cycles, cold start):')
    print(f'  (a) solve residual: {resid:.2e} (tol 1e-8)          '
          f'-> {"PASS" if ok_a else "FAIL"}')
    print(f'  (b) max|div|: {d0:.2e} -> {d1:.2e}  '
          f'(reduction {d0/max(d1,1e-300):.1e}x)  '
          f'-> {"PASS" if ok_b else "FAIL"}')
    print(f'  (c) energy ratio after/before: {E1/max(E0,1e-300):.6f} '
          f'(<= 1)  -> {"PASS" if ok_c else "FAIL"}')
    print('      (~2/3 is the discrete Helmholtz signature in 3D)')
    x, y, z = axes
    ok_d = True
    print('  targeted regression modes (old bridge failure bands):')
    for k, lbl in ((1.0, 'low-k (k h = 0.19)'),
                   (8.0, 'mid-k (k h = pi/2, old retention 50%)')):
        ck, sk = nth_trig(k*x)
        W = np.zeros((1, n, n, n, 3))
        W[..., 0] = ck
        dw0 = float(np.max(np.abs(div_bundle(W, dx))))
        Wp, _, _, _ = project_bundle(W, dx, None, 1e-10, 25)
        dw1 = float(np.max(np.abs(div_bundle(Wp, dx))))
        ok = np.isfinite(dw1) and dw1 <= 1e-7*dw0
        ok_d = ok_d and ok
        print(f'  (d) {lbl:34s}: reduction {dw0/max(dw1,1e-300):.1e}x  '
              f'-> {"PASS" if ok else "FAIL"}')
    assert ok_a and ok_b and ok_c and ok_d, (
        'BRIDGE VALIDATION FAILED — aborting before any run so the '
        'failure cannot pose as a framework result.')
    print('  bridge validated: operator-exact, non-expansive, mod-2 '
          'class structure.')

print('\n' + '='*79)
print('BRIDGE GATE 1/2 — solver unit test (exact recovery)')
print('='*79)
validate_solver(16)
print('\n' + '='*79)
print('BRIDGE GATE 2/2 — projection validation')
print('='*79)
validate_projection(32)

# =============================================================================
# SECTION 7b — TRANFINITE METER
# =============================================================================
def transfinite_meter():
    L = '='*79
    print('\n' + L)
    print('TRANFINITE METER — the pi-phi cylinder compactification')
    print(L)
    print('  The Omega angle selector is a compactifier. The division spectrum')
    print('     n_|g,gi| / {1+g, 1+gi, i+g, i+gi}')
    print('  maps every finite tension excess g in [0, inf) onto t in [0, 1):')
    print('     t = g/(1+g),   rotation angle in [0, pi/2).')
    print('  "Infinity" is not a value the dynamics can reach; it is the LIMIT')
    print('  POINT t -> 1 — the quarter-phase lock of Appendix J: the phase-')
    print('  locked cylindrical orbit, approached, never attained.\n')
    print(f'  {"g":>10s}  {"t = g/(1+g)":>12s}  {"c":>12s}  {"s":>12s}  '
          f'{"1-t (lock deficit)":>19s}')
    for g in (0.0, 1e-6, 1e-3, 1.0, 1e3, 1e6, 1e12, 1e100, 1e300):
        t, c, s = angle_selector(g)
        print(f'  {g:10.0e}  {t:12.9f}  {c:12.6f}  {s:12.6f}  {1.0-t:19.0e}')
    print('\n  transfer stress test — total, bounded, invariant-exact at')
    print('  magnitudes far beyond any physical velocity:')
    thr, gain, dxs = 1.0, 10.0, 0.2
    for g_target in (1e6, 1e50, 1e300):
        tension = thr + g_target/(gain*dxs)
        jac = JacobianChannels(
            R=np.zeros((1, 1, 1)), U=np.zeros((1, 1, 1)),
            C1=np.zeros((1, 1, 1)), C2=np.ones((1, 1, 1)),
            vort=np.zeros((1, 1, 1, 3)),
            tension=np.full((1, 1, 1), tension))
        jac.vort[..., 2] = 1.0
        u = np.zeros((1, 1, 1, 3)); u[..., 0] = 3.0
        p = np.zeros_like(u)
        u2, p2, ph, rt, oerr, aud = omega_transfer_nth(
            u, p, jac, dxs, thr, gain)
        e_in = float(np.sum(u*u + p*p))
        e_out = float(np.sum(u2*u2 + p2*p2))
        print(f'    g = {g_target:8.0e}:  max|u| 3.000 -> '
              f'{float(np.sqrt(np.max(np.sum(u2*u2, -1)))):.3f}   '
              f'energy ratio = {e_out/max(e_in,1e-300):.12f}   '
              f'invariant err = {oerr:.1e}   phase = {ph.flat[0]}')
    print('\n  READING: at g = 1e300 the classical magnitude channel has long')
    print('  since overflowed every physical scale, yet the native transfer')
    print('  executes an exact quarter-phase lock — AT the lock, still')
    print('  bounded, still conservative. The trans-finite is a boundary')
    print('  point of the bounded selector space, not an escape from it.')
    print(L)

transfinite_meter()

# =============================================================================
# SECTION 8 — Observables and run driver
# =============================================================================
def observables(u, p, dx):
    vol = dx**3
    wu, wp = curl(u, dx), curl(p, dx)
    return {'Eu': 0.5*float(np.sum(u*u))*vol,
            'Ep': 0.5*float(np.sum(p*p))*vol,
            'E':  0.5*float(np.sum(u*u + p*p))*vol,
            'Zu': 0.5*float(np.sum(wu*wu))*vol,
            'Zp': 0.5*float(np.sum(wp*wp))*vol,
            'Z':  0.5*float(np.sum(wu*wu + wp*wp))*vol,
            'max_u': float(np.sqrt(np.max(np.sum(u*u, axis=-1)))),
            'max_p': float(np.sqrt(np.max(np.sum(p*p, axis=-1)))),
            'max_w': float(np.sqrt(np.max(np.sum(wu*wu, axis=-1)))),
            'mom': np.sum(u + p, axis=(0, 1, 2))*vol}

@dataclass
class RunResult:
    label: str; name: str; use_omega: bool; nu: float
    times: np.ndarray; E: np.ndarray; Eu: np.ndarray; Ep: np.ndarray
    Zu: np.ndarray; Zp: np.ndarray; Z: np.ndarray
    max_u: np.ndarray; max_p: np.ndarray; max_w: np.ndarray
    mom_drift: np.ndarray; div_max: np.ndarray; phase_routes: np.ndarray
    jac_R: np.ndarray; jac_U: np.ndarray; jac_C1: np.ndarray; jac_C2: np.ndarray
    omega_err: float; routes_peak: int
    E0: float; visc_cum: float; strip_cum: float
    pstats: ProjStats; finite: bool; failure_step: int
    u_final: np.ndarray; p_final: np.ndarray
    phase_final: np.ndarray; jac_final: object; wall_time: float
    circ_err: float; orth_err: float; nrm_err: float; collapse_err: float
    g_peak: float

def run_ns(label, name, use_omega, nu, n, steps, dt, amplitude, harmonic,
           thresh_frac, gain, proj_tol=1e-9, diag_every=5, report_every=50):
    print('\n' + '='*79)
    print(name)
    print(f'  grid={n}^3  steps={steps}  dt={dt}  nu={nu}  '
          f'Omega={"ON" if use_omega else "OFF"}  '
          f'thresh_frac={thresh_frac}  gain={gain}')
    print('='*79)
    t0 = time.time()
    axes, dx = make_grid(n)
    vol = dx**3
    u = initial_selector_field(axes, amplitude, harmonic)
    p = np.zeros_like(u)
    pstats = ProjStats()
    V, phi, _, _ = project_bundle(np.stack([u, p]), dx, None, proj_tol,
                                  25, stats=pstats)
    u, p = V[0], V[1]
    jac0 = nth_jacobian(u, dx)
    threshold = thresh_frac * float(np.max(jac0.tension))
    obs0 = observables(u, p, dx)
    mom0 = obs0['mom']
    mom_n0 = max(1.0, float(np.sqrt(np.sum(mom0*mom0))))
    print(f'  initial peak tension = {float(np.max(jac0.tension)):.4f}  ->  '
          f'threshold = {threshold:.4f}')
    print(f'  stability: CFL = {obs0["max_u"]*dt/dx:.3f}   '
          f'diffusion number = {6.0*nu*dt/(dx*dx):.4f} (Euler limit 2.0)')

    keys = ['t', 'E', 'Eu', 'Ep', 'Zu', 'Zp', 'Z', 'max_u', 'max_p', 'max_w',
            'mom_drift', 'div_max', 'phase_routes',
            'jac_R', 'jac_U', 'jac_C1', 'jac_C2']
    hist = {k: [] for k in keys}
    phase = np.full(u.shape[:-1], 'Real', dtype='<U6')
    jac = jac0

    def record(idx):
        obs = observables(u, p, dx)
        jn = nth_jacobian(u, dx)
        hist['t'].append(idx*dt)
        for k in ('E', 'Eu', 'Ep', 'Zu', 'Zp', 'Z', 'max_u', 'max_p', 'max_w'):
            hist[k].append(obs[k])
        hist['mom_drift'].append(
            float(np.sqrt(np.sum((obs['mom']-mom0)**2)))/mom_n0)
        hist['div_max'].append(max(float(np.max(np.abs(div_u(u, dx)))),
                                   float(np.max(np.abs(div_u(p, dx))))))
        hist['phase_routes'].append(int(np.count_nonzero(phase != 'Real')))
        hist['jac_R'].append(float(np.max(np.abs(jn.R))))
        hist['jac_U'].append(float(np.max(jn.U)))
        hist['jac_C1'].append(float(np.max(jn.C1)))
        hist['jac_C2'].append(float(np.max(jn.C2)))

    record(0)
    E_prev = E0 = obs0['E']
    visc_cum = strip_cum = 0.0
    max_omega_err = routes_peak = g_peak = 0.0
    circ_w = orth_w = nrm_w = coll_w = 0.0
    finite, failure_step = True, -1

    for step in range(steps):
        jac = nth_jacobian(u, dx)
        Lu, Lp = lap_vec(u, dx), lap_vec(p, dx)
        ev = float(np.sum(u*Lu + p*Lp))
        au, ap = advect_skew(u, dx), advect_skew(p, dx)
        u_s = u + dt*(-au + nu*Lu)
        p_s = p + dt*(-ap + nu*Lp)

        routes = 0
        if use_omega:
            u_s, p_s, phase, routes, oerr, aud = omega_transfer_nth(
                u_s, p_s, jac, dx, threshold, gain)
            if np.isfinite(oerr):
                max_omega_err = max(max_omega_err, oerr)
            routes_peak = max(routes_peak, routes)
            g_peak = max(g_peak, aud['g_max'])
            circ_w = max(circ_w, aud['circle'])
            orth_w = max(orth_w, aud['orth'])
            nrm_w = max(nrm_w, aud['norm'])
            coll_w = max(coll_w, aud['collapse'])

        V, phi, cycles, resid = project_bundle(
            np.stack([u_s, p_s]), dx, phi, proj_tol, 12, pstats)
        u, p = V[0], V[1]

        if not (np.all(np.isfinite(u)) and np.all(np.isfinite(p))):
            finite, failure_step = False, step
            print(f'  step {step+1}: NON-FINITE selector value -> HALTED, '
                  f'nothing repaired or replaced.')
            break

        E_now = 0.5*float(np.sum(u*u + p*p))*vol
        dE = E_now - E_prev
        vloss = vol*dt*nu*ev
        visc_cum += vloss
        strip_cum += dE - vloss
        E_prev = E_now

        if (step+1) % diag_every == 0 or step == steps-1:
            record(step+1)
        if step % report_every == 0 or step == steps-1:
            obs = observables(u, p, dx)
            print(f'  step {step+1:4d}  t={(step+1)*dt:7.3f}  '
                  f'E={obs["E"]:9.4f}  Zu={obs["Zu"]:9.3f}  '
                  f'Zp={obs["Zp"]:9.3f}  max|u|={obs["max_u"]:7.3f}  '
                  f'max|w|={obs["max_w"]:8.3f}  '
                  f'div={hist["div_max"][-1]:.2e}  routes={routes}')

    wall = time.time() - t0
    arr = lambda k: np.asarray(hist[k], dtype=float)
    res = RunResult(label, name, use_omega, nu, arr('t'), arr('E'),
                    arr('Eu'), arr('Ep'), arr('Zu'), arr('Zp'), arr('Z'),
                    arr('max_u'), arr('max_p'), arr('max_w'),
                    arr('mom_drift'), arr('div_max'), arr('phase_routes'),
                    arr('jac_R'), arr('jac_U'), arr('jac_C1'), arr('jac_C2'),
                    max_omega_err, routes_peak, E0, visc_cum, strip_cum,
                    pstats, finite, failure_step, u, p, phase, jac, wall,
                    circ_w, orth_w, nrm_w, coll_w, g_peak)
    print(f'  -> finite={finite}  Omega_err={max_omega_err:.2e}  '
          f'g_peak={g_peak:.2e}  '
          f'circle={circ_w:.1e}  mirror_orth={orth_w:.1e}  '
          f'mirror_norm={nrm_w:.1e}  collapse={coll_w:.1e}  '
          f'wall={wall:.1f}s')
    return res

