def audit(runs):
    L = '='*79
    print('\n' + L)
    print('AUDIT — finite-grid verification, this implementation only')
    print(L)

    print('[J0] NATIVE SELECTOR CONSTRUCTION — exactness record')
    print('   product canonical tuple ...... (+mn,+mn,-mn,-mn), DUAL arms')
    print('   dual-arm symmetry ............. |real arm| == |unreal arm|,'
          ' all channels')
    print(f'   division-spectrum collapse .... worst = '
          f'{max(r.collapse_err for r in runs):.2e}   [Prop 8 corollary]')
    print(f'   unit-circle closure c^2+s^2=1 . worst = '
          f'{max(r.circ_err for r in runs):.2e}   [Axiom 7.2]')
    print(f'   mirror quarter-phase .......... orth {max(r.orth_err for r in runs):.2e}'
          f'   norm {max(r.nrm_err for r in runs):.2e}   [Ax 9.0/9.3]')
    print(f'   native IC bridge deviation .... {BRIDGE_DEV:.2e} (same IC every run)')

    print('\n[J1] Omega pointwise invariants (u+p, |u|^2+|p|^2, raw transfer):')
    for r in runs:
        if r.use_omega:
            v = 'PASS' if r.omega_err < 1e-12 else 'FAIL'
            print(f'  [{r.label:16s}] err = {r.omega_err:.2e}  -> {v}')
        else:
            print(f'  [{r.label:16s}] Omega disabled')

    print('[J2] Boundedness (no clipping, no NaN repair, no artificial nu):')
    for r in runs:
        gu = float(np.max(r.max_u))/max(float(r.max_u[0]), 1e-30)
        gw = float(np.max(r.max_w))/max(float(r.max_w[0]), 1e-30)
        st = 'finite' if r.finite else f'HALTED step {r.failure_step+1}'
        print(f'  [{r.label:16s}] max|u| x{gu:6.2f}   max|w| x{gw:6.2f}   -> {st}')

    print('[J3] Whole-term residual (NOW = solve residual, same operator):')
    for r in runs:
        print(f'  [{r.label:16s}] final max|div| = {r.div_max[-1]:.2e}   '
              f'cycles/solve = {r.pstats.cycles_total/max(r.pstats.solves,1):.1f}   '
              f'worst resid = {r.pstats.worst_resid:.1e}')
    print('       (v1 showed ~6e-2 here: retained mid/high-k divergence.)')

    print('[J4] Energy ledger:')
    for r in runs:
        print(f'  [{r.label:16s}] dE={r.E[-1]-r.E0:+9.4f}  '
              f'viscous={r.visc_cum:+9.4f}  stripping+O(dt^2)={r.strip_cum:+9.4f}')
    print('       (advection loss = 0 exactly; Omega loss = 0 exactly)')

    print('[J5] Routing comparisons (identical discretization):')
    for nth, cls, desc in ((rB, rC, 'high tension, nu=2e-4'),
                           (rD, rE, 'zero viscosity  , nu=0')):
        pk_n = float(np.max(nth.Zu)); pk_c = float(np.max(cls.Zu))
        fw_n = float(nth.max_w[-1]); fw_c = float(cls.max_w[-1])
        share = float(nth.Zp[-1])/max(float(nth.Z[-1]), 1e-30)
        print(f'  {desc}:')
        print(f'    peak Zu: {pk_n:9.3f} (Omega) vs {pk_c:9.3f} (classical)'
              f'   -> {100*(1-pk_n/pk_c):+.1f}%')
        print(f'    final max|w| ratio (Omega/classical) = '
              f'{fw_n/max(fw_c,1e-30):.3f}')
        print(f'    phase share of final enstrophy = {100*share:.1f}%   '
              f'peak routes = {nth.routes_peak}')

    print('[J6] Zero-viscosity concentration test:')
    for r in (rD, rE):
        gw = float(np.max(r.max_w))/max(float(r.max_w[0]), 1e-30)
        print(f'  [{r.label:16s}] finite={r.finite}   max|w| growth x{gw:.2f}'
              f'   Zu: {r.Zu[0]:.1f} -> {r.Zu[-1]:.1f}')
    gD = float(np.max(rD.max_w))/max(float(rD.max_w[0]), 1e-30)
    gE = float(np.max(rE.max_w))/max(float(rE.max_w[0]), 1e-30)
    if rD.finite and rE.finite:
        if gD < gE:
            print(f'  -> Omega SUPPRESSES concentration at nu=0 '
                  f'(x{gD:.2f} vs x{gE:.2f}) on this horizon.')
        else:
            print('  -> no suppression detected on this horizon; extend '
                  'steps or amplitude before concluding anything.')

    print('\n[J7] TRANFINITE RECORD — deepest approach to the quarter-phase lock')
    for r in runs:
        if r.use_omega and r.g_peak > 0.0:
            t_pk, c_pk, s_pk = angle_selector(r.g_peak)
            print(f'  [{r.label:16s}] peak g = {r.g_peak:.3e}  ->  t = '
                  f'{t_pk:.9f}   (c, s) = ({c_pk:+.6f}, {s_pk:+.6f})   '
                  f'lock deficit 1-t = {1.0-t_pk:.2e}')
        elif r.use_omega:
            print(f'  [{r.label:16s}] transfer never activated')
        else:
            print(f'  [{r.label:16s}] Omega disabled')

    print('\n  MOMENTUM CHECK (was a symptom of the old defect):')
    print(f'   worst momentum drift over all runs = '
          f'{max(float(np.max(r.mom_drift)) for r in runs):.2e}')
    print('   (v1 showed ~8e-4 from retained divergence; with the')
    print('    operator-exact bridge expect <= 1e-9.)')

    print('\n' + L)
    print('COST')
    for r in runs:
        print(f'  [{r.label:16s}] wall = {r.wall_time:6.1f}s   '
              f'{1000*r.wall_time/max(len(r.times)-1,1):6.1f} ms/step')
    print(L)
    print('SCOPE: finite-grid statements about this implementation. The')
    print('compactifier bounds the TRANSFER operator; advection between')
    print('transfers is a separate mechanism (the nu=0 A/B probe). A proof')
    print('would still need the continuum selector space, discrete-to-')
    print('continuum convergence, the Real-channel recovery theorem, an a')
    print('priori gradient bound, and a phase-closure lemma for p.')

audit([rA, rB, rC, rD, rE])

