def plot_transfinite():
    fig = plt.figure(figsize=(15.5, 4.6))
    fig.suptitle('Trans-finite cylinder: infinity as the quarter-phase lock',
                 fontsize=12, fontweight='bold')
    ax1 = fig.add_subplot(1, 3, 1)
    ks = np.arange(0, 19)
    ts = [angle_selector(float(np.power(10.0, k)))[0] for k in ks]
    ax1.plot(ks, ts, 'o-', ms=3)
    ax1.axhline(1.0, color='k', ls='--', lw=1, label='lock t = 1 (trans-finite)')
    ax1.set_xlabel('decade index k   (g = 10^k)')
    ax1.set_ylabel('t = g/(1+g)')
    ax1.set_title('Approach to the infinite horizon\n(2D frame: spiral inward)')
    ax1.legend(); ax1.grid(alpha=0.3)
    ax2 = fig.add_subplot(1, 3, 2, projection='3d')
    t = (0.37*TAU)/(2*128)
    dc = (1.0 - t*t)/(1.0 + t*t); ds = (2.0*t)/(1.0 + t*t)
    c, s = 1.0, 0.0
    cs, ss, zs = [c], [s], [0.0]
    for k in range(1, 129):
        c, s = c*dc - s*ds, s*dc + c*ds
        cs.append(c); ss.append(s); zs.append(k/128)
    ax2.plot(cs, ss, zs, lw=1.5)
    ax2.plot(cs, ss, np.zeros_like(zs), alpha=0.25, lw=0.8)
    ax2.scatter([cs[-1]], [ss[-1]], [zs[-1]], color='r', s=25)
    ax2.set_title('Native walk on the cylinder\n(3D spiral; 2D frame: circle)')
    ax2.set_xlabel('c'); ax2.set_ylabel('s'); ax2.set_zlabel('fusion step')
    ax3 = fig.add_subplot(1, 3, 3)
    gs = np.power(10.0, np.linspace(0.0, 18.0, 200))
    cc, ss2 = [], []
    for g in gs:
        _, c, s = angle_selector(float(g))
        cc.append(c); ss2.append(s)
    ref = np.linspace(0.0, TAU/4, 64)
    rc, rs = nth_trig(ref)
    ax3.plot(rc, rs, 'k--', lw=0.8, alpha=0.5)
    ax3.plot(cc, ss2, lw=2)
    ax3.plot([1.0], [0.0], 'go', label='g = 1 (start)')
    ax3.plot([cc[-1]], [ss2[-1]], 'rs', label='g = 1e18 (lock approach)')
    ax3.set_title('Quarter-phase arc\n(position on the unit selector circle)')
    ax3.set_xlabel('c'); ax3.set_ylabel('s')
    ax3.legend(); ax3.grid(alpha=0.3); ax3.set_aspect('equal')
    plt.tight_layout(); plt.show()

def plot_bridge():
    a = np.linspace(0.0, TAU, 361)
    c, s = nth_trig(a)
    fig, ax = plt.subplots(1, 2, figsize=(11, 3.6))
    ax[0].plot(a, s, lw=2, label='sin_N (native circle walk)')
    ax[0].plot(a, np.sin(a), '--', label='classical magnitude projection')
    ax[0].legend(); ax[0].set_title('Unit selector circle: sin arm')
    ax[0].set_xlabel('angle'); ax[0].grid(alpha=0.3)
    ax[1].plot(a, s - np.sin(a))
    ax[1].set_title('Bridge deviation (walk closure shortfall)')
    ax[1].set_xlabel('angle'); ax[1].grid(alpha=0.3)
    plt.tight_layout(); plt.show()

def plot_run(res):
    if len(res.times) < 2:
        print(f'  (skipping plots for {res.label}: halted early)')
        return
    fig, ax = plt.subplots(3, 3, figsize=(16, 12))
    fig.suptitle(res.name, fontsize=12, fontweight='bold')
    T = res.times
    ax[0, 0].plot(T, res.Eu, label='Real $E_u$')
    ax[0, 0].plot(T, res.Ep, label='Phase $E_p$')
    ax[0, 0].plot(T, res.E, 'k-', lw=2, label='Total')
    ax[0, 0].set_title('Selector energy'); ax[0, 0].legend()
    ax[0, 1].plot(T, res.Zu, label='Real $Z_u$')
    ax[0, 1].plot(T, res.Zp, label='Phase $Z_p$')
    ax[0, 1].set_title('Structural enstrophy'); ax[0, 1].legend()
    ax[0, 2].plot(T, res.max_u, label='max|u|')
    ax[0, 2].plot(T, res.max_p, label='max|p|')
    ax[0, 2].plot(T, res.max_w, label='max|$\\omega$|')
    ax[0, 2].set_title('Concentration monitor'); ax[0, 2].legend()
    ax[1, 0].plot(T, res.jac_R, label='|R| det')
    ax[1, 0].plot(T, res.jac_U, label='|U| mirror')
    ax[1, 0].set_title('Nth Jacobian R, U'); ax[1, 0].legend()
    ax[1, 1].plot(T, res.jac_C1, label='C1 strain')
    ax[1, 1].plot(T, res.jac_C2, label='C2 rotation')
    ax[1, 1].set_title('Nth Jacobian C1, C2'); ax[1, 1].legend()
    ax[1, 2].plot(T, res.div_max)
    ax[1, 2].set_title('Whole-term residual max|div|')
    ax[2, 0].plot(T, res.phase_routes)
    ax[2, 0].set_title('Non-Real phase points (structural labels)')
    ax[2, 1].plot(T, res.mom_drift)
    ax[2, 1].set_title('Selector momentum drift')
    ax[2, 2].plot(T, res.Ep/np.maximum(res.E, 1e-30), label='phase share')
    ax[2, 2].plot(T, res.Eu/np.maximum(res.E, 1e-30), label='real share')
    ax[2, 2].set_title('Energy channel shares'); ax[2, 2].legend()
    for row in ax:
        for a in row:
            a.set_xlabel('time'); a.grid(alpha=0.3)
    plt.tight_layout(); plt.show()

def plot_cmp(a, b, title):
    if len(a.times) < 2 or len(b.times) < 2:
        print('  (skipping comparison: a run halted early)')
        return
    fig, ax = plt.subplots(1, 3, figsize=(15, 4.2))
    fig.suptitle(title, fontsize=12, fontweight='bold')
    ax[0].plot(a.times, a.Zu, label=a.label)
    ax[0].plot(b.times, b.Zu, label=b.label)
    ax[0].set_title('Real enstrophy $Z_u$')
    ax[1].plot(a.times, a.max_w, label=a.label)
    ax[1].plot(b.times, b.max_w, label=b.label)
    ax[1].set_title('max |vorticity| (concentration)')
    ax[2].plot(a.times, a.E, label=a.label)
    ax[2].plot(b.times, b.E, label=b.label)
    ax[2].set_title('Total selector energy')
    for a_ in ax:
        a_.set_xlabel('time'); a_.legend(); a_.grid(alpha=0.3)
    plt.tight_layout(); plt.show()

def plot_jac(res):
    if res.jac_final is None or len(res.times) < 2:
        return
    mid = res.u_final.shape[0]//2
    j = res.jac_final
    fig, ax = plt.subplots(2, 3, figsize=(16, 9))
    fig.suptitle(f'{res.label}: final mid-plane structure', fontsize=12)
    panels = [(np.sqrt(np.sum(res.u_final**2, -1))[mid], '|u| Real'),
              (np.sqrt(np.sum(res.p_final**2, -1))[mid], '|p| phase'),
              (j.R[mid], 'R determinant'),
              (j.U[mid], 'U mirror'),
              (j.C1[mid], 'C1 strain'),
              (j.C2[mid], 'C2 rotation')]
    for a_, (F, ti) in zip(ax.flat, panels):
        im = a_.imshow(F.T, origin='lower', cmap='viridis')
        a_.set_title(ti); fig.colorbar(im, ax=a_, shrink=0.8)
    plt.tight_layout(); plt.show()

print('\nGenerating figures...')
plot_transfinite()
plot_bridge()
plot_run(rA); plot_run(rB); plot_run(rD)
plot_cmp(rB, rC, 'High tension: Omega ON vs OFF (nu=2e-4)')
plot_cmp(rD, rE, 'Zero viscosity: Omega ON vs OFF (nu=0)')
plot_jac(rB); plot_jac(rD)

worst = max(r.omega_err for r in (rA, rB, rD))
assert worst < 1e-12, 'Omega invariant violated — implementation error.'
print('\nAll runs, native constructions, and audits complete.')

