# =============================================================================
# SECTION 1 — SELECTOR ARITHMETIC LAYER (dual-arm, validated)
# =============================================================================
P_REAL, P_UNREAL = '1', 'i'

def phase_mul(p, q):
    return P_REAL if (p == P_REAL and q == P_REAL) else P_UNREAL

def quotient_phase(p, q):
    return P_REAL if p == q else P_UNREAL

def S(mag, phase=P_REAL):
    return (float(mag), float(mag), phase)

def dual_str(s):
    m, mu, ph = s
    arm2 = f'{mu:+.6f}i' if ph == P_UNREAL else f'{mu:+.6f}'
    return f'n_|{m:+.6f}, {arm2}|'

def product_spectrum(m, n):
    return [S(m*n, P_REAL), S(m*n, P_UNREAL),
            S(-m*n, P_REAL), S(-m*n, P_UNREAL)]

def t_spectrum(g):
    num = [(g, P_REAL), (g, P_UNREAL)]
    den = [(1.0+g, P_REAL), (1.0+g, P_REAL),
           (1.0+g, P_UNREAL), (1.0+g, P_UNREAL)]
    return num, den, g / (1.0 + g)

def cs_spectra(t):
    arms = [(t*t, P_REAL), (t*t, P_UNREAL),
            (t*t, P_UNREAL), (t*t, P_UNREAL)]
    leads = [(1.0, P_REAL), (1.0, P_UNREAL)]
    num_c = [(lm - am, lp) for (lm, lp) in leads for (am, ap) in arms]
    den_c = [(lm + am, lp) for (lm, lp) in leads for (am, ap) in arms]
    num_s = [(2.0*t, ph) for (am, ph) in arms]
    return num_c, den_c, num_s

def collapse_check(num, den, ref):
    worst = 0.0
    for (nm, nph) in num:
        for (dm, dph) in den:
            worst = max(worst, abs(nm/dm - ref))
    return worst

def selector_demo(g_sample=0.6):
    L = '=' * 79
    print(L)
    print('SELECTOR ARITHMETIC — NATIVE CONSTRUCTION (dual-arm notation)')
    print(L)
    print('\nstructural product  n_|5,5i| (x) n_|5,5i| :')
    spec = product_spectrum(5.0, 5.0)
    for lbl, s in zip(('R', 'U', 'C1', 'C2'), spec):
        print(f'   {lbl:2s} = {dual_str(s)}')
    print(f'   dual-arm symmetry: {all(s[0] == s[1] for s in spec)} (audited)')
    g = g_sample
    num, den, t_ref = t_spectrum(g)
    print(f'\n--- t-selector (g = {g:.4f}): collapse = {t_ref:.6f}, '
          f'deviation = {collapse_check(num, den, t_ref):.2e}')
    num_c, den_c, num_s = cs_spectra(t_ref)
    c_ref = (1.0 - t_ref*t_ref) / (1.0 + t_ref*t_ref)
    s_ref = (2.0 * t_ref) / (1.0 + t_ref*t_ref)
    print(f'--- c-selector: 64 quotients all = {c_ref:.6f}, dev = '
          f'{collapse_check(num_c, den_c, c_ref):.2e}')
    print(f'--- s-selector: 32 quotients all = {s_ref:.6f}, dev = '
          f'{collapse_check(num_s, den_c, s_ref):.2e}')
    print(f'unit selector circle closure: c^2+s^2-1 = '
          f'{abs(c_ref*c_ref + s_ref*s_ref - 1.0):.2e}')
    print(L)

selector_demo(0.6)

# =============================================================================
# SECTION 2 — Cyclic grid and fusion stencils (validated)
# =============================================================================
def make_grid(n, length=2.0*np.pi):
    assert n >= 4 and (n & (n - 1)) == 0, 'grid must be a power of two'
    x = np.linspace(0.0, length, n, endpoint=False)
    axes = np.meshgrid(x, x, x, indexing='ij')
    return axes, length / n

def dd(f, axis, dx):
    """Centered periodic difference; exact telescoping over the torus."""
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis)) * (0.5/dx)

def grad_vec(u, dx):
    gu = np.empty(u.shape + (3,))
    for i in range(3):
        for j in range(3):
            gu[..., i, j] = dd(u[..., i], j, dx)
    return gu

def curl(u, dx):
    g = grad_vec(u, dx)
    w = np.empty_like(u)
    w[..., 0] = g[..., 2, 1] - g[..., 1, 2]
    w[..., 1] = g[..., 0, 2] - g[..., 2, 0]
    w[..., 2] = g[..., 1, 0] - g[..., 0, 1]
    return w

def div_u(u, dx):
    return (dd(u[..., 0], 0, dx) + dd(u[..., 1], 1, dx)
            + dd(u[..., 2], 2, dx))

def lap_vec(u, dx):
    out = np.empty_like(u)
    inv = 1.0 / (dx*dx)
    for i in range(3):
        f = u[..., i]
        out[..., i] = (-6.0*f + np.roll(f, -1, 0) + np.roll(f, 1, 0)
                       + np.roll(f, -1, 1) + np.roll(f, 1, 1)
                       + np.roll(f, -1, 2) + np.roll(f, 1, 2)) * inv
    return out

def advect_skew(u, dx):
    """Fused structural product (Prop 7). sum(u.adv) = 0 exactly."""
    out = np.zeros_like(u)
    for i in range(3):
        for j in range(3):
            fi, fj = u[..., i], u[..., j]
            out[..., i] += 0.5 * (dd(fj*fi, j, dx) + fj*dd(fi, j, dx))
    return out

# =============================================================================
# SECTION 3 — Nth Jacobian (validated)
# =============================================================================
@dataclass
class JacobianChannels:
    R: np.ndarray; U: np.ndarray; C1: np.ndarray; C2: np.ndarray
    vort: np.ndarray; tension: np.ndarray

def nth_jacobian(u, dx):
    G = grad_vec(u, dx)
    S_ = 0.5 * (G + np.swapaxes(G, -1, -2))
    A_ = 0.5 * (G - np.swapaxes(G, -1, -2))
    C1 = np.sqrt(np.sum(S_*S_, axis=(-2, -1)))
    C2 = np.sqrt(np.sum(A_*A_, axis=(-2, -1)))
    a, b, c = G[..., 0, 0], G[..., 0, 1], G[..., 0, 2]
    d, e, f = G[..., 1, 0], G[..., 1, 1], G[..., 1, 2]
    g, h, i = G[..., 2, 0], G[..., 2, 1], G[..., 2, 2]
    R = a*(e*i - f*h) - b*(d*i - f*g) + c*(d*h - e*g)
    U = np.sqrt(np.sum(G*G, axis=(-2, -1))) - np.abs(R)
    vort = np.stack([G[..., 2, 1] - G[..., 1, 2],
                     G[..., 0, 2] - G[..., 2, 0],
                     G[..., 1, 0] - G[..., 0, 1]], axis=-1)
    return JacobianChannels(R, U, C1, C2, vort, C1 + C2 + np.abs(R))

# =============================================================================
# SECTION 4 — Native trigonometry and initial field (validated)
# =============================================================================
def nth_trig(angle, n_steps=128):
    a = np.mod(angle, TAU)
    t = a / (2.0 * n_steps)
    dc = (1.0 - t*t) / (1.0 + t*t)
    ds = (2.0 * t) / (1.0 + t*t)
    c = np.ones_like(a)
    s = np.zeros_like(a)
    for _ in range(n_steps):
        c, s = c*dc - s*ds, s*dc + c*ds
    return c, s

def initial_selector_field(axes, amplitude, harmonic):
    x, y, z = axes
    def mode(k):
        cx, sx = nth_trig(k*x)
        cy, sy = nth_trig(k*y)
        cz, sz = nth_trig(k*z)
        return np.stack([sx*cy*cz, -(cx*sy*cz), np.zeros_like(x)], axis=-1)
    return amplitude * (mode(1.0) + harmonic * mode(2.0))

# =============================================================================
# SECTION 5 — Omega selector (validated native assembly)
# =============================================================================
def angle_selector(g):
    """Trans-finite compactifier: g in [0,inf) -> t in [0,1) -> angle in
    [0, pi/2). Collapsed magnitude arms of the division spectra."""
    t = g / (1.0 + g)
    c = (1.0 - t*t) / (1.0 + t*t)
    s = (2.0 * t) / (1.0 + t*t)
    return t, c, s

def unreal_mirror(axis):
    a1, a2, a3 = (axis[..., 0], axis[..., 1], axis[..., 2])
    M = np.zeros(axis.shape[:-1] + (3, 3))
    M[..., 0, 1] = -a3; M[..., 0, 2] =  a2
    M[..., 1, 0] =  a3; M[..., 1, 2] = -a1
    M[..., 2, 0] = -a2; M[..., 2, 1] =  a1
    return M

def partner(M, d):
    return np.einsum('...ij,...j->...i', M, d)

def sample_collapse_audit(g_field, n=16):
    flat = g_field.ravel()
    flat = flat[flat > 0.0]
    if flat.size == 0:
        return 0.0
    idx = rng.choice(flat.size, size=min(n, flat.size), replace=False)
    worst = 0.0
    for g in flat[idx]:
        num, den, t_ref = t_spectrum(float(g))
        worst = max(worst, collapse_check(num, den, t_ref))
        num_c, den_c, num_s = cs_spectra(t_ref)
        c_ref = (1.0 - t_ref*t_ref)/(1.0 + t_ref*t_ref)
        s_ref = 2.0*t_ref/(1.0 + t_ref*t_ref)
        worst = max(worst, collapse_check(num_c, den_c, c_ref),
                    collapse_check(num_s, den_c, s_ref))
    return worst

def omega_transfer_nth(u, p, jac, dx, threshold, gain):
    """Omega-selector, fully native: m = u (+) p, d = u (-) p, angle from
    the division spectrum, quarter-phase partner from the unreal mirror,
    unit-circle fusion on the transverse arm. Pointwise invariants
    u+p and |u|^2+|p|^2 hold by construction (audited)."""
    excess = np.maximum(jac.tension - threshold, 0.0)
    active = excess > 0.0
    g = gain * excess * dx
    t, c, s = angle_selector(g)
    m = u + p
    d = 0.5 * (u - p)
    rot_dom = jac.C2 > jac.C1
    wn = np.sqrt(np.sum(jac.vort*jac.vort, axis=-1))
    gs = np.stack([dd(jac.C1, a, dx) for a in (0, 1, 2)], axis=-1)
    gn = np.sqrt(np.sum(gs*gs, axis=-1))
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    axis = np.zeros_like(u)
    if use_v.any():
        axis[use_v] = (jac.vort / np.maximum(wn, 1e-30)[..., None])[use_v]
    if use_g.any():
        axis[use_g] = (gs / np.maximum(gn, 1e-30)[..., None])[use_g]
    M = unreal_mirror(axis)
    Pd = partner(M, d)
    d_ax = d + partner(M, Pd)          # d + P(P(d)) = axial projection
    d_tr = d - d_ax
    Ptr = partner(M, d_tr)
    d_new = d_ax + c[..., None]*d_tr + s[..., None]*Ptr
    u_new = 0.5*m + d_new
    p_new = 0.5*m - d_new
    rdom = np.abs(jac.R) > np.maximum(jac.C1, jac.C2)
    phase = np.full(excess.shape, 'Real', dtype='<U6')
    phase[active & rdom] = 'C2'
    phase[active & ~rdom & rot_dom] = 'Unreal'
    phase[active & ~rdom & ~rot_dom] = 'C1'
    routes = int(np.count_nonzero(active))
    aud = {'circle': float(np.max(np.abs(c*c + s*s - 1.0))),
           'g_max': float(np.max(g))}
    if active.any():
        scale = float(np.max(np.sum(d_tr*d_tr, -1) + np.sum(Ptr*Ptr, -1)))
        aud['orth'] = float(np.max(np.abs(np.sum(d_tr*Ptr, -1)))) / max(scale, 1e-300)
        aud['norm'] = float(np.max(np.abs(np.sum(Ptr*Ptr, -1)
                                          - np.sum(d_tr*d_tr, -1)))) / max(scale, 1e-300)
        aud['collapse'] = sample_collapse_audit(g)
    else:
        aud['orth'] = aud['norm'] = aud['collapse'] = 0.0
    err_m = float(np.max(np.abs((u_new + p_new) - (u + p))))
    e0 = float(np.sum(u*u + p*p))
    e1 = float(np.sum(u_new*u_new + p_new*p_new))
    err_e = abs(e1 - e0) / max(abs(e0), 1e-300)
    return u_new, p_new, phase, routes, max(err_m, err_e), aud

# =============================================================================
# SECTION 6 — WHOLE-TERM CASCADE with EXPLICIT ENFORCEMENT TARGET
# =============================================================================
def restrict(F):
    a, b, c = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (a//2, 2, b//2, 2, c//2, 2)
                     ).mean(axis=(-5, -3, -1))

def _interp1(F, axis):
    n = F.shape[axis]
    shp = list(F.shape); shp[axis] = 2*n
    G = np.empty(shp, dtype=F.dtype)
    se = [slice(None)]*F.ndim; se[axis] = slice(0, 2*n, 2)
    G[tuple(se)] = F
    so = [slice(None)]*F.ndim; so[axis] = slice(1, 2*n, 2)
    G[tuple(so)] = 0.5 * (F + np.roll(F, -1, axis=axis))
    return G

def prolong(C):
    F = _interp1(C, C.ndim - 3)
    F = _interp1(F, F.ndim - 2)
    F = _interp1(F, F.ndim - 1)
    return F

def lap_apply(F, dx):
    """Compact 7-point Laplacian, spatial axes = LAST THREE (negative
    indexing). Negative semi-definite; null space = constants."""
    inv = 1.0 / (dx*dx)
    s = -6.0 * F
    for a in (F.ndim - 3, F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s * inv

_RBGS_CACHE = {}
def _rb_mask(m):
    if m not in _RBGS_CACHE:
        idx = np.indices((m, m, m))
        red = ((idx[0] + idx[1] + idx[2]) % 2 == 0)
        _RBGS_CACHE[m] = (red, ~red)
    return _RBGS_CACHE[m]

def smooth_gs(phi, f, dx, iters):
    """RBGS for L phi = f (L negative semi-definite, diagonal -6/dx^2).
    v5 sign convention: phi <- phi - (dx^2/6)(f - L phi) per color."""
    c = dx * dx / 6.0
    red, black = _rb_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - lap_apply(phi, dx)
        phi = phi - c * np.where(red, r, 0.0)
        r = f - lap_apply(phi, dx)
        phi = phi - c * np.where(black, r, 0.0)
    return phi

def v_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - f.mean(axis=(-3, -2, -1), keepdims=True)
        return smooth_gs(phi, f, dx, 40)
    phi = smooth_gs(phi, f, dx, 2)
    r = f - lap_apply(phi, dx)
    rc = restrict(r)
    ec = v_cycle(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + prolong(ec)
    return smooth_gs(phi, f, dx, 2)

def split_classes(f):
    """GATHER: decimate into the 8 mod-2 parity classes (Axiom 0 closure
    structure). Pure indexing — exact. Spatial axes = last three."""
    N = f.shape[-1]
    M = N // 2
    out = np.empty(f.shape[:-3] + (8, M, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                out[..., c, :, :, :] = f[..., a::2, b::2, d::2]
                c += 1
    return out

def merge_classes(g, N):
    """DISPERSE: interleave the 8 class bundles back onto the full grid."""
    f = np.empty(g.shape[:-4] + (N, N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                f[..., a::2, b::2, d::2] = g[..., c, :, :, :]
                c += 1
    return f

def div_bundle(V, dx):
    """Divergence of a bundle with vector components on the LAST axis.
    Spatial axes are the LAST THREE of each scalar slice, so this works
    for (N,N,N,3), (1,N,N,N,3), (2,N,N,N,3) alike. [v9.2 fix: negative
    indexing; v9.1 call sites had lost the dx argument.]"""
    out = np.zeros(V.shape[:-1])
    for j in range(3):
        out += dd(V[..., j], V.ndim - 4 + j, dx)
    return out

def grad_bundle(phi, dx):
    """Gradient of scalar field(s) whose spatial axes are the LAST THREE.
    Works for (N,N,N) or any (..., N,N,N); returns (..., N,N,N,3).
    [v9.2 fix: negative indexing — the v8 call sites pass 3-dim
    per-channel potentials, where absolute axis 3 was out of bounds.]"""
    return np.stack([dd(phi, phi.ndim - 3 + j, dx) for j in range(3)],
                    axis=-1)

@dataclass
class ProjStats:
    solves: int = 0; cycles_total: int = 0; cycles_max: int = 0
    worst_resid: float = 0.0

def project_bundle(V, dx, mode='channels', phi=None, tol=1e-9,
                   max_cycles=20, stats=None):
    """Whole-Term projection with explicit ENFORCEMENT TARGET.

    mode='channels': div u = 0 and div p = 0 separately. Pays
      |grad phi_u|^2 + |grad phi_p|^2 against every transfer event.
    mode='fused': enforce div m = 0 on the BUNDLE momentum m = u+p
      [Axiom 3.3: the total structural bundle]. Solve L phi = -div m,
      add grad(phi)/2 to BOTH channels: d is preserved EXACTLY, and
      since the Omega transfer preserves m pointwise, div m is
      transfer-invariant — after a transfer there is almost nothing to
      pay. Classical limit: p == 0 reduces this to the classical
      projection.
    Returns (Vp, gu, gp, phi, cycles, worst) — gu/gp are the APPLIED
    corrections; the exact ledger consumes them directly."""
    if mode == 'fused':
        Mb = (V[0] + V[1])[None, ...]          # (1,N,N,N,3)
        f = -div_bundle(Mb, dx)                # (1,N,N,N)
    else:
        f = -div_bundle(V, dx)                 # (2,N,N,N)
    fc = split_classes(f)
    H = 2.0 * dx
    fc = fc - fc.mean(axis=(-3, -2, -1), keepdims=True)
    f0 = np.sqrt(np.sum(fc*fc, axis=(-3, -2, -1)))
    live = f0 > 1e-300
    live5 = live[..., None, None, None]
    fc = fc * live5
    if phi is None:
        psic = np.zeros_like(fc)
    else:
        psic = split_classes(phi) * live5
    psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
    cycles, worst = 0, 0.0
    if live.any():
        def rel_resid():
            r = fc - lap_apply(psic, H)
            rn = np.sqrt(np.sum(r*r, axis=(-3, -2, -1)))
            rel = rn / np.maximum(f0, 1e-300)
            return float(np.max(rel[live]))
        worst = rel_resid()
        while worst >= tol and cycles < max_cycles:
            psic = v_cycle(psic, fc, H)
            psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
            cycles += 1
            worst = rel_resid()
    phi_out = merge_classes(psic, V.shape[-3])
    if mode == 'fused':
        g = grad_bundle(phi_out[0], dx)
        gu = 0.5 * g; gp = 0.5 * g
    else:
        gu = grad_bundle(phi_out[0], dx)
        gp = grad_bundle(phi_out[1], dx)
    Vp = np.stack([V[0] + gu, V[1] + gp])
    if stats is not None and live.any():
        stats.solves += 1
        stats.cycles_total += cycles
        stats.cycles_max = max(stats.cycles_max, cycles)
        stats.worst_resid = max(stats.worst_resid, worst)
    return Vp, gu, gp, phi_out, cycles, worst

def validate_solver(m=16, seed=3):
    """GATE 1 — exact recovery: construct f = L(phi_true) for a random
    smooth mean-zero phi_true and require the same v_cycle to recover
    it. Categorical against wrong sign / operator / spacing."""
    H = 0.4
    g = np.random.default_rng(seed)
    phi_true = g.standard_normal((m, m, m))
    for _ in range(6):
        for a in (0, 1, 2):
            phi_true = 0.5*phi_true + 0.25*(np.roll(phi_true, -1, axis=a)
                                            + np.roll(phi_true, 1, axis=a))
    phi_true -= phi_true.mean()
    f = lap_apply(phi_true, H)
    phi = np.zeros_like(f)
    for _ in range(30):
        phi = v_cycle(phi, f, H)
        phi -= phi.mean()
        res = float(np.max(np.abs(f - lap_apply(phi, H))))
        if res < 1e-11 * max(1.0, float(np.max(np.abs(f)))):
            break
    err = float(np.max(np.abs(phi - phi_true)))
    scale = max(1.0, float(np.max(np.abs(phi_true))))
    ok = np.isfinite(err) and err < 1e-6 * scale
    print(f'  exact recovery: |phi-phi_true|/scale = {err/scale:.2e} '
          f'(tol 1e-6)  -> {"PASS" if ok else "FAIL"}')
    assert ok, 'SOLVER UNIT TEST FAILED.'

def validate_projection(n=32, seed=7):
    """GATE 2 — both enforcement targets on a random smooth bundle:
    (a) solve termination, (b) actual divergence elimination,
    (c) non-expansiveness, (e) fused mode: bundle constraint + EXACT
    deviation preservation (the load-bearing check)."""
    axes, dx = make_grid(n)
    g = np.random.default_rng(seed)
    V = g.standard_normal((2, n, n, n, 3))
    for _ in range(6):
        for a in (1, 2, 3):
            V = 0.5*V + 0.25*(np.roll(V, -1, axis=a) + np.roll(V, 1, axis=a))
    E0 = float(np.sum(V*V))
    wt0 = float(np.max(np.abs(div_u(V[0]+V[1], dx))))
    Vp, _, _, _, cycles, resid = project_bundle(V, dx, 'channels',
                                                None, 1e-10, 25)
    d1 = float(np.max(np.abs(div_bundle(Vp, dx))))
    ok_a = np.isfinite(resid) and resid < 1e-8
    ok_b = np.isfinite(d1) and d1 <= max(1e-9, 1e-6*float(np.max(np.abs(div_bundle(V, dx)))))
    ok_c = float(np.sum(Vp*Vp)) <= E0*(1.0 + 1e-6)
    print(f'  channels mode ({cycles} cycles):')
    print(f'  (a) residual {resid:.2e} -> {"PASS" if ok_a else "FAIL"}   '
          f'(b) div -> {d1:.2e} {"PASS" if ok_b else "FAIL"}   '
          f'(c) energy {float(np.sum(Vp*Vp))/E0:.6f} <= 1 '
          f'{"PASS" if ok_c else "FAIL"}')
    Vf, _, _, _, cycles_f, resid_f = project_bundle(V, dx, 'fused',
                                                    None, 1e-10, 25)
    wt1 = float(np.max(np.abs(div_u(Vf[0]+Vf[1], dx))))
    d_before = 0.5*(V[0]-V[1]); d_after = 0.5*(Vf[0]-Vf[1])
    dpres = float(np.max(np.abs(d_after - d_before)))
    Ef = float(np.sum(Vf*Vf))
    ok_e = (np.isfinite(wt1) and wt1 <= max(1e-9, 1e-6*wt0)
            and dpres < 1e-12 and Ef <= E0*(1.0 + 1e-6))
    print(f'  (e) fused mode ({cycles_f} cycles): div(u+p) {wt0:.2e} -> '
          f'{wt1:.2e}   |d\'-d| = {dpres:.2e}   energy {Ef/E0:.6f} <= 1  '
          f'-> {"PASS" if ok_e else "FAIL"}')
    assert ok_a and ok_b and ok_c and ok_e, \
        'BRIDGE VALIDATION FAILED — aborting before any run.'
    print('  bridge validated: solver exact, both enforcement targets valid.')

print('\n' + '='*79)
print('BRIDGE GATES — solver unit test + both projection modes')
print('='*79)
validate_solver(16)
validate_projection(32)

# =============================================================================
# SECTION 7 — Observables, tethering, closed-system driver
# =============================================================================
def observables(u, p, dx):
    vol = dx**3
    wu, wp = curl(u, dx), curl(p, dx)
    return {'Eu': 0.5*float(np.sum(u*u))*vol,
            'Ep': 0.5*float(np.sum(p*p))*vol,
            'E':  0.5*float(np.sum(u*u + p*p))*vol,
            'Zu': 0.5*float(np.sum(wu*wu))*vol,
            'Zp': 0.5*float(np.sum(wp*wp))*vol,
            'Z':  0.5*float(np.sum(wu*wu + wp*wp))*vol,
            'max_u': float(np.sqrt(np.max(np.sum(u*u, axis=-1)))),
            'max_p': float(np.sqrt(np.max(np.sum(p*p, axis=-1)))),
            'max_w': float(np.sqrt(np.max(np.sum(wu*wu, axis=-1)))),
            'mom': np.sum(u + p, axis=(0, 1, 2))*vol}

def angular_impulse(u, p, axes, dx):
    """Angular impulse of the bundle, L = sum(x x omega_m) dV.
    DIAGNOSTIC ONLY: coordinate-branch dependent on a periodic torus
    (flagged since the first notebook). Classically the vortex-tethering
    invariant (why vortex rings keep their impulse)."""
    x, y, z = axes
    w = curl(u + p, dx)
    vol = dx**3
    return np.array([
        float(np.sum(y*w[..., 2] - z*w[..., 1]))*vol,
        float(np.sum(z*w[..., 0] - x*w[..., 2]))*vol,
        float(np.sum(x*w[..., 1] - y*w[..., 0]))*vol])

def great_circle_circulations(u, p, dx):
    """Circulation of bundle momentum m = u+p around three orthogonal
    fixed rectangles through the domain center. Kelvin's theorem holds
    for MATERIAL loops; these fixed loops measure vortex tubes passing
    through them. Eulerian diagnostic — no theorem claimed."""
    n = u.shape[0]
    m = u + p
    lo, hi, c = n//4, 3*n//4, n//2
    Gx = dx*(np.sum(m[c, lo:hi+1, lo, 1]) + np.sum(m[c, hi, lo:hi+1, 2])
             - np.sum(m[c, lo:hi+1, hi, 1]) - np.sum(m[c, lo, lo:hi+1, 2]))
    Gy = dx*(np.sum(m[lo:hi+1, c, lo, 0]) + np.sum(m[hi, c, lo:hi+1, 2])
             - np.sum(m[lo:hi+1, c, hi, 0]) - np.sum(m[lo, c, lo:hi+1, 2]))
    Gz = dx*(np.sum(m[lo:hi+1, lo, c, 0]) + np.sum(m[hi, lo:hi+1, c, 1])
             - np.sum(m[lo:hi+1, hi, c, 0]) - np.sum(m[lo, lo:hi+1, c, 1]))
    return np.array([Gx, Gy, Gz])

def compression_meter(u_s, p_s, dx, tol=0.05):
    """Fraction of the domain where pre-enforcement bundle divergence
    exceeds tol — the direct meter of 'spatial occupation resistance'
    events (convergent flow the Whole-Term Principle must refuse)."""
    d = np.abs(div_u(u_s + p_s, dx))
    return float(np.count_nonzero(d > tol)) / d.size, float(np.max(d))

@dataclass
class RunResult:
    label: str; name: str; use_omega: bool; nu: float; mode: str
    times: np.ndarray; E: np.ndarray; Eu: np.ndarray; Ep: np.ndarray
    Zu: np.ndarray; Zp: np.ndarray; Z: np.ndarray
    max_u: np.ndarray; max_p: np.ndarray; max_w: np.ndarray
    mom_drift: np.ndarray; div_wt: np.ndarray; div_sh: np.ndarray
    phase_routes: np.ndarray
    omega_err: float; routes_peak: int
    E0: float; visc_cum: float; euler2_cum: float; proj_cum: float
    closure_max: float
    pstats: ProjStats; finite: bool; failure_step: int
    u_final: np.ndarray; p_final: np.ndarray
    phase_final: np.ndarray; jac_final: object; wall_time: float
    g_peak: float
    R: np.ndarray; Et: np.ndarray
    L: np.ndarray; G: np.ndarray
    comp_frac: np.ndarray; comp_peak: float
    cons_err: float; drag_route_corr: float

def run_ns(label, name, use_omega, nu, mode, n, steps, dt, amplitude,
           harmonic, thresh_frac, gain, proj_tol=1e-9, diag_every=5,
           report_every=50):
    print('\n' + '='*79)
    print(name)
    print(f'  grid={n}^3  steps={steps}  dt={dt}  nu={nu}  '
          f'Omega={"ON" if use_omega else "OFF"}  mode={mode}  '
          f'thresh_frac={thresh_frac}  gain={gain}')
    print('='*79)
    t0 = time.time()
    axes, dx = make_grid(n)
    vol = dx**3
    u = initial_selector_field(axes, amplitude, harmonic)
    p = np.zeros_like(u)
    pstats = ProjStats()
    # Initial projection in CHANNELS mode: p == 0, so this is the
    # classical projection — the IC is IDENTICAL for every run.
    V, _, _, _, _, _ = project_bundle(np.stack([u, p]), dx, 'channels',
                                      None, proj_tol, 25, pstats)
    u, p = V[0], V[1]
    phi = None
    jac0 = nth_jacobian(u, dx)
    threshold = thresh_frac * float(np.max(jac0.tension))
    obs0 = observables(u, p, dx)
    mom0 = obs0['mom']
    mom_n0 = max(1.0, float(np.sqrt(np.sum(mom0*mom0))))
    print(f'  initial peak tension = {float(np.max(jac0.tension)):.4f}  '
          f'->  threshold = {threshold:.4f}')
    print(f'  stability: CFL = {obs0["max_u"]*dt/dx:.3f}   '
          f'diffusion number = {6.0*nu*dt/(dx*dx):.4f}')

    keys = ['t', 'E', 'Eu', 'Ep', 'Zu', 'Zp', 'Z', 'max_u', 'max_p',
            'max_w', 'mom_drift', 'div_wt', 'div_sh', 'phase_routes',
            'R', 'Et', 'comp']
    hist = {k: [] for k in keys}
    Ls, Gs = [], []
    phase = np.full(u.shape[:-1], 'Real', dtype='<U6')
    jac = jac0
    R = 0.0
    comp_state = {'frac': 0.0, 'peak': 0.0}

    def record(idx):
        obs = observables(u, p, dx)
        hist['t'].append(idx*dt)
        for k in ('E', 'Eu', 'Ep', 'Zu', 'Zp', 'Z', 'max_u', 'max_p', 'max_w'):
            hist[k].append(obs[k])
        hist['mom_drift'].append(
            float(np.sqrt(np.sum((obs['mom']-mom0)**2)))/mom_n0)
        hist['div_wt'].append(float(np.max(np.abs(div_u(u + p, dx)))))
        hist['div_sh'].append(float(np.max(np.abs(div_u(u, dx)))))
        hist['phase_routes'].append(int(np.count_nonzero(phase != 'Real')))
        hist['R'].append(R)
        hist['Et'].append(obs['E'] + R)
        hist['comp'].append(comp_state['frac'])
        Ls.append(angular_impulse(u, p, axes, dx))
        Gs.append(great_circle_circulations(u, p, dx))

    record(0)
    E_prev = E0 = obs0['E']
    visc_cum = euler2_cum = proj_cum = 0.0
    closure_max = 0.0
    max_omega_err = routes_peak = g_peak = 0.0
    finite, failure_step = True, -1

    for step in range(steps):
        jac = nth_jacobian(u, dx)
        Lu, Lp = lap_vec(u, dx), lap_vec(p, dx)
        ev = float(np.sum(u*Lu + p*Lp))            # exact viscous input
        au, ap = advect_skew(u, dx), advect_skew(p, dx)
        F_u = -au + nu*Lu
        F_p = -ap + nu*Lp
        euler2 = 0.5*vol*dt*dt*float(np.sum(F_u*F_u + F_p*F_p))
        visc = vol*dt*nu*ev
        u_s = u + dt*F_u
        p_s = p + dt*F_p

        routes = 0
        if use_omega:
            u_s, p_s, phase, routes, oerr, aud = omega_transfer_nth(
                u_s, p_s, jac, dx, threshold, gain)
            if np.isfinite(oerr):
                max_omega_err = max(max_omega_err, oerr)
            routes_peak = max(routes_peak, routes)
            g_peak = max(g_peak, aud['g_max'])

        # occupation-resistance meter: pre-enforcement bundle divergence
        cf, cp = compression_meter(u_s, p_s, dx)
        comp_state['frac'] = cf
        comp_state['peak'] = max(comp_state['peak'], cp)

        Vp, gu, gp, phi, cycles, resid = project_bundle(
            np.stack([u_s, p_s]), dx, mode, phi, proj_tol, 20, pstats)
        # exact projection work, from the APPLIED corrections
        dE_proj = 0.5*vol*float(np.sum(2*u_s*gu + gu*gu + 2*p_s*gp + gp*gp))
        u, p = Vp[0], Vp[1]
        R -= dE_proj      # the reservoir STORES what enforcement removes

        if not (np.all(np.isfinite(u)) and np.all(np.isfinite(p))):
            finite, failure_step = False, step
            print(f'  step {step+1}: NON-FINITE -> HALTED, nothing repaired.')
            break

        E_now = 0.5*float(np.sum(u*u + p*p))*vol
        dE = E_now - E_prev
        closure = dE - visc - euler2 - dE_proj   # transfer drift + roundoff
        closure_max = max(closure_max, abs(closure))
        visc_cum += visc; euler2_cum += euler2; proj_cum += dE_proj
        E_prev = E_now

        if (step+1) % diag_every == 0 or step == steps-1:
            record(step+1)
        if step % report_every == 0 or step == steps-1:
            obs = observables(u, p, dx)
            print(f'  step {step+1:4d}  t={(step+1)*dt:7.3f}  '
                  f'E={obs["E"]:9.4f}  R={R:9.4f}  E+R={obs["E"]+R:9.4f}  '
                  f'Zu={obs["Zu"]:9.3f}  max|w|={obs["max_w"]:7.3f}  '
                  f'comp={comp_state["frac"]:.3f}  routes={routes}')

    wall = time.time() - t0
    Et = np.asarray(hist['Et'], dtype=float)
    cons_err = abs((Et[-1] - Et[0]) - visc_cum - euler2_cum)
    Rser = np.asarray(hist['R'], dtype=float)
    Rt = np.asarray(hist['phase_routes'], dtype=float)
    dR = np.diff(Rser)
    if dR.size > 2 and np.std(dR) > 1e-12 and np.std(Rt[:-1]) > 1e-12:
        drag_corr = float(np.corrcoef(dR, Rt[:-1])[0, 1])
    else:
        drag_corr = float('nan')

    arr = lambda k: np.asarray(hist[k], dtype=float)
    res = RunResult(label, name, use_omega, nu, mode, arr('t'), arr('E'),
                    arr('Eu'), arr('Ep'), arr('Zu'), arr('Zp'), arr('Z'),
                    arr('max_u'), arr('max_p'), arr('max_w'),
                    arr('mom_drift'), arr('div_wt'), arr('div_sh'),
                    arr('phase_routes'), max_omega_err, routes_peak, E0,
                    visc_cum, euler2_cum, proj_cum, closure_max, pstats,
                    finite, failure_step, u, p, phase, jac, wall, g_peak,
                    Rser, Et, np.asarray(Ls), np.asarray(Gs),
                    arr('comp'), comp_state['peak'], cons_err, drag_corr)
    print(f'  -> finite={finite}  Omega_err={max_omega_err:.2e}  '
          f'R_final={R:.4f} ({100.0*R/max(E0,1e-30):.1f}% of E0)  '
          f'cons_err={cons_err:.2e}  closure_max={closure_max:.2e}  '
          f'drag-route corr={drag_corr:+.3f}  wall={wall:.1f}s')
    return res

