# SECTION 9 — AUDIT
# =============================================================================
def audit(rE, rDch, rDfu):
    L = '='*79
    print('\n' + L)
    print('AUDIT — finite-grid verification, this implementation only')
    print(L)

    print('[J1] Omega pointwise invariants (raw transfer):')
    for r in (rDch, rDfu):
        v = 'PASS' if r.omega_err < 1e-12 else 'FAIL'
        print(f'  [{r.label:16s}] err = {r.omega_err:.2e}  -> {v}')
    assert np.all(rE.p_final == 0.0), \
        'classical run developed a phase channel — implementation error.'

    print('\n[J2] Boundedness (no clipping, no NaN repair, no artificial nu):')
    for r in (rE, rDch, rDfu):
        gw = float(np.max(r.max_w))/max(float(r.max_w[0]), 1e-30)
        st = 'finite' if r.finite else f'HALTED step {r.failure_step+1}'
        print(f'  [{r.label:16s}] max|w| growth x{gw:.2f}  -> {st}')

    print('\n[J3] Whole-term residual div(u+p) and Real-channel shadow div(u):')
    for r in (rE, rDch, rDfu):
        print(f'  [{r.label:16s}] div(u+p) = {r.div_wt[-1]:.2e}   '
              f'div(u) = {r.div_sh[-1]:.2e}   '
              f'({"shadow absorbed by p" if r.mode == "fused" and r.div_sh[-1] > 1e-6 else "both clean"})')

    print('\n[J4] EXACT LEDGER, CLOSED-SYSTEM (kinetic + reservoir):')
    print(f'  {"run":18s} {"dE_kin":>9s} {"visc":>7s} {"euler dt2":>10s} '
          f'{"proj->R":>9s} {"R fin":>8s} {"E+R fin":>9s} {"cons err":>9s}')
    for r in (rE, rDch, rDfu):
        print(f'  [{r.label:16s}] {r.E[-1]-r.E0:+9.3f} {r.visc_cum:+7.3f} '
              f'{r.euler2_cum:+10.3f} {r.proj_cum:+9.3f} '
              f'{r.R[-1]:8.3f} {r.Et[-1]:9.3f} {r.cons_err:9.2e}')
    print('  cons err = |d(E+R) - visc - euler_dt2| : must be ~roundoff.')
    print('  (The classical run\'s small +dE is forward-Euler dt^2 injection,')
    print('   a known scheme artifact; a Cayley-exact time update — the')
    print('   same rational structure as the t/c/s selectors — removes it.)')

    print('\n[J9] THE DRAG METER — occupation resistance as consequence of')
    print('     vortex routing (the user\'s physical reading, quantified):')
    for r in (rDch, rDfu):
        print(f'  [{r.label:16s}] peak comp-event fraction = '
              f'{float(np.max(r.comp_frac)):.3f}   '
              f'reservoir R = {r.R[-1]:8.3f} '
              f'({100.0*r.R[-1]/max(r.E0,1e-30):5.1f}% of E0)   '
              f'dR-routes correlation = {r.drag_route_corr:+.3f}')
    if np.isfinite(rDch.drag_route_corr) and rDch.drag_route_corr > 0.5:
        print('  -> reservoir growth tracks Omega routing activity: the')
        print('     "drag" is generated BY the vortex-routing events, as')
        print('     read. In fused mode the bundle does not compress at a')
        print('     transfer (div m is transfer-invariant), so the same')
        print('     events cost ~nothing — the drag was the price of')
        print('     enforcing non-physical per-channel constraints.')

    print('\n[J9b] TETHERING — Kelvin shadows at nu=0 (diagnostics, no claim):')
    for r in (rE, rDch, rDfu):
        Ln = np.linalg.norm(r.L, axis=1)     # (T,)  [v9.1 axis fix]
        Gn = np.linalg.norm(r.G, axis=1)
        ldrift = abs(Ln[-1]-Ln[0])/max(Ln[0], 1e-30)
        gret = float(np.mean(Gn/max(Gn[0], 1e-30)))
        print(f'  [{r.label:16s}] |L| drift = {ldrift:.3f} (branch-caveated)'
              f'   mean |G|/|G0| = {gret:.3f}')

    print('\n' + L)
    print('[J8/J10] VERDICT — storage, not loss; routing, not damping?')
    print(L)
    fu_kept = rDfu.Et[-1] >= 0.98*rDfu.Et[0] - 1.0
    fu_supp = rDfu.Zu[-1]/max(rE.Zu[-1], 1e-30)
    scale_fu = rE.E[-1]/max(rDfu.E[-1], 1e-30)
    print(f'  fused run: closed total retained '
          f'{100.0*rDfu.Et[-1]/rDfu.Et[0]:.1f}%   '
          f'Zu ratio vs classical = {fu_supp:.3f}   '
          f'(energy-normalized: {fu_supp*scale_fu:.3f})')
    if fu_kept and fu_supp < 0.7:
        print('\n  VERDICT: CONSERVATION VIA STORAGE + ROUTING, both confirmed.')
        print('  The closed system (kinetic + tension reservoir) conserves')
        print('  to roundoff; within it, the transfer relocates Real-channel')
        print('  concentration into the phase channel at nu=0 without')
        print('  destroying energy. This is the defensible form of the')
        print('  PDF\'s conservation claim: TOTAL STRUCTURAL ENERGY is')
        print('  conserved; REAL-channel energy alone is not — the')
        print('  difference is stored tension routed by Omega. Revise')
        print('  Section 6 of the proof document to this two-channel')
        print('  statement.')
    elif fu_kept:
        print('\n  VERDICT: conservation holds, but suppression was mostly')
        print('  the per-channel toll — fused routing alone does not')
        print('  suppress. The honest claim is the closed-system')
        print('  conservation plus the thresholded reservoir, not')
        print('  concentration suppression.')
    else:
        print('\n  VERDICT: reservoir grows even in fused mode beyond')
        print('  prediction — report and investigate before any claim.')
    print(L)

    print('MOMENTUM CHECK: worst drift = '
          f'{max(float(np.max(r.mom_drift)) for r in (rE, rDch, rDfu)):.2e}')
    print('\nCOST:')
    for r in (rE, rDch, rDfu):
        print(f'  [{r.label:16s}] wall = {r.wall_time:6.1f}s   '
              f'cycles/solve = {r.pstats.cycles_total/max(r.pstats.solves,1):.1f}')
    print('\nSCOPE: finite-grid statements. R is bookkeeping that makes')
    print('conservation true by construction; its PHYSICS content is that')
    print('(a) every other channel conserves exactly, and (b) the only')
    print('irreversible sink is threshold-triggered and vortex-correlated.')
    print('Storage vs dissipation is decided by a return path (the release')
    print('test) — a modeling choice, not something this run can settle.')

audit(rE, rDch, rDfu)

