def audit(rC0, rCH, rFU, rREL):
    L = '='*79
    runs = (rC0, rCH, rFU, rREL)
    print('\n' + L)
    print('AUDIT — finite-grid verification, this implementation only')
    print(L)

    print('[K1] Omega pointwise invariants (raw transfer):')
    for r in (rCH, rFU, rREL):
        v = 'PASS' if r.omega_err < 1e-12 else 'FAIL'
        print(f'  [{r.label:14s}] err = {r.omega_err:.2e}  -> {v}')
    assert np.all(rC0.p_final == 0.0), \
        'classical run developed a phase channel — implementation error.'

    print('\n[K2] Boundedness and routing activity (first -> last):')
    for r in runs:
        gw = float(np.max(r.max_w))/max(float(r.max_w[0]), 1e-30)
        st = 'finite' if r.finite else f'HALTED step {r.failure_step+1}'
        print(f'  [{r.label:14s}] max|w| x{gw:.2f}   routes '
              f'{int(r.phase_routes[1]) if len(r.phase_routes) > 1 else 0}'
              f' -> {int(r.phase_routes[-1])}   -> {st}')

    print('\n[K3] MOMENTUM — the v10 gate (material advection prediction):')
    print('      v9 fused leaked 1.05e-01 (each channel self-advected by')
    print('      its own compressible carrier, leak 0.5*<div f, f>). The')
    print('      particle-consistent carrier m makes it exact. Expect ~1e-9:')
    for r in runs:
        print(f'  [{r.label:14s}] worst momentum drift = '
              f'{float(np.max(r.mom_drift)):.2e}')
    worst_mom = max(float(np.max(r.mom_drift)) for r in runs)
    print(f'  -> {"PASS" if worst_mom < 1e-6 else "FAIL"} '
          f'(threshold 1e-6)')

    print('\n[K4] EXACT LEDGER, CLOSED-SYSTEM (kinetic + reservoir):')
    print(f'  {"run":16s} {"dE_kin":>9s} {"euler dt2":>10s} {"proj->R":>9s} '
          f'{"R trans":>9s} {"R fin":>8s} {"E+R fin":>9s} {"cons err":>9s}')
    for r in runs:
        print(f'  [{r.label:14s}] {r.E[-1]-r.E0:+9.3f} {r.euler2_cum:+10.3f} '
              f'{r.proj_cum:+9.3f} {r.R_transient:9.3f} {r.R[-1]:8.3f} '
              f'{r.Et[-1]:9.3f} {r.cons_err:9.2e}')
    print('  (euler dt2 is the forward-Euler injection — scheme artifact,')
    print('   attributed exactly; a Cayley-exact update would remove it.)')

    print('\n[K11] SCALE DISPERSAL — the particle-dispersion meter')
    print('      (fine = sub-filter kinetic fraction, scale < 2dx: velocity')
    print('      variance at particle scale — the bumping/deflection')
    print('      signature; pre = post-transfer, before the projection)')
    print(f'  {"run":16s} {"fine u":>8s} {"fine p":>8s} '
          f'{"pre u":>8s} {"pre p":>8s}')
    for r in runs:
        print(f'  [{r.label:14s}] {r.fine_u[-1]:8.3f} {r.fine_p[-1]:8.3f} '
              f'{r.fine_pre_u[-1]:8.3f} {r.fine_pre_p[-1]:8.3f}')
    print('  reading:')
    print('   * fine_p HIGH in Omega runs -> phase channel carries DISPERSED')
    print('     particle-scale velocity variance: the bumping/deflection')
    print('     picture — dissipation-CHARACTER storage (dispersed).')
    print('   * fine_p LOW (organized)    -> phase energy sits in coherent')
    print('     structures: storage without dispersal.')
    print('   * pre >> post               -> the projection toll eats')
    print('     fine-scale energy preferentially: the toll IS the')
    print('     deflection event, paid at enforcement time.')

    print('\n[K12] RELEASE PROTOCOL — the return-path question:')
    i_rel = int(np.searchsorted(rREL.times, rREL.omega_off_step*rREL.times[1]
                                if len(rREL.times) > 1 else 0.0))
    i_rel = min(max(i_rel, 1), len(rREL.times)-1)
    print(f'  Omega released at step {rREL.omega_off_step} '
          f'(t = {rREL.times[i_rel]:.3f}):')
