# =============================================================================
# SECTION 1 — SELECTOR SPECTRA (validated; provenance + audit source)
# =============================================================================
P_REAL, P_UNREAL = '1', 'i'

def t_spectrum(g):
    num = [(g, P_REAL), (g, P_UNREAL)]
    den = [(1.0+g, P_REAL), (1.0+g, P_REAL),
           (1.0+g, P_UNREAL), (1.0+g, P_UNREAL)]
    return num, den, g / (1.0 + g)

def cs_spectra(t):
    arms = [(t*t, P_REAL), (t*t, P_UNREAL),
            (t*t, P_UNREAL), (t*t, P_UNREAL)]
    leads = [(1.0, P_REAL), (1.0, P_UNREAL)]
    num_c = [(lm - am, lp) for (lm, lp) in leads for (am, ap) in arms]
    den_c = [(lm + am, lp) for (lm, lp) in leads for (am, ap) in arms]
    num_s = [(2.0*t, ph) for (am, ph) in arms]
    return num_c, den_c, num_s

def collapse_check(num, den, ref):
    worst = 0.0
    for (nm, nph) in num:
        for (dm, dph) in den:
            worst = max(worst, abs(nm/dm - ref))
    return worst

def angle_selector(g):
    """Trans-finite compactifier: g in [0,inf) -> t in [0,1) -> [0,pi/2).
    Collapsed magnitude arms of the division spectra above."""
    t = g / (1.0 + g)
    return t, (1.0 - t*t)/(1.0 + t*t), (2.0*t)/(1.0 + t*t)

def selector_demo(g=0.6):
    L = '=' * 79
    print(L)
    print('SELECTOR SPECTRA — collapse audit (Prop 8 corollary)')
    num, den, t_ref = t_spectrum(g)
    num_c, den_c, num_s = cs_spectra(t_ref)
    c_ref = (1.0-t_ref*t_ref)/(1.0+t_ref*t_ref)
    s_ref = 2.0*t_ref/(1.0+t_ref*t_ref)
    print(f'  t: {collapse_check(num, den, t_ref):.2e}   '
          f'c (64 quotients): {collapse_check(num_c, den_c, c_ref):.2e}   '
          f's (32 quotients): {collapse_check(num_s, den_c, s_ref):.2e}   '
          f'circle c^2+s^2-1 = {abs(c_ref*c_ref+s_ref*s_ref-1.0):.2e}')
    print(L)

selector_demo(0.6)

# =============================================================================
# SECTION 2 — SHARED NATIVE PIECES (validated)
# =============================================================================
def nth_trig(angle, n_steps=128):
    """Nth trigonometric projection operators: modular fusion fold
    [Ax 7.3], half-selector by division spectrum [Prop 8], n fusions
    around the unit selector circle [Ax 7.2]. No np.sin/np.cos."""
    a = np.mod(angle, TAU)
    t = a / (2.0 * n_steps)
    dc = (1.0 - t*t) / (1.0 + t*t)
    ds = (2.0 * t) / (1.0 + t*t)
    c = np.ones_like(a)
    s = np.zeros_like(a)
    for _ in range(n_steps):
        c, s = c*dc - s*ds, s*dc + c*ds
    return c, s

def sample_collapse_audit(g_field, n=16):
    flat = g_field.ravel()
    flat = flat[flat > 0.0]
    if flat.size == 0:
        return 0.0
    idx = rng.choice(flat.size, size=min(n, flat.size), replace=False)
    worst = 0.0
    for g in flat[idx]:
        num, den, t_ref = t_spectrum(float(g))
        worst = max(worst, collapse_check(num, den, t_ref))
        num_c, den_c, num_s = cs_spectra(t_ref)
        c_ref = (1.0-t_ref*t_ref)/(1.0+t_ref*t_ref)
        s_ref = 2.0*t_ref/(1.0+t_ref*t_ref)
        worst = max(worst, collapse_check(num_c, den_c, c_ref),
                    collapse_check(num_s, den_c, s_ref))
    return worst

# =============================================================================
# SECTION 3 — 3D STACK (validated v10, unchanged)
# =============================================================================
def make_grid(n, length=2.0*np.pi):
    assert n >= 4 and (n & (n - 1)) == 0, 'grid must be a power of two'
    x = np.linspace(0.0, length, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), length / n

def dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis)) * (0.5/dx)

def grad_vec(u, dx):
    gu = np.empty(u.shape + (3,))
    for i in range(3):
        for j in range(3):
            gu[..., i, j] = dd(u[..., i], j, dx)
    return gu

def curl(u, dx):
    g = grad_vec(u, dx)
    w = np.empty_like(u)
    w[..., 0] = g[..., 2, 1] - g[..., 1, 2]
    w[..., 1] = g[..., 0, 2] - g[..., 2, 0]
    w[..., 2] = g[..., 1, 0] - g[..., 0, 1]
    return w

def div_u(u, dx):
    return (dd(u[..., 0], 0, dx) + dd(u[..., 1], 1, dx)
            + dd(u[..., 2], 2, dx))

def lap_vec(u, dx):
    out = np.empty_like(u)
    inv = 1.0 / (dx*dx)
    for i in range(3):
        f = u[..., i]
        out[..., i] = (-6.0*f + np.roll(f, -1, 0) + np.roll(f, 1, 0)
                       + np.roll(f, -1, 1) + np.roll(f, 1, 1)
                       + np.roll(f, -1, 2) + np.roll(f, 1, 2)) * inv
    return out

def advect_material(f, v, dx):
    """Particle-consistent structural product: state f carried by the
    bundle velocity v. sum(f.adv)=0 needs div v=0; sum(adv)=0 per
    channel needs div v=0; energy sum(f.adv(f,v))=0 always (skew)."""
    out = np.zeros_like(f)
    for i in range(3):
        fi = f[..., i]
        acc = np.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc += 0.5 * (dd(vj*fi, j, dx) + vj*dd(fi, j, dx))
        out[..., i] = acc
    return out

@dataclass
class JacobianChannels:
    R: np.ndarray; U: np.ndarray; C1: np.ndarray; C2: np.ndarray
    vort: np.ndarray; tension: np.ndarray

def nth_jacobian(u, dx):
    G = grad_vec(u, dx)
    S_ = 0.5 * (G + np.swapaxes(G, -1, -2))
    A_ = 0.5 * (G - np.swapaxes(G, -1, -2))
    C1 = np.sqrt(np.sum(S_*S_, axis=(-2, -1)))
    C2 = np.sqrt(np.sum(A_*A_, axis=(-2, -1)))
    a, b, c = G[..., 0, 0], G[..., 0, 1], G[..., 0, 2]
    d, e, f = G[..., 1, 0], G[..., 1, 1], G[..., 1, 2]
    g, h, i = G[..., 2, 0], G[..., 2, 1], G[..., 2, 2]
    R = a*(e*i - f*h) - b*(d*i - f*g) + c*(d*h - e*g)
    U = np.sqrt(np.sum(G*G, axis=(-2, -1))) - np.abs(R)
    vort = np.stack([G[..., 2, 1] - G[..., 1, 2],
                     G[..., 0, 2] - G[..., 2, 0],
                     G[..., 1, 0] - G[..., 0, 1]], axis=-1)
    return JacobianChannels(R, U, C1, C2, vort, C1 + C2 + np.abs(R))

def initial_selector_field(axes, amplitude, harmonic):
    x, y, z = axes
    def mode(k):
        cx, sx = nth_trig(k*x)
        cy, sy = nth_trig(k*y)
        cz, sz = nth_trig(k*z)
        return np.stack([sx*cy*cz, -(cx*sy*cz), np.zeros_like(x)], axis=-1)
    return amplitude * (mode(1.0) + harmonic * mode(2.0))

def unreal_mirror(axis):
    a1, a2, a3 = (axis[..., 0], axis[..., 1], axis[..., 2])
    M = np.zeros(axis.shape[:-1] + (3, 3))
    M[..., 0, 1] = -a3; M[..., 0, 2] =  a2
    M[..., 1, 0] =  a3; M[..., 1, 2] = -a1
    M[..., 2, 0] = -a2; M[..., 2, 1] =  a1
    return M

def partner(M, d):
    return np.einsum('...ij,...j->...i', M, d)

def omega_transfer_nth(u, p, jac, dx, threshold, gain):
    excess = np.maximum(jac.tension - threshold, 0.0)
    active = excess > 0.0
    g = gain * excess * dx
    t, c, s = angle_selector(g)
    m = u + p
    d = 0.5 * (u - p)
    rot_dom = jac.C2 > jac.C1
    wn = np.sqrt(np.sum(jac.vort*jac.vort, axis=-1))
    gs = np.stack([dd(jac.C1, a, dx) for a in (0, 1, 2)], axis=-1)
    gn = np.sqrt(np.sum(gs*gs, axis=-1))
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    axis = np.zeros_like(u)
    if use_v.any():
        axis[use_v] = (jac.vort / np.maximum(wn, 1e-30)[..., None])[use_v]
    if use_g.any():
        axis[use_g] = (gs / np.maximum(gn, 1e-30)[..., None])[use_g]
    M = unreal_mirror(axis)
    Pd = partner(M, d)
    d_ax = d + partner(M, Pd)
    d_tr = d - d_ax
    Ptr = partner(M, d_tr)
    d_new = d_ax + c[..., None]*d_tr + s[..., None]*Ptr
    u_new = 0.5*m + d_new
    p_new = 0.5*m - d_new
    rdom = np.abs(jac.R) > np.maximum(jac.C1, jac.C2)
    phase = np.full(excess.shape, 'Real', dtype='<U6')
    phase[active & rdom] = 'C2'
    phase[active & ~rdom & rot_dom] = 'Unreal'
    phase[active & ~rdom & ~rot_dom] = 'C1'
    routes = int(np.count_nonzero(active))
    aud = {'g_max': float(np.max(g))}
    err_m = float(np.max(np.abs((u_new + p_new) - (u + p))))
    e0 = float(np.sum(u*u + p*p))
    e1 = float(np.sum(u_new*u_new + p_new*p_new))
    err_e = abs(e1 - e0) / max(abs(e0), 1e-300)
    return u_new, p_new, phase, routes, max(err_m, err_e), aud

def restrict(F):
    a, b, c = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (a//2, 2, b//2, 2, c//2, 2)
                     ).mean(axis=(-5, -3, -1))

def _interp1(F, axis):
    n = F.shape[axis]
    shp = list(F.shape); shp[axis] = 2*n
    G = np.empty(shp, dtype=F.dtype)
    se = [slice(None)]*F.ndim; se[axis] = slice(0, 2*n, 2)
    G[tuple(se)] = F
    so = [slice(None)]*F.ndim; so[axis] = slice(1, 2*n, 2)
    G[tuple(so)] = 0.5 * (F + np.roll(F, -1, axis=axis))
    return G

def prolong(C):
    F = _interp1(C, C.ndim - 3)
    F = _interp1(F, F.ndim - 2)
    F = _interp1(F, F.ndim - 1)
    return F

def lap_apply(F, dx):
    inv = 1.0 / (dx*dx)
    s = -6.0 * F
    for a in (F.ndim - 3, F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s * inv

_RBGS_CACHE = {}
def _rb_mask(m):
    if m not in _RBGS_CACHE:
        idx = np.indices((m, m, m))
        red = ((idx[0] + idx[1] + idx[2]) % 2 == 0)
        _RBGS_CACHE[m] = (red, ~red)
    return _RBGS_CACHE[m]

def smooth_gs(phi, f, dx, iters):
    """RBGS, v5 sign convention: phi <- phi - (dx^2/6)(f - L phi)."""
    c = dx * dx / 6.0
    red, black = _rb_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - lap_apply(phi, dx)
        phi = phi - c * np.where(red, r, 0.0)
        r = f - lap_apply(phi, dx)
        phi = phi - c * np.where(black, r, 0.0)
    return phi

def v_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - f.mean(axis=(-3, -2, -1), keepdims=True)
        return smooth_gs(phi, f, dx, 40)
    phi = smooth_gs(phi, f, dx, 2)
    r = f - lap_apply(phi, dx)
    rc = restrict(r)
    ec = v_cycle(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + prolong(ec)
    return smooth_gs(phi, f, dx, 2)

def split_classes(f):
    N = f.shape[-1]
    M = N // 2
    out = np.empty(f.shape[:-3] + (8, M, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                out[..., c, :, :, :] = f[..., a::2, b::2, d::2]
                c += 1
    return out

def merge_classes(g, N):
    f = np.empty(g.shape[:-4] + (N, N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                f[..., a::2, b::2, d::2] = g[..., c, :, :, :]
                c += 1
    return f

def div_bundle(V, dx):
    out = np.zeros(V.shape[:-1])
    for j in range(3):
        out += dd(V[..., j], V.ndim - 4 + j, dx)
    return out

def grad_bundle(phi, dx):
    return np.stack([dd(phi, phi.ndim - 3 + j, dx) for j in range(3)],
                    axis=-1)

@dataclass
class ProjStats:
    solves: int = 0; cycles_total: int = 0; cycles_max: int = 0
    worst_resid: float = 0.0

def project_bundle(V, dx, mode='channels', phi=None, tol=1e-9,
                   max_cycles=20, stats=None):
    if mode == 'fused':
        Mb = (V[0] + V[1])[None, ...]
        f = -div_bundle(Mb, dx)
    else:
        f = -div_bundle(V, dx)
    fc = split_classes(f)
    H = 2.0 * dx
    fc = fc - fc.mean(axis=(-3, -2, -1), keepdims=True)
    f0 = np.sqrt(np.sum(fc*fc, axis=(-3, -2, -1)))
    live = f0 > 1e-300
    fc = fc * live[..., None, None, None]
    if phi is None:
        psic = np.zeros_like(fc)
    else:
        psic = split_classes(phi) * live[..., None, None, None]
    psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
    cycles, worst = 0, 0.0
    if live.any():
        def rel_resid():
            r = fc - lap_apply(psic, H)
            rn = np.sqrt(np.sum(r*r, axis=(-3, -2, -1)))
            return float(np.max((rn / np.maximum(f0, 1e-300))[live]))
        worst = rel_resid()
        while worst >= tol and cycles < max_cycles:
            psic = v_cycle(psic, fc, H)
            psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
            cycles += 1
            worst = rel_resid()
    phi_out = merge_classes(psic, V.shape[-3])
    if mode == 'fused':
        g = grad_bundle(phi_out[0], dx)
        gu = 0.5 * g; gp = 0.5 * g
    else:
        gu = grad_bundle(phi_out[0], dx)
        gp = grad_bundle(phi_out[1], dx)
    Vp = np.stack([V[0] + gu, V[1] + gp])
    if stats is not None and live.any():
        stats.solves += 1
        stats.cycles_total += cycles
        stats.cycles_max = max(stats.cycles_max, cycles)
        stats.worst_resid = max(stats.worst_resid, worst)
    return Vp, gu, gp, phi_out, cycles, worst

def validate_solver(m=16, seed=3):
    H = 0.4
    g = np.random.default_rng(seed)
    phi_true = g.standard_normal((m, m, m))
    for _ in range(6):
        for a in (0, 1, 2):
            phi_true = 0.5*phi_true + 0.25*(np.roll(phi_true, -1, axis=a)
                                            + np.roll(phi_true, 1, axis=a))
    phi_true -= phi_true.mean()
    f = lap_apply(phi_true, H)
    phi = np.zeros_like(f)
    for _ in range(30):
        phi = v_cycle(phi, f, H)
        phi -= phi.mean()
        if float(np.max(np.abs(f - lap_apply(phi, H)))) < 1e-11*max(1.0, float(np.max(np.abs(f)))):
            break
    err = float(np.max(np.abs(phi - phi_true)))
    scale = max(1.0, float(np.max(np.abs(phi_true))))
    ok = np.isfinite(err) and err < 1e-6*scale
    print(f'  3D exact recovery: {err/scale:.2e} (tol 1e-6)  '
          f'-> {"PASS" if ok else "FAIL"}')
    assert ok, '3D SOLVER UNIT TEST FAILED.'

def validate_projection(n=32, seed=7):
    axes, dx = make_grid(n)
    g = np.random.default_rng(seed)
    V = g.standard_normal((2, n, n, n, 3))
    for _ in range(6):
        for a in (1, 2, 3):
            V = 0.5*V + 0.25*(np.roll(V, -1, axis=a) + np.roll(V, 1, axis=a))
    E0 = float(np.sum(V*V))
    Vp, _, _, _, cycles, resid = project_bundle(V, dx, 'channels',
                                                None, 1e-10, 25)
    d1 = float(np.max(np.abs(div_bundle(Vp, dx))))
    ok_a = np.isfinite(resid) and resid < 1e-8
    ok_b = np.isfinite(d1) and d1 <= max(1e-9, 1e-6*float(np.max(np.abs(div_bundle(V, dx)))))
    ok_c = float(np.sum(Vp*Vp)) <= E0*(1.0 + 1e-6)
    print(f'  3D channels ({cycles} cy): resid {resid:.2e} '
          f'{"PASS" if ok_a else "FAIL"}   div {d1:.2e} '
          f'{"PASS" if ok_b else "FAIL"}   energy '
          f'{float(np.sum(Vp*Vp))/E0:.6f} {"PASS" if ok_c else "FAIL"}')
    Vf, _, _, _, cycles_f, _ = project_bundle(V, dx, 'fused', None, 1e-10, 25)
    wt1 = float(np.max(np.abs(div_u(Vf[0]+Vf[1], dx))))
    dpres = float(np.max(np.abs(0.5*(Vf[0]-Vf[1]) - 0.5*(V[0]-V[1]))))
    ok_e = (wt1 <= max(1e-9, 1e-6*float(np.max(np.abs(div_u(V[0]+V[1], dx)))))
            and dpres < 1e-12 and float(np.sum(Vf*Vf)) <= E0*(1.0+1e-6))
    print(f'  3D fused   ({cycles_f} cy): div(m) {wt1:.2e}   '
          f'|d\'-d| {dpres:.2e}   -> {"PASS" if ok_e else "FAIL"}')
    assert ok_a and ok_b and ok_c and ok_e, '3D BRIDGE GATE FAILED.'
    print('  3D bridge validated.')

# =============================================================================
# SECTION 4 — 2D STACK (NEW). In 2D the unreal mirror is the CONSTANT
# quarter-turn J = [[0,-1],[1,0]]: the phase-locked orbit is the unit
# circle itself, d is fully transverse (d_ax = 0 identically), and the
# transfer is PURE unit-circle fusion on d. The 3D extension is the
# lifting of this constant mirror to the vorticity-aligned mirror field
# — which is precisely what opens the C1/C2 coupling channel.
# =============================================================================
def make_grid2(n, length=2.0*np.pi):
    assert n >= 4 and (n & (n - 1)) == 0, 'grid must be a power of two'
    x = np.linspace(0.0, length, n, endpoint=False)
    return np.meshgrid(x, x, indexing='ij'), length / n

def dd2(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis)) * (0.5/dx)

def curl2(u, dx):
    """Scalar vorticity w = du_y/dx - du_x/dy. Spatial axes are the two
    axes before the component axis (negative indexing, per the v9.2
    lesson)."""
    return (dd2(u[..., 1], u.ndim - 3, dx)
            - dd2(u[..., 0], u.ndim - 2, dx))

def div2(V, dx):
    out = np.zeros(V.shape[:-1])
    for j in range(2):
        out += dd2(V[..., j], V.ndim - 3 + j, dx)
    return out

def grad2(phi, dx):
    return np.stack([dd2(phi, phi.ndim - 2, dx),
                     dd2(phi, phi.ndim - 1, dx)], axis=-1)

def lap_vec2(u, dx):
    out = np.empty_like(u)
    inv = 1.0 / (dx*dx)
    for i in range(2):
        f = u[..., i]
        out[..., i] = (-4.0*f + np.roll(f, -1, axis=u.ndim-3)
                       + np.roll(f, 1, axis=u.ndim-3)
                       + np.roll(f, -1, axis=u.ndim-2)
                       + np.roll(f, 1, axis=u.ndim-2)) * inv
    return out

def advect_material2(f, v, dx):
    """2D material advection (state f carried by bundle v). Same exact
    identities as 3D: sum(f.adv(f)) = 0 always."""
    out = np.zeros_like(f)
    for i in range(2):
        fi = f[..., i]
        acc = np.zeros_like(fi)
        for j in range(2):
            vj = v[..., j]
            ax = fi.ndim - 2 + j        # x then y (last two axes)
            acc += 0.5 * (dd2(vj*fi, ax, dx) + vj*dd2(fi, ax, dx))
        out[..., i] = acc
    return out

def advect_scalar2(g, v, dx):
    """Material advection of a 2D scalar (used for the vorticity
    leakage meter)."""
    acc = np.zeros_like(g)
    for j in range(2):
        vj = v[..., j]
        ax = g.ndim - 2 + j
        acc += 0.5 * (dd2(vj*g, ax, dx) + vj*dd2(g, ax, dx))
    return acc

@dataclass
class JacobianChannels2:
    R: np.ndarray; C1: np.ndarray; C2: np.ndarray
    w: np.ndarray; tension: np.ndarray

def nth_jacobian2(u, dx):
    G = np.empty(u.shape + (2,))          # G[...,i,j] = du_i/dx_j
    for i in range(2):
        for j in range(2):
            G[..., i, j] = dd2(u[..., i], u.ndim - 3 + j, dx)
    S_ = 0.5 * (G + np.swapaxes(G, -1, -2))
    A_ = 0.5 * (G - np.swapaxes(G, -1, -2))
    C1 = np.sqrt(np.sum(S_*S_, axis=(-2, -1)))
    C2 = np.sqrt(np.sum(A_*A_, axis=(-2, -1)))
    R = G[..., 0, 0]*G[..., 1, 1] - G[..., 0, 1]*G[..., 1, 0]
    w = G[..., 1, 0] - G[..., 0, 1]
    return JacobianChannels2(R, C1, C2, w, C1 + C2 + np.abs(R))

def initial_field2(axes, amplitude, harmonic):
    x, y = axes
    def mode(k):
        cx, sx = nth_trig(k*x)
        cy, sy = nth_trig(k*y)
        return np.stack([sx*cy, -(cx*sy)], axis=-1)
    return amplitude * (mode(1.0) + harmonic * mode(2.0))

def omega_transfer2(u, p, jac, dx, threshold, gain):
    """2D Omega: the mirror is the constant quarter-turn J (Axiom 9.0 in
    its 2D form). d is fully transverse (J(Jd) = -d), so the transfer is
    pure unit-circle fusion: d' = c*d + s*Jd. Same pointwise invariants
    (u+p, |u|^2+|p|^2), audited. NOTE: no axial arm exists in 2D — the
    C1/C2 coupling channel is structurally closed."""
    excess = np.maximum(jac.tension - threshold, 0.0)
    active = excess > 0.0
    g = gain * excess * dx
    t, c, s = angle_selector(g)
    m = u + p
    d = 0.5 * (u - p)
    Pd = np.stack([-d[..., 1], d[..., 0]], axis=-1)   # J d
    d_new = c[..., None]*d + s[..., None]*Pd
    u_new = 0.5*m + d_new
    p_new = 0.5*m - d_new
    rdom = np.abs(jac.R) > np.maximum(jac.C1, jac.C2)
    rot_dom = jac.C2 > jac.C1
    phase = np.full(excess.shape, 'Real', dtype='<U6')
    phase[active & rdom] = 'C2'
    phase[active & ~rdom & rot_dom] = 'Unreal'
    phase[active & ~rdom & ~rot_dom] = 'C1'
    routes = int(np.count_nonzero(active))
    aud = {'g_max': float(np.max(g))}
    err_m = float(np.max(np.abs((u_new + p_new) - (u + p))))
    e0 = float(np.sum(u*u + p*p))
    e1 = float(np.sum(u_new*u_new + p_new*p_new))
    err_e = abs(e1 - e0) / max(abs(e0), 1e-300)
    return u_new, p_new, phase, routes, max(err_m, err_e), aud

def restrict2(F):
    a, b = F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-2] + (a//2, 2, b//2, 2)).mean(axis=(-3, -1))

def prolong2(C):
    F = _interp1(C, C.ndim - 2)
    F = _interp1(F, F.ndim - 1)
    return F

def lap2_apply(F, dx):
    inv = 1.0 / (dx*dx)
    s = -4.0 * F
    for a in (F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s * inv

_RB2_CACHE = {}
def _rb2_mask(m):
    if m not in _RB2_CACHE:
        idx = np.indices((m, m))
        red = ((idx[0] + idx[1]) % 2 == 0)
        _RB2_CACHE[m] = (red, ~red)
    return _RB2_CACHE[m]

def smooth_gs2(phi, f, dx, iters):
    """2D RBGS, same sign convention: phi <- phi - (dx^2/4)(f - L phi)."""
    c = dx * dx / 4.0
    red, black = _rb2_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - lap2_apply(phi, dx)
        phi = phi - c * np.where(red, r, 0.0)
        r = f - lap2_apply(phi, dx)
        phi = phi - c * np.where(black, r, 0.0)
    return phi

def v_cycle2(phi, f, dx):
    if min(f.shape[-2], f.shape[-1]) <= 4:
        f = f - f.mean(axis=(-2, -1), keepdims=True)
        return smooth_gs2(phi, f, dx, 60)
    phi = smooth_gs2(phi, f, dx, 3)
    r = f - lap2_apply(phi, dx)
    rc = restrict2(r)
    ec = v_cycle2(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + prolong2(ec)
    return smooth_gs2(phi, f, dx, 3)

def split_classes2(f):
    """2D mod-2 classes: 4 (Axiom 0 closure structure of the 2-torus)."""
    N = f.shape[-1]
    M = N // 2
    out = np.empty(f.shape[:-2] + (4, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            out[..., c, :, :] = f[..., a::2, b::2]
            c += 1
    return out

def merge_classes2(g, N):
    f = np.empty(g.shape[:-3] + (N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            f[..., a::2, b::2] = g[..., c, :, :]
            c += 1
    return f

def project_bundle2(V, dx, mode='channels', phi=None, tol=1e-9,
                    max_cycles=30, stats=None):
    """2D Whole-Term projection, same explicit enforcement target.
    The wide operator div2(grad2(.)) decouples along the 4 mod-2 classes
    of the 2-torus; on each class it is the compact 5-point balance at
    H = 2dx. Same transfer-invariance argument as 3D: fused mode pays
    ~nothing at a transfer."""
    if mode == 'fused':
        Mb = (V[0] + V[1])[None, ...]          # (1,n,n,2)
        f = -div2(Mb, dx)                      # (1,n,n)
    else:
        f = -div2(V, dx)                       # (2,n,n)
    fc = split_classes2(f)                     # (C,4,M,M)
    H = 2.0 * dx
    fc = fc - fc.mean(axis=(-2, -1), keepdims=True)
    f0 = np.sqrt(np.sum(fc*fc, axis=(-2, -1)))
    live = f0 > 1e-300
    fc = fc * live[..., None, None]
    if phi is None:
        psic = np.zeros_like(fc)
    else:
        psic = split_classes2(phi) * live[..., None, None]
    psic = psic - psic.mean(axis=(-2, -1), keepdims=True)
    cycles, worst = 0, 0.0
    if live.any():
        def rel_resid():
            r = fc - lap2_apply(psic, H)
            rn = np.sqrt(np.sum(r*r, axis=(-2, -1)))
            return float(np.max((rn / np.maximum(f0, 1e-300))[live]))
        worst = rel_resid()
        while worst >= tol and cycles < max_cycles:
            psic = v_cycle2(psic, fc, H)
            psic = psic - psic.mean(axis=(-2, -1), keepdims=True)
            cycles += 1
            worst = rel_resid()
    phi_out = merge_classes2(psic, V.shape[-2])
    if mode == 'fused':
        g = grad2(phi_out[0], dx)
        gu = 0.5 * g; gp = 0.5 * g
    else:
        gu = grad2(phi_out[0], dx)
        gp = grad2(phi_out[1], dx)
    Vp = np.stack([V[0] + gu, V[1] + gp])
    if stats is not None and live.any():
        stats.solves += 1
        stats.cycles_total += cycles
        stats.cycles_max = max(stats.cycles_max, cycles)
        stats.worst_resid = max(stats.worst_resid, worst)
    return Vp, gu, gp, phi_out, cycles, worst

def validate_solver2(m=16, seed=3):
    """2D gate 1 — exact recovery (categorical against sign/axis/
    operator errors in the NEW 2D cascade)."""
    H = 0.4
    g = np.random.default_rng(seed)
    phi_true = g.standard_normal((m, m))
    for _ in range(6):
        for a in (0, 1):
            phi_true = 0.5*phi_true + 0.25*(np.roll(phi_true, -1, axis=a)
                                            + np.roll(phi_true, 1, axis=a))
    phi_true -= phi_true.mean()
    f = lap2_apply(phi_true, H)
    phi = np.zeros_like(f)
    for _ in range(40):
        phi = v_cycle2(phi, f, H)
        phi -= phi.mean()
        if float(np.max(np.abs(f - lap2_apply(phi, H)))) < 1e-11*max(1.0, float(np.max(np.abs(f)))):
            break
    err = float(np.max(np.abs(phi - phi_true)))
    scale = max(1.0, float(np.max(np.abs(phi_true))))
    ok = np.isfinite(err) and err < 1e-6*scale
    print(f'  2D exact recovery: {err/scale:.2e} (tol 1e-6)  '
          f'-> {"PASS" if ok else "FAIL"}')
    assert ok, '2D SOLVER UNIT TEST FAILED.'

def validate_projection2(n=32, seed=7):
    """2D gate 2 — both enforcement targets on a random smooth bundle."""
    axes, dx = make_grid2(n)
    g = np.random.default_rng(seed)
    V = g.standard_normal((2, n, n, 2))
    for _ in range(6):
        for a in (1, 2):
            V = 0.5*V + 0.25*(np.roll(V, -1, axis=a) + np.roll(V, 1, axis=a))
    E0 = float(np.sum(V*V))
    Vp, _, _, _, cycles, resid = project_bundle2(V, dx, 'channels',
                                                 None, 1e-10, 30)
    d1 = float(np.max(np.abs(div2(Vp, dx))))
    ok_a = np.isfinite(resid) and resid < 1e-8
    ok_b = np.isfinite(d1) and d1 <= max(1e-9, 1e-6*float(np.max(np.abs(div2(V, dx)))))
    ok_c = float(np.sum(Vp*Vp)) <= E0*(1.0 + 1e-6)
    print(f'  2D channels ({cycles} cy): resid {resid:.2e} '
          f'{"PASS" if ok_a else "FAIL"}   div {d1:.2e} '
          f'{"PASS" if ok_b else "FAIL"}   energy '
          f'{float(np.sum(Vp*Vp))/E0:.6f} {"PASS" if ok_c else "FAIL"}')
    Vf, _, _, _, cycles_f, _ = project_bundle2(V, dx, 'fused', None, 1e-10, 30)
    wt1 = float(np.max(np.abs(div2(Vf[0]+Vf[1], dx))))
    dpres = float(np.max(np.abs(0.5*(Vf[0]-Vf[1]) - 0.5*(V[0]-V[1]))))
    ok_e = (wt1 <= max(1e-9, 1e-6*float(np.max(np.abs(div2(V[0]+V[1], dx)))))
            and dpres < 1e-12 and float(np.sum(Vf*Vf)) <= E0*(1.0+1e-6))
    print(f'  2D fused   ({cycles_f} cy): div(m) {wt1:.2e}   '
          f'|d\'-d| {dpres:.2e}   -> {"PASS" if ok_e else "FAIL"}')
    assert ok_a and ok_b and ok_c and ok_e, '2D BRIDGE GATE FAILED.'
    print('  2D bridge validated.')

print('\n' + '='*79)
print('BRIDGE GATES — 3D (validated stack) and 2D (new stack)')
print('='*79)
validate_solver(16)
validate_projection(32)
validate_solver2(16)
validate_projection2(32)

# =============================================================================
# SECTION 5 — METERS
# =============================================================================
def fine3(f):
    """3D dispersal meter: (total, sub-filter) kinetic content of one
    channel; cutoff scale 2dx via the cascade's restrict/prolong."""
    E = Ef = 0.0
    for i in range(3):
        comp = f[..., i]
        coarse = prolong(restrict(comp))
        E += float(np.sum(comp*comp))
        Ef += float(np.sum((comp-coarse)*(comp-coarse)))
    return E, Ef

def fine2(f):
    E = Ef = 0.0
    for i in range(2):
        comp = f[..., i]
        coarse = prolong2(restrict2(comp))
        E += float(np.sum(comp*comp))
        Ef += float(np.sum((comp-coarse)*(comp-coarse)))
    return E, Ef

def stretch3(u, dx, vol):
    """THE 3D ENSTROPHY-PRODUCTION METER: <w, (grad u) w> — vortex
    stretching. Only the symmetric part contributes; this term is
    IDENTICALLY ABSENT in 2D (no axial arm)."""
    G = grad_vec(u, dx)
    w = curl(u, dx)
    P = np.einsum('...i,...ij,...j->...', w, G, w)
    return float(np.sum(P)) * vol

def leak3(u, m, dx):
    """3D advection enstrophy leakage: sum w.(m.grad)w — EXACT 0 by the
    skew telescoping identity, in any dimension. Audited."""
    w = curl(u, dx)
    aw = advect_material(w, m, dx)
    return float(np.sum(w*aw))

def leak2(u, m, dx):
    w = curl2(u, dx)
    aw = advect_scalar2(w, m, dx)
    return float(np.sum(w*aw))

# =============================================================================
# SECTION 6 — SHARED DRIVER (exact closed-system ledger, both dims)
# =============================================================================
@dataclass
class RunResult:
    label: str; name: str; dim: int; mode: str
    use_omega: bool; nu: float; gain: float; n: int
    times: np.ndarray; E: np.ndarray; Eu: np.ndarray; Ep: np.ndarray
    Zu: np.ndarray; Zp: np.ndarray; R: np.ndarray; Et: np.ndarray
    max_w: np.ndarray; mom_drift: np.ndarray; routes: np.ndarray
    fine_u: np.ndarray; fine_p: np.ndarray
    stretch: np.ndarray; leak: np.ndarray
    omega_err: float; E0: float
    visc_cum: float; euler2_cum: float; proj_cum: float
    closure_max: float; cons_err: float
    finite: bool; wall: float

def run_ns(dim, label, name, use_omega, nu, mode, n, steps, dt,
           amplitude, harmonic, thresh_frac, gain,
           proj_tol=1e-9, diag_every=5, report_every=50):
    print('\n' + '='*79)
    print(name)
    print(f'  dim={dim}  grid={n}^{dim}  steps={steps}  dt={dt}  nu={nu}  '
          f'Omega={"ON" if use_omega else "OFF"}  mode={mode}  gain={gain:.4g}')
    print('='*79)
    t0 = time.time()
    if dim == 2:
        axes, dx = make_grid2(n)
        vol = dx*dx
        u = initial_field2(axes, amplitude, harmonic)
        p = np.zeros_like(u)
        project = project_bundle2
        jacobian = nth_jacobian2
        omega = omega_transfer2
        lap = lap_vec2
        advect = advect_material2
        vort = curl2
        fine = fine2
    else:
        axes, dx = make_grid(n)
        vol = dx**3
        u = initial_selector_field(axes, amplitude, harmonic)
        p = np.zeros_like(u)
        project = project_bundle
        jacobian = nth_jacobian
        omega = omega_transfer_nth
        lap = lap_vec
        advect = advect_material
        vort = curl
        fine = fine3
    pstats = ProjStats()
    # initial projection in CHANNELS mode: p==0 => classical projection,
    # IDENTICAL initial state for every run at this dimension.
    V, _, _, _, _, _ = project(np.stack([u, p]), dx, 'channels',
                               None, proj_tol, 25 if dim == 3 else 30,
                               pstats)
    u, p = V[0], V[1]
    phi = None
    jac0 = jacobian(u, dx)
    threshold = thresh_frac * float(np.max(jac0.tension))
    axes_sum = (0, 1) if dim == 2 else (0, 1, 2)
    E0 = 0.5*float(np.sum(u*u + p*p))*vol
    mom0 = np.sum(u + p, axis=axes_sum)*vol
    mom_n0 = max(1.0, float(np.sqrt(np.sum(mom0*mom0))))
    print(f'  initial peak tension = {float(np.max(jac0.tension)):.4f}  '
          f'->  threshold = {threshold:.4f}   E0 = {E0:.4f}')

    keys = ['t', 'E', 'Eu', 'Ep', 'Zu', 'Zp', 'R', 'Et', 'max_w',
            'mom_drift', 'routes', 'fine_u', 'fine_p', 'stretch', 'leak']
    hist = {k: [] for k in keys}
    phase = np.full(u.shape[:-1], 'Real', dtype='<U6')
    R = 0.0
    holder = {'fu': 0.0, 'fp': 0.0}

    def record(idx, u_, p_, m_):
        wu = vort(u_, dx)
        wp = vort(p_, dx)
        Eu_ = 0.5*float(np.sum(u_*u_))*vol
        Ep_ = 0.5*float(np.sum(p_*p_))*vol
        Et_, Efu = fine(u_)
        _, Efp = fine(p_)
        hist['t'].append(idx*dt)
        hist['E'].append(Eu_ + Ep_)
        hist['Eu'].append(Eu_); hist['Ep'].append(Ep_)
        hist['Zu'].append(0.5*float(np.sum(wu*wu))*vol)
        hist['Zp'].append(0.5*float(np.sum(wp*wp))*vol)
        hist['R'].append(R)
        hist['Et'].append(Eu_ + Ep_ + R)
        hist['max_w'].append(float(np.max(np.abs(wu))))
        mom = np.sum(u_ + p_, axis=axes_sum)*vol
        hist['mom_drift'].append(
            float(np.sqrt(np.sum((mom-mom0)**2)))/mom_n0)
        hist['routes'].append(int(np.count_nonzero(phase != 'Real')))
        hist['fine_u'].append(Efu/max(Et_, 1e-300))
        hist['fine_p'].append(Efp/max(0.5*float(np.sum(p_*p_)), 1e-300))
        hist['stretch'].append(stretch3(u_, dx, vol) if dim == 3 else 0.0)
        hist['leak'].append(leak2(u_, m_, dx) if dim == 2 else leak3(u_, m_, dx))

    record(0, u, p, u + p)
    E_prev = E0
    visc_cum = euler2_cum = proj_cum = 0.0
    closure_max = 0.0
    max_omega_err = 0.0
    finite = True

    for step in range(steps):
        jac = jacobian(u, dx)
        Lu = lap(u, dx)
        Lp = lap(p, dx)
        ev = float(np.sum(u*Lu + p*Lp))
        m_cur = u + p
        au = advect(u, m_cur, dx)
        ap = advect(p, m_cur, dx)
        F_u = -au + nu*Lu
        F_p = -ap + nu*Lp
        euler2 = 0.5*vol*dt*dt*float(np.sum(F_u*F_u + F_p*F_p))
        visc = vol*dt*nu*ev
        u_s = u + dt*F_u
        p_s = p + dt*F_p

        routes = 0
        if use_omega:
            u_s, p_s, phase, routes, oerr, aud = omega(
                u_s, p_s, jac, dx, threshold, gain)
            if np.isfinite(oerr):
                max_omega_err = max(max_omega_err, oerr)

        if (step+1) % diag_every == 0 or step == steps-1:
            _, Efu_pre = fine(u_s)
            Epp, Efp_pre = fine(p_s)
            holder['fu'] = Efu_pre/max(float(np.sum(u_s*u_s)), 1e-300)
            holder['fp'] = Efp_pre/max(Epp, 1e-300)

        Vp, gu, gp, phi, cycles, resid = project(
            np.stack([u_s, p_s]), dx, mode, phi, proj_tol,
            20 if dim == 3 else 30, pstats)
        dE_proj = 0.5*vol*float(np.sum(2*u_s*gu + gu*gu + 2*p_s*gp + gp*gp))
        u, p = Vp[0], Vp[1]
        R -= dE_proj

        if not (np.all(np.isfinite(u)) and np.all(np.isfinite(p))):
            finite = False
            print(f'  step {step+1}: NON-FINITE -> HALTED, nothing repaired.')
            break

        E_now = 0.5*float(np.sum(u*u + p*p))*vol
        closure = (E_now - E_prev) - visc - euler2 - dE_proj
        closure_max = max(closure_max, abs(closure))
        visc_cum += visc; euler2_cum += euler2; proj_cum += dE_proj
        E_prev = E_now

        if (step+1) % diag_every == 0 or step == steps-1:
            record(step+1, u, p, u + p)
        if step % report_every == 0 or step == steps-1:
            print(f'  step {step+1:4d}  t={(step+1)*dt:7.3f}  '
                  f'E={hist["E"][-1]:9.4f}  R={R:9.4f}  '
                  f'E+R={hist["Et"][-1]:9.4f}  Zu={hist["Zu"][-1]:9.2f}  '
                  f'Zp={hist["Zp"][-1]:9.2f}  max|w|={hist["max_w"][-1]:7.3f}'
                  f'  routes={routes}')

    wall = time.time() - t0
    Et = np.asarray(hist['Et'], dtype=float)
    cons_err = abs((Et[-1] - Et[0]) - visc_cum - euler2_cum)
    arr = lambda k: np.asarray(hist[k], dtype=float)
    res = RunResult(label, name, dim, mode, use_omega, nu, gain, n,
                    arr('t'), arr('E'), arr('Eu'), arr('Ep'), arr('Zu'),
                    arr('Zp'), arr('R'), arr('Et'), arr('max_w'),
                    arr('mom_drift'), arr('routes'), arr('fine_u'),
                    arr('fine_p'), arr('stretch'), arr('leak'),
                    max_omega_err, E0, visc_cum, euler2_cum, proj_cum,
                    closure_max, cons_err, finite, wall)
    print(f'  -> finite={finite}  Omega_err={max_omega_err:.2e}  '
          f'R={R:.3f} ({100.0*R/max(E0,1e-30):.1f}% of E0)  '
          f'cons_err={cons_err:.2e}  wall={wall:.1f}s')
    return res

