# SECTION 3 — 2D STACK (validated, unchanged)
# =============================================================================
def make_grid2(n, length=2.0*np.pi):
    assert n >= 4 and (n & (n - 1)) == 0, 'grid must be a power of two'
    x = np.linspace(0.0, length, n, endpoint=False)
    return np.meshgrid(x, x, indexing='ij'), length / n

def dd2(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis)) * (0.5/dx)

def curl2(u, dx):
    return (dd2(u[..., 1], u.ndim - 3, dx)
            - dd2(u[..., 0], u.ndim - 2, dx))

def div2(V, dx):
    out = np.zeros(V.shape[:-1])
    for j in range(2):
        out += dd2(V[..., j], V.ndim - 3 + j, dx)
    return out

def grad2(phi, dx):
    return np.stack([dd2(phi, phi.ndim - 2, dx),
                     dd2(phi, phi.ndim - 1, dx)], axis=-1)

def lap_vec2(u, dx):
    out = np.empty_like(u)
    inv = 1.0 / (dx*dx)
    for i in range(2):
        f = u[..., i]
        out[..., i] = (-4.0*f + np.roll(f, -1, axis=u.ndim-3)
                       + np.roll(f, 1, axis=u.ndim-3)
                       + np.roll(f, -1, axis=u.ndim-2)
                       + np.roll(f, 1, axis=u.ndim-2)) * inv
    return out

def advect_material2(f, v, dx):
    out = np.zeros_like(f)
    for i in range(2):
        fi = f[..., i]
        acc = np.zeros_like(fi)
        for j in range(2):
            vj = v[..., j]
            ax = fi.ndim - 2 + j
            acc += 0.5 * (dd2(vj*fi, ax, dx) + vj*dd2(fi, ax, dx))
        out[..., i] = acc
    return out

def advect_scalar2(g, v, dx):
    acc = np.zeros_like(g)
    for j in range(2):
        vj = v[..., j]
        ax = g.ndim - 2 + j
        acc += 0.5 * (dd2(vj*g, ax, dx) + vj*dd2(g, ax, dx))
    return acc

@dataclass
class JacobianChannels2:
    R: np.ndarray; C1: np.ndarray; C2: np.ndarray
    w: np.ndarray; tension: np.ndarray

def nth_jacobian2(u, dx):
    G = np.empty(u.shape + (2,))
    for i in range(2):
        for j in range(2):
            G[..., i, j] = dd2(u[..., i], u.ndim - 3 + j, dx)
    S_ = 0.5 * (G + np.swapaxes(G, -1, -2))
    A_ = 0.5 * (G - np.swapaxes(G, -1, -2))
    C1 = np.sqrt(np.sum(S_*S_, axis=(-2, -1)))
    C2 = np.sqrt(np.sum(A_*A_, axis=(-2, -1)))
    R = G[..., 0, 0]*G[..., 1, 1] - G[..., 0, 1]*G[..., 1, 0]
    w = G[..., 1, 0] - G[..., 0, 1]
    return JacobianChannels2(R, C1, C2, w, C1 + C2 + np.abs(R))

def initial_field2(axes, amplitude, harmonic):
    x, y = axes
    def mode(k):
        cx, sx = nth_trig(k*x)
        cy, sy = nth_trig(k*y)
        return np.stack([sx*cy, -(cx*sy)], axis=-1)
    return amplitude * (mode(1.0) + harmonic * mode(2.0))

def omega_transfer2(u, p, jac, dx, threshold, gain):
    excess = np.maximum(jac.tension - threshold, 0.0)
    active = excess > 0.0
    g = gain * excess * dx
    t, c, s = angle_selector(g)
    m = u + p
    d = 0.5 * (u - p)
    Pd = np.stack([-d[..., 1], d[..., 0]], axis=-1)
    d_new = c[..., None]*d + s[..., None]*Pd
    u_new = 0.5*m + d_new
    p_new = 0.5*m - d_new
    rdom = np.abs(jac.R) > np.maximum(jac.C1, jac.C2)
    rot_dom = jac.C2 > jac.C1
    phase = np.full(excess.shape, 'Real', dtype='<U6')
    phase[active & rdom] = 'C2'
    phase[active & ~rdom & rot_dom] = 'Unreal'
    phase[active & ~rdom & ~rot_dom] = 'C1'
    routes = int(np.count_nonzero(active))
    aud = {'g_max': float(np.max(g)),
           't_mean': float(np.mean(t[active])) if routes > 0 else 0.0}
    err_m = float(np.max(np.abs((u_new + p_new) - (u + p))))
    e0 = float(np.sum(u*u + p*p))
    e1 = float(np.sum(u_new*u_new + p_new*p_new))
    err_e = abs(e1 - e0) / max(abs(e0), 1e-300)
    return u_new, p_new, phase, routes, max(err_m, err_e), aud

def restrict2(F):
    a, b = F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-2] + (a//2, 2, b//2, 2)).mean(axis=(-3, -1))

def prolong2(C):
    F = _interp1(C, C.ndim - 2)
    F = _interp1(F, F.ndim - 1)
    return F

def spread2(F):
    F = np.repeat(F, 2, axis=F.ndim - 2)
    F = np.repeat(F, 2, axis=F.ndim - 1)
    return F

def lap2_apply(F, dx):
    inv = 1.0 / (dx*dx)
    s = -4.0 * F
    for a in (F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s * inv

_RB2_CACHE = {}
def _rb2_mask(m):
    if m not in _RB2_CACHE:
        idx = np.indices((m, m))
        red = ((idx[0] + idx[1]) % 2 == 0)
        _RB2_CACHE[m] = (red, ~red)
    return _RB2_CACHE[m]

def smooth_gs2(phi, f, dx, iters):
    c = dx * dx / 4.0
    red, black = _rb2_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - lap2_apply(phi, dx)
        phi = phi - c * np.where(red, r, 0.0)
        r = f - lap2_apply(phi, dx)
        phi = phi - c * np.where(black, r, 0.0)
    return phi

def v_cycle2(phi, f, dx):
    if min(f.shape[-2], f.shape[-1]) <= 4:
        f = f - f.mean(axis=(-2, -1), keepdims=True)
        return smooth_gs2(phi, f, dx, 60)
    phi = smooth_gs2(phi, f, dx, 3)
    r = f - lap2_apply(phi, dx)
    rc = restrict2(r)
    ec = v_cycle2(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + prolong2(ec)
    return smooth_gs2(phi, f, dx, 3)

def split_classes2(f):
    N = f.shape[-1]
    M = N // 2
    out = np.empty(f.shape[:-2] + (4, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            out[..., c, :, :] = f[..., a::2, b::2]
            c += 1
    return out

def merge_classes2(g, N):
    f = np.empty(g.shape[:-3] + (N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            f[..., a::2, b::2] = g[..., c, :, :]
            c += 1
    return f

def project_bundle2(V, dx, mode='channels', phi=None, tol=1e-9,
                    max_cycles=30, stats=None):
    if mode == 'fused':
        Mb = (V[0] + V[1])[None, ...]
        f = -div2(Mb, dx)
    else:
        f = -div2(V, dx)
    fc = split_classes2(f)
    H = 2.0 * dx
    fc = fc - fc.mean(axis=(-2, -1), keepdims=True)
    f0 = np.sqrt(np.sum(fc*fc, axis=(-2, -1)))
    live = f0 > 1e-300
    fc = fc * live[..., None, None]
    if phi is None:
        psic = np.zeros_like(fc)
    else:
        psic = split_classes2(phi) * live[..., None, None]
    psic = psic - psic.mean(axis=(-2, -1), keepdims=True)
    cycles, worst = 0, 0.0
    if live.any():
        def rel_resid():
            r = fc - lap2_apply(psic, H)
            rn = np.sqrt(np.sum(r*r, axis=(-2, -1)))
            return float(np.max((rn / np.maximum(f0, 1e-300))[live]))
        worst = rel_resid()
        while worst >= tol and cycles < max_cycles:
            psic = v_cycle2(psic, fc, H)
            psic = psic - psic.mean(axis=(-2, -1), keepdims=True)
            cycles += 1
            worst = rel_resid()
    phi_out = merge_classes2(psic, V.shape[-2])
    if mode == 'fused':
        g = grad2(phi_out[0], dx)
        gu = 0.5 * g; gp = 0.5 * g
    else:
        gu = grad2(phi_out[0], dx)
        gp = grad2(phi_out[1], dx)
    Vp = np.stack([V[0] + gu, V[1] + gp])
    if stats is not None and live.any():
        stats.solves += 1
        stats.cycles_total += cycles
        stats.cycles_max = max(stats.cycles_max, cycles)
        stats.worst_resid = max(stats.worst_resid, worst)
    return Vp, gu, gp, phi_out, cycles, worst

def validate_solver2(m=16, seed=3):
    H = 0.4
    g = np.random.default_rng(seed)
    phi_true = g.standard_normal((m, m))
    for _ in range(6):
        for a in (0, 1):
            phi_true = 0.5*phi_true + 0.25*(np.roll(phi_true, -1, axis=a)
                                            + np.roll(phi_true, 1, axis=a))
    phi_true -= phi_true.mean()
    f = lap2_apply(phi_true, H)
    phi = np.zeros_like(f)
    for _ in range(40):
        phi = v_cycle2(phi, f, H)
        phi -= phi.mean()
        if float(np.max(np.abs(f - lap2_apply(phi, H)))) < 1e-11*max(1.0, float(np.max(np.abs(f)))):
            break
    err = float(np.max(np.abs(phi - phi_true)))
    scale = max(1.0, float(np.max(np.abs(phi_true))))
    ok = np.isfinite(err) and err < 1e-6*scale
    print(f'  2D exact recovery: {err/scale:.2e}  -> {"PASS" if ok else "FAIL"}')
    assert ok

def validate_projection2(n=32, seed=7):
    axes, dx = make_grid2(n)
    g = np.random.default_rng(seed)
    V = g.standard_normal((2, n, n, 2))
    for _ in range(6):
        for a in (1, 2):
            V = 0.5*V + 0.25*(np.roll(V, -1, axis=a) + np.roll(V, 1, axis=a))
    E0 = float(np.sum(V*V))
    Vp, _, _, _, cycles, resid = project_bundle2(V, dx, 'channels',
                                                 None, 1e-10, 30)
    d1 = float(np.max(np.abs(div2(Vp, dx))))
    ok_a = np.isfinite(resid) and resid < 1e-8
    ok_b = np.isfinite(d1) and d1 <= max(1e-9, 1e-6*float(np.max(np.abs(div2(V, dx)))))
    ok_c = float(np.sum(Vp*Vp)) <= E0*(1.0 + 1e-6)
    print(f'  2D channels ({cycles} cy): resid {resid:.1e} '
          f'{"PASS" if ok_a else "FAIL"}  div {d1:.1e} '
          f'{"PASS" if ok_b else "FAIL"}  energy '
          f'{float(np.sum(Vp*Vp))/E0:.6f} {"PASS" if ok_c else "FAIL"}')
    Vf, _, _, _, cf, _ = project_bundle2(V, dx, 'fused', None, 1e-10, 30)
    wt1 = float(np.max(np.abs(div2(Vf[0]+Vf[1], dx))))
    dpres = float(np.max(np.abs(0.5*(Vf[0]-Vf[1]) - 0.5*(V[0]-V[1]))))
    ok_e = (wt1 <= max(1e-9, 1e-6*float(np.max(np.abs(div2(V[0]+V[1], dx)))))
            and dpres < 1e-12 and float(np.sum(Vf*Vf)) <= E0*(1.0+1e-6))
    print(f'  2D fused   ({cf} cy): div(m) {wt1:.1e}  |d\'-d| {dpres:.1e}  '
          f'-> {"PASS" if ok_e else "FAIL"}')
    assert ok_a and ok_b and ok_c and ok_e

print('\n' + '='*79)
print('BRIDGE GATES — 3D and 2D stacks')
print('='*79)
validate_solver(16)
validate_projection(32)
validate_solver2(16)
validate_projection2(32)

# =============================================================================
# SECTION 4 — METERS (validated v12)
# =============================================================================
def _fine_comp(comp, dim):
    if dim == 2:
        coarse = spread2(restrict2(comp))
    else:
        coarse = spread3(restrict(comp))
    E = float(np.sum(comp*comp))
    Ef = float(np.sum((comp-coarse)*(comp-coarse)))
    return E, Ef

def fine_frac(f, dim):
    E = Ef = 0.0
    for i in range(f.shape[-1]):
        a, b = _fine_comp(f[..., i], dim)
        E += a; Ef += b
    return Ef / max(E, 1e-300)

def pair_fine_frac(gu, gp, dim):
    E = Ef = 0.0
    for f in (gu, gp):
        for i in range(f.shape[-1]):
            a, b = _fine_comp(f[..., i], dim)
            E += a; Ef += b
    return Ef / max(E, 1e-300)

def leak_rel(u, m, dx, dim):
    if dim == 2:
        w = curl2(u, dx)
        aw = advect_scalar2(w, m, dx)
    else:
        w = curl(u, dx)
        aw = advect_material(w, m, dx)
    num = abs(float(np.sum(w*aw)))
    den = (float(np.sqrt(np.sum(w*w)))
           * float(np.sqrt(np.sum(aw*aw))))
    return num / max(den, 1e-300)

def stretch3(u, dx, vol):
    G = grad_vec(u, dx)
    w = curl(u, dx)
    return float(np.sum(np.einsum('...i,...ij,...j->...', w, G, w))) * vol

def scale_energy(f, dim, level=0):
    """Per-component cascade band energies: total, after one coarsening
    (spread o restrict), after two. Bands: coarse = E2, mid = E1-E2,
    fine = E0-E1. Orthogonal decomposition (spread is restrict's
    adjoint), so band energies are exact and partition the total."""
    def coarse(c):
        if dim == 2:
            return spread2(restrict2(c))
        return spread3(restrict(c))
    e_tot = e1 = e2 = 0.0
    for i in range(f.shape[-1]):
        c = f[..., i]
        e_tot += float(np.sum(c*c))
        c1 = coarse(c)
        e1 += float(np.sum(c1*c1))
        c2 = coarse(c1)
        e2 += float(np.sum(c2*c2))
    return e_tot, e1, e2

# =============================================================================
# SECTION 5 — AXIOM R: COARSE-GRAINED RETURN OPERATOR (v13.1 fixed)
# =============================================================================
def return_op(u, p, Pd, tension, threshold, R_coh, kappa, dt, vol, dim,
              coarse=True):
    """XI — return operator, v13.1 COARSE variant. Injection direction =
    block-coarse partner field, computed PER COMPONENT (spread/restrict
    act on scalar spatial fields; calling them on the vector bundle
    reshapes across the component axis — the v13 latent bug, fixed).
    Returned energy enters at scale > 2dx: the pressure-work analogy.

    Gate: tension < threshold (disjoint from Omega). Rate: exponential
    drain of R_coh, weight ~ tension deficit. Magnitude: exact energy
    match (quadratic root). Momentum exact by construction (d-only).
    coarse=False reproduces the v12 pointwise Xi (control)."""
    D = np.maximum(threshold - tension, 0.0)
    ok = (D > 0.0) & (np.sum(Pd*Pd, axis=-1) > 1e-28)
    if R_coh <= 0.0 or not ok.any():
        return u, p, 0.0, R_coh, 0.0, 0.0
    if coarse:
        Pdc = np.empty_like(Pd)
        for i in range(Pd.shape[-1]):
            comp = Pd[..., i]
            if dim == 2:
                Pdc[..., i] = spread2(restrict2(comp))
            else:
                Pdc[..., i] = spread3(restrict(comp))
        ok = ok & (np.sum(Pdc*Pdc, axis=-1) > 1e-28)
        if not ok.any():
            return u, p, 0.0, R_coh, 0.0, 0.0
    else:
        Pdc = Pd
    W = min(R_coh, kappa*dt*R_coh)
    wgt = np.where(ok, D, 0.0)
    tot = float(wgt.sum())
    if tot <= 0.0:
        return u, p, 0.0, R_coh, 0.0, 0.0
    e = W * wgt / tot                       # requested energy per point
    m = u + p
    d = 0.5 * (u - p)
    Pn = np.sqrt(np.sum(Pdc*Pdc, axis=-1))
    ehat = Pdc / np.maximum(Pn, 1e-30)[..., None]
    dd_ = np.sum(d*ehat, axis=-1)
    alpha = np.where(ok, -dd_ + np.sqrt(dd_*dd_ + e/vol), 0.0)
    d = d + alpha[..., None]*ehat
    u_new = 0.5*m + d
    p_new = 0.5*m - d
    dS = 4.0*alpha*dd_ + 2.0*alpha*alpha
    dE = 0.5*vol*float(np.sum(dS))
    return u_new, p_new, dE, R_coh - dE, abs(dE - W), e

# =============================================================================
# SECTION 6 — SHARED DRIVER
# =============================================================================
@dataclass
class RunResult:
    label: str; name: str; dim: int; mode: str; use_omega: bool
    nu: float; gain: float; n: int; xi_at: object; kappa: float
    xi_coarse: bool
    steps_hist: np.ndarray; times: np.ndarray
    E: np.ndarray; Eu: np.ndarray; Ep: np.ndarray
    Zu: np.ndarray; Zp: np.ndarray
    R_coh: np.ndarray; R_dis: np.ndarray; Et: np.ndarray
    max_w: np.ndarray; mom_drift: np.ndarray; routes: np.ndarray
    fine_u: np.ndarray; fine_p: np.ndarray
    leak: np.ndarray; stretch: np.ndarray; t_act: np.ndarray
    omega_err: float; E0: float
    visc_cum: float; euler2_cum: float; proj_cum: float; xi_cum: float
    closure_max: float; cons_err: float; xi_match: float
    finite: bool; failure_step: int; wall: float

def run_ns(dim, label, name, use_omega, nu, mode, n, steps, dt,
           amplitude, harmonic, thresh_frac, gain, xi_at=None, kappa=2.0,
           xi_coarse=True, proj_tol=1e-9, diag_every=5, report_every=50,
           quiet=False):
    if not quiet:
        print('\n' + '='*79)
        print(name)
        print(f'  dim={dim}  grid={n}  steps={steps}  dt={dt}  nu={nu}  '
              f'Omega={"ON" if use_omega else "OFF"}  mode={mode}  '
              f'gain={gain:.4g}  xi_at={xi_at}  kappa={kappa}  '
              f'xi_coarse={xi_coarse}')
        print('='*79)
    t0 = time.time()
    if dim == 2:
        axes, dx = make_grid2(n)
        vol = dx*dx
        u = initial_field2(axes, amplitude, harmonic)
        jacobian, omega = nth_jacobian2, omega_transfer2
        lap, advect, vort = lap_vec2, advect_material2, curl2
        project, max_cyc = project_bundle2, 30
        proj_field_axes = (0, 1)
    else:
        axes, dx = make_grid(n)
        vol = dx**3
        u = initial_selector_field(axes, amplitude, harmonic)
        jacobian, omega = nth_jacobian, omega_transfer_nth
        lap, advect, vort = lap_vec, advect_material, curl
        project, max_cyc = project_bundle, 20
        proj_field_axes = (0, 1, 2)
    p = np.zeros_like(u)
    pstats = ProjStats()
    V, _, _, _, _, _ = project(np.stack([u, p]), dx, 'channels',
                               None, proj_tol, max_cyc, pstats)
    u, p = V[0], V[1]
    phi = None
    jac0 = jacobian(u, dx)
    threshold = thresh_frac * float(np.max(jac0.tension))
    E0 = 0.5*float(np.sum(u*u + p*p))*vol
    mom0 = np.sum(u + p, axis=proj_field_axes)*vol
    mom_n0 = max(1.0, float(np.sqrt(np.sum(mom0*mom0))))
    if not quiet:
        print(f'  initial peak tension = {float(np.max(jac0.tension)):.4f}'
              f'  ->  threshold = {threshold:.4f}   E0 = {E0:.4f}')

    keys = ['step', 't', 'E', 'Eu', 'Ep', 'Zu', 'Zp', 'Rc', 'Rd', 'Et',
            'max_w', 'mom', 'routes', 'fu', 'fp', 'leak', 'stretch', 'tact']
    hist = {k: [] for k in keys}
    phase = np.full(u.shape[:-1], 'Real', dtype='<U6')
    R_coh = R_dis = 0.0
    visc_cum = euler2_cum = proj_cum = xi_cum = 0.0
    closure_max = xi_match = max_omega_err = 0.0
    last_tact = 0.0
    finite, failure_step = True, -1

    def record(idx):
        wu, wp = vort(u, dx), vort(p, dx)
        Eu_ = 0.5*float(np.sum(u*u))*vol
        Ep_ = 0.5*float(np.sum(p*p))*vol
        mom = np.sum(u + p, axis=proj_field_axes)*vol
        hist['step'].append(idx)
        hist['t'].append(idx*dt)
        hist['E'].append(Eu_ + Ep_)
        hist['Eu'].append(Eu_); hist['Ep'].append(Ep_)
        hist['Zu'].append(0.5*float(np.sum(wu*wu))*vol)
        hist['Zp'].append(0.5*float(np.sum(wp*wp))*vol)
        hist['Rc'].append(R_coh); hist['Rd'].append(R_dis)
        hist['Et'].append(Eu_ + Ep_ + R_coh + R_dis)
        hist['max_w'].append(float(np.max(np.abs(wu))))
        hist['mom'].append(float(np.sqrt(np.sum((mom-mom0)**2)))/mom_n0)
        hist['routes'].append(int(np.count_nonzero(phase != 'Real')))
        hist['fu'].append(fine_frac(u, dim))
        hist['fp'].append(fine_frac(p, dim) if Ep_ > 1e-300 else 0.0)
        hist['leak'].append(leak_rel(u, u + p, dx, dim))
        hist['stretch'].append(stretch3(u, dx, vol) if dim == 3 else 0.0)
        hist['tact'].append(last_tact)

    record(0)
    E_prev = E0

    for step in range(steps):
        jac = jacobian(u, dx)
        Lu, Lp = lap(u, dx), lap(p, dx)
        ev = float(np.sum(u*Lu + p*Lp))
        m_cur = u + p
        au, ap = advect(u, m_cur, dx), advect(p, m_cur, dx)
        F_u = -au + nu*Lu
        F_p = -ap + nu*Lp
        euler2 = 0.5*vol*dt*dt*float(np.sum(F_u*F_u + F_p*F_p))
        visc = vol*dt*nu*ev
        u_s = u + dt*F_u
        p_s = p + dt*F_p

        routes = 0
        if use_omega:
            u_s, p_s, phase, routes, oerr, aud = omega(
                u_s, p_s, jac, dx, threshold, gain)
            if np.isfinite(oerr):
                max_omega_err = max(max_omega_err, oerr)
            if np.isfinite(aud['t_mean']):
                last_tact = aud['t_mean']

        if xi_at is not None and step == xi_at and step > 0 and not quiet:
            print(f'  --- XI ACTIVATION at step {step} '
                  f'(R_coh={R_coh:.3f}, R_dis={R_dis:.3f}) ---')
        if xi_at is not None and step >= xi_at:
            d_cur = 0.5*(u_s - p_s)
            if dim == 2:
                Pd = np.stack([-d_cur[..., 1], d_cur[..., 0]], axis=-1)
            else:
                Pd = partner(unreal_mirror(dominant_axis3(jac, dx)), d_cur)
            u_s, p_s, xi_dE, R_coh, xerr, _ = return_op(
                u_s, p_s, Pd, jac.tension, threshold, R_coh, kappa,
                dt, vol, dim, coarse=xi_coarse)
            xi_match = max(xi_match, xerr)
            xi_cum += xi_dE
        else:
            xi_dE = 0.0

        Vp, gu, gp, phi, cycles, resid = project(
            np.stack([u_s, p_s]), dx, mode, phi, proj_tol, max_cyc, pstats)
        u, p = Vp[0], Vp[1]
        if not (np.all(np.isfinite(u)) and np.all(np.isfinite(p))):
            finite, failure_step = False, step
            print(f'  step {step+1}: NON-FINITE -> HALTED, nothing '
                  f'repaired. (A finding, not a crash, for scan runs.)')
            break

        dE_proj = 0.5*vol*float(np.sum(2*u_s*gu + gu*gu + 2*p_s*gp + gp*gp))
        phd = pair_fine_frac(gu, gp, dim)
        R_coh += (-dE_proj)*(1.0 - phd)
        R_dis += (-dE_proj)*phd

        E_now = 0.5*float(np.sum(u*u + p*p))*vol
        closure = (E_now - E_prev) - visc - euler2 - dE_proj - xi_dE
        closure_max = max(closure_max, abs(closure))
        visc_cum += visc; euler2_cum += euler2; proj_cum += dE_proj
        E_prev = E_now

        if (step+1) % diag_every == 0 or step == steps-1:
            record(step+1)
        if step % report_every == 0 or step == steps-1:
            if not quiet:
                cfl = float(np.sqrt(np.max(np.sum(u*u, axis=-1))))*dt/dx
                print(f'  step {step+1:4d}  t={(step+1)*dt:7.3f}  '
                      f'E={hist["E"][-1]:10.3f}  Rc={R_coh:8.3f}  '
                      f'Rd={R_dis:8.3f}  E+R={hist["Et"][-1]:10.3f}  '
                      f'Zu={hist["Zu"][-1]:10.2f}  '
                      f'max|w|={hist["max_w"][-1]:9.3f}  CFL={cfl:6.3f}  '
                      f'routes={routes}')

    wall = time.time() - t0
    Et = np.asarray(hist['Et'], dtype=float)
    if finite:
        cons_err = abs((Et[-1] - Et[0]) - visc_cum - euler2_cum)
    else:
        cons_err = float('nan')
    arr = lambda k: np.asarray(hist[k], dtype=float)
    res = RunResult(label, name, dim, mode, use_omega, nu, gain, n,
                    xi_at, kappa, xi_coarse, arr('step'), arr('t'),
                    arr('E'), arr('Eu'), arr('Ep'), arr('Zu'), arr('Zp'),
                    arr('Rc'), arr('Rd'), arr('Et'), arr('max_w'),
                    arr('mom'), arr('routes'), arr('fu'), arr('fp'),
                    arr('leak'), arr('stretch'), arr('tact'),
                    max_omega_err, E0, visc_cum, euler2_cum, proj_cum,
                    xi_cum, closure_max, cons_err, xi_match, finite,
                    failure_step, wall)
    if not quiet:
        print(f'  -> finite={finite}  Omega_err={max_omega_err:.2e}  '
              f'Rc={R_coh:.3f}  Rd={R_dis:.3f}  xi_cum={xi_cum:.3f}  '
              f'xi_match={xi_match:.1e}  cons_err={cons_err:.2e}  '
              f'closure={closure_max:.2e}  wall={wall:.1f}s')
    return res

# =============================================================================
# SECTION 7 — CONTINUUM GATES (v13.1 fixed)
# =============================================================================
def gate_submanifold():
    """GATE G1 — SUB-MANIFOLD THEOREM ('vanishing deficit', correctly
    stated). v13.1 fix: the sub-manifold check uses an UNREACHABLE
    threshold (1e6 x initial peak). The shipped 0.95 margin was wrongly
    called 'provably inactive' — tension grows past its initial peak in
    this flow (v11: max|w| x1.77), so 0.95 ACTIVATES Omega and the gate
    would have failed its own assert. With the unreachable threshold the
    transfer is exactly the identity and the trajectories must agree to
    floating-point non-associativity. The margin scan (0.95/0.85/0.75)
    then measures genuine, threshold-gated departure."""
    print('\n' + '='*79)
    print('GATE G1 — SUB-MANIFOLD: transfer inactive => selector == classical')
    print('='*79)
    common = dict(dim=3, nu=0.0, mode='channels', n=32, steps=250,
                  dt=0.004, amplitude=2.0, harmonic=0.7, gain=10.0)
    rA = run_ns(label='G1 classical', name='G1-A classical reference',
                use_omega=False, thresh_frac=0.95, quiet=False, **common)
    rB = run_ns(label='G1 omega-quiet',
                name='G1-B Omega ON, threshold UNREACHABLE (never active)',
                use_omega=True, thresh_frac=1e6, quiet=False, **common)
    n_rec = min(len(rA.times), len(rB.times))
    dev = np.max(np.abs(rA.E[:n_rec] - rB.E[:n_rec]))/max(rA.E0, 1e-300)
    routes_B = int(np.max(rB.routes))
    print(f'\n  trajectory deviation (E): {dev:.2e}   '
          f'max routes in Omega-quiet run: {routes_B}')
    ok = (dev < 1e-10) and (routes_B == 0)
    if ok:
        print('  -> PASS: the classical sub-manifold is an exact invariant '
              'of the selector system (deviation ~ roundoff, zero routes)')
    else:
        print('  -> FAIL')
    assert ok, ('Sub-manifold failure: Omega activated at an unreachable '
                'threshold, or trajectories diverged — implementation error.')
    margins = []
    for tf in (0.95, 0.85, 0.75):
        rM = run_ns(label=f'G1 m={tf:.2f}',
                    name=f'G1 margin {tf:.2f} — departure vs threshold',
                    use_omega=True, thresh_frac=tf, quiet=True, **common)
        n_rec = min(len(rA.times), len(rM.times))
        dev_m = np.max(np.abs(rA.E[:n_rec] - rM.E[:n_rec]))/max(rA.E0, 1e-300)
        margins.append((tf, dev_m, float(rM.Ep[-1])))
        print(f'  margin {tf:.2f}: max |E - E_classical|/E0 = {dev_m:.3e}'
              f'   final phase energy {float(rM.Ep[-1]):.4f}')
    print('  READING: departure is exactly zero while the transfer is')
    print('  inactive (the sub-manifold), and threshold-gated below:')
    print('  the classical solution is an exact invariant sub-manifold of')
    print('  the selector system; departures occur ONLY through')
    print('  threshold-crossing events. This is the vanishing-deficit')
    print('  statement the data supports — not convergence of the active')
    print('  selector dynamics to classical NS, which v12 refuted.')
    return rA, margins

def gate_spectral():
    """GATE G2 — SCALE-STRUCTURED TRANSFER AUDIT (no FFT). Synthetic
    multi-scale selector state; transfer forced active (threshold 0).
    Band energies via the cascade's restrict/spread pair at two levels:
    coarse (>4dx, survives two coarsenings), mid (2-4dx), fine (<2dx).
    v13.1 fix: the fine component is built PER COMPONENT (the shipped
    version called restrict on the vector bundle — reshape crash)."""
    print('\n' + '='*79)
    print('GATE G2 — SCALE-STRUCTURED TRANSFER AUDIT (no FFT)')
    print('='*79)
    for dim, n in ((3, 32), (2, 128)):
        if dim == 3:
            axes, dx = make_grid(n)
            u = initial_selector_field(axes, 1.0, 0.7)
            jacobian = nth_jacobian
            omega = omega_transfer_nth
        else:
            axes, dx = make_grid2(n)
            u = initial_field2(axes, 1.0, 0.7)
            jacobian = nth_jacobian2
            omega = omega_transfer2
        rngm = np.random.default_rng(11)
        d_fine = rngm.standard_normal(u.shape)
        for _ in range(2):
            for a_ in range(u.ndim - 1):
                d_fine = 0.5*d_fine + 0.25*(np.roll(d_fine, -1, axis=a_)
                                             + np.roll(d_fine, 1, axis=a_))
        for i in range(d_fine.shape[-1]):          # v13.1: per component
            comp = d_fine[..., i]
            if dim == 3:
                d_fine[..., i] = comp - spread3(restrict(comp))
            else:
                d_fine[..., i] = comp - spread2(restrict2(comp))
        d = 0.8*u + 0.25*d_fine
        u_s = d.copy()
        p_s = -d.copy()              # m = 0; d is the multi-scale state
        jac = jacobian(u_s, dx)
        e_tot0, e1_0, e2_0 = scale_energy(d, dim)
        u2, p2, _, routes, oerr, aud = omega(u_s, p_s, jac, dx, 0.0, 10.0)
        d2 = 0.5*(u2 - p2)
        e_tot1, e1_1, e2_1 = scale_energy(d2, dim)
        coarse0, coarse1 = e2_0, e2_1
        mid0, mid1 = e1_0 - e2_0, e1_1 - e2_1
        fine0, fine1 = e_tot0 - e1_0, e_tot1 - e1_1
        print(f'\n  dim={dim}  n={n}  routes={routes} '
              f'(threshold 0 -> fully active)')
        print('  band energies (before -> after one transfer):')
        print(f'    coarse (>4dx): {coarse0:10.4f} -> {coarse1:10.4f}   '
              f'ratio {coarse1/max(coarse0,1e-300):.4f}')
        print(f'    mid  (2-4dx) : {mid0:10.4f} -> {mid1:10.4f}   '
              f'ratio {mid1/max(mid0,1e-300):.4f}')
        print(f'    fine (<2dx)  : {fine0:10.4f} -> {fine1:10.4f}   '
              f'ratio {fine1/max(fine0,1e-300):.4f}')
        print(f'    total        : {e_tot0:10.4f} -> {e_tot1:10.4f}   '
              f'ratio {e_tot1/max(e_tot0,1e-300):.6f}  '
              f'(invariant {oerr:.1e})')
        cr = coarse1/max(coarse0, 1e-300)
        fr = fine1/max(fine0, 1e-300)
        cr_ok = abs(cr - 1.0) < 0.15
