def _xi_index(r):
    """Activation index with bound guard (v13.1)."""
    return min(int(np.searchsorted(r.steps_hist, r.xi_at))
               if r.xi_at is not None else 0, len(r.steps_hist) - 1)

def _persistence(r):
    """Persistence = (actual drain - control drain)/xi_cum, where the
    control drain extrapolates the pre-activation slope (the first
    xi_at steps are the exact CH control). Same definition as the v12
    analysis baseline (pointwise 3D: ~11%)."""
    i = _xi_index(r)
    pre = r.E[:i+1]
    slope = (pre[-1] - pre[-2]) if len(pre) >= 3 else 0.0
    n_post = len(r.E) - 1 - i
    ctrl_drain = slope*n_post
    actual = r.E[-1] - r.E[i]
    persist = (actual - ctrl_drain)/max(r.xi_cum, 1e-300)
    return ctrl_drain, actual, persist

def audit():
    L = '='*79
    print('\n' + L)
    print('AUDIT [W1-W5] — v13.1 verdicts')
    print(L)

    print('[W1] CLEAN PUMP SCAN (constant CFL 0.06):')
    for r in (rP32, rP64):
        gw = float(np.max(r.max_w))/max(float(r.max_w[0]), 1e-30)
        ge = r.E[-1]/r.E0
        print(f'  [{r.label:14s}] E x{ge:8.3f}   max|w| x{gw:7.2f}   '
              f'euler2 share '
              f'{100.0*r.euler2_cum/max(r.E[-1]-r.E0,1e-300):6.1f}%   '
              f'routes {int(r.routes[-1])}')
    g32 = float(np.max(rP32.max_w))/max(float(rP32.max_w[0]), 1e-30)
    g64 = float(np.max(rP64.max_w))/max(float(rP64.max_w[0]), 1e-30)
    if (not rP64.finite) or g64 > 1.8*g32:
        print(f'  -> SPATIAL PUMP CONFIRMED at constant CFL: max|w| growth '
              f'x{g32:.2f} (n=32) vs x{g64:.2f} (n=64). The 1/dx gradient '
              'pump is REAL and independent of time-stepping.')
        print('     Consequence: the fused transfer has no continuum limit '
              'without a spatial-regularity axiom on the rotation angle;')
        print('     the CH toll is load-bearing. This is a Part 2 result.')
    elif abs(g64 - g32)/max(g32, 1e-9) < 0.3:
        print(f'  -> NO SPATIAL PUMP at constant CFL (x{g32:.2f} vs '
              f'x{g64:.2f}): the v12 acceleration was the CFL^2 confound. '
              'Fused-mode growth is a time-integration artifact; the')
        print('     fix is exact (Cayley) time stepping, and fused mode is '
              'salvageable in principle. Honest and important.')
    else:
        print(f'  -> SUB-LINEAR: x{g32:.2f} vs x{g64:.2f}. Partial '
              'regularization; report as found.')

    print('\n[W2] COARSE vs POINTWISE XI (persistence, control-offset):')
    for r in (rRET3c, rRET2c, rRET3p):
        i = _xi_index(r)
        ctrl_drain, actual, persist = _persistence(r)
        print(f'  [{r.label:14s}] xi_cum={r.xi_cum:7.3f}  '
              f'Rc {float(r.R_coh[i]):6.3f}->{float(r.R_coh[-1]):6.3f}  '
              f'Rd {float(r.R_dis[i]):6.3f}->{float(r.R_dis[-1]):6.3f}')
        print(f'                   control drain {ctrl_drain:8.3f}  '
              f'actual {actual:8.3f}   '
              f'PERSISTENCE (offset/xi) {persist:+.3f}')
    _, _, pp = _persistence(rRET3p)
    _, _, pc = _persistence(rRET3c)
