    order = np.argsort(rates)
    for j in order:
        i = idx[j]
        ax.plot(r_a[i]*np.cos(th_a[i]), r_a[i]*np.sin(th_a[i]),
                lw=0.7, alpha=0.8,
                color=plt.cm.viridis(min(rates[j]/vmax, 1.0)))
    th_g = np.linspace(0.0, 6*np.pi, 600)
    r_g = 0.95*L_half*np.exp(-th_g*np.tan(GOLDEN_PITCH))
