    for j in order:
        i = idx[j]
        ax.plot(r_a[i]*np.cos(th_a[i]), r_a[i]*np.sin(th_a[i]),
                lw=0.6, alpha=0.75,
                color=plt.cm.viridis(min(rates[j]/vmax, 1.0)))
    ax.add_patch(plt.Circle((0, 0), L_half, fill=False, color='k',
                            ls=':', lw=1))
    ax.plot([0], [0], 'k+', ms=9)
    ax.set_title(title, fontsize=10)
    ax.set_aspect('equal')
    ax.grid(alpha=0.2)

