def channel_series(r_a, tags, k, min_count):
    series = np.full(S_run, np.nan)
    occ = np.zeros(S_run, dtype=int)
    for s in range(S_run):
        sel = msk & (tags[:, s] == k)
        occ[s] = int(sel.sum())
        if occ[s] >= min_count:
            series[s] = float(np.mean(r_a[sel, s]))
    return series, occ

def pipe_det(series):
    """The v17 pipeline exactly: NaN-interp, downsample, recurrence."""
    good = ~np.isnan(series)
    if good.sum() < 40:
        return None
    si = np.interp(np.arange(S_run), np.where(good)[0], series[good])
    stride = max(1, S_run//120)
    sub = si[::stride]
    if len(sub) < 30:
        return None
    rr_, det_, rrs, dets_ = recurrence_analysis(sub)
    return det_, dets_

