def compactify(tracks):
    N, _, S = tracks.shape
    R = L_half
    r_all = np.empty((N, S))
    th_all = np.empty((N, S))
    for i in range(N):
        rx = (tracks[i, 0, :] - np.pi + L_half) % L_dom - L_half
        ry = (tracks[i, 1, :] - np.pi + L_half) % L_dom - L_half
        th_all[i] = np.unwrap(np.arctan2(ry, rx))
        zm = tracks[i, 2, :] % L_dom
        r_all[i] = R*(1.0 - zm/L_dom)
    return r_all, th_all

rC, thC = compactify(trkC)
