# =============================================================================
# SECTION 1 — SELECTOR SPECTRA (verbatim, validated)
# =============================================================================
P_REAL, P_UNREAL = '1', 'i'

def t_spectrum(g):
    num = [(g, P_REAL), (g, P_UNREAL)]
    den = [(1.0+g, P_REAL), (1.0+g, P_REAL),
           (1.0+g, P_UNREAL), (1.0+g, P_UNREAL)]
    return num, den, g/(1.0+g)

def cs_spectra(t):
    arms = [(t*t, P_REAL), (t*t, P_UNREAL),
            (t*t, P_UNREAL), (t*t, P_UNREAL)]
    leads = [(1.0, P_REAL), (1.0, P_UNREAL)]
    num_c = [(lm-am, lp) for (lm, lp) in leads for (am, ap) in arms]
    den_c = [(lm+am, lp) for (lm, lp) in leads for (am, ap) in arms]
    num_s = [(2.0*t, ph) for (am, ph) in arms]
    return num_c, den_c, num_s

def collapse_check(num, den, ref):
    worst = 0.0
    for (nm, nph) in num:
        for (dm, dph) in den:
            worst = max(worst, abs(nm/dm - ref))
    return worst

def angle_selector(g):
    t = g/(1.0+g)
    return t, (1.0-t*t)/(1.0+t*t), (2.0*t)/(1.0+t*t)

def spectra_audit(g=0.6):
    num, den, t_ref = t_spectrum(g)
    num_c, den_c, num_s = cs_spectra(t_ref)
    c_ref = (1.0-t_ref*t_ref)/(1.0+t_ref*t_ref)
    s_ref = 2.0*t_ref/(1.0+t_ref*t_ref)
    print(f'spectra collapse: t {collapse_check(num,den,t_ref):.1e}  '
          f'c {collapse_check(num_c,den_c,c_ref):.1e}  '
          f's {collapse_check(num_s,den_c,s_ref):.1e}  '
          f'circle {abs(c_ref*c_ref+s_ref*s_ref-1.0):.1e}')

spectra_audit()

# =============================================================================
# SECTION 2 — 3D STACK (verbatim, validated)
# =============================================================================
def make_grid(n, length=2.0*np.pi):
    assert n >= 4 and (n & (n-1)) == 0, 'grid must be a power of two'
    x = np.linspace(0.0, length, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), length/n

def dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis))*(0.5/dx)

def grad_vec(u, dx):
    gu = np.empty(u.shape + (3,))
    for i in range(3):
        for j in range(3):
            gu[..., i, j] = dd(u[..., i], j, dx)
    return gu

def curl(u, dx):
    g = grad_vec(u, dx)
    w = np.empty_like(u)
    w[..., 0] = g[..., 2, 1] - g[..., 1, 2]
    w[..., 1] = g[..., 0, 2] - g[..., 2, 0]
    w[..., 2] = g[..., 1, 0] - g[..., 0, 1]
    return w

def lap_vec(u, dx):
    out = np.empty_like(u)
    inv = 1.0/(dx*dx)
    for i in range(3):
        f = u[..., i]
        out[..., i] = (-6.0*f + np.roll(f, -1, 0) + np.roll(f, 1, 0)
                       + np.roll(f, -1, 1) + np.roll(f, 1, 1)
                       + np.roll(f, -1, 2) + np.roll(f, 1, 2))*inv
    return out

def advect_material(f, v, dx):
    out = np.zeros_like(f)
    for i in range(3):
        fi = f[..., i]
        acc = np.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc += 0.5*(dd(vj*fi, j, dx) + vj*dd(fi, j, dx))
        out[..., i] = acc
    return out

@dataclass
class JacobianChannels:
    R: np.ndarray; U: np.ndarray; C1: np.ndarray; C2: np.ndarray
    vort: np.ndarray; tension: np.ndarray

def nth_jacobian(u, dx):
    G = grad_vec(u, dx)
    S_ = 0.5*(G + np.swapaxes(G, -1, -2))
    A_ = 0.5*(G - np.swapaxes(G, -1, -2))
    C1 = np.sqrt(np.sum(S_*S_, axis=(-2, -1)))
    C2 = np.sqrt(np.sum(A_*A_, axis=(-2, -1)))
    a, b, c = G[..., 0, 0], G[..., 0, 1], G[..., 0, 2]
    d, e, f = G[..., 1, 0], G[..., 1, 1], G[..., 1, 2]
    g, h, i = G[..., 2, 0], G[..., 2, 1], G[..., 2, 2]
    R = a*(e*i - f*h) - b*(d*i - f*g) + c*(d*h - e*g)
    U = np.sqrt(np.sum(G*G, axis=(-2, -1))) - np.abs(R)
    vort = np.stack([G[..., 2, 1] - G[..., 1, 2],
                     G[..., 0, 2] - G[..., 2, 0],
                     G[..., 1, 0] - G[..., 0, 1]], axis=-1)
    return JacobianChannels(R, U, C1, C2, vort, C1 + C2 + np.abs(R))

def unreal_mirror(axis):
    a1, a2, a3 = (axis[..., 0], axis[..., 1], axis[..., 2])
    M = np.zeros(axis.shape[:-1] + (3, 3))
    M[..., 0, 1] = -a3; M[..., 0, 2] =  a2
    M[..., 1, 0] =  a3; M[..., 1, 2] = -a1
    M[..., 2, 0] = -a2; M[..., 2, 1] =  a1
    return M

def partner(M, d):
    return np.einsum('...ij,...j->...i', M, d)

def dominant_axis3(jac, dx):
    rot_dom = jac.C2 > jac.C1
    wn = np.sqrt(np.sum(jac.vort*jac.vort, axis=-1))
    gs = np.stack([dd(jac.C1, a, dx) for a in (0, 1, 2)], axis=-1)
    gn = np.sqrt(np.sum(gs*gs, axis=-1))
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    axis = np.zeros_like(jac.vort)
    if use_v.any():
        axis[use_v] = (jac.vort/np.maximum(wn, 1e-30)[..., None])[use_v]
    if use_g.any():
        axis[use_g] = (gs/np.maximum(gn, 1e-30)[..., None])[use_g]
    return axis

def omega_transfer_nth(u, p, jac, dx, threshold, gain):
    """Returns SIX values: (u_new, p_new, phase, routes, err, aud)."""
    excess = np.maximum(jac.tension - threshold, 0.0)
    active = excess > 0.0
    g = gain*excess*dx
    t, c, s = angle_selector(g)
    m = u + p
    d = 0.5*(u - p)
    M = unreal_mirror(dominant_axis3(jac, dx))
    Pd = partner(M, d)
    d_ax = d + partner(M, Pd)
    d_tr = d - d_ax
    Ptr = partner(M, d_tr)
    d_new = d_ax + c[..., None]*d_tr + s[..., None]*Ptr
    u_new = 0.5*m + d_new
    p_new = 0.5*m - d_new
    rdom = np.abs(jac.R) > np.maximum(jac.C1, jac.C2)
    rot_dom = jac.C2 > jac.C1
    phase = np.full(excess.shape, 'Real', dtype='<U6')
    phase[active & rdom] = 'C2'
    phase[active & ~rdom & rot_dom] = 'Unreal'
    phase[active & ~rdom & ~rot_dom] = 'C1'
    routes = int(np.count_nonzero(active))
    aud = {'g_max': float(np.max(g)),
           't_mean': float(np.mean(t[active])) if routes > 0 else 0.0}
    err_m = float(np.max(np.abs((u_new + p_new) - (u + p))))
    e0 = float(np.sum(u*u + p*p))
    e1 = float(np.sum(u_new*u_new + p_new*p_new))
    err_e = abs(e1 - e0)/max(abs(e0), 1e-300)
    return u_new, p_new, phase, routes, max(err_m, err_e), aud

# =============================================================================
# SECTION 3 — WHOLE-TERM CASCADE + GATES (verbatim, validated)
# =============================================================================
def restrict(F):
    a, b, c = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (a//2, 2, b//2, 2, c//2, 2)
                     ).mean(axis=(-5, -3, -1))

def _interp1(F, axis):
    n = F.shape[axis]
    shp = list(F.shape); shp[axis] = 2*n
    G = np.empty(shp, dtype=F.dtype)
    se = [slice(None)]*F.ndim; se[axis] = slice(0, 2*n, 2)
    G[tuple(se)] = F
    so = [slice(None)]*F.ndim; so[axis] = slice(1, 2*n, 2)
    G[tuple(so)] = 0.5*(F + np.roll(F, -1, axis=axis))
    return G

def prolong(C):
    F = _interp1(C, C.ndim - 3)
    F = _interp1(F, F.ndim - 2)
    F = _interp1(F, F.ndim - 1)
    return F

def lap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    for a in (F.ndim - 3, F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s*inv

_RBGS_CACHE = {}
def _rb_mask(m):
    if m not in _RBGS_CACHE:
        idx = np.indices((m, m, m))
        red = ((idx[0] + idx[1] + idx[2]) % 2 == 0)
        _RBGS_CACHE[m] = (red, ~red)
    return _RBGS_CACHE[m]

def smooth_gs(phi, f, dx, iters):
    c = dx*dx/6.0
    red, black = _rb_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - lap_apply(phi, dx)
        phi = phi - c*np.where(red, r, 0.0)
        r = f - lap_apply(phi, dx)
        phi = phi - c*np.where(black, r, 0.0)
    return phi

def v_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - f.mean(axis=(-3, -2, -1), keepdims=True)
        return smooth_gs(phi, f, dx, 40)
    phi = smooth_gs(phi, f, dx, 2)
    r = f - lap_apply(phi, dx)
    rc = restrict(r)
    ec = v_cycle(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + prolong(ec)
    return smooth_gs(phi, f, dx, 2)

def split_classes(f):
    N = f.shape[-1]
    M = N//2
    out = np.empty(f.shape[:-3] + (8, M, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                out[..., c, :, :, :] = f[..., a::2, b::2, d::2]
                c += 1
    return out

def merge_classes(g, N):
    f = np.empty(g.shape[:-4] + (N, N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                f[..., a::2, b::2, d::2] = g[..., c, :, :, :]
                c += 1
    return f

def div_bundle(V, dx):
    out = np.zeros(V.shape[:-1])
    for j in range(3):
        out += dd(V[..., j], V.ndim - 4 + j, dx)
    return out

def grad_bundle(phi, dx):
    return np.stack([dd(phi, phi.ndim - 3 + j, dx) for j in range(3)],
                    axis=-1)

@dataclass
class ProjStats:
    solves: int = 0; cycles_total: int = 0; cycles_max: int = 0
    worst_resid: float = 0.0

def project_bundle(V, dx, mode='channels', phi=None, tol=1e-9,
                   max_cycles=20, stats=None):
    """Returns SIX values: (Vp, gu, gp, phi_out, cycles, worst)."""
    f = -div_bundle(V, dx)
    fc = split_classes(f)
    H = 2.0*dx
    fc = fc - fc.mean(axis=(-3, -2, -1), keepdims=True)
    f0 = np.sqrt(np.sum(fc*fc, axis=(-3, -2, -1)))
    live = f0 > 1e-300
    fc = fc*live[..., None, None, None]
    if phi is None:
        psic = np.zeros_like(fc)
    else:
        psic = split_classes(phi)*live[..., None, None, None]
    psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
    cycles, worst = 0, 0.0
    if live.any():
        def rel_resid():
            r = fc - lap_apply(psic, H)
            rn = np.sqrt(np.sum(r*r, axis=(-3, -2, -1)))
            return float(np.max((rn/np.maximum(f0, 1e-300))[live]))
        worst = rel_resid()
        while worst >= tol and cycles < max_cycles:
            psic = v_cycle(psic, fc, H)
            psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
            cycles += 1
            worst = rel_resid()
    phi_out = merge_classes(psic, V.shape[-3])
    gu = grad_bundle(phi_out[0], dx)
    gp = grad_bundle(phi_out[1], dx)
    Vp = np.stack([V[0] + gu, V[1] + gp])
    if stats is not None and live.any():
        stats.solves += 1
        stats.cycles_total += cycles
        stats.cycles_max = max(stats.cycles_max, cycles)
        stats.worst_resid = max(stats.worst_resid, worst)
    return Vp, gu, gp, phi_out, cycles, worst

def validate_solver(m=16, seed=3):
    H = 0.4
    g = np.random.default_rng(seed)
    phi_true = g.standard_normal((m, m, m))
    for _ in range(6):
        for a in (0, 1, 2):
            phi_true = 0.5*phi_true + 0.25*(np.roll(phi_true, -1, axis=a)
                                            + np.roll(phi_true, 1, axis=a))
    phi_true -= phi_true.mean()
    f = lap_apply(phi_true, H)
    phi = np.zeros_like(f)
    for _ in range(30):
        phi = v_cycle(phi, f, H)
        phi -= phi.mean()
        if float(np.max(np.abs(f - lap_apply(phi, H)))) < \
                1e-11*max(1.0, float(np.max(np.abs(f)))):
            break
    err = float(np.max(np.abs(phi - phi_true)))
    scale = max(1.0, float(np.max(np.abs(phi_true))))
    ok = np.isfinite(err) and err < 1e-6*scale
    verdict = 'PASS' if ok else 'FAIL'
    print(f'  3D exact recovery: {err/scale:.2e}  -> {verdict}')
    assert ok

def validate_projection(n=32, seed=7):
    axes, dx = make_grid(n)
    g = np.random.default_rng(seed)
    V = g.standard_normal((2, n, n, n, 3))
    for _ in range(6):
        for a in (1, 2, 3):
            V = 0.5*V + 0.25*(np.roll(V, -1, axis=a) + np.roll(V, 1, axis=a))
    E0 = float(np.sum(V*V))
    Vp, _, _, _, cycles, resid = project_bundle(V, dx, 'channels',
                                                None, 1e-10, 25)
    d1 = float(np.max(np.abs(div_bundle(Vp, dx))))
    ok_a = np.isfinite(resid) and resid < 1e-8
    ok_b = np.isfinite(d1) and d1 <= max(1e-9,
        1e-6*float(np.max(np.abs(div_bundle(V, dx)))))
    ok_c = float(np.sum(Vp*Vp)) <= E0*(1.0 + 1e-6)
    va = 'PASS' if ok_a else 'FAIL'
    vb = 'PASS' if ok_b else 'FAIL'
    vc = 'PASS' if ok_c else 'FAIL'
    print(f'  3D channels ({cycles} cy): resid {resid:.1e} {va}  '
          f'div {d1:.1e} {vb}  energy '
          f'{float(np.sum(Vp*Vp))/E0:.6f} {vc}')
    assert ok_a and ok_b and ok_c

print('\n' + '='*79)
print('BRIDGE GATES')
print('='*79)
validate_solver(16)
validate_projection(32)

# =============================================================================
# SECTION 4 — WOUND-CORE IC + COMPOSITE-STATE TRACER
# =============================================================================
A_SWIRL = 6.0
W_GOLD = 12.0/PHI
SIGMA = 1.0
A_WIND = 0.35

def core_center(z):
    return (np.pi + A_WIND*np.sin(z), np.pi + A_WIND*np.sin(2.0*z))

def initial_wound_field(axes, w_axial):
    x, y, z = axes
    xc, yc = core_center(z)
    rx = x - xc
    ry = y - yc
    rx = (rx + L_half) % L_dom - L_half
    ry = (ry + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA*SIGMA))
    return np.stack([-A_SWIRL*ry*f, A_SWIRL*rx*f, w_axial*f], axis=-1)

def track_composite(n_uniform=400, n_core=150, steps=300, dt=0.004,
                    seed=42, use_omega=False, n=32, thresh_frac=0.5,
                    gain=10.0, w_axial=W_GOLD):
    """Tracks the COMPOSITE STATE per core tracer per step:
        s(t) = (theta_c, r_c,        # F1: compactified position
                U, R, C1, C2,        # F2: channel tuple magnitudes
                u_loc, p_loc)        # F3: local channel partition
    plus the ACTIVATION flag a(t) (F4): local tension > threshold.
    Returns (tracks, states, act, cohort, routes_total, thr):
      tracks (N,3,S); states (N,S,8); act (N,S) bool."""
    axes, dx = make_grid(n)
    L = L_dom
    u3 = initial_wound_field(axes, w_axial)
    p3 = np.zeros_like(u3)
    pstats = ProjStats()
    V, _, _, _, _, _ = project_bundle(np.stack([u3, p3]), dx, 'channels',
                                      None, 1e-9, 25, pstats)
    u3, p3 = V[0], V[1]
    phi_p = None
    jac0 = nth_jacobian(u3, dx)
    thr = thresh_frac*float(np.max(jac0.tension))
    rngt = np.random.default_rng(seed)
    pos_u = rngt.uniform(0.0, L, size=(n_uniform, 3))
    rr = 2.0*SIGMA*np.sqrt(rngt.uniform(0.0, 1.0, n_core))
    aa = rngt.uniform(0.0, TAU, n_core)
    zz = rngt.uniform(0.0, L, n_core)
    xc_c, yc_c = core_center(zz)
    pos_c = np.stack([xc_c + rr*np.cos(aa), yc_c + rr*np.sin(aa), zz],
                     axis=1) % L
    N = n_uniform + n_core
    cohort = np.zeros(N, dtype=int)
    cohort[n_uniform:] = 1
    pos = np.concatenate([pos_u, pos_c], axis=0)
    tracks = np.empty((N, 3, steps+1))
    tracks[:, :, 0] = pos
    states = np.empty((N, steps+1, 8))
    act = np.zeros((N, steps+1), dtype=bool)
    r0u = np.sqrt(((pos_u[:, 0] - np.pi + L_half) % L_dom - L_half)**2
                  + ((pos_u[:, 1] - np.pi + L_half) % L_dom - L_half)**2)
    n_near = int((r0u < 1.5).sum())
    print(f'    seeds: near-core {n_near}/400 (expected 70)')
    assert 40 <= n_near <= 110, f'SEED ANOMALY: {n_near}/400 — aborting.'
    assert np.array_equal(tracks[:n_uniform, :, 0], pos_u), \
        'SEED STORAGE MISMATCH — aborting.'
    routes_total = 0
    n_g = n

    def grid_at(q):
        """Grid indices + weights at particle positions."""
        qi = q/L*n_g
        x0 = np.floor(qi[:, 0]).astype(int) % n_g
        y0 = np.floor(qi[:, 1]).astype(int) % n_g
        z0 = np.floor(qi[:, 2]).astype(int) % n_g
        fx = qi[:, 0] - np.floor(qi[:, 0])
        fy = qi[:, 1] - np.floor(qi[:, 1])
        fz = qi[:, 2] - np.floor(qi[:, 2])
        return x0, y0, z0, fx, fy, fz

    def interp_field(comp, q):
        x0, y0, z0, fx, fy, fz = grid_at(q)

        def get(ix, iy, iz):
            return comp[ix % n_g, iy % n_g, iz % n_g]
        return (get(x0, y0, z0)*(1-fx)*(1-fy)*(1-fz)
                + get(x0+1, y0, z0)*fx*(1-fy)*(1-fz)
                + get(x0, y0+1, z0)*(1-fx)*fy*(1-fz)
                + get(x0, y0, z0+1)*(1-fx)*(1-fy)*fz
                + get(x0+1, y0+1, z0)*fx*fy*(1-fz)
                + get(x0+1, y0, z0+1)*fx*(1-fy)*fz
                + get(x0, y0+1, z0+1)*(1-fx)*fy*fz
                + get(x0+1, y0+1, z0+1)*fx*fy*fz)

    for step in range(steps):
        jac = nth_jacobian(u3, dx)
        mags = np.stack([jac.U, np.abs(jac.R), jac.C1, jac.C2], axis=-1)
        tension = jac.tension
        m = u3 + p3
        vel_src = u3
        # composite state at current positions
        xs = pos[:, 0]; ys = pos[:, 1]; zs = pos[:, 2]
        rx = (xs - np.pi + L_half) % L_dom - L_half
        ry = (ys - np.pi + L_half) % L_dom - L_half
        th_c = np.arctan2(ry, rx)
        r_c = L_half*(1.0 - (zs % L_dom)/L_dom)
        tup = np.stack([interp_field(mags[..., k], pos)
                        for k in range(4)], axis=-1)
        u_loc = np.sqrt(np.sum(interp_field(
            np.sqrt(np.sum(u3*u3, axis=-1)), pos)**2))
        u_mag = interp_field(np.sqrt(np.sum(u3*u3, axis=-1)), pos)
        p_mag = interp_field(np.sqrt(np.sum(p3*p3, axis=-1)), pos)
        states[:, step, 0] = np.cos(th_c)*L_half   # position as (x,y)
        states[:, step, 1] = np.sin(th_c)*L_half
        states[:, step, 2:6] = tup
        states[:, step, 6] = u_mag
        states[:, step, 7] = p_mag
        act[:, step] = interp_field(tension, pos) > thr
        # advect (RK2 on the Real channel — same as validated)
        def vel(q):
            v = np.empty_like(q)
            for c in range(3):
                v[:, c] = interp_field(vel_src[..., c], q)
            return v
        k1 = vel(pos)
        k2 = vel((pos + 0.5*dt*k1) % L)
        pos = (pos + dt*k2) % L
        tracks[:, :, step+1] = pos
        # field update (validated)
        au = advect_material(u3, m, dx)
        ap = advect_material(p3, m, dx)
        u_s = u3 + dt*(-au)
        p_s = p3 + dt*(-ap)
        if use_omega:
            u_s, p_s, _, routes, _, _ = omega_transfer_nth(
                u_s, p_s, jac, dx, thr, gain)
            routes_total += routes
        Vp, _, _, phi_p, _, _ = project_bundle(
            np.stack([u_s, p_s]), dx, 'channels', phi_p, 1e-9, 20, pstats)
        u3, p3 = Vp[0], Vp[1]
        if not (np.all(np.isfinite(u3)) and np.all(np.isfinite(p3))):
            print(f'    field non-finite at step {step+1}; halting.')
            break
    # final state
    jac_f = nth_jacobian(u3, dx)
    mags_f = np.stack([jac_f.U, np.abs(jac_f.R), jac_f.C1, jac_f.C2],
                      axis=-1)
    xs = pos[:, 0]; ys = pos[:, 1]; zs = pos[:, 2]
    rx = (xs - np.pi + L_half) % L_dom - L_half
    ry = (ys - np.pi + L_half) % L_dom - L_half
    states[:, -1, 0] = np.cos(np.arctan2(ry, rx))*L_half
    states[:, -1, 1] = np.sin(np.arctan2(ry, rx))*L_half
    states[:, -1, 2:6] = np.stack([interp_field(mags_f[..., k], pos)
                                   for k in range(4)], axis=-1)
    states[:, -1, 6] = interp_field(np.sqrt(np.sum(u3*u3, axis=-1)), pos)
    states[:, -1, 7] = interp_field(np.sqrt(np.sum(p3*p3, axis=-1)), pos)
    act[:, -1] = interp_field(jac_f.tension, pos) > thr
    state = 'Omega ACTIVE' if routes_total > 0 else 'Omega INACTIVE'
    print(f'    routes total = {routes_total}   ({state})')
    return tracks, states, act, cohort, routes_total, thr

# =============================================================================
# SECTION 5 — RECURRENCE INSTRUMENTS (multivariate, gated, detrended)
# =============================================================================
def standardize(x):
    sd = x.std()
    if sd < 1e-30:
        return x*0.0
    return (x - x.mean())/sd

def composite_state_matrix(states, msk, factors='all'):
    """Assemble the per-tracer standardized state matrix.
    factors: 'pos' (F1), 'tuple' (F2), 'part' (F3), 'all'."""
    S = states[msk]                       # (n, T, 8)
    if factors == 'pos':
        cols = [0, 1]
    elif factors == 'tuple':
        cols = [2, 3, 4, 5]
    elif factors == 'part':
        cols = [6, 7]
    else:
        cols = list(range(8))
    sub = S[:, :, cols]                   # (n, T, k)
    n, T, k = sub.shape
    flat = sub.reshape(n*T, k)
    for j in range(k):
        flat[:, j] = standardize(flat[:, j])
    return flat.reshape(n, T, k), cols

def detrend_time(sub):
    """Remove the slow monotone trend per factor (linear fit in time),
    so across-episode comparisons aren't forced-null by drift."""
    n, T, k = sub.shape
    t_axis = np.arange(T, dtype=float)
    out = sub.copy()
    for j in range(k):
        for i in range(n):
            coeffs = np.polyfit(t_axis, sub[i, :, j], 1)
            out[i, :, j] = sub[i, :, j] - np.polyval(coeffs, t_axis)
    return out

def multivariate_recurrence(sub, eps=0.9, max_lag=None):
    """Per-tracer multivariate recurrence: fraction of time-pairs
    (t1, t2), |t1-t2| >= min_lag, with ||s(t2)-s(t1)|| < eps (rms-normal
    distance across factors). Also the determinism proxy: fraction of
    recurring pairs that are part of diagonal runs (>=3 consecutive).
    Returns (rec_rate, det_score) averaged over tracers."""
    n, T, k = sub.shape
    if max_lag is None:
        max_lag = T
    rr_all = []
    det_all = []
    for i in range(n):
        s = sub[i]                          # (T, k)
        # pairwise distances (chunked)
        dmat = np.zeros((T, T))
        for a in range(T):
            dmat[a] = np.sqrt(np.mean((s - s[a])**2, axis=1))
        mask = np.ones((T, T), dtype=bool)
        np.fill_diagonal(mask, False)
        for lag in range(1, 3):
            for a in range(T - lag):
                mask[a, a+lag] = False
                mask[a+lag, a] = False
        rec = (dmat < eps) & mask
        n_pairs = mask.sum()
        if n_pairs == 0:
            continue
        rr = rec.sum()/n_pairs
        # determinism: diagonal runs of length >= 3
        det_pts = 0
        tot_pts = 0
        for a in range(2, T-2):
            for b in range(2, T-2):
                if rec[a, b]:
                    tot_pts += 1
                    if rec[a-1, b-1] and rec[a+1, b+1]:
                        det_pts += 1
        det = det_pts/max(tot_pts, 1)
        rr_all.append(rr)
        det_all.append(det)
    if not rr_all:
        return float('nan'), float('nan')
    return float(np.mean(rr_all)), float(np.mean(det_all))

def surrogate_recurrence(sub, eps=0.9, n_draws=5, seed=11):
    """Null: shuffle each factor's time series independently per tracer
    (destroys temporal structure, preserves distributions)."""
    rngs = np.random.default_rng(seed)
    n, T, k = sub.shape
    dets = []
    for _ in range(n_draws):
        sub_s = sub.copy()
        for i in range(n):
            for j in range(k):
                sub_s[i, :, j] = sub_s[i, np.random.permutation(T), j] \
                    if False else sub_s[i][rngs.permutation(T), j]
        _, det = multivariate_recurrence(sub_s[:20], eps=eps)
        if det == det:
            dets.append(det)
    return float(np.mean(dets)) if dets else float('nan')

def episodes(act_row, min_len=15):
    """Contiguous activation episodes (True runs) of length >= min_len."""
    T = len(act_row)
    eps_ = []
    s = 0
    while s < T:
        if act_row[s]:
            e = s
            while e < T and act_row[e]:
                e += 1
            if e - s >= min_len:
                eps_.append((s, e))
            s = e
        else:
            s += 1
    return eps_

