# recurrence restricted to pairs where activation state MATCHES, vs all
# pairs — the difference is the gating statistic
def gated_det(sub, act_sub, eps=0.9):
    n, T, k = sub.shape
    dets = []
    for i in range(min(n, 20)):
        s = sub[i]
        a = act_sub[i]
        dmat = np.zeros((T, T))
        for aa in range(T):
            dmat[aa] = np.sqrt(np.mean((s - s[aa])**2, axis=1))
        mask = np.ones((T, T), dtype=bool)
        np.fill_diagonal(mask, False)
        for lag in range(1, 3):
            for aa in range(T - lag):
                mask[aa, aa+lag] = False
                mask[aa+lag, aa] = False
        match = (a[:, None] == a[None, :])
        for name, m_ in (('gated', mask & match),
                         ('ungated', mask)):
            rec = (dmat < eps) & m_
            n_pairs = m_.sum()
            if n_pairs < 20:
                continue
            det_pts = 0
            tot_pts = 0
            for aa in range(2, T-2):
                for bb in range(2, T-2):
                    if rec[aa, bb]:
                        tot_pts += 1
                        if rec[aa-1, bb-1] and rec[aa+1, bb+1]:
                            det_pts += 1
            dets.append((name, det_pts/max(tot_pts, 1)))
    g = [d for (nm, d) in dets if nm == 'gated']
    u = [d for (nm, d) in dets if nm == 'ungated']
    if g and u:
        return float(np.mean(g)), float(np.mean(u))
    return float('nan'), float('nan')

