import numpy as np

required = ['stC', 'stO', 'actO', 'cohort']
missing = [k for k in required if k not in globals()]
assert not missing, f'Run v19 first in this session; missing: {missing}'

msk = cohort == 1
act_core = actO[msk]
TARGET_RR = 0.05
THEILER = 25
N_USE = 30
COLS_TP = [2, 3, 4, 5, 6, 7]     # tuple + partition (position excluded:
                                  # sub-orbital horizon, 267-431 step
                                  # periods vs 300-step run)

def prep(states_all, cols):
    """Per-tracer linear detrend + standardize."""
    S = states_all[:, :, cols].astype(float)
    n, T, k = S.shape
    out = np.empty_like(S)
    t_ax = np.arange(T, dtype=float)
    for i in range(n):
        for j in range(k):
            x = S[i, :, j]
            c = np.polyfit(t_ax, x, 1)
            x = x - np.polyval(c, t_ax)
            sd = x.std()
            if sd > 1e-30:
                out[i, :, j] = (x - x.mean())/sd
            else:
                out[i, :, j] = 0.0
    return out

def diag_counts(rec):
    core = rec[1:-1, 1:-1]
    tot = int(core.sum())
    det_pts = int((core & rec[:-2, :-2] & rec[2:, 2:]).sum())
    return det_pts, tot

def dist_mat(s):
    return np.sqrt(((s[:, None, :] - s[None, :, :])**2).mean(axis=2))

def sep_mask(T, theiler):
    idx = np.arange(T)
    return np.abs(idx[:, None] - idx[None, :]) >= theiler

def cal_rec(s, target_rr=TARGET_RR, theiler=THEILER, seed=7):
    """One tracer: (rr, det, det_surrogate, n_rec). Surrogate = time
    permutation (destroys temporal order; distance multiset invariant)."""
    T, k = s.shape
    d = dist_mat(s)
    sep = sep_mask(T, theiler)
    dists = d[sep]
    if len(dists) < 200:
        return float('nan'), float('nan'), float('nan'), 0
    eps = np.quantile(dists, target_rr)
    rec = (d < eps) & sep
    rr = float(rec.sum())/int(sep.sum())
    dp, tot = diag_counts(rec)
    det = dp/tot if tot > 0 else float('nan')
    rng = np.random.default_rng(seed)
    s2 = s[rng.permutation(T)]
    rec2 = (dist_mat(s2) < eps) & sep
    dp2, tot2 = diag_counts(rec2)
    det_s = dp2/tot2 if tot2 > 0 else float('nan')
    return rr, det, det_s, int(rec.sum())

def episodes_of(a_row, min_len=15):
    T = len(a_row)
    out = []
    s = 0
    while s < T:
        if a_row[s]:
            e = s
            while e < T and a_row[e]:
                e += 1
            if e - s >= min_len:
                out.append((s, e))
            s = e
        else:
            s += 1
    return out

def pooled_det_windows(sub, windows, target_rr=0.10):
    """Per-window eps at target RR, theiler = max(3, L//3); pooled
    diagonal counts across windows."""
    DP = 0
    TOT = 0
    for (i, s0, e0) in windows:
        w = sub[i, s0:e0, :]
        L = w.shape[0]
        th = max(3, L//3)
        if L < 2*th + 4:
            continue
        d = dist_mat(w)
        sep = sep_mask(L, th)
        dists = d[sep]
        if len(dists) < 40:
            continue
        eps = np.quantile(dists, target_rr)
        dp, tot = diag_counts((d < eps) & sep)
        DP += dp
        TOT += tot
    return (DP/TOT if TOT > 0 else float('nan')), TOT

