from fractions import Fraction as Fr

def poly_mul(p, q):
    """Multiply integer-coefficient polynomials (lists, index=degree)."""
    out = [0]*(len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            out[i+j] += a*b
    return out

def poly_sub(p, q):
    n = max(len(p), len(q))
    out = [0]*n
    for i in range(n):
        out[i] = (p[i] if i < len(p) else 0) - (q[i] if i < len(q) else 0)
    return out

# lhs = (1 - t^2)^2 + (2t)^2  ->  expand exactly
