def run_four_arm(steps=300, dt=0.004, n=32, thresh_frac=0.5, gain=10.0,
                 A_swirl=6.0, W_axial=None, sigma=1.0, A_wind=0.35,
                 seed_tag='default'):
    """Evolve the wound-core system in channels mode with the Omega
    transfer, while maintaining the FOUR-ARM bundle:
        A1 = u+p    (real-real)   -> tracked as m
        A2, A3      (cross-phase) -> magnitudes equal |m| by [S1d];
                                     we track the PHASE FRACTIONS
        A4 = (u+p)i (dual)        -> dual of A1
    The four-arm state is (m, phase-label field over {rr, ri, ir, ii}).
    Returns per-step: m-energy, |d| (deviation), enstrophy, stretching,
    C1/C2-decomposed stretching, and the phase-label fractions."""
    if W_axial is None:
        W_axial = 12.0/PHI
    axes, dx = make_grid(n)
    x, y, z = axes
    xc = np.pi + A_wind*np.sin(z)
    yc = np.pi + A_wind*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*sigma*sigma))
    u3 = np.stack([-A_swirl*ry*f, A_swirl*rx*f, W_axial*f], axis=-1)
    p3 = np.zeros_like(u3)
    pstats = ProjStats()
    V, _, _, _, _, _ = project_bundle(np.stack([u3, p3]), dx, 'channels',
                                      None, 1e-9, 25, pstats)
    u3, p3 = V[0], V[1]
    phi_p = None
    jac0 = nth_jacobian(u3, dx)
    thr = thresh_frac*float(np.max(jac0.tension))
    vol = dx**3
    hist = {k: [] for k in ('step', 'E_m', 'E_d', 'Z', 'stretch', 'sC1',
                            'sC2', 'phi_rr', 'phi_ri', 'phi_ir', 'phi_ii',
                            'flux')}
    routes_total = 0
    for step in range(steps):
        jac = nth_jacobian(u3, dx)
        m = u3 + p3
        d = 0.5*(u3 - p3)
        w = curl(m, dx)
        G = grad_vec(m, dx)
        # stretching production: <w, (grad m) w> — the 3D enstrophy source
        stretch = float(np.sum(np.einsum('...i,...ij,...j->...', w, G, w)))*vol
        # C1/C2 decomposition of the stretching, per the Nth Jacobian:
        # the symmetric part S and antisymmetric part A of grad m give
        # w^T S w (strain-stretching) and w^T A w (= 0 identically for
        # the antisymmetric part — the rotation never stretches).
        S_ = 0.5*(G + np.swapaxes(G, -1, -2))
        sC1 = float(np.sum(np.einsum('...i,...ij,...j->...', w, S_, w)))*vol
        # the antisymmetric contribution is identically zero — verified
        A_ = 0.5*(G - np.swapaxes(G, -1, -2))
        sC2 = float(np.sum(np.einsum('...i,...ij,...j->...', w, A_, w)))*vol
        # four-arm phase-label fractions (the bookkeeping layer):
        # which arm is 'dominant' at each routed point — rr where the
        # transfer is rotation-dominated, ir/ri at strain boundaries, ii
        # in the determinant-dominant interior
        rdom = np.abs(jac.R) > np.maximum(jac.C1, jac.C2)
        rot_dom = jac.C2 > jac.C1
        active = jac.tension > thr
        n_act = max(int(active.sum()), 1)
        phi_rr = float((active & ~rdom & rot_dom).sum())/n_act
        phi_ri = float((active & ~rdom & ~rot_dom).sum())/n_act
        phi_ir = float((active & rdom).sum())/n_act
        phi_ii = 1.0 - phi_rr - phi_ri - phi_ir
        # flux diagnostic: volume-integrated |m| through mid-planes
        mid = n//2
        flux = float(np.sum(np.abs(u3[mid, :, :, 0]))
                     + np.sum(np.abs(u3[:, mid, :, 1]))
                     + np.sum(np.abs(u3[:, :, mid, 2])))*dx*dx
        hist['step'].append(step)
        hist['E_m'].append(0.5*float(np.sum(m*m))*vol)
        hist['E_d'].append(0.5*float(np.sum(d*d))*vol)
        hist['Z'].append(0.5*float(np.sum(w*w))*vol)
        hist['stretch'].append(stretch)
        hist['sC1'].append(sC1)
        hist['sC2'].append(sC2)
        hist['phi_rr'].append(phi_rr)
        hist['phi_ri'].append(phi_ri)
        hist['phi_ir'].append(phi_ir)
        hist['phi_ii'].append(phi_ii)
        hist['flux'].append(flux)
        # evolution (validated stack)
        au = advect_material(u3, m, dx)
        ap = advect_material(p3, m, dx)
        u_s = u3 + dt*(-au)
        p_s = p3 + dt*(-ap)
        if True:  # omega always on for the four-arm test
            u_s, p_s, _, routes, _, _ = omega_transfer_nth(
                u_s, p_s, jac, dx, thr, gain)
            routes_total += routes
        Vp, _, _, phi_p, _, _ = project_bundle(
            np.stack([u_s, p_s]), dx, 'channels', phi_p, 1e-9, 20, pstats)
        u3, p3 = Vp[0], Vp[1]
        if not (np.all(np.isfinite(u3)) and np.all(np.isfinite(p3))):
            print(f'  HALT at step {step+1}: non-finite.')
            break
    print(f'  [{seed_tag}] steps {steps}, routes {routes_total}, '
          f'final E_m {hist["E_m"][-1]:.3f}, Z {hist["Z"][-1]:.3f}')
    return hist, routes_total

