# =============================================================================
# [M4] THE ANTICIPATION TEST
# =============================================================================
print('\n' + '='*79)
print('[M4] ANTICIPATION TEST: does routing precede C1 concentration?')
print('='*79)

def anticipation_test(hist, label, max_lag=15):
    routes = np.diff(np.array(hist['routes'], dtype=float))
    conc = np.array(hist['conc'], dtype=float)
    dconc = np.diff(conc)
    T = min(len(routes), len(dconc))
    if T < 20:
        print(f'  [{label}] series too short — no test.')
        return None
    r_ = routes[:T]
    c_ = dconc[:T]
    if r_.std() < 1e-12 or c_.std() < 1e-12:
        print(f'  [{label}] degenerate series — no test.')
        return None
    r_z = (r_ - r_.mean())/r_.std()
    c_z = (c_ - c_.mean())/c_.std()
    best = None
    for lag in range(0, max_lag):
        if lag >= T - 5:
            break
        x_ = r_z[:T-lag]
        y_ = c_z[lag:]
        corr = float(np.mean(x_*y_))
        if best is None or abs(corr) > abs(best[1]):
            best = (lag, corr)
    rngn = np.random.default_rng(13)
    null_max = []
    for _ in range(200):
        rs = r_z[rngn.permutation(T)]
        bm = 0.0
        for lag in range(0, max_lag):
            if lag >= T - 5:
                break
            x_ = rs[:T-lag]
            y_ = c_z[lag:]
            bm = max(bm, abs(float(np.mean(x_*y_))))
        null_max.append(bm)
    null_max = np.array(null_max)
    p_val = float(np.mean(null_max >= abs(best[1])))
    print(f'  [{label}] best lag {best[0]} (diag steps), corr '
          f'{best[1]:+.4f}   shuffle-null p = {p_val:.3f}')
    return (best[0], best[1], p_val)

ant_tubes = anticipation_test(hist_tubes, 'tubes omega')
ant_tubes_c = anticipation_test(hist_tubes_c, 'tubes classical')
for (seed_, h, r) in hist_rand:
    tag_a = make_tag('rand', seed_)
    anticipation_test(h, tag_a)
ant_long = anticipation_test(hist_long, 'wound-long omega')

# =============================================================================
