def initial_antiparallel(axes, strength=8.0, sigma=0.8, sep=1.6,
                         tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt)
    st = np.sin(tilt)

    def tube(cx, sign):
        dx_ = x - cx
        dy_ = y - np.pi
        dx_ = (dx_ + L_half) % L_dom - L_half
        dy_ = (dy_ + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        dy_t = dy_
        r2 = dx_t*dx_t + dy_t*dy_t
        f = np.exp(-r2/(2.0*sigma*sigma))
        ux = -sign*strength*dy_t*f
        uy = sign*strength*dx_t*f
        uz = np.zeros_like(x)
        return np.stack([ux, uy, uz], axis=-1)

    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)

def initial_random_divfree(axes, seed, n_modes=6, target_E=500.0):
    """Random smooth divergence-free field, u = curl(A), band-limited,
    normalized to target PHYSICAL energy 0.5*sum(u*u)*vol = target_E
    ([F8]: the previous discrete-sum normalization put E_m at ~0.01,
    five orders below the organized runs — frozen fields)."""
    rng = np.random.default_rng(seed)
    n = axes[0].shape[0]
    dxg = axes[0][1, 0, 0] - axes[0][0, 0, 0]

    def smooth_band(f):
        for _ in range(3):
            for a in (0, 1, 2):
                f = 0.5*f + 0.25*(np.roll(f, -1, axis=a)
                                  + np.roll(f, 1, axis=a))
        fh = np.fft.fftn(f)
        k = np.fft.fftfreq(n)*(n/(2.0*np.pi))
        KX, KY, KZ = np.meshgrid(k, k, k, indexing='ij')
        mask = (np.abs(KX) <= n_modes) & (np.abs(KY) <= n_modes) \
            & (np.abs(KZ) <= n_modes)
        return np.real(np.fft.ifftn(fh*mask))

    psi1 = smooth_band(rng.standard_normal((n, n, n)))
    psi2 = smooth_band(rng.standard_normal((n, n, n)))

    def ddx(f, ax):
        return (np.roll(f, -1, axis=ax) - np.roll(f, 1, axis=ax)) \
            * (0.5/dxg)

    u = np.empty((n, n, n, 3))
    u[..., 0] = -ddx(psi2, 2)
    u[..., 1] = ddx(psi1, 2)
    u[..., 2] = ddx(psi2, 0) - ddx(psi1, 1)
    norm = np.sqrt(float(np.sum(u*u)))
    u = u/max(norm, 1e-30)                     # discrete sum(u*u) = 1
    vol = dxg**3
    scale = np.sqrt(2.0*target_E/vol)           # [F8] physical energy
    u = scale*u
    assert np.all(np.isfinite(u)), \
        'random IC construction produced NaN'
    return u

def initial_wound_core(axes, A_swirl=6.0, W_axial=None, sigma=1.0,
                       A_wind=0.35):
    if W_axial is None:
        W_axial = 12.0/PHI
    x, y, z = axes
    xc = np.pi + A_wind*np.sin(z)
    yc = np.pi + A_wind*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*sigma*sigma))
    return np.stack([-A_swirl*ry*f, A_swirl*rx*f, W_axial*f], axis=-1)

# =============================================================================
# THE INSTRUMENTED RUN (scheme-selectable: 'euler' | 'rk2')
# =============================================================================
def run_candidate(ic_func, ic_kwargs, steps, dt=0.004, n=32,
                  thresh_frac=0.5, gain=10.0, tag='', diag_every=5,
                  use_omega=True, scheme='rk2'):
    """Full four-arm instrumented run. scheme='rk2' ([F6]): Heun's
    method on the skew advection — STABLE for CFL <= sqrt(2), killing
    the forward-Euler dt^2 injection (the only energy-adding operator
    in the scheme; it blew up wound-long at step 616 under 'euler')."""
    axes, dx = make_grid(n)
    u3 = ic_func(axes, **ic_kwargs)
    p3 = np.zeros_like(u3)
    assert np.all(np.isfinite(u3)), f'[{tag}] IC non-finite — aborting.'
    pstats = ProjStats()
    V, _, _, _, _, _ = project_bundle(np.stack([u3, p3]), dx, 'channels',
                                      None, 1e-9, 25, pstats)
    u3, p3 = V[0], V[1]
    phi_p = None
    jac0 = nth_jacobian(u3, dx)
    thr = thresh_frac*float(np.max(jac0.tension))
    vol = dx**3
    hist = {k: [] for k in ('step', 'E_m', 'E_d', 'Z', 'stretch', 'conc',
                            'routes')}
    routes_total = 0
    halt_step = -1
    t_start = time.time()
    for step in range(steps):
        jac = nth_jacobian(u3, dx)
        m = u3 + p3
        d = 0.5*(u3 - p3)
        w = curl(m, dx)
        G = grad_vec(m, dx)
        stretch = float(np.sum(np.einsum('...i,...ij,...j->...',
                                        w, G, w)))*vol
        n_ = w.shape[0]
        w2 = np.sum(w*w, axis=-1)
        blk = w2.reshape(n_//4, 4, n_//4, 4, n_//4, 4).mean(axis=(1, 3, 5))
        conc = float(np.max(blk))
        if step % diag_every == 0 or step == steps - 1:
            hist['step'].append(step)
            hist['E_m'].append(0.5*float(np.sum(m*m))*vol)
            hist['E_d'].append(0.5*float(np.sum(d*d))*vol)
            hist['Z'].append(0.5*float(np.sum(w2))*vol)
            hist['stretch'].append(stretch)
            hist['conc'].append(conc)
            hist['routes'].append(routes_total)
        # ---- time step ([F6]) ----
        if scheme == 'euler':
            au = advect_material(u3, m, dx)
            ap = advect_material(p3, m, dx)
            u_s = u3 + dt*(-au)
            p_s = p3 + dt*(-ap)
        else:
            # RK2 (Heun) on the skew (zero-leakage) advection:
            # predictor at carrier m, corrector at carrier m*.
            au1 = advect_material(u3, m, dx)
            ap1 = advect_material(p3, m, dx)
            u_star = u3 - dt*au1
            p_star = p3 - dt*ap1
            m_star = u_star + p_star
            au2 = advect_material(u_star, m_star, dx)
            ap2 = advect_material(p_star, m_star, dx)
            u_s = u3 - 0.5*dt*(au1 + au2)
            p_s = p3 - 0.5*dt*(ap1 + ap2)
        if use_omega:
            u_s, p_s, _, routes, _, _ = omega_transfer_nth(
                u_s, p_s, jac, dx, thr, gain)
            routes_total += routes
        Vp, _, _, phi_p, _, _ = project_bundle(
            np.stack([u_s, p_s]), dx, 'channels', phi_p, 1e-9, 20, pstats)
        u3, p3 = Vp[0], Vp[1]
        if not (np.all(np.isfinite(u3)) and np.all(np.isfinite(p3))):
            halt_step = step + 1
            print(f'  [{tag}] HALT at step {halt_step}: non-finite.')
            break
    wall = time.time() - t_start
    print(f'  [{tag}] scheme={scheme} steps {steps}'
          f'{" HALTED@" + str(halt_step) if halt_step > 0 else ""}, '
          f'routes {routes_total}, wall {wall:.0f}s')
    print(f'    E_m {hist["E_m"][0]:.2f} -> {hist["E_m"][-1]:.2f}   '
          f'Z {hist["Z"][0]:.2f} -> {hist["Z"][-1]:.2f}   '
          f'conc {hist["conc"][0]:.4f} -> {hist["conc"][-1]:.4f}')
    hist['halt_step'] = halt_step
    return hist, routes_total

