def anticipation_test(hist, label, max_lag=15):
    rh = np.array(hist['routes'], dtype=float)
    ch = np.array(hist['conc'], dtype=float)
    # [F7] finite guard: blow-up runs record inf before halting; corr
    # on inf -> nan, and p becomes a nan-comparison artifact.
    n_fin = int(np.sum(np.isfinite(ch)))
    if n_fin < len(ch):
        print(f'  [{label}] non-finite values: testing the pre-blowup '
              f'segment (first {n_fin} of {len(ch)} points).')
        rh = rh[:n_fin]
        ch = ch[:n_fin]
    routes = np.diff(rh)
    dconc = np.diff(ch)
    T = min(len(routes), len(dconc))
    if T < 20:
        print(f'  [{label}] series too short — no test.')
        return None
    r_ = routes[:T]
    c_ = dconc[:T]
    if r_.std() < 1e-12 or c_.std() < 1e-12:
        print(f'  [{label}] degenerate series — no test.')
        return None
    r_z = (r_ - r_.mean())/r_.std()
    c_z = (c_ - c_.mean())/c_.std()
    if not (np.all(np.isfinite(r_z)) and np.all(np.isfinite(c_z))):
        print(f'  [{label}] non-finite standardized series — no test.')
        return None
    best = None
    for lag in range(0, max_lag):
        if lag >= T - 5:
            break
        x_ = r_z[:T-lag]
        y_ = c_z[lag:]
        corr = float(np.mean(x_*y_))
        if best is None or abs(corr) > abs(best[1]):
            best = (lag, corr)
    rngn = np.random.default_rng(13)
    null_max = []
    for _ in range(200):
        rs = r_z[rngn.permutation(T)]
        bm = 0.0
        for lag in range(0, max_lag):
            if lag >= T - 5:
                break
            x_ = rs[:T-lag]
            y_ = c_z[lag:]
            bm = max(bm, abs(float(np.mean(x_*y_))))
        null_max.append(bm)
    null_max = np.array(null_max)
    p_val = float(np.mean(null_max >= abs(best[1])))
    print(f'  [{label}] best lag {best[0]} (diag steps), corr '
          f'{best[1]:+.4f}   shuffle-null p = {p_val:.3f}')
    return (best[0], best[1], p_val)

