print('\n' + '#'*79)
print('V21.1 — THE TEMPORAL ARCHITECTURE TEST: clock field, shear, '
      'Mercury loops, anchor persistence')
print('#'*79)

print('\n--- temporal-architecture runs (RK2, wound-core golden IC) ---')
t0 = time.time()
(trkC, tauC, thC, tenC, drC, dthC, cohort, rtsC, TmC) = \
    track_temporal(steps=STEPS_RUN, dt=DT, seed=42, use_omega=False)
print(f'  classical: {time.time()-t0:.0f}s')
