def mercury_loops(theta, msk_, label):
    th_core = theta[msk_]
    th_mean = th_core.mean(axis=0)
    n_loops_all = []
    interval_all = []
    for i in range(th_core.shape[0]):
        dphi = th_core[i] - th_mean
        crossings = 0
        last_t = None
        for t in range(1, len(dphi)):
            if abs(dphi[t] - dphi[t-1]) > np.pi:
                continue
            prev = dphi[t-1] % TAU
            curr = dphi[t] % TAU
            if prev - curr > np.pi:
                crossings += 1
                if last_t is not None:
                    interval_all.append(t - last_t)
                last_t = t
            elif curr - prev > np.pi:
                crossings -= 1
        n_loops_all.append(crossings)
    n_loops = np.array(n_loops_all)
    frac_loop = float(np.mean(n_loops != 0))
    print(f'  [{label}] tracers with >=1 phase loop vs the mean: '
          f'{100.0*frac_loop:.0f}%   median |loops|: '
          f'{np.median(np.abs(n_loops)):.0f}   '
          f'max {np.max(np.abs(n_loops))}')
    if interval_all:
        itv = np.array(interval_all)
        print(f'          loop intervals: median {np.median(itv):.0f} '
              f'steps  IQR {np.percentile(itv, 75) - np.percentile(itv, 25):.0f}')
    return n_loops

