def tiered_anchor_scores(disc_r, disc_th, msk_, eps_r=EPS_R,
                         eps_th=EPS_TH, stride=STRIDE,
                         tier_a=TIER_A_EXC, tier_b=TIER_B_EXC):
    """Per-tracer (tierA, tierB) anchor counts. A return (t1, t2) with
    |dr| < eps_r and phase agreement counts into a tier by radial
    EXCURSION between t1 and t2: > tier_a => A (genuine transit-and-
    return); tier_b..tier_a => B (small periodic orbit / marginal);
    < tier_b => excluded (window-limited or parked: not an anchor)."""
    N, T = disc_r.shape
    scoreA = np.zeros(N)
    scoreB = np.zeros(N)
    for i in np.where(msk_)[0]:
        r_i = disc_r[i]
        th_i = disc_th[i] % TAU_
        for t1 in range(0, T - 60, stride):
            for t2 in range(t1 + 50, T, stride):
                if abs(r_i[t2] - r_i[t1]) < eps_r:
                    seg = r_i[t1:t2]
                    if seg.size == 0:
                        continue
                    exc = float(seg.max() - seg.min())
                    if exc < tier_b:
                        continue
                    dth = abs(th_i[t2] - th_i[t1]) % TAU_
                    dth = min(dth, TAU_ - dth)
                    if dth < eps_th:
                        if exc > tier_a:
                            scoreA[i] += 1.0
                        else:
                            scoreB[i] += 1.0
    return scoreA, scoreB

def perm_test(aO, aC, n_perm=N_PERM, seed=42):
    diff_obs = aO.mean() - aC.mean()
    allv = np.concatenate([aO, aC])
    n_o = len(aO)
    rngp = np.random.default_rng(seed)
    count = 0
    for _ in range(n_perm):
        pv = rngp.permutation(allv)
        d_ = pv[:n_o].mean() - pv[n_o:].mean()
        if abs(d_) >= abs(diff_obs):
            count += 1
    return diff_obs, count/n_perm

