P_REAL, P_UNREAL = '1', 'i'

def t_spectrum(g):
    num = [(g, P_REAL), (g, P_UNREAL)]
    den = [(1.0+g, P_REAL), (1.0+g, P_REAL),
           (1.0+g, P_UNREAL), (1.0+g, P_UNREAL)]
    return num, den, g/(1.0+g)

def cs_spectra(t):
    arms = [(t*t, P_REAL), (t*t, P_UNREAL),
            (t*t, P_UNREAL), (t*t, P_UNREAL)]
    leads = [(1.0, P_REAL), (1.0, P_UNREAL)]
    num_c = [(lm-am, lp) for (lm, lp) in leads for (am, ap) in arms]
    den_c = [(lm+am, lp) for (lm, lp) in leads for (am, ap) in arms]
    num_s = [(2.0*t, ph) for (am, ph) in arms]
    return num_c, den_c, num_s

def collapse_check(num, den, ref):
    worst = 0.0
    for (nm, nph) in num:
        for (dm, dph) in den:
            worst = max(worst, abs(nm/dm - ref))
    return worst

def angle_selector(g):
    t = g/(1.0+g)
    return t, (1.0-t*t)/(1.0+t*t), (2.0*t)/(1.0+t*t)

def spectra_audit(g=0.6):
    num, den, t_ref = t_spectrum(g)
    num_c, den_c, num_s = cs_spectra(t_ref)
    c_ref = (1.0-t_ref*t_ref)/(1.0+t_ref*t_ref)
    s_ref = 2.0*t_ref/(1.0+t_ref*t_ref)
    print(f'spectra collapse: t {collapse_check(num,den,t_ref):.1e}  '
          f'c {collapse_check(num_c,den_c,c_ref):.1e}  '
          f's {collapse_check(num_s,den_c,s_ref):.1e}  '
          f'circle {abs(c_ref*c_ref+s_ref*s_ref-1.0):.1e}')

spectra_audit()

def make_grid(n, length=2.0*np.pi):
    assert n >= 4 and (n & (n-1)) == 0, 'grid must be a power of two'
    x = np.linspace(0.0, length, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), length/n

def dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis))*(0.5/dx)

def grad_vec(u, dx):
    gu = np.empty(u.shape + (3,))
    for i in range(3):
        for j in range(3):
            gu[..., i, j] = dd(u[..., i], j, dx)
    return gu

def curl(u, dx):
    g = grad_vec(u, dx)
    w = np.empty_like(u)
    w[..., 0] = g[..., 2, 1] - g[..., 1, 2]
    w[..., 1] = g[..., 0, 2] - g[..., 2, 0]
    w[..., 2] = g[..., 1, 0] - g[..., 0, 1]
    return w

def lap_vec(u, dx):
    out = np.empty_like(u)
    inv = 1.0/(dx*dx)
    for i in range(3):
        f = u[..., i]
        out[..., i] = (-6.0*f + np.roll(f, -1, 0) + np.roll(f, 1, 0)
                       + np.roll(f, -1, 1) + np.roll(f, 1, 1)
                       + np.roll(f, -1, 2) + np.roll(f, 1, 2))*inv
    return out

def advect_material(f, v, dx):
    out = np.zeros_like(f)
    for i in range(3):
        fi = f[..., i]
        acc = np.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc += 0.5*(dd(vj*fi, j, dx) + vj*dd(fi, j, dx))
        out[..., i] = acc
    return out

@dataclass
class JacobianChannels:
    R: np.ndarray; U: np.ndarray; C1: np.ndarray; C2: np.ndarray
    vort: np.ndarray; tension: np.ndarray

def nth_jacobian(u, dx):
    G = grad_vec(u, dx)
    S_ = 0.5*(G + np.swapaxes(G, -1, -2))
    A_ = 0.5*(G - np.swapaxes(G, -1, -2))
    C1 = np.sqrt(np.sum(S_*S_, axis=(-2, -1)))
    C2 = np.sqrt(np.sum(A_*A_, axis=(-2, -1)))
    a, b, c = G[..., 0, 0], G[..., 0, 1], G[..., 0, 2]
    d, e, f = G[..., 1, 0], G[..., 1, 1], G[..., 1, 2]
    g, h, i = G[..., 2, 0], G[..., 2, 1], G[..., 2, 2]
    R = a*(e*i - f*h) - b*(d*i - f*g) + c*(d*h - e*g)
    U = np.sqrt(np.sum(G*G, axis=(-2, -1))) - np.abs(R)
    vort = np.stack([G[..., 2, 1] - G[..., 1, 2],
                     G[..., 0, 2] - G[..., 2, 0],
                     G[..., 1, 0] - G[..., 0, 1]], axis=-1)
    return JacobianChannels(R, U, C1, C2, vort, C1 + C2 + np.abs(R))

def unreal_mirror(axis):
    a1, a2, a3 = (axis[..., 0], axis[..., 1], axis[..., 2])
    M = np.zeros(axis.shape[:-1] + (3, 3))
    M[..., 0, 1] = -a3; M[..., 0, 2] =  a2
    M[..., 1, 0] =  a3; M[..., 1, 2] = -a1
    M[..., 2, 0] = -a2; M[..., 2, 1] =  a1
    return M

def partner(M, d):
    return np.einsum('...ij,...j->...i', M, d)

def dominant_axis3(jac, dx):
    rot_dom = jac.C2 > jac.C1
    wn = np.sqrt(np.sum(jac.vort*jac.vort, axis=-1))
    gs = np.stack([dd(jac.C1, a, dx) for a in (0, 1, 2)], axis=-1)
    gn = np.sqrt(np.sum(gs*gs, axis=-1))
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    axis = np.zeros_like(jac.vort)
    if use_v.any():
        axis[use_v] = (jac.vort/np.maximum(wn, 1e-30)[..., None])[use_v]
    if use_g.any():
        axis[use_g] = (gs/np.maximum(gn, 1e-30)[..., None])[use_g]
    return axis

def omega_transfer_nth(u, p, jac, dx, threshold, gain):
    """Returns SIX values: (u_new, p_new, phase, routes, err, aud)."""
    excess = np.maximum(jac.tension - threshold, 0.0)
    active = excess > 0.0
    g = gain*excess*dx
    t, c, s = angle_selector(g)
    m = u + p
    d = 0.5*(u - p)
    M = unreal_mirror(dominant_axis3(jac, dx))
    Pd = partner(M, d)
    d_ax = d + partner(M, Pd)
    d_tr = d - d_ax
    Ptr = partner(M, d_tr)
    d_new = d_ax + c[..., None]*d_tr + s[..., None]*Ptr
    u_new = 0.5*m + d_new
    p_new = 0.5*m - d_new
    rdom = np.abs(jac.R) > np.maximum(jac.C1, jac.C2)
    rot_dom = jac.C2 > jac.C1
    phase = np.full(excess.shape, 'Real', dtype='<U6')
    phase[active & rdom] = 'C2'
    phase[active & ~rdom & rot_dom] = 'Unreal'
    phase[active & ~rdom & ~rot_dom] = 'C1'
    routes = int(np.count_nonzero(active))
    aud = {'g_max': float(np.max(g)),
           't_mean': float(np.mean(t[active])) if routes > 0 else 0.0}
    err_m = float(np.max(np.abs((u_new + p_new) - (u + p))))
    e0 = float(np.sum(u*u + p*p))
    e1 = float(np.sum(u_new*u_new + p_new*p_new))
    err_e = abs(e1 - e0)/max(abs(e0), 1e-300)
    return u_new, p_new, phase, routes, max(err_m, err_e), aud

def restrict(F):
    a, b, c = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (a//2, 2, b//2, 2, c//2, 2)
                     ).mean(axis=(-5, -3, -1))

def _interp1(F, axis):
    n = F.shape[axis]
    shp = list(F.shape); shp[axis] = 2*n
    G = np.empty(shp, dtype=F.dtype)
    se = [slice(None)]*F.ndim; se[axis] = slice(0, 2*n, 2)
    G[tuple(se)] = F
    so = [slice(None)]*F.ndim; so[axis] = slice(1, 2*n, 2)
    G[tuple(so)] = 0.5*(F + np.roll(F, -1, axis=axis))
    return G

def prolong(C):
    F = _interp1(C, C.ndim - 3)
    F = _interp1(F, F.ndim - 2)
    F = _interp1(F, F.ndim - 1)
    return F

def lap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    for a in (F.ndim - 3, F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s*inv

_RBGS_CACHE = {}
def _rb_mask(m):
    if m not in _RBGS_CACHE:
        idx = np.indices((m, m, m))
        red = ((idx[0] + idx[1] + idx[2]) % 2 == 0)
        _RBGS_CACHE[m] = (red, ~red)
    return _RBGS_CACHE[m]

def smooth_gs(phi, f, dx, iters):
    c = dx*dx/6.0
    red, black = _rb_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - lap_apply(phi, dx)
        phi = phi - c*np.where(red, r, 0.0)
        r = f - lap_apply(phi, dx)
        phi = phi - c*np.where(black, r, 0.0)
    return phi

def v_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - f.mean(axis=(-3, -2, -1), keepdims=True)
        return smooth_gs(phi, f, dx, 40)
    phi = smooth_gs(phi, f, dx, 2)
    r = f - lap_apply(phi, dx)
    rc = restrict(r)
    ec = v_cycle(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + prolong(ec)
    return smooth_gs(phi, f, dx, 2)

def split_classes(f):
    N = f.shape[-1]
    M = N//2
    out = np.empty(f.shape[:-3] + (8, M, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                out[..., c, :, :, :] = f[..., a::2, b::2, d::2]
                c += 1
    return out

def merge_classes(g, N):
    f = np.empty(g.shape[:-4] + (N, N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                f[..., a::2, b::2, d::2] = g[..., c, :, :, :]
                c += 1
    return f

def div_bundle(V, dx):
    out = np.zeros(V.shape[:-1])
    for j in range(3):
        out += dd(V[..., j], V.ndim - 4 + j, dx)
    return out

def grad_bundle(phi, dx):
    return np.stack([dd(phi, phi.ndim - 3 + j, dx) for j in range(3)],
                    axis=-1)

@dataclass
class ProjStats:
    solves: int = 0; cycles_total: int = 0; cycles_max: int = 0
    worst_resid: float = 0.0

def project_bundle(V, dx, mode='channels', phi=None, tol=1e-9,
                   max_cycles=20, stats=None):
    f = -div_bundle(V, dx)
    fc = split_classes(f)
    H = 2.0*dx
    fc = fc - fc.mean(axis=(-3, -2, -1), keepdims=True)
    f0 = np.sqrt(np.sum(fc*fc, axis=(-3, -2, -1)))
    live = f0 > 1e-300
    fc = fc*live[..., None, None, None]
    if phi is None:
        psic = np.zeros_like(fc)
    else:
        psic = split_classes(phi)*live[..., None, None, None]
    psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
    cycles, worst = 0, 0.0
    if live.any():
        def rel_resid():
            r = fc - lap_apply(psic, H)
            rn = np.sqrt(np.sum(r*r, axis=(-3, -2, -1)))
            return float(np.max((rn/np.maximum(f0, 1e-300))[live]))
        worst = rel_resid()
        while worst >= tol and cycles < max_cycles:
            psic = v_cycle(psic, fc, H)
            psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
            cycles += 1
            worst = rel_resid()
    phi_out = merge_classes(psic, V.shape[-3])
    gu = grad_bundle(phi_out[0], dx)
    gp = grad_bundle(phi_out[1], dx)
    Vp = np.stack([V[0] + gu, V[1] + gp])
    if stats is not None and live.any():
        stats.solves += 1
        stats.cycles_total += cycles
        stats.cycles_max = max(stats.cycles_max, cycles)
        stats.worst_resid = max(stats.worst_resid, worst)
    return Vp, gu, gp, phi_out, cycles, worst

def validate_solver(m=16, seed=3):
    H = 0.4
    g = np.random.default_rng(seed)
    phi_true = g.standard_normal((m, m, m))
    for _ in range(6):
        for a in (0, 1, 2):
            phi_true = 0.5*phi_true + 0.25*(np.roll(phi_true, -1, axis=a)
                                            + np.roll(phi_true, 1, axis=a))
    phi_true -= phi_true.mean()
    f = lap_apply(phi_true, H)
    phi = np.zeros_like(f)
    for _ in range(30):
        phi = v_cycle(phi, f, H)
        phi -= phi.mean()
        if float(np.max(np.abs(f - lap_apply(phi, H)))) < \
                1e-11*max(1.0, float(np.max(np.abs(f)))):
            break
    err = float(np.max(np.abs(phi - phi_true)))
    scale = max(1.0, float(np.max(np.abs(phi_true))))
    ok = np.isfinite(err) and err < 1e-6*scale
    verdict = 'PASS' if ok else 'FAIL'
    print(f'  3D exact recovery: {err/scale:.2e}  -> {verdict}')
    assert ok

def validate_projection(n=32, seed=7):
    axes, dx = make_grid(n)
    g = np.random.default_rng(seed)
    V = g.standard_normal((2, n, n, n, 3))
    for _ in range(6):
        for a in (1, 2, 3):
            V = 0.5*V + 0.25*(np.roll(V, -1, axis=a) + np.roll(V, 1, axis=a))
    E0 = float(np.sum(V*V))
    Vp, _, _, _, cycles, resid = project_bundle(V, dx, 'channels',
                                                None, 1e-10, 25)
    d1 = float(np.max(np.abs(div_bundle(Vp, dx))))
    ok_a = np.isfinite(resid) and resid < 1e-8
    ok_b = np.isfinite(d1) and d1 <= max(1e-9,
        1e-6*float(np.max(np.abs(div_bundle(V, dx)))))
    ok_c = float(np.sum(Vp*Vp)) <= E0*(1.0 + 1e-6)
    va = 'PASS' if ok_a else 'FAIL'
    vb = 'PASS' if ok_b else 'FAIL'
    vc = 'PASS' if ok_c else 'FAIL'
    print(f'  3D channels ({cycles} cy): resid {resid:.1e} {va}  '
          f'div {d1:.1e} {vb}  energy '
          f'{float(np.sum(Vp*Vp))/E0:.6f} {vc}')
    assert ok_a and ok_b and ok_c

print('\n' + '='*79)
print('BRIDGE GATES')
print('='*79)
validate_solver(16)
validate_projection(32)

# =============================================================================
# INITIAL CONDITIONS (from v20-M.3, verbatim)
# =============================================================================
A_SWIRL = 6.0
W_GOLD = 12.0/PHI
SIGMA = 1.0
A_WIND = 0.35

def initial_antiparallel(axes, strength=8.0, sigma=0.8, sep=1.6,
                         tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt)
    st = np.sin(tilt)

    def tube(cx, sign):
        dx_ = x - cx
        dy_ = y - np.pi
        dx_ = (dx_ + L_half) % L_dom - L_half
        dy_ = (dy_ + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        dy_t = dy_
        r2 = dx_t*dx_t + dy_t*dy_t
        f = np.exp(-r2/(2.0*sigma*sigma))
        ux = -sign*strength*dy_t*f
        uy = sign*strength*dx_t*f
        uz = np.zeros_like(x)
        return np.stack([ux, uy, uz], axis=-1)

    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)

def initial_wound_core(axes, A_swirl=6.0, W_axial=None, sigma=1.0,
                       A_wind=0.35):
    if W_axial is None:
        W_axial = W_GOLD
    x, y, z = axes
    xc = np.pi + A_wind*np.sin(z)
    yc = np.pi + A_wind*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*sigma*sigma))
    return np.stack([-A_swirl*ry*f, A_swirl*rx*f, W_axial*f], axis=-1)

def initial_random_divfree(axes, seed, n_modes=6, target_E=500.0):
    rng = np.random.default_rng(seed)
    n = axes[0].shape[0]
    dxg = axes[0][1, 0, 0] - axes[0][0, 0, 0]

    def smooth_band(f):
        for _ in range(3):
            for a in (0, 1, 2):
                f = 0.5*f + 0.25*(np.roll(f, -1, axis=a)
                                  + np.roll(f, 1, axis=a))
        fh = np.fft.fftn(f)
        k = np.fft.fftfreq(n)*(n/(2.0*np.pi))
        KX, KY, KZ = np.meshgrid(k, k, k, indexing='ij')
        mask = (np.abs(KX) <= n_modes) & (np.abs(KY) <= n_modes) \
            & (np.abs(KZ) <= n_modes)
        return np.real(np.fft.ifftn(fh*mask))

    psi1 = smooth_band(rng.standard_normal((n, n, n)))
    psi2 = smooth_band(rng.standard_normal((n, n, n)))

    def ddx(f, ax):
        return (np.roll(f, -1, axis=ax) - np.roll(f, 1, axis=ax)) \
            * (0.5/dxg)

    u = np.empty((n, n, n, 3))
    u[..., 0] = -ddx(psi2, 2)
    u[..., 1] = ddx(psi1, 2)
    u[..., 2] = ddx(psi2, 0) - ddx(psi1, 1)
    norm = np.sqrt(float(np.sum(u*u)))
    u = u/max(norm, 1e-30)
    vol = dxg**3
    scale = np.sqrt(2.0*target_E/vol)
    u = scale*u
    assert np.all(np.isfinite(u)), 'random IC construction produced NaN'
    return u

def build_ic(name, axes):
    if name == 'tubes':
        return initial_antiparallel(axes)
    if name == 'wound':
        return initial_wound_core(axes)
    if name == 'random':
        return initial_random_divfree(axes, seed=101)
    raise ValueError(name)

# =============================================================================
# THE BKM-NTH INSTRUMENTED RUN
# =============================================================================
def run_bkm_nth(ic_name, nu, n, steps=STEPS, dt=DT, use_omega=True,
                thresh_frac=0.5, gain=10.0, scheme='rk2', tag=''):
    """RK2 (or euler) run tracking the BKM-Nth quadruple:
      M_k: located structural maximum of the tension field per tick
      Σ_K: the fusion accumulation (running sum of M_k, in time units:
           sum of M_k * dt — so Σ has the same units as the classical
           integral and cross-resolution comparison is meaningful)
      B_K: the Res-estimate bound — the linear projection of Σ over the
           recent B_WINDOW, recomputed every FIT_STRIDE ticks (the
           backwards method: hypothesize the bound the trajectory is
           currently honoring, then test it)
      D_K: the Nth-divergence |Σ_K − B_K| — the verdict series
    Also tracks: Z (enstrophy, the classical comparison), the toll
    (projection energy removed — the ν=0 lesson: at ν>0 the toll and
    viscosity BOTH act), and routes. Returns the history dict."""
    axes, dx = make_grid(n)
    u3 = build_ic(ic_name, axes)
    p3 = np.zeros_like(u3)
    assert np.all(np.isfinite(u3)), f'[{tag}] IC non-finite — aborting.'
    pstats = ProjStats()
    V, _, _, _, _, _ = project_bundle(np.stack([u3, p3]), dx, 'channels',
                                      None, 1e-9, 25, pstats)
    u3, p3 = V[0], V[1]
    phi_p = None
    jac0 = nth_jacobian(u3, dx)
    thr = thresh_frac*float(np.max(jac0.tension))
    vol = dx**3
    hist = {k: [] for k in ('step', 'M', 'Sigma', 'B', 'D', 'Z',
                            'toll_cum', 'routes_cum', 'maxw')}
    routes_total = 0
    toll_cum = 0.0
    Sigma = 0.0
    B_val = 0.0
    B_hist_window = []
    halt_step = -1
    t_start = time.time()
    for step in range(steps):
        jac = nth_jacobian(u3, dx)
        m = u3 + p3
        w = curl(m, dx)
        M_k = float(np.max(jac.tension))          # located maximum
        Sigma += M_k*dt                            # fusion accumulation
        # B_K: the Res-estimate (backwards fit) — the linear projection
        # of Σ over the recent window, evaluated at the CURRENT tick
        B_hist_window.append((step*dt, Sigma))
        if len(B_hist_window) > B_WINDOW:
            B_hist_window.pop(0)
        if step % FIT_STRIDE == 0 and len(B_hist_window) >= 20:
            ts = np.array([p_[0] for p_ in B_hist_window])
            ss = np.array([p_[1] for p_ in B_hist_window])
            cf = np.polyfit(ts, ss, 1)
            B_val = float(np.polyval(cf, step*dt))
        D_val = abs(Sigma - B_val)
        if step % 5 == 0 or step == steps - 1:
            hist['step'].append(step)
            hist['M'].append(M_k)
            hist['Sigma'].append(Sigma)
            hist['B'].append(B_val)
            hist['D'].append(D_val)
            hist['Z'].append(0.5*float(np.sum(w*w))*vol)
            hist['maxw'].append(float(np.sqrt(np.max(np.sum(w*w,
                                                            axis=-1)))))
            hist['toll_cum'].append(toll_cum)
            hist['routes_cum'].append(routes_total)
        # ---- evolution (RK2 default; euler for the control) ----
        if scheme == 'euler':
            au = advect_material(u3, m, dx)
            ap = advect_material(p3, m, dx)
            u_s = u3 + dt*(-au + nu*lap_vec(u3, dx))
            p_s = p3 + dt*(-ap + nu*lap_vec(p3, dx))
        else:
            au1 = advect_material(u3, m, dx)
            ap1 = advect_material(p3, m, dx)
            Lu = lap_vec(u3, dx)
            Lp = lap_vec(p3, dx)
            u_star = u3 + dt*(-au1 + nu*Lu)
            p_star = p3 + dt*(-ap1 + nu*Lp)
            m_star = u_star + p_star
            au2 = advect_material(u_star, m_star, dx)
            ap2 = advect_material(p_star, m_star, dx)
            Lu2 = lap_vec(u_star, dx)
            Lp2 = lap_vec(p_star, dx)
            u_s = u3 + 0.5*dt*(-(au1 + au2) + nu*(Lu + Lu2))
            p_s = p3 + 0.5*dt*(-(ap1 + ap2) + nu*(Lp + Lp2))
        if use_omega:
            u_s, p_s, _, routes, _, _ = omega_transfer_nth(
                u_s, p_s, jac, dx, thr, gain)
            routes_total += routes
        Vp, gu, gp, phi_p, _, _ = project_bundle(
            np.stack([u_s, p_s]), dx, 'channels', phi_p, 1e-9, 20,
            pstats)
        # the toll: exact energy removed by the projection
        dE = 0.5*vol*float(np.sum(2*u_s*gu + gu*gu + 2*p_s*gp + gp*gp))
        toll_cum += dE
        u3, p3 = Vp[0], Vp[1]
        if not (np.all(np.isfinite(u3)) and np.all(np.isfinite(p3))):
            halt_step = step + 1
            print(f'  [{tag}] HALT at step {halt_step}: non-finite.')
            break
    wall = time.time() - t_start
    h_s = f'HALTED@{halt_step}' if halt_step > 0 else 'complete'
    print(f'  [{tag}] {h_s}, routes {routes_total}, wall {wall:.0f}s   '
          f'M: {hist["M"][0]:.2f}->{hist["M"][-1]:.2f}   '
          f'Σ: {hist["Sigma"][-1]:.2f}   D_final: {hist["D"][-1]:.3f}   '
          f'Z: {hist["Z"][0]:.1f}->{hist["Z"][-1]:.1f}')
    hist['halt_step'] = halt_step
    hist['nu'] = nu
    hist['n'] = n
    hist['ic'] = ic_name
    return hist

