def growth_class(D):
    """Classify the D series: contracting / flat / growing, and
    whether growth accelerates (2nd-half slope > 1.5x 1st-half)."""
    if len(D) < 20:
        return 'short'
    h = len(D)//2
    s1 = np.polyfit(np.arange(h), D[:h], 1)[0]
    s2 = np.polyfit(np.arange(h, len(D)), D[h:], 1)[0]
    if s2 < 0.5*s1 and s2 < 0:
        return 'CONTRACTING'
    if abs(s2 - s1) < 0.5*abs(s1) and abs(s1) < 0.05*max(np.mean(D),
                                                          1e-9):
        return 'FLAT'
    if s2 > 1.5*s1:
        return 'GROWING-ACCELERATING'
    return 'GROWING-LINEAR'

