# =============================================================================
# THE NATIVE NTH JACOBIAN — NumPy reference (channel-explicit)
# =============================================================================
def np_nth_jacobian(u, dx):
    """THE NTH JACOBIAN, channel-explicit. Four channels from the
    gradient substrate G[i,j] = du_i/dx_j:
      C1 symmetric coupling (strain) — ALL stretching production
      C2 antisymmetric coupling (rotation) — axis = vorticity
      R determinant (volume change)
      U mirror (discarded content)
    TENSION = C1 + C2 + |R|."""
    n = u.shape[0]
    G = np.empty((n, n, n, 3, 3))
    for i in range(3):
        for j in range(3):
            G[..., i, j] = (np.roll(u[..., i], -1, axis=j)
                            - np.roll(u[..., i], 1, axis=j))*(0.5/dx)
    S = 0.5*(G + np.swapaxes(G, -1, -2))
    C1 = np.sqrt(np.sum(S*S, axis=(-2, -1)))
    A = 0.5*(G - np.swapaxes(G, -1, -2))
    C2 = np.sqrt(np.sum(A*A, axis=(-2, -1)))
    a, b, c = G[..., 0, 0], G[..., 0, 1], G[..., 0, 2]
    d, e, f_ = G[..., 1, 0], G[..., 1, 1], G[..., 1, 2]
    g_, h, i_ = G[..., 2, 0], G[..., 2, 1], G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    Gf = np.sqrt(np.sum(G*G, axis=(-2, -1)))
    U = Gf - np.abs(R)
    tension = C1 + C2 + np.abs(R)
    vort = np.stack([G[..., 2, 1] - G[..., 1, 2],
                     G[..., 0, 2] - G[..., 2, 0],
                     G[..., 1, 0] - G[..., 0, 1]], axis=-1)
    return {'G': G, 'C1': C1, 'C2': C2, 'R': R, 'U': U,
            'tension': tension, 'vort': vort}

# =============================================================================
# THE NUMPY REFERENCE CASCADE (v9-validated, verbatim)
# =============================================================================
def np_dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis))*(0.5/dx)

def np_restrict(F):
    a, b, c = F.shape[-3], F.shape[-2], F.shape[-1]
    out = F.reshape(F.shape[:-3] + (a//2, 2, b//2, 2, c//2, 2))
    return out.mean(axis=(-5, -3, -1))

def np_interp1(F, axis):
    n = F.shape[axis]
    shp = list(F.shape); shp[axis] = 2*n
    G = np.empty(shp, dtype=F.dtype)
    se = [slice(None)]*F.ndim; se[axis] = slice(0, 2*n, 2)
    G[tuple(se)] = F
    so = [slice(None)]*F.ndim; so[axis] = slice(1, 2*n, 2)
    G[tuple(so)] = 0.5*(F + np.roll(F, -1, axis=axis))
    return G

def np_prolong(C):
    F = np_interp1(C, C.ndim - 3)
    F = np_interp1(F, F.ndim - 2)
    F = np_interp1(F, F.ndim - 1)
    return F

def np_lap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    for a in (F.ndim - 3, F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s*inv

_RBGS_MASKS = {}
def np_rb_mask(m):
    if m not in _RBGS_MASKS:
        idx = np.indices((m, m, m))
        parity = (idx[0] + idx[1] + idx[2]) % 2
        _RBGS_MASKS[m] = (parity == 0, parity == 1)
    return _RBGS_MASKS[m]

def np_smooth_gs(phi, f, dx, iters):
    """Red-black GS, v5 sign convention: phi -= (h^2/6)(f - L phi)."""
    c = dx*dx/6.0
    red, black = np_rb_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - np_lap_apply(phi, dx)
        phi = phi - c*np.where(red, r, 0.0)
        r = f - np_lap_apply(phi, dx)
        phi = phi - c*np.where(black, r, 0.0)
    return phi

def np_v_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - f.mean(axis=(-3, -2, -1), keepdims=True)
        return np_smooth_gs(phi, f, dx, 40)
    phi = np_smooth_gs(phi, f, dx, 2)
    r = f - np_lap_apply(phi, dx)
    rc = np_restrict(r)
    ec = np_v_cycle(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + np_prolong(ec)
    return np_smooth_gs(phi, f, dx, 2)

def np_split_classes(f):
    N = f.shape[-1]
    M = N//2
    out = np.empty(f.shape[:-3] + (8, M, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out[..., c, :, :, :] = f[..., a::2, b::2, d_::2]
                c += 1
    return out

def np_merge_classes(g, N):
    f = np.empty(g.shape[:-4] + (N, N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                f[..., a::2, b::2, d_::2] = g[..., c, :, :, :]
                c += 1
    return f

def np_div_bundle(V, dx):
    out = np.zeros(V.shape[:-1])
    for j in range(3):
        out += np_dd(V[..., j], V.ndim - 4 + j, dx)
    return out

def np_grad_bundle(phi, dx):
    return np.stack([np_dd(phi, phi.ndim - 3 + j, dx)
                     for j in range(3)], axis=-1)

def np_project_channels(V, dx, tol=1e-9, max_cycles=20):
    """The v9-validated Whole-Term projection (channels) — THE
    REFERENCE."""
    f = -np_div_bundle(V, dx)
    fc = np_split_classes(f)
    H = 2.0*dx
    fc = fc - fc.mean(axis=(-3, -2, -1), keepdims=True)
    f0 = np.sqrt(np.sum(fc*fc, axis=(-3, -2, -1)))
    live = f0 > 1e-300
    fc = fc*live[..., None, None, None]
    psic = np.zeros_like(fc)
    psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
    cycles = 0
    if live.any():
        def rel_resid():
            r = fc - np_lap_apply(psic, H)
            rn = np.sqrt(np.sum(r*r, axis=(-3, -2, -1)))
            return float(np.max((rn/np.maximum(f0, 1e-300))[live]))
        worst = rel_resid()
        while worst >= tol and cycles < max_cycles:
            psic = np_v_cycle(psic, fc, H)
            psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
            cycles += 1
            worst = rel_resid()
    phi_out = np_merge_classes(psic, V.shape[-3])
    gu = np_grad_bundle(phi_out, dx)
    return V + gu

# =============================================================================
# ICs — NumPy (identical to V22.2)
# =============================================================================
A_SWIRL = 6.0
W_GOLD = 12.0/PHI
SIGMA = 1.0
A_WIND = 0.35

def np_mesh(n):
    x = np.linspace(0.0, L_dom, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), L_dom/n

def ic_tubes(axes, strength=8.0, sigma=0.8, sep=1.6, tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt); st = np.sin(tilt)
    def tube(cx, sign):
        dx_ = (x - cx + L_half) % L_dom - L_half
        dy_ = (y - np.pi + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        r2 = dx_t*dx_t + dy_*dy_
        f = np.exp(-r2/(2.0*sigma*sigma))
        return np.stack([-sign*strength*dy_*f,
                         sign*strength*dx_t*f,
                         np.zeros_like(x)], axis=-1)
    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)

def ic_wound(axes):
    x, y, z = axes
    xc = np.pi + A_WIND*np.sin(z)
    yc = np.pi + A_WIND*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA*SIGMA))
    return np.stack([-A_SWIRL*ry*f, A_SWIRL*rx*f, W_GOLD*f], axis=-1)

def ic_random(axes, seed=101, n_modes=6, target_E=500.0):
    rng = np.random.default_rng(seed)
    n = axes[0].shape[0]
    dxg = L_dom/n
    def smooth_band(f):
        for _ in range(3):
            for a in (0, 1, 2):
                f = 0.5*f + 0.25*(np.roll(f, -1, axis=a)
                                  + np.roll(f, 1, axis=a))
        fh = np.fft.fftn(f)
        k = np.fft.fftfreq(n)*(n/(2.0*np.pi))
        KX, KY, KZ = np.meshgrid(k, k, k, indexing='ij')
        mask = (np.abs(KX) <= n_modes) & (np.abs(KY) <= n_modes) \
            & (np.abs(KZ) <= n_modes)
        return np.real(np.fft.ifftn(fh*mask))
    psi1 = smooth_band(rng.standard_normal((n, n, n)))
    psi2 = smooth_band(rng.standard_normal((n, n, n)))
    def ddx(f, ax):
        return (np.roll(f, -1, axis=ax) - np.roll(f, 1, axis=ax))*(0.5/dxg)
    u = np.empty((n, n, n, 3))
    u[..., 0] = -ddx(psi2, 2)
    u[..., 1] = ddx(psi1, 2)
    u[..., 2] = ddx(psi2, 0) - ddx(psi1, 1)
    norm = np.sqrt(float(np.sum(u*u)))
    u = u/max(norm, 1e-30)
    return np.sqrt(2.0*target_E/dxg**3)*u

def build_ics_np(n):
    axes, dx = np_mesh(n)
    return {'tubes': ic_tubes(axes), 'wound': ic_wound(axes),
            'random': ic_random(axes)}, dx

# =============================================================================
# THE JAX CORE — the native Nth Jacobian's exact image
# =============================================================================
def jdd(f, axis, dx):
    return (jnp.roll(f, -1, axis=axis) - jnp.roll(f, 1, axis=axis)) \
        * (0.5/dx)

def jnth_jacobian(u, dx):
    """THE NATIVE NTH JACOBIAN, JAX image of np_nth_jacobian."""
    gu = []
    for i in range(3):
        for j in range(3):
            gu.append(jdd(u[..., i], j + 1, dx))
    G = jnp.stack(gu, axis=-1)
    Cb, nb = u.shape[0], u.shape[1]
    G = G.reshape(Cb, nb, nb, nb, 3, 3)
    S = 0.5*(G + jnp.swapaxes(G, -1, -2))
    C1 = jnp.sqrt(jnp.sum(S*S, axis=(-2, -1)))
    A = 0.5*(G - jnp.swapaxes(G, -1, -2))
    C2 = jnp.sqrt(jnp.sum(A*A, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    tension = C1 + C2 + jnp.abs(R)
    return G, C1, C2, R, tension

def jlap(u, dx):
    inv = 1.0/(dx*dx)
    out = -6.0*u
    for a in (1, 2, 3):
        out = out + jnp.roll(u, -1, axis=a) + jnp.roll(u, 1, axis=a)
    return out*inv

def jadvect(f, v, dx):
    parts = []
    for i in range(3):
        fi = f[..., i]
        acc = jnp.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc = acc + 0.5*(jdd(vj*fi, j + 1, dx)
                             + vj*jdd(fi, j + 1, dx))
        parts.append(acc)
    return jnp.stack(parts, axis=-1)

def jaxis_dominant(C1, C2, G, dx):
    rot_dom = C2 > C1
    w0 = G[..., 2, 1] - G[..., 1, 2]
    w1 = G[..., 0, 2] - G[..., 2, 0]
    w2 = G[..., 1, 0] - G[..., 0, 1]
    wn = jnp.sqrt(w0*w0 + w1*w1 + w2*w2)
    gs0 = jdd(C1, 1, dx); gs1 = jdd(C1, 2, dx); gs2 = jdd(C1, 3, dx)
    gn = jnp.sqrt(gs0*gs0 + gs1*gs1 + gs2*gs2)
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    ax_v = jnp.stack([w0, w1, w2], axis=-1) \
        / jnp.maximum(wn, 1e-30)[..., None]
    ax_g = jnp.stack([gs0, gs1, gs2], axis=-1) \
        / jnp.maximum(gn, 1e-30)[..., None]
    axis = jnp.where(use_v[..., None], ax_v,
                     jnp.where(use_g[..., None], ax_g,
                               jnp.zeros_like(ax_v)))
    return axis

def jomega_transfer(u, p, G, C1, C2, R, tension, dx, threshold, gain):
    excess = jnp.maximum(tension - threshold[:, None, None, None], 0.0)
    g = gain*excess*dx
    t_ = g/(1.0 + g)
    c = (1.0 - t_*t_)/(1.0 + t_*t_)
    s = (2.0*t_)/(1.0 + t_*t_)
    m = u + p
    d = 0.5*(u - p)
    axis = jaxis_dominant(C1, C2, G, dx)
    Pd = jnp.cross(axis, d)
    PPd = jnp.cross(axis, Pd)
    d_ax = d + PPd
    d_tr = d - d_ax
    Ptr = jnp.cross(axis, d_tr)
    d_new = d_ax + c[..., None]*d_tr + s[..., None]*Ptr
    return 0.5*m + d_new, 0.5*m - d_new

# ---- the FAITHFUL cascade port ([N1]-[N3]) ----------------------------------
def jrestrict(F):
    """The CLASS GATHER (mod-2 decomposition into 8 classes) — matches
    np_split_classes exactly. NOT the V-cycle restriction."""
    classes = []
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                classes.append(F[:, a::2, b::2, d_::2])
    return jnp.stack(classes, axis=1)

def jmerge(G8, n):
    """The CLASS DISPERSE — matches np_merge_classes exactly."""
    out = jnp.zeros((G8.shape[0], n, n, n), dtype=G8.dtype)
    idx = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out = out.at[:, a::2, b::2, d_::2].set(G8[:, idx])
                idx += 1
    return out

def jrestrict_fw(F):
    """[N2] Full-weighting restriction on the last three axes — the
    reference's np_restrict, verbatim."""
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    out = F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2))
    return out.mean(axis=(-5, -3, -1))

def j_interp1(F, axis):
    """[N2] Linear interpolation on one axis — the reference's
    np_interp1, ported via stack+reshape (even positions = F, odd
    positions = 0.5*(F + roll(F,-1)) — verified equivalent)."""
    n = F.shape[axis]
    odd = 0.5*(F + jnp.roll(F, -1, axis=axis))
    out = jnp.stack([F, odd], axis=axis + 1)
    new_shape = list(F.shape)
    new_shape[axis] = 2*n
    return out.reshape(new_shape)

def jprolong(C):
    """[N2] The reference's np_prolong, verbatim."""
    F = j_interp1(C, C.ndim - 3)
    F = j_interp1(F, F.ndim - 2)
    F = j_interp1(F, F.ndim - 1)
    return F

def jdiv_bundle(V, dx):
    return jdd(V[..., 0], 1, dx) + jdd(V[..., 1], 2, dx) \
        + jdd(V[..., 2], 3, dx)

def jgrad_bundle(phi, dx):
    return jnp.stack([jdd(phi, 1, dx), jdd(phi, 2, dx),
                      jdd(phi, 3, dx)], axis=-1)

def jlap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    nd = F.ndim
    for a in (nd - 3, nd - 2, nd - 1):
        s = s + jnp.roll(F, -1, axis=a) + jnp.roll(F, 1, axis=a)
    return s*inv

def jsmooth_gs(phi, f, dx, iters):
    """[N1] The reference's red-black GS, FAITHFULLY ported. The color
    masks broadcast against the (C, 8, m, m, m) class grid on trailing
    axes. v5 sign convention: phi -= (h^2/6)(f - L phi) per color.
    lax.fori_loop for the sweep loop ([L3])."""
    c = dx*dx/6.0
    m = phi.shape[-1]
    idx = jnp.indices((m, m, m))
    parity = (idx[0] + idx[1] + idx[2]) % 2
    red = (parity == 0)
    black = (parity == 1)

    def body(i, phi_):
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - c*jnp.where(red, r, 0.0)
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - c*jnp.where(black, r, 0.0)
        return phi_

    return lax.fori_loop(0, iters, body, phi)

def jv_cycle(phi, f, dx):
    """[N3] The reference's V-cycle, FAITHFULLY ported: 2 pre/post GS
    sweeps, 40 at base, full-weighting restriction, interpolation
    prolongation."""
    if f.shape[-1] <= 4:
        f = f - jnp.mean(f, axis=(-3, -2, -1), keepdims=True)
        return jsmooth_gs(phi, f, dx, 40)
    phi = jsmooth_gs(phi, f, dx, 2)
    r = f - jlap_apply(phi, dx)
    rc = jrestrict_fw(r)
    ec = jv_cycle(jnp.zeros_like(rc), rc, 2.0*dx)
    phi = phi + jprolong(ec)
    return jsmooth_gs(phi, f, dx, 2)

def _project_one_channel(Vch, dx):
    """Project one channel: the class decomposition (jrestrict), then
    PROJ_CYCLES=20 V-cycles of the faithful cascade, then the class
    disperse (jmerge) and gradient correction. With the faithful
    components, this IS the reference cascade with a fixed cycle count
    (the reference's tolerance loop converges within 20; extra cycles
    are harmless — GS decreases the energy monotonically)."""
    f = -jdiv_bundle(Vch, dx)
    fc = jrestrict(f)
    H = 2.0*dx
    fc = fc - jnp.mean(fc, axis=(-3, -2, -1), keepdims=True)
    psic0 = jnp.zeros_like(fc)

    def cycle_body(i, psic):
        return jv_cycle(psic, fc, H)

    psic = lax.fori_loop(0, PROJ_CYCLES, cycle_body, psic0)
    n = Vch.shape[1]
    phi_full = jmerge(psic, n)
    gphi = jgrad_bundle(phi_full, dx)
    return Vch + gphi

# ---- THE FULL STEP ----------------------------------------------------------
def jstep(u, p, nu, threshold, dx, gain=10.0):
    G, C1, C2, R, tension = jnth_jacobian(u, dx)
    M_k = jnp.max(tension.reshape(tension.shape[0], -1), axis=1)
    m = u + p
    au1 = jadvect(u, m, dx)
    ap1 = jadvect(p, m, dx)
    Lu = jlap(u, dx)
    Lp = jlap(p, dx)
    nu_ = nu[:, None, None, None, None]
    u_star = u + DT*(-au1 + nu_*Lu)
    p_star = p + DT*(-ap1 + nu_*Lp)
    m_star = u_star + p_star
    au2 = jadvect(u_star, m_star, dx)
    ap2 = jadvect(p_star, m_star, dx)
    Lu2 = jlap(u_star, dx)
    Lp2 = jlap(p_star, dx)
    u_s = u + 0.5*DT*(-(au1 + au2) + nu_*(Lu + Lu2))
    p_s = p + 0.5*DT*(-(ap1 + ap2) + nu_*(Lp + Lp2))
    u_s, p_s = jomega_transfer(u_s, p_s, G, C1, C2, R, tension, dx,
                               threshold, gain)
    u_pre = u_s
    p_pre = p_s
    u_new = _project_one_channel(u_s, dx)
    p_new = _project_one_channel(p_s, dx)
    gu = u_new - u_pre
    gp = p_new - p_pre
    vol = dx**3
    integrand = 2.0*jnp.sum(u_pre*gu, axis=-1) + jnp.sum(gu*gu, axis=-1) \
        + 2.0*jnp.sum(p_pre*gp, axis=-1) + jnp.sum(gp*gp, axis=-1)
    toll_dE = 0.5*vol*jnp.sum(integrand, axis=(1, 2, 3))
    return u_new, p_new, M_k, toll_dE

RING_T = jnp.asarray((np.arange(B_WINDOW) - (B_WINDOW - 1))*DT)

def scan_body(carry, _):
    u, p, Sigma, ring = carry
    u, p, M_k, toll = jstep(u, p, NU_ARR, THR_ARR, DX_VAL)
    Sigma = Sigma + M_k*DT
    ring = jnp.concatenate([ring[:, 1:], Sigma[:, None]], axis=1)
    tbar = jnp.mean(RING_T)
    sbar = jnp.mean(ring, axis=1)
    num = jnp.sum((RING_T - tbar)[None, :]*(ring - sbar[:, None]),
                  axis=1)
    den = jnp.sum((RING_T - tbar)**2)
    slope = num/den
    Bfit = sbar - slope*tbar
    D = jnp.abs(Sigma - Bfit)
    return (u, p, Sigma, ring), (M_k, Sigma, Bfit, D, toll)

NU_ARR = None
THR_ARR = None
DX_VAL = None

def run_batch(ics_dict, nu_list, ic_names, n, dx, steps=STEPS,
              thresh_frac=0.5, gain=10.0):
    global NU_ARR, THR_ARR, DX_VAL
    C = len(nu_list)*len(ic_names)
    u_list = []
    labels = []
    for nu in nu_list:
        for ic in ic_names:
            u_list.append(ics_dict[ic])
            labels.append((nu, ic))
    U0 = np.stack(u_list)
    P0 = np.zeros_like(U0)
    for ci in range(C):
        U0[ci] = np_project_channels(U0[ci][None], dx)[0]
    U0j = jnp.asarray(U0)
    P0j = jnp.asarray(P0)
    _, _, _, _, tension0 = jnth_jacobian(U0j, dx)
    M0 = jnp.max(tension0.reshape(C, -1), axis=1)
    THR = thresh_frac*M0
    NU = jnp.asarray(np.repeat(np.array(nu_list, dtype=np.float64),
                              len(ic_names)))
    NU_ARR = NU
    THR_ARR = THR
    DX_VAL = dx
    ring0 = jnp.zeros((C, B_WINDOW))
    carry = (U0j, P0j, jnp.zeros(C), ring0)
    t0 = time.time()
    (uF, pF, SigmaF, ringF), (Ms, Ss, Bs, Ds, tolls) = \
        lax.scan(scan_body, carry, xs=None, length=steps)
    jax.block_until_ready(SigmaF)
    wall = time.time() - t0
    print(f'  batch n={n} C={C} steps={steps}: '
          f'compiled+executed in {wall:.0f}s on {jax.devices()[0]}')
    Ms_np = np.asarray(Ms)
    Ss_np = np.asarray(Ss)
    Ds_np = np.asarray(Ds)
    tolls_np = np.asarray(tolls)
    M0_np = np.asarray(M0)
    out = {}
    for ci, (nu, ic) in enumerate(labels):
        out[(nu, ic, n)] = {
            'M': Ms_np[:, ci].tolist(),
            'Sigma': Ss_np[:, ci].tolist(),
            'D': Ds_np[:, ci].tolist(),
            'toll_cum': np.cumsum(tolls_np[:, ci]).tolist(),
            'step': list(range(steps)),
            'nu': nu, 'n': n, 'ic': ic, 'halt_step': -1,
            'M0': float(M0_np[ci]),
        }
    return out

