# =============================================================================
# NTH MATHEMATICS — V25: PATTERN-PREDICT + RES-OPERATOR PROJECTION
# The million-step resolution: fit the sustained-tail growth model,
# resolve the fixed point analytically, verify by snapshot extension.
# Complete self-contained cell. CPU or CUDA. One paste, top to bottom.
# =============================================================================
# ARCHITECTURE (three stages, per the user's design):
#   [P1] PATTERN EXTRACTION: fit three candidate growth models to the
#        sustained-tail Σ data (beyond the early transient, t > 0.4):
#          Model S (saturating): Σ(t) = B - A*exp(-k*t)
#              -> Res succeeds: the bound identity B exists
#              -> BKM integral BOUNDED (affirmative answer)
#          Model L (linear): Σ(t) = rate*t + c
#              -> Res gives the rate; the integral diverges linearly
#              -> BKM integral UNBOUNDED at constant rate (borderline)
#          Model P (power-law): Σ(t) = a*t^p + c, p > 1
#              -> Res fails to converge
#              -> BKM integral ACCELERATING (counterexample direction)
#        Model selection by AIC on the sustained tail.
#   [P2] RES-OPERATOR PROJECTION: the best-fit model evaluated at
#        t = 4000 (10^6 steps) — the fixed-point resolution, no
#        iteration. The projected Σ, the projected bound (if Model S),
#        and the model's validity envelope are reported.
#   [P3] VERIFICATION: extend the 32^3 runs to 5000 steps (t = 20,
#        5x beyond the fitting data at that resolution) and check the
#        projected pattern against the actual evolution at snapshot
#        intervals. If the model holds at t=20, the projection to
#        t=4000 is computational evidence; if not, the model class
#        is rejected and that is reported.
# PRE-REGISTERED PREDICTIONS (from the V24 R2 surprise):
#   tubes: the deceleration continues; Model S or L fits best
#     (the accumulation is saturating or approaching constant rate)
#   wound: the acceleration continues; Model P fits best
#     (the accumulation is accelerating beyond linear)
#   IF both predictions hold: the split has INVERTED at long horizon
#     (tubes -> affirmative, wound -> counterexample) and the V25
#     projection captures each direction's asymptotic character.
#   IF both fit Model S: the affirmative answer holds globally.
#   IF both fit Model P: the counterexample direction is global.
# RUNTIME: gates ~1 min + 32^3 x 5000 steps ~2-3 min + 64^3 x 1000
#   re-run (if V24 not in session) ~2 min. Total GPU ~5-8 min.
# =============================================================================
import os
import time
import numpy as np
import matplotlib.pyplot as plt
from scipy import optimize

np.set_printoptions(precision=6, suppress=True)
TAU = 6.283185307179586
PHI = 0.5*(1.0 + np.sqrt(5.0))
L_dom = 2.0*np.pi
L_half = L_dom/2.0
DT = 0.004
B_WINDOW = 60
SAVE_DIR = '/content/v25_results'
os.makedirs(SAVE_DIR, exist_ok=True)

def make_tag(*parts):
    return ','.join(str(p) for p in parts)

# =============================================================================
# SYNTHETIC PATTERN GENERATION (the growth models as generative tests)
# =============================================================================
def model_saturating(t, B, A, k):
    """Model S: Σ(t) = B - A*exp(-k*t). B = the bound identity (Res)."""
    return B - A*np.exp(-k*t)

def model_linear(t, rate, c):
    """Model L: Σ(t) = rate*t + c. Constant accumulation rate."""
    return rate*t + c

def model_power(t, a, p, c):
    """Model P: Σ(t) = a*t^p + c, p > 1. Accelerating."""
    return a*np.power(t, p) + c

def fit_models(t_data, s_data, t_min=0.4):
    """Fit all three models to the sustained tail (t >= t_min).
    Returns (fits, aic_scores, best_model_name)."""
    mask = t_data >= t_min
    t_fit = t_data[mask]
    s_fit = s_data[mask]
    n = len(t_fit)
    if n < 10:
        return None, None, None

    fits = {}
    aic = {}

    # Model S: saturating
    try:
        s_max = s_fit[-1]
        s_range = max(s_fit[-1] - s_fit[0], 1e-9)
        p0_S = [s_max + 0.5*s_range, s_range, 0.5]
        popt_S, _ = optimize.curve_fit(model_saturating, t_fit, s_fit,
                                       p0=p0_S, maxfev=10000)
        resid_S = s_fit - model_saturating(t_fit, *popt_S)
        ss_S = float(np.sum(resid_S**2))
        k_S = 3  # parameters
        aic_S = n*np.log(max(ss_S/n, 1e-30)) + 2*k_S
        fits['S'] = popt_S
        aic['S'] = aic_S
    except Exception:
        fits['S'] = None
        aic['S'] = np.inf

    # Model L: linear
    try:
        popt_L, _ = optimize.curve_fit(model_linear, t_fit, s_fit,
                                       p0=[(s_fit[-1]-s_fit[0])/
                                           max(t_fit[-1]-t_fit[0], 1e-9),
                                           s_fit[0]])
        resid_L = s_fit - model_linear(t_fit, *popt_L)
        ss_L = float(np.sum(resid_L**2))
        k_L = 2
        aic_L = n*np.log(max(ss_L/n, 1e-30)) + 2*k_L
        fits['L'] = popt_L
        aic['L'] = aic_L
    except Exception:
        fits['L'] = None
        aic['L'] = np.inf

    # Model P: power law (p > 1 required)
    try:
        # estimate p from log-log slope
        log_t = np.log(np.maximum(t_fit, 1e-9))
        log_s = np.log(np.maximum(s_fit, 1e-9))
        p_est = max(np.polyfit(log_t, log_s, 1)[0], 1.05)
        a_est = s_fit[-1] / max(t_fit[-1]**p_est, 1e-9)
        p0_P = [a_est, p_est, 0.0]
        popt_P, _ = optimize.curve_fit(model_power, t_fit, s_fit,
                                        p0=p0_P, maxfev=10000)
        # enforce p > 1 for Model P; if p <= 1 it degenerates to L
        if popt_P[1] <= 1.0:
            popt_P = list(popt_P)
            popt_P[1] = 1.001
            popt_P = tuple(popt_P)
        resid_P = s_fit - model_power(t_fit, *popt_P)
        ss_P = float(np.sum(resid_P**2))
        k_P = 3
        aic_P = n*np.log(max(ss_P/n, 1e-30)) + 2*k_P
        fits['P'] = popt_P
        aic['P'] = aic_P
    except Exception:
        fits['P'] = None
        aic['P'] = np.inf

    # best model by AIC (lower = better)
    valid = {k_: v for k_, v in aic.items() if np.isfinite(v)}
    if not valid:
        return fits, aic, None
    best = min(valid, key=valid.get)
    return fits, aic, best

def project_to_target(best, fits, t_target):
    """[P2] The Res-operator projection: evaluate the best model at
    t_target. Returns (Sigma_projected, bound_or_None, model_name,
    interpretation)."""
    if best is None or fits.get(best) is None:
        return None, None, None, 'FIT FAILED'
    if best == 'S':
        B, A, k = fits['S']
        sigma_proj = model_saturating(t_target, B, A, k)
        return sigma_proj, B, 'S', \
            'SATURATING: the accumulation resolves to the bound ' \
            f'identity B = {B:.2f}. BKM integral BOUNDED (affirmative).'
    if best == 'L':
        rate, c = fits['L']
        sigma_proj = model_linear(t_target, rate, c)
        return sigma_proj, None, 'L', \
            f'LINEAR: constant rate {rate:.4f}/step. BKM integral ' \
            'diverges linearly (borderline: bounded rate, unbounded ' \
            'integral).'
    if best == 'P':
        a, p, c = fits['P']
        sigma_proj = model_power(t_target, a, p, c)
        return sigma_proj, None, 'P', \
            f'POWER-LAW (p={p:.3f} > 1): accelerating. BKM integral ' \
            'diverges super-linearly (counterexample direction).'
    return None, None, None, 'UNKNOWN MODEL'

# =============================================================================
# SYNTHETIC DATA TEST (the models must recover known patterns)
# =============================================================================
print('='*79)
print('V25 STAGE 0: SYNTHETIC MODEL RECOVERY TEST')
print('='*79)

rng_test = np.random.default_rng(42)
t_test = np.arange(50, 1001)*DT  # sustained tail: t = 0.2 to 4.0

for true_model, true_params, true_name in (
    (model_saturating, (5000.0, 3000.0, 0.8), 'SATURATING'),
    (model_linear, (15.0, 500.0), 'LINEAR'),
    (model_power, (2.0, 1.5, 100.0), 'POWER-LAW p=1.5')):
    s_true = true_model(t_test, *true_params)
    s_noisy = s_true + rng_test.normal(0, 0.005*np.max(np.abs(s_true)),
                                        len(t_test))
    fits_t, aic_t, best_t = fit_models(t_test, s_noisy, t_min=0.4)
    if best_t is not None:
        delta_aic = {k_: aic_t[k_] - aic_t[best_t]
                    for k_ in aic_t if np.isfinite(aic_t[k_])}
        print(f'  true = {true_name:16s} -> best fit = {best_t}  '
              f'(ΔAIC: S={delta_aic.get("S", "inf"):.1f}, '
              f'L={delta_aic.get("L", "inf"):.1f}, '
              f'P={delta_aic.get("P", "inf"):.1f})')
        if best_t == 'S' and true_name == 'SATURATING':
            B_fit = fits_t['S'][0]
            print(f'       recovered bound B = {B_fit:.1f} '
                  f'(true = {true_params[0]:.1f})')
    else:
        print(f'  true = {true_name:16s} -> FIT FAILED')

print('\n  (the model selection must recover known patterns before')
print('   it is trusted on the fluid data.)')

# =============================================================================
# THE FLUID DATA (re-run 64³×1000 + 32³×5000, or load from persistence)
# =============================================================================
# Since the V24 session is likely gone, we re-run the needed data.
# The 64³ 1000-step run provides the fitting data; the 32³ 5000-step
# run provides the verification snapshot.

print('\n' + '#'*79)
print('V25 — PATTERN-PREDICT + RES-PROJECTION + VERIFICATION')
print('#'*79)

# --- rebuild the compiled stack (all V23.7/V24 code, verbatim) ---
import jax
jax.config.update("jax_enable_x64", True)
import jax.numpy as jnp
from jax import lax

print('backend:', jax.devices())

PROJ_CYCLES = 20

def np_mesh(n):
    x = np.linspace(0.0, L_dom, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), L_dom/n

def ic_tubes(axes, strength=8.0, sigma=0.8, sep=1.6, tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt); st = np.sin(tilt)
    def tube(cx, sign):
        dx_ = (x - cx + L_half) % L_dom - L_half
        dy_ = (y - np.pi + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        r2 = dx_t*dx_t + dy_*dy_
        f = np.exp(-r2/(2.0*sigma*sigma))
        return np.stack([-sign*strength*dy_*f,
                         sign*strength*dx_t*f,
                         np.zeros_like(x)], axis=-1)
    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)

def ic_wound(axes):
    x, y, z = axes
    xc = np.pi + A_WIND*np.sin(z)
    yc = np.pi + A_WIND*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA*SIGMA))
    return np.stack([-A_SWIRL*ry*f, A_SWIRL*rx*f, W_GOLD*f], axis=-1)

A_SWIRL = 6.0
W_GOLD = 12.0/PHI
SIGMA = 1.0
A_WIND = 0.35

def np_dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis))*(0.5/dx)

def np_restrict(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))

def np_interp1(F, axis):
    n = F.shape[axis]
    shp = list(F.shape); shp[axis] = 2*n
    G = np.empty(shp, dtype=F.dtype)
    se = [slice(None)]*F.ndim; se[axis] = slice(0, 2*n, 2)
    G[tuple(se)] = F
    so = [slice(None)]*F.ndim; so[axis] = slice(1, 2*n, 2)
    G[tuple(so)] = 0.5*(F + np.roll(F, -1, axis=axis))
    return G

def np_prolong(C):
    F = np_interp1(C, C.ndim - 3)
    F = np_interp1(F, F.ndim - 2)
    F = np_interp1(F, F.ndim - 1)
    return F

def np_lap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    for a in (F.ndim - 3, F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s*inv

_RBGS_MASKS = {}
def np_rb_mask(m):
    if m not in _RBGS_MASKS:
        idx = np.indices((m, m, m))
        parity = (idx[0] + idx[1] + idx[2]) % 2
        _RBGS_MASKS[m] = (parity == 0, parity == 1)
    return _RBGS_MASKS[m]

def np_smooth_gs(phi, f, dx, iters):
    c = dx*dx/6.0
    red, black = np_rb_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - np_lap_apply(phi, dx)
        phi = phi - c*np.where(red, r, 0.0)
        r = f - np_lap_apply(phi, dx)
        phi = phi - c*np.where(black, r, 0.0)
    return phi

def np_v_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - f.mean(axis=(-3, -2, -1), keepdims=True)
        return np_smooth_gs(phi, f, dx, 40)
    phi = np_smooth_gs(phi, f, dx, 2)
    r = f - np_lap_apply(phi, dx)
    rc = np_restrict(r)
    ec = np_v_cycle(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + np_prolong(ec)
    return np_smooth_gs(phi, f, dx, 2)

def np_split_classes(f):
    N = f.shape[-1]
    M = N//2
    out = np.empty(f.shape[:-3] + (8, M, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out[..., c, :, :, :] = f[..., a::2, b::2, d_::2]
                c += 1
    return out

def np_merge_classes(g, N):
    f = np.empty(g.shape[:-4] + (N, N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                f[..., a::2, b::2, d_::2] = g[..., c, :, :, :]
                c += 1
    return f

def np_div_bundle(V, dx):
    out = np.zeros(V.shape[:-1])
    for j in range(3):
        out += np_dd(V[..., j], V.ndim - 4 + j, dx)
    return out

def np_grad_bundle(phi, dx):
    return np.stack([np_dd(phi, phi.ndim - 3 + j, dx)
                     for j in range(3)], axis=-1)

def np_project_channels(V, dx, tol=1e-9, max_cycles=20):
    f = -np_div_bundle(V, dx)
    fc = np_split_classes(f)
    H = 2.0*dx
    fc = fc - fc.mean(axis=(-3, -2, -1), keepdims=True)
    psic = np.zeros_like(fc)
    psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
    cycles = 0
    while cycles < max_cycles:
        psic = np_v_cycle(psic, fc, H)
        psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
        cycles += 1
        r = fc - np_lap_apply(psic, H)
        rn = np.sqrt(np.sum(r*r))
        if rn < tol*np.sqrt(np.sum(fc*fc)):
            break
    phi_out = np_merge_classes(psic, V.shape[-3])
    gu = np_grad_bundle(phi_out, dx)
    return V + gu

# --- the JAX core (V23.7 faithful, verbatim) ---
def jdd(f, axis, dx):
    return (jnp.roll(f, -1, axis=axis) - jnp.roll(f, 1, axis=axis)) \
        * (0.5/dx)

def jnth_jacobian(u, dx):
    gu = []
    for i in range(3):
        for j in range(3):
            gu.append(jdd(u[..., i], j + 1, dx))
    G = jnp.stack(gu, axis=-1)
    Cb, nb = u.shape[0], u.shape[1]
    G = G.reshape(Cb, nb, nb, nb, 3, 3)
    S = 0.5*(G + jnp.swapaxes(G, -1, -2))
    C1 = jnp.sqrt(jnp.sum(S*S, axis=(-2, -1)))
    A = 0.5*(G - jnp.swapaxes(G, -1, -2))
    C2 = jnp.sqrt(jnp.sum(A*A, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    tension = C1 + C2 + jnp.abs(R)
    return G, C1, C2, R, tension

def jlap(u, dx):
    inv = 1.0/(dx*dx)
    out = -6.0*u
    for a in (1, 2, 3):
        out = out + jnp.roll(u, -1, axis=a) + jnp.roll(u, 1, axis=a)
    return out*inv

def jadvect(f, v, dx):
    parts = []
    for i in range(3):
        fi = f[..., i]
        acc = jnp.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc = acc + 0.5*(jdd(vj*fi, j + 1, dx)
                             + vj*jdd(fi, j + 1, dx))
        parts.append(acc)
    return jnp.stack(parts, axis=-1)

def jaxis_dominant(C1, C2, G, dx):
    rot_dom = C2 > C1
    w0 = G[..., 2, 1] - G[..., 1, 2]
    w1 = G[..., 0, 2] - G[..., 2, 0]
    w2 = G[..., 1, 0] - G[..., 0, 1]
    wn = jnp.sqrt(w0*w0 + w1*w1 + w2*w2)
    gs0 = jdd(C1, 1, dx); gs1 = jdd(C1, 2, dx); gs2 = jdd(C1, 3, dx)
    gn = jnp.sqrt(gs0*gs0 + gs1*gs1 + gs2*gs2)
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    ax_v = jnp.stack([w0, w1, w2], axis=-1) \
        / jnp.maximum(wn, 1e-30)[..., None]
    ax_g = jnp.stack([gs0, gs1, gs2], axis=-1) \
        / jnp.maximum(gn, 1e-30)[..., None]
    axis = jnp.where(use_v[..., None], ax_v,
                     jnp.where(use_g[..., None], ax_g,
                               jnp.zeros_like(ax_v)))
    return axis

def jomega_transfer(u, p, G, C1, C2, R, tension, dx, threshold, gain):
    excess = jnp.maximum(tension - threshold[:, None, None, None], 0.0)
    g = gain*excess*dx
    t_ = g/(1.0 + g)
    c = (1.0 - t_*t_)/(1.0 + t_*t_)
    s = (2.0*t_)/(1.0 + t_*t_)
    m = u + p
    d = 0.5*(u - p)
    axis = jaxis_dominant(C1, C2, G, dx)
    Pd = jnp.cross(axis, d)
    PPd = jnp.cross(axis, Pd)
    d_ax = d + PPd
    d_tr = d - d_ax
    Ptr = jnp.cross(axis, d_tr)
    d_new = d_ax + c[..., None]*d_tr + s[..., None]*Ptr
    return 0.5*m + d_new, 0.5*m - d_new

def jrestrict(F):
    classes = []
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                classes.append(F[:, a::2, b::2, d_::2])
    return jnp.stack(classes, axis=1)

def jmerge(G8, n):
    out = jnp.zeros((G8.shape[0], n, n, n), dtype=G8.dtype)
    idx = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out = out.at[:, a::2, b::2, d_::2].set(G8[:, idx])
                idx += 1
    return out

def jrestrict_fw(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))

def j_interp1(F, axis):
    n = F.shape[axis]
    odd = 0.5*(F + jnp.roll(F, -1, axis=axis))
    out = jnp.stack([F, odd], axis=axis + 1)
    new_shape = list(F.shape)
    new_shape[axis] = 2*n
    return out.reshape(new_shape)

def jprolong(C):
    F = j_interp1(C, C.ndim - 3)
    F = j_interp1(F, F.ndim - 2)
    F = j_interp1(F, F.ndim - 1)
    return F

def jdiv_bundle(V, dx):
    return jdd(V[..., 0], 1, dx) + jdd(V[..., 1], 2, dx) \
        + jdd(V[..., 2], 3, dx)

def jgrad_bundle(phi, dx):
    return jnp.stack([jdd(phi, 1, dx), jdd(phi, 2, dx),
                      jdd(phi, 3, dx)], axis=-1)

def jlap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    nd = F.ndim
    for a in (nd - 3, nd - 2, nd - 1):
        s = s + jnp.roll(F, -1, axis=a) + jnp.roll(F, 1, axis=a)
    return s*inv

def jsmooth_gs(phi, f, dx, iters):
    c = dx*dx/6.0
    m = phi.shape[-1]
    idx = jnp.indices((m, m, m))
    parity = (idx[0] + idx[1] + idx[2]) % 2
    red = (parity == 0)
    black = (parity == 1)
    def body(i, phi_):
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - c*jnp.where(red, r, 0.0)
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - c*jnp.where(black, r, 0.0)
        return phi_
    return lax.fori_loop(0, iters, body, phi)

def jv_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - jnp.mean(f, axis=(-3, -2, -1), keepdims=True)
        return jsmooth_gs(phi, f, dx, 40)
    phi = jsmooth_gs(phi, f, dx, 2)
    r = f - jlap_apply(phi, dx)
    rc = jrestrict_fw(r)
    ec = jv_cycle(jnp.zeros_like(rc), rc, 2.0*dx)
    phi = phi + jprolong(ec)
    return jsmooth_gs(phi, f, dx, 2)

def _project_one_channel(Vch, dx):
    f = -jdiv_bundle(Vch, dx)
    fc = jrestrict(f)
    H = 2.0*dx
    fc = fc - jnp.mean(fc, axis=(-3, -2, -1), keepdims=True)
    psic0 = jnp.zeros_like(fc)
    def cycle_body(i, psic):
        return jv_cycle(psic, fc, H)
    psic = lax.fori_loop(0, PROJ_CYCLES, cycle_body, psic0)
    n = Vch.shape[1]
    phi_full = jmerge(psic, n)
    gphi = jgrad_bundle(phi_full, dx)
    return Vch + gphi

def jstep(u, p, nu, threshold, dx, gain=10.0):
    G, C1, C2, R, tension = jnth_jacobian(u, dx)
    M_k = jnp.max(tension.reshape(tension.shape[0], -1), axis=1)
    m = u + p
    au1 = jadvect(u, m, dx)
    ap1 = jadvect(p, m, dx)
    Lu = jlap(u, dx)
    Lp = jlap(p, dx)
    nu_ = nu[:, None, None, None, None]
    u_star = u + DT*(-au1 + nu_*Lu)
    p_star = p + DT*(-ap1 + nu_*Lp)
    m_star = u_star + p_star
    au2 = jadvect(u_star, m_star, dx)
    ap2 = jadvect(p_star, m_star, dx)
    Lu2 = jlap(u_star, dx)
    Lp2 = jlap(p_star, dx)
    u_s = u + 0.5*DT*(-(au1 + au2) + nu_*(Lu + Lu2))
    p_s = p + 0.5*DT*(-(ap1 + ap2) + nu_*(Lp + Lp2))
    u_s, p_s = jomega_transfer(u_s, p_s, G, C1, C2, R, tension, dx,
                               threshold, gain)
    u_new = _project_one_channel(u_s, dx)
    p_new = _project_one_channel(p_s, dx)
    return u_new, p_new, M_k

RING_T = jnp.asarray((np.arange(B_WINDOW) - (B_WINDOW - 1))*DT)
NU_ARR = None
THR_ARR = None
DX_VAL = None

def scan_body(carry, _):
    global NU_ARR, THR_ARR, DX_VAL
    u, p, Sigma, ring = carry
    u, p, M_k = jstep(u, p, NU_ARR, THR_ARR, DX_VAL)
    Sigma = Sigma + M_k*DT
    ring = jnp.concatenate([ring[:, 1:], Sigma[:, None]], axis=1)
    tbar = jnp.mean(RING_T)
    sbar = jnp.mean(ring, axis=1)
    num = jnp.sum((RING_T - tbar)[None, :]*(ring - sbar[:, None]),
                  axis=1)
    den = jnp.sum((RING_T - tbar)**2)
    slope = num/den
    Bfit = sbar - slope*tbar
    D = jnp.abs(Sigma - Bfit)
    return (u, p, Sigma, ring), (M_k, Sigma, Bfit, D)

def run_batch(ics_dict, nu_list, ic_names, n, dx, steps,
              thresh_frac=0.5, gain=10.0):
    global NU_ARR, THR_ARR, DX_VAL
    C = len(nu_list)*len(ic_names)
    u_list = []
    labels = []
    for nu in nu_list:
        for ic in ic_names:
            u_list.append(ics_dict[ic])
            labels.append((nu, ic))
    U0 = np.stack(u_list)
    for ci in range(C):
        U0[ci] = np_project_channels(U0[ci][None], dx)[0]
    P0 = np.zeros_like(U0)
    U0j = jnp.asarray(U0)
    P0j = jnp.asarray(P0)
    _, _, _, _, tension0 = jnth_jacobian(U0j, dx)
    M0 = jnp.max(tension0.reshape(C, -1), axis=1)
    THR = thresh_frac*M0
    NU = jnp.asarray(np.repeat(np.array(nu_list, dtype=np.float64),
                              len(ic_names)))
    NU_ARR = NU
    THR_ARR = THR
    DX_VAL = dx
    ring0 = jnp.zeros((C, B_WINDOW))
    carry = (U0j, P0j, jnp.zeros(C), ring0)
    t0 = time.time()
    (uF, pF, SigmaF, ringF), (Ms, Ss, Bs, Ds) = \
        lax.scan(scan_body, carry, xs=None, length=steps)
    jax.block_until_ready(SigmaF)
    wall = time.time() - t0
    print(f'  batch n={n} C={C} steps={steps}: '
          f'{wall:.0f}s on {jax.devices()[0]}')
    Ms_np = np.asarray(Ms)
    Ss_np = np.asarray(Ss)
    Ds_np = np.asarray(Ds)
    M0_np = np.asarray(M0)
    out = {}
    for ci, (nu, ic) in enumerate(labels):
        out[(nu, ic, n)] = {
            'M': Ms_np[:, ci].tolist(),
            'Sigma': Ss_np[:, ci].tolist(),
            'D': Ds_np[:, ci].tolist(),
            'step': list(range(steps)),
            'nu': nu, 'n': n, 'ic': ic,
            'M0': float(M0_np[ci]),
        }
        fn = os.path.join(SAVE_DIR, make_tag(
            f'nu{nu:g}', ic, f'n{n}', f's{steps}'
        ).replace(',', '_') + '.npz')
        np.savez(fn, **{kk: np.asarray(vv) for kk, vv in
                        out[(nu, ic, n)].items()
                        if isinstance(vv, list)})
    return out

