# -----------------------------------------------------------------------------
# [P1] UNIT SELECTOR CIRCLE — native construction, no transcendental scalar
# -----------------------------------------------------------------------------
def unit_selector_circle(n):
    """Circle points at cyclic positions k*(2*pi/n) WITHOUT the scalar pi:
      * ground state (1,0); quarter point (0,1) = the unreal unit,
      * bisection by Appendix K nth-root selectors,
      * walk by Axiom 7.3 circle fusion."""
    assert n >= 8 and n % 4 == 0 and (n & (n - 1)) == 0
    nbis = int(round(np.log2(n // 4)))
    c, s = 0.0, 1.0
    for _ in range(nbis):
        c, s = np.sqrt(0.5*(1.0 + c)), np.sqrt(0.5*(1.0 - c))
    cs, sn = np.empty(n), np.empty(n)
    cs[0], sn[0] = 1.0, 0.0
    for k in range(1, n):
        cs[k] = cs[k-1]*c - sn[k-1]*s
        sn[k] = cs[k-1]*s + sn[k-1]*c
    nxt_c, nxt_s = cs[n-1]*c - sn[n-1]*s, cs[n-1]*s + sn[n-1]*c
    return cs, sn, float(np.hypot(nxt_c - 1.0, nxt_s))

_TAB = {}
def circle_tables(n):
    if n not in _TAB:
        _TAB[n] = unit_selector_circle(n)
    return _TAB[n]

CS32, SN32, CIRC_CLOSE = circle_tables(32)
_k = np.arange(32)
print(f'[P1] unit selector circle (n=32): cyclic closure error (Axiom 0 '
      f'audit): {CIRC_CLOSE:.2e}')
print(f'     bridge vs np.cos/np.sin (audit print only): '
      f'{np.max(np.abs(CS32 - np.cos(2*np.pi*_k/32))):.2e} / '
      f'{np.max(np.abs(SN32 - np.sin(2*np.pi*_k/32))):.2e}')

def harm(kind, m, axis, n):
    """Harmonic-m circle points along one axis, from table strides ONLY:
    tab[(m*j) mod n] = selector-circle point at cyclic position m*j —
    the same physical mode at every ladder level (wavelength L/m)."""
    cs, sn, _ = circle_tables(n)
    tab = sn if kind == 's' else cs
    vals = tab[(m * np.arange(n)) % n]
    shp = [1, 1, 1]; shp[axis] = n
    return vals.reshape(shp)

