# [P2] DR. MARTIN'S SELECTOR-SPECTRUM TRANSLATION — operational audit
# -----------------------------------------------------------------------------
def martin_spectrum_audit():
    print('\n' + '='*79)
    print('[P2] DR. MARTIN SELECTOR-SPECTRUM TRANSLATION — OPERATIONAL AUDIT')
    print('='*79)
    print('  t : n_|g,gi| / n_|1+g, 1+gi, i+g, i+gi|         8 quotient channels')
    print('  c : (1 - t^2 spectrum) / (1 + t^2 spectrum)    8 / 8 channels')
    print('  s : (2*t spectrum) / (1 + t^2 spectrum)        4 / 8 channels')
    worst_spread = 0.0; worst_bridge = 0.0
    for g in (0.5, 1.0, 2.0, 8.0, 10.0):
        den = [(1.0+g, 'real'), (1.0+g, 'unr'), (1.0+g, 'unr'), (1.0+g, 'unr')]
        num = [(g, 'real'), (g, 'unr')]
        t_ch = [(mk/dk, 'real' if mp == dp else 'unr')
                for (mk, mp) in num for (dk, dp) in den]
        t = g/(1.0 + g)
        cnum, cden, snum = [], [], []
        for po in ('real', 'unr'):
            for pb in ('real', 'unr'):
                ph = 'real' if po == pb else 'unr'   # Prop. 8 phase rule
                cnum.append((1.0 - t*t, ph))
                cden.append((1.0 + t*t, ph))
                if po == 'real':
                    snum.append((2.0*t, ph))
        for lst in (t_ch, cnum, cden, snum):
            mags = [m for m, _ in lst]
            worst_spread = max(worst_spread, max(mags) - min(mags))
        c_coll = cnum[0][0]/cden[0][0]; s_coll = snum[0][0]/cden[0][0]
        ang = 2.0*np.arctan(t)              # transcendental bridge (audit only)
        worst_bridge = max(worst_bridge, abs(c_coll - np.cos(ang)),
                           abs(s_coll - np.sin(ang)))
        if g == 8.0:
            n_re = sum(1 for _, ph in t_ch if ph == 'real')
            print(f'  sample g=8.0: t channels = {len(t_ch)} '
                  f'({n_re} real, {len(t_ch)-n_re} unreal), magnitude {t:.6f}')
            print(f'               c = {c_coll:.6f}, s = {s_coll:.6f} '
                  f'(angle {np.degrees(ang):.2f} deg — below a quarter phase '
                  f'for EVERY routed g >= 0)')
    print(f'  worst channel-magnitude spread (quotient collapse, Prop. 8 '
          f'cor.): {worst_spread:.2e}')
    print(f'  worst bridge deviation vs transcendental angle: {worst_bridge:.2e}')
    print('  the evolution consumes exactly these collapsed magnitudes')
    print('  (circle_pair_from_gain below): floats unchanged, provenance')
    print('  selector-native.')

martin_spectrum_audit()

# -----------------------------------------------------------------------------
# 2. FUSION STENCILS — F/B mirror pair and centered output fusion
# -----------------------------------------------------------------------------
def F_(f, ax, dx):
    return (np.roll(f, -1, axis=ax) - f) / dx
def B_(f, ax, dx):
    return (f - np.roll(f, 1, axis=ax)) / dx
def dd_(f, ax, dx):
    return (np.roll(f, -1, axis=ax) - np.roll(f, 1, axis=ax)) * (0.5/dx)

def div_B(w, dx):
    return B_(w[..., 0], 0, dx) + B_(w[..., 1], 1, dx) + B_(w[..., 2], 2, dx)

def A_apply(phi, dx):
    """PSD fusion Laplacian A = F^T F (last three axes spatial). Null space:
    constants only — cyclic closure removes the null direction."""
    out = 6.0*phi
    for ax in range(phi.ndim - 3, phi.ndim):
        out = out - np.roll(phi, -1, axis=ax) - np.roll(phi, 1, axis=ax)
    return out / (dx*dx)

def visc_op(w, dx):
    """Nth-Divergence (Axiom 5.1) per component: compact fusion Laplacian.
    Exact dissipation identity: sum w.visc(w) = -sum_j |F_j w|^2."""
    out = np.empty_like(w)
    for j in range(3):
        out[..., j] = -A_apply(w[..., j], dx)
    return out

# -----------------------------------------------------------------------------
# 3. STRUCTURAL FUSION CASCADE — whole-term projection (gather/fuse/disperse)
# -----------------------------------------------------------------------------
_WJ = 2.0/3.0

def _wjac(phi, b, dx):
    return phi + (_WJ*dx*dx/6.0)*(b - A_apply(phi, dx))

def _restrict(f):
    lead, nf = f.shape[:-3], f.shape[-1]; nc = nf//2
    g = f.reshape(lead + (nc, 2, nc, 2, nc, 2))
    return g.mean(axis=(-5, -3, -1))

def _blow1d(a):
    nc = a.shape[-1]
    out = np.empty(a.shape[:-1] + (2*nc,))
    out[..., 0::2] = 0.75*a + 0.25*np.roll(a, 1, axis=-1)
    out[..., 1::2] = 0.75*a + 0.25*np.roll(a, -1, axis=-1)
    return out

def _prolong(c):
    f = c.copy()
    for ax in (f.ndim - 1, f.ndim - 2, f.ndim - 3):
        f = np.moveaxis(f, ax, -1); f = _blow1d(f); f = np.moveaxis(f, -1, ax)
    return f

def _vcycle(phi, b, dx, n):
    if n <= 4:
        for _ in range(60):
            phi = _wjac(phi, b, dx)
        return phi
    for _ in range(3):
        phi = _wjac(phi, b, dx)
    rc = _restrict(b - A_apply(phi, dx))
    ec = _vcycle(np.zeros_like(rc), rc, 2.0*dx, n//2)
    e = _prolong(ec)
    assert e.shape == phi.shape
    phi = phi + e
    for _ in range(2):
        phi = _wjac(phi, b, dx)
    return phi

def fusion_cascade(b, phi0, dx, tol=1e-10, max_cycles=20, stats=None):
    """Resolution solve (Axiom 5.2 pattern): finite V-cycle iteration with
    explicit tolerance and recorded termination. Classical name: multigrid."""
    phi = np.array(phi0, dtype=float, copy=True)
    maxes = tuple(range(phi.ndim - 3, phi.ndim))
    phi = phi - phi.mean(axis=maxes, keepdims=True)
    b = b - b.mean(axis=maxes, keepdims=True)
    bmax = float(np.max(np.abs(b))) + 1e-300
    n = phi.shape[-1]
    rel = np.inf; cycles = 0
    for cyc in range(max_cycles):
        phi = _vcycle(phi, b, dx, n)
        phi = phi - phi.mean(axis=maxes, keepdims=True)
        rel = float(np.max(np.abs(b - A_apply(phi, dx)))) / bmax
        cycles = cyc + 1
        if rel < tol:
            break
    if stats is not None:
        stats.append((cycles, rel))
    return phi

def project_bundle(V, dx, phi_prev, stats):
    """Whole-term projection of the (u,p) bundle (channel-first (2,n,n,n)):
    per channel solve A phi_c = F^T(channel), then channel <- channel -
    F(phi_c). Exactly energy-decreasing: strips 0.5*sum|F phi|^2 — the full
    energy of the divergent column (orthogonal: only removes, never amps)."""
    C = V.shape[0]
    b = np.empty(V.shape[:-1])
    for c in range(C):
        b[c] = -div_B(V[c], dx)
    phi = fusion_cascade(b, phi_prev, dx, stats=stats)
    for c in range(C):
        for j in range(3):
            V[c][..., j] -= F_(phi[c], j, dx)
    strip_raw = 0.0
    for c in range(C):
        for j in range(3):
            strip_raw += float(np.sum(F_(phi[c], j, dx)**2))
    return V, phi, strip_raw

# -----------------------------------------------------------------------------
# 4. SELECTOR BUNDLE DECOMPOSITION — Axiom 2.6.1 (CONTRACT-VALIDATED)
#    Incident-2 fix: the contract is enforced at FUNCTION ENTRY, in both
#    directions, with a message that names the remedy. This also rejects the
#    incident-1 allocation shape at merge entry. Vector fields stored
#    component-LAST (n,n,n,3) violate the contract — extract a component
#    first. No silent convention auto-detection, by design.
# -----------------------------------------------------------------------------
def split_classes(f):
    """Axiom 2.6.1 bundle decomposition: the 8 parity classes of the cyclic
    grid (even/odd along each spatial axis), class channel as the LAST axis.
    CONTRACT: the LAST THREE axes of f are the spatial axes — equal-sized,
    even. Leading axes (any count) are bundled channels."""
    s = f.shape
    if f.ndim < 3 or s[-1] != s[-2] or s[-2] != s[-3]:
        raise ValueError(
            'split_classes contract: last three axes must be equal-sized '
            f'spatial axes; got shape {s}. For a component-last vector field '
            '(n,n,n,3), extract a component first: split_classes(f[..., j]).')
    if s[-1] % 2:
        raise ValueError(f'split_classes: spatial axes must be even; got {s}')
    lead = s[:-3]
    h = (s[-3] // 2, s[-2] // 2, s[-1] // 2)
    out = np.empty(lead + h + (8,))
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                out[..., c] = f[..., a::2, b::2, d::2]
                c += 1
    return out

def merge_classes(g):
    """Exact inverse of split_classes. CONTRACT: LAST axis is the 8-class
    axis; the three axes before it are the equal-sized spatial axes."""
    s = g.shape
    if g.ndim < 4 or s[-1] != 8:
        raise ValueError(
            f'merge_classes contract: last axis must be the 8-class axis; '
            f'got shape {s}')
    if s[-2] != s[-3] or s[-3] != s[-4]:
        raise ValueError(
            f'merge_classes contract: axes -4..-2 must be equal-sized '
            f'spatial axes; got shape {s}')
    lead = s[:-4]
    h = s[-4:-1]
    f = np.empty(lead + (2*h[0], 2*h[1], 2*h[2]))
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d in (0, 1):
                f[..., a::2, b::2, d::2] = g[..., c]
                c += 1
    return f

def finest_scale_share(w):
    """Share of a vector channel's energy living at the finest (2-cell)
    scale, from the bundle decomposition. EXACT identity (no transform):
      total SS = between-block SS + within-block SS,
      within-block SS of the 8 parity classes = energy in the top octave.
    0 => field resolvable on the coarse lattice; -> 1 => energy piling up at
    grid scale: the discretized signature of the concentration obstruction.
    NOTE: components are extracted FIRST (w[..., j] is a pure (n,n,n)
    spatial field) — the contract-respecting path."""
    num = 0.0; den = 0.0
    for j in range(w.shape[-1]):
        f = w[..., j]
        g = split_classes(f)
        blk = g.mean(axis=-1, keepdims=True)   # block fusion average
        num += float(np.sum((g - blk)**2))
        den += float(np.sum((f - f.mean())**2))
    return num / (den + 1e-300)

# -----------------------------------------------------------------------------
# 5. NTH JACOBIAN — four structural channels of the gradient bundle
# -----------------------------------------------------------------------------
def nth_jacobian(u, dx):
    g = np.empty(u.shape + (3,))
    for i in range(3):
        for j in range(3):
            g[..., i, j] = dd_(u[..., i], j, dx)
    sym = 0.5*(g + np.swapaxes(g, -1, -2))
    ant = 0.5*(g - np.swapaxes(g, -1, -2))
    C1 = np.sqrt(np.sum(sym*sym, axis=(-2, -1)))    # strain coupling
    C2 = np.sqrt(np.sum(ant*ant, axis=(-2, -1)))    # rotation coupling
    a, b_, c_ = g[..., 0, 0], g[..., 0, 1], g[..., 0, 2]
    d, e, f_ = g[..., 1, 0], g[..., 1, 1], g[..., 1, 2]
    h, i_, j_ = g[..., 2, 0], g[..., 2, 1], g[..., 2, 2]
    R = a*(e*j_ - f_*i_) - b_*(d*j_ - f_*h) + c_*(d*i_ - e*h)   # Real channel
    Fro = np.sqrt(np.sum(g*g, axis=(-2, -1)))
    U = Fro - np.abs(R)                              # unreal mirror
    vort = np.empty_like(u)
    vort[..., 0] = g[..., 2, 1] - g[..., 1, 2]
    vort[..., 1] = g[..., 0, 2] - g[..., 2, 0]
    vort[..., 2] = g[..., 1, 0] - g[..., 0, 1]
    tau = np.sqrt(C1*C1 + C2*C2)
    return dict(R=R, U=U, C1=C1, C2=C2, vort=vort, tau=tau)

# -----------------------------------------------------------------------------
# 6. FUSED STRUCTURAL PRODUCT — advection with exact zero leakage
# -----------------------------------------------------------------------------
def advect_fused(w, u, dx):
    """Symmetric fusion of the two dual output forms of the structural
    product (Axiom 9.3 under Proposition 7): divergence form and advective
    form. Exact identity on this stencil: sum w.adv = 0 (zero leakage)."""
    out = np.zeros_like(w)
    for ci in range(3):
        for sj in range(3):
            out[..., ci] += 0.5*(dd_(u[..., sj]*w[..., ci], sj, dx)
                                 + u[..., sj]*dd_(w[..., ci], sj, dx))
    return out

# -----------------------------------------------------------------------------
# 7. OMEGA TRANSFER — pure selector assembly (no classical rotation formula)
# -----------------------------------------------------------------------------
def circle_pair_from_gain(g):
    """Collapsed magnitude pair (c, s) of Dr. Martin's spectrum (audited in
    [P2]): c^2 + s^2 = 1 exactly for every g; for routed points g >= 0 the
    transfer angle is bounded below a quarter phase — the bounded transfer
    operator, the structural speed limit."""
    t = g/(1.0 + g)
    return (1.0 - t*t)/(1.0 + t*t), (2.0*t)/(1.0 + t*t)

def omega_transfer(u, p, jac, tau0, gain, wfloor):
    """Omega-selector transfer (Appendix J), assembled from native parts:
    axis = vorticity selector; mirror A (Axiom 9.0) gives the coupling
    tensor; quarter partner P(d) = axis x d; axial arm = fusion R-channel of
    d (+) P(P(d)); transverse arm = deviation (Axiom 2.2); transfer =
    unit-circle fusion with the (c, s) pair from Dr. Martin's spectrum.
    Pointwise invariants (exact): u+p unchanged; |u|^2+|p|^2 unchanged."""
    tau = jac['tau']; w = jac['vort']
    wmag = np.sqrt(np.sum(w*w, axis=-1))
    route = (tau > tau0) & (wmag > wfloor)
    g_loc = gain*(tau/np.maximum(tau0, 1e-300) - 1.0)
    c, s = circle_pair_from_gain(g_loc)
    c = np.where(route, c, 1.0)      # identity transfer where unrouted
    s = np.where(route, s, 0.0)      # (routing gate, not value clipping)
    ah = w/np.maximum(wmag, 1e-300)[..., None]
    m = 0.5*(u + p)
    d = 0.5*(u - p)
    dpar = ah*np.sum(ah*d, axis=-1)[..., None]
    dper = d - dpar
    q = np.cross(ah, dper)
    dnew = dpar + c[..., None]*dper + s[..., None]*q
    un = m + dnew
    pn = m - dnew
    errS = float(np.max(np.abs((un + pn) - (u + p)))) / \
        (float(np.max(np.abs(u + p))) + 1e-300)
    q0 = np.sum(u*u + p*p, axis=-1); q1 = np.sum(un*un + pn*pn, axis=-1)
    errQ = float(np.max(np.abs(q1 - q0))) / (float(np.max(q0)) + 1e-300)
    return un, pn, int(route.sum()), errS, errQ

# -----------------------------------------------------------------------------
# 8. INITIAL SELECTOR FIELDS — table strides only (no transcendental scalars)
# -----------------------------------------------------------------------------
L_DOMAIN = 16.0   # physical period: integer count of base-level cells — no pi

def build_ics(n):
    """Initial selector fields at grid n (dx = L/n): the SAME physical modes
    at every ladder level (harmonic m -> physical wavelength L/m), built only
    from circle-table strides.
      tubes : u_i = A sin(m x_j) cos(m x_k), (i,j,k) cyclic — each component
              independent of its own axis => exactly divergence-free;
              vorticity organizes into counter-rotating tube arrays.
      wound : ABC/Beltrami field — vorticity PARALLEL to velocity (maximal
              helicity): the wound-vortex limit, the canonical hard case;
              exactly divergence-free.
    SHAPE NOTE: fields are stored component-LAST, (n,n,n,3) — grid axes
    first. split_classes consumes EXTRACTED COMPONENTS (n,n,n), never these
    directly (see the contract in section 4)."""
    assert n >= 8 and (n & (n - 1)) == 0, 'ladder levels must be powers of 2'
    dx = L_DOMAIN / n
    m = 2
    S = lambda ax: harm('s', m, ax, n)
    C = lambda ax: harm('c', m, ax, n)
    A = 1.5
    tubes = np.empty((n, n, n, 3))
    tubes[..., 0] = A * S(1) * C(2)
    tubes[..., 1] = A * S(2) * C(0)
    tubes[..., 2] = A * S(0) * C(1)
    a = b = c_ = 2.0
    wound = np.empty((n, n, n, 3))
    wound[..., 0] = a * S(2) + c_ * C(1)
    wound[..., 1] = b * S(0) + a * C(2)
    wound[..., 2] = c_ * S(1) + b * C(0)
    return dict(tubes=tubes, wound=wound), dx

def vort_dd(w, dx):
    v = np.empty_like(w)
    v[..., 0] = dd_(w[..., 2], 1, dx) - dd_(w[..., 1], 2, dx)
    v[..., 1] = dd_(w[..., 0], 2, dx) - dd_(w[..., 2], 0, dx)
    v[..., 2] = dd_(w[..., 1], 0, dx) - dd_(w[..., 0], 1, dx)
    return v

# -----------------------------------------------------------------------------
# 9. RUN DRIVER — atomic history recording (desync impossible by design)
# -----------------------------------------------------------------------------
HIST_KEYS = ['t', 'E', 'Eu', 'Ep', 'Zu', 'Zp', 'max_u', 'max_p', 'max_w',
             'div', 'routes', 'fs_u', 'fs_w']

def run_selector_evolution(name, u0, n, dx, steps, dt, nu, use_omega,
                            thresh_frac=0.5, gain=8.0,
                            record_every=10, report_every=100):
    t0 = time.time()
    vol = dx**3
    print('\n' + '-'*79)
    print(f'RUN {name}')
    print(f'  grid={n}^3  dx={dx}  steps={steps}  dt={dt}  T={steps*dt}  '
          f'nu={nu}  Omega={"ON" if use_omega else "OFF"}  '
          f'tau0={thresh_frac}*peak  gain={gain}')
    print('-'*79)

    u = np.array(u0, dtype=float, copy=True)
    p = np.zeros_like(u)
    phi = np.zeros((2, n, n, n))
    stats = []

    V = np.stack([u, p])                     # initial whole-term projection
    V, phi, strip_raw = project_bundle(V, dx, phi, stats)
    u, p = V[0], V[1]

    jac0 = nth_jacobian(u, dx)
    tau0 = thresh_frac*float(np.max(jac0['tau']))
    wfloor = 1e-12

    hist = {k: [] for k in HIST_KEYS}
    routes_now = 0
    def record(step):
        wu = vort_dd(u, dx); wp = vort_dd(p, dx)
        obs = dict(t=step*dt,
                   E=0.5*float(np.sum(u*u + p*p))*vol,
                   Eu=0.5*float(np.sum(u*u))*vol,
                   Ep=0.5*float(np.sum(p*p))*vol,
                   Zu=0.5*float(np.sum(wu*wu))*vol,
                   Zp=0.5*float(np.sum(wp*wp))*vol,
                   max_u=float(np.max(np.sqrt(np.sum(u*u, axis=-1)))),
                   max_p=float(np.max(np.sqrt(np.sum(p*p, axis=-1)))),
                   max_w=float(np.max(np.sqrt(np.sum(wu*wu, axis=-1)))),
                   div=float(np.max(np.abs(div_B(u, dx)))),
                   routes=routes_now,
                   fs_u=finest_scale_share(u),
                   fs_w=finest_scale_share(wu))
        for k in HIST_KEYS:                  # atomic append: no desync possible
            hist[k].append(obs[k])
    record(0)

    E_prev = E0 = 0.5*float(np.sum(u*u + p*p))*vol
    visc_cum = 0.0
    strip_cum = 0.5*vol*strip_raw            # initial projection strip counted
    R_cum = 0.0
    omega_err = 0.0; leak_max = 0.0; ledger_max = 0.0
    leak_scale = float(np.sum(u*u)) + 1e-300
    finite = True; fail_step = -1

    for step in range(steps):
        au = advect_fused(u, u, dx)          # fused structural product
        ap = advect_fused(p, u, dx)
        Lu = visc_op(u, dx); Lp = visc_op(p, dx)

        lk = max(abs(float(np.sum(u*au))), abs(float(np.sum(p*ap)))) / leak_scale
        leak_max = max(leak_max, lk)

        fj2 = 0.0                            # exact dissipation input
        for wch in (u, p):
            for j in range(3):
                fj2 += float(np.sum(F_(wch[..., j], j, dx)**2))
        visc_step = nu*dt*fj2*vol

        Xu = -au + nu*Lu; Xp = -ap + nu*Lp   # explicit selector step
        us = u + dt*Xu; ps = p + dt*Xp
        R_step = 0.5*dt*dt*float(np.sum(Xu*Xu + Xp*Xp))*vol   # >= 0, O(dt^2)

        if use_omega:                        # Omega transfer (native assembly)
            jac = nth_jacobian(u, dx)
            us, ps, routes_now, eS, eQ = omega_transfer(
                us, ps, jac, tau0, gain, wfloor)
            omega_err = max(omega_err, eS, eQ)
        else:
            routes_now = 0

        V = np.stack([us, ps])               # whole-term projection
        V, phi, strip_raw = project_bundle(V, dx, phi, stats)
        u, p = V[0], V[1]
        strip_E = 0.5*vol*strip_raw

        if not (np.all(np.isfinite(u)) and np.all(np.isfinite(p))):
            finite, fail_step = False, step
            print(f'  step {step+1}: NON-FINITE selector value -> HALTED '
                  f'(nothing repaired or replaced)')
            break

        # exact energy ledger:  E_now = E_prev - visc - strip + R
        E_now = 0.5*float(np.sum(u*u + p*p))*vol
        resid = abs((E_now - E_prev) + visc_step + strip_E - R_step)
        ledger_max = max(ledger_max, resid/max(E0, 1e-300))
        E_prev = E_now
        visc_cum += visc_step; strip_cum += strip_E; R_cum += R_step

        if (step + 1) % record_every == 0 or step == steps - 1:
            record(step + 1)
        if (step + 1) % report_every == 0 or step == steps - 1:
            print(f'  step {step+1:5d}  t={hist["t"][-1]:7.3f}  '
                  f'E={hist["E"][-1]:10.4f}  Zu={hist["Zu"][-1]:10.4f}  '
                  f'Zp={hist["Zp"][-1]:9.4f}  max|u|={hist["max_u"][-1]:7.3f}  '
                  f'max|w|={hist["max_w"][-1]:8.3f}  '
                  f'fs_w={hist["fs_w"][-1]:.3f}  routes={routes_now}')

    wall = time.time() - t0

    labels = {}
    if use_omega and finite:                 # final phase-label distribution
        jacF = nth_jacobian(u, dx)
        wmag = np.sqrt(np.sum(jacF['vort']*jacF['vort'], axis=-1))
        route = (jacF['tau'] > tau0) & (wmag > wfloor)
        stack = np.stack([np.abs(jacF['R']), jacF['U'], jacF['C1'], jacF['C2']])
        lab = np.argmax(stack, axis=0)
        for i, nm in enumerate(('Real', 'Unreal', 'C1', 'C2')):
            labels[nm] = int(np.sum((lab == i) & route))

    print(f'  finished: finite={finite}  omega_err={omega_err:.2e}  '
          f'leak={leak_max:.2e}  ledger={ledger_max:.2e}  wall={wall:.1f}s')
    return dict(name=name, n=n, dx=dx, dt=dt, nu=nu, use_omega=use_omega,
                hist={k: np.asarray(hist[k]) for k in HIST_KEYS},
                finite=finite, fail_step=fail_step,
                omega_err=omega_err, leak=leak_max, ledger=ledger_max,
                E0=E0, visc=visc_cum, strip=strip_cum, R=R_cum,
                E_final=E_prev, stats=stats, tau0=tau0, labels=labels,
                u=u.copy(), p=p.copy(), wall=wall)

def run_batch(ics, names, n, dx, steps, dt, nu, tag,
              thresh_frac=0.5, gain=8.0, record_every=10):
    """Fair A/B per initial condition: Omega ON and Omega OFF with identical
    discretization and parameters."""
    out = {}
    report_every = max(record_every, (steps//4//record_every)*record_every)
    for nm in names:
        for om in (True, False):
            cfg = 'omega' if om else 'classical'
            r = run_selector_evolution(
                f'{tag} | {nm} | {cfg}', ics[nm], n, dx, steps, dt, nu, om,
                thresh_frac, gain, record_every, report_every)
            out[(tag, nm, cfg)] = r
    return out

