_GATE_W = 0.5    # transition width in units of tau0

def omega_transfer_mild(u, p, jac, tau0, gain, wfloor):
    """Omega transfer with a SMOOTH gate: routing weight ramps linearly over
    a tension band of width _GATE_W*tau0. Same native assembly and the same
    exact pointwise invariants as v6's omega_transfer."""
    tau = jac['tau']; w = jac['vort']
    wmag = np.sqrt(np.sum(w*w, axis=-1))
    if _GATE_W > 0.0:
        gate = np.clip((tau - tau0)/(_GATE_W*tau0), 0.0, 1.0)
    else:
        gate = (tau > tau0).astype(float)
    gate = gate*(wmag > wfloor)
    g_loc = np.maximum(gain*gate*(tau/np.maximum(tau0, 1e-300) - 1.0), 0.0)
    c, s = circle_pair_from_gain(g_loc)
    ah = w/np.maximum(wmag, 1e-300)[..., None]
    m = 0.5*(u + p); d = 0.5*(u - p)
    dpar = ah*np.sum(ah*d, axis=-1)[..., None]
    dper = d - dpar
    q = np.cross(ah, dper)
    dnew = dpar + c[..., None]*dper + s[..., None]*q
    un = m + dnew; pn = m - dnew
    errS = float(np.max(np.abs((un + pn) - (u + p)))) / \
        (float(np.max(np.abs(u + p))) + 1e-300)
    q0 = np.sum(u*u + p*p, axis=-1); q1 = np.sum(un*un + pn*pn, axis=-1)
    errQ = float(np.max(np.abs(q1 - q0))) / (float(np.max(q0)) + 1e-300)
    return un, pn, int(np.sum(gate > 0.5)), errS, errQ

