TAU = 6.283185307179586
PHI = 0.5*(1.0 + np.sqrt(5.0))
L_dom = 2.0*np.pi
L_half = L_dom/2.0
DT = 0.004
B_WINDOW = 60
PROJ_CYCLES = 20
NU_TEST = 0.0001
