print('\n' + '='*79)
print('V26.2 VALIDATION GATES')
print('='*79)

axes_g, dx_g = np_mesh(32)
u_g = ic_tubes(axes_g)

# [G1] Jacobian equivalence — THE V26.1 PARSE-KILLER, corrected:
#     the malformed expression left the outer float( unclosed and put the
#     comma inside a two-argument float(...) -> SyntaxError; nothing ran.
_, C1_j_full, _, _, _ = jnth_jacobian(jnp.asarray(u_g[None]), dx_g)
C1_j = np.asarray(C1_j_full[0])
n_g = u_g.shape[0]
G_np = np.empty((n_g, n_g, n_g, 3, 3))
for i in range(3):
    for j in range(3):
        G_np[..., i, j] = (np.roll(u_g[..., i], -1, axis=j)
                           - np.roll(u_g[..., i], 1, axis=j))*(0.5/dx_g)
S_np = 0.5*(G_np + np.swapaxes(G_np, -1, -2))
C1_np = np.sqrt(np.sum(S_np*S_np, axis=(-2, -1)))
err1 = (float(np.max(np.abs(C1_np - C1_j)))
        / max(float(np.max(np.abs(C1_np))), 1e-30))
print(f'  [G1] Jacobian equivalence: rel err = {err1:.2e}')
assert err1 < 1e-12, 'Jacobian mismatch'

# [G2] non-expansiveness of the class-decomposed projection
rng_g = np.random.default_rng(7)
Vg = rng_g.standard_normal((1, 32, 32, 32, 3))
for _ in range(6):
    for a in (1, 2, 3):
        Vg = 0.5*Vg + 0.25*(np.roll(Vg, -1, axis=a)
                            + np.roll(Vg, 1, axis=a))
Vg_j = _project_one_channel(jnp.asarray(Vg), dx_g)
E0g = float(jnp.sum(jnp.asarray(Vg)**2))
E1g = float(jnp.sum(Vg_j**2))
ok2 = np.isfinite(E1g) and E1g <= E0g*(1.0 + 1e-5)
print(f'  [G2] non-expansiveness: E ratio = '
      f'{E1g/max(E0g,1e-30):.8f}  ({"PASS" if ok2 else "FAIL"})')
assert ok2, 'projection expansive'

# [G3] NEW (v26.2): divergence reduction — the quantity the whole-term
#      projection exists to control. REPORT, not assert: the reduction
#      factor on a real IC is itself a measured quantity.
u_w0 = ic_wound(axes_g)
div_pre = float(np.max(np.abs(np_div_bundle(u_w0[None], dx_g))))
Vw_j = _project_one_channel(jnp.asarray(u_w0[None]), dx_g)
div_post = float(np.max(np.abs(np.asarray(jdiv_bundle(Vw_j, dx_g)))))
print(f'  [G3] whole-term projection on ic_wound (32³): max|div| '
      f'{div_pre:.3e} -> {div_post:.3e}  '
      f'(reduction {div_pre/max(div_post, 1e-300):.1f}x)')

# [G4] NEW (v26.2): the [B0] mechanics, machine-verified — the foundation
#      V26c's classical-floor attribution rests on:
#      (a) the class projection is EXACTLY linear (=> project(u)+project(p)
#          = project(u+p): the bundle m = u+p feels the shared closure);
#      (b) the omega transfer preserves u+p and |u|²+|p|² pointwise.
axes_4, dx_4 = np_mesh(16)
rng4 = np.random.default_rng(3)
a4 = rng4.standard_normal((1, 16, 16, 16, 3))
b4 = rng4.standard_normal((1, 16, 16, 16, 3))
a4j, b4j = jnp.asarray(a4), jnp.asarray(b4)
pa = _project_one_channel(a4j, dx_4)
pb = _project_one_channel(b4j, dx_4)
pab = _project_one_channel(a4j + b4j, dx_4)
lin_err = (float(np.max(np.abs(np.asarray(pa + pb - pab))))
           / max(float(np.max(np.abs(np.asarray(pab)))), 1e-30))
G4_, C14, C24, R4, T4 = jnth_jacobian(a4j, dx_4)
thr4 = jnp.asarray(np.zeros(1))
un4, pn4 = jomega_transfer(a4j, b4j, G4_, C14, C24, R4, T4, dx_4,
                            thr4, 10.0)
m_err = (float(np.max(np.abs(np.asarray(un4 + pn4 - a4j - b4j))))
         / max(float(np.max(np.abs(np.asarray(a4j + b4j)))), 1e-30))
q0 = jnp.sum(a4j*a4j + b4j*b4j, axis=-1)
q1 = jnp.sum(un4*un4 + pn4*pn4, axis=-1)
q_err = (float(np.max(np.abs(np.asarray(q1 - q0))))
         / max(float(np.max(np.asarray(q0))), 1e-30))
print(f'  [G4] [B0] mechanics: projection linearity = {lin_err:.2e}  '
      f'omega m-preservation = {m_err:.2e}  omega energy = {q_err:.2e}')
assert lin_err < 1e-10, 'projection not linear'
assert m_err < 1e-12, 'omega does not preserve u+p'
assert q_err < 1e-12, 'omega does not preserve |u|^2+|p|^2'

print('  ALL GATES PASS.\n')

