# ---- V26a: long-horizon model fit ------------------------------------------
print('\n[V26a] LONG-HORIZON MODEL FIT (64³, t=0 to 20):')

def model_saturating(t, B, A, k):
    return B - A*np.exp(-k*t)

def model_linear(t, rate, c):
    return rate*t + c

def model_power(t, a, p, c):
    return a*np.power(t, p) + c

def fit_three_models(t_data, s_data, t_min=1.0):
    """Returns (dict of {name: (popt, aic)}, best_name) or None."""
    mask = t_data >= t_min
    t_fit = t_data[mask]
    s_fit = s_data[mask]
    n = len(t_fit)
    if n < 20:
        return None
    fits_dict = {}
    for name, model, p0, nparams in (
        ('S', model_saturating,
         [s_fit[-1] + 0.5*max(s_fit[-1]-s_fit[0], 1e-9),
          max(s_fit[-1]-s_fit[0], 1e-9), 0.5], 3),
        ('L', model_linear,
         [(s_fit[-1]-s_fit[0])/max(t_fit[-1]-t_fit[0], 1e-9),
          s_fit[0]], 2),
        ('P', model_power, None, 3)):
        try:
            if p0 is None:
                lt = np.log(np.maximum(t_fit, 1e-9))
                ls = np.log(np.maximum(s_fit, 1e-9))
                p_est = max(float(np.polyfit(lt, ls, 1)[0]), 1.05)
                a_est = s_fit[-1]/max(t_fit[-1]**p_est, 1e-9)
                p0 = [a_est, p_est, 0.0]
            popt, _ = optimize.curve_fit(model, t_fit, s_fit,
                                         p0=p0, maxfev=10000)
            if name == 'P' and popt[1] <= 1.0:
                popt = (popt[0], 1.001, popt[2])
            resid = s_fit - model(t_fit, *popt)
            ss = float(np.sum(resid**2))
            aic = n*np.log(max(ss/n, 1e-30)) + 2*nparams
            fits_dict[name] = (popt, aic)
        except Exception:
            fits_dict[name] = (None, np.inf)
    valid = {k_: v for k_, v in fits_dict.items()
             if v[0] is not None and np.isfinite(v[1])}
    if not valid:
        return None
    best = min(valid, key=lambda k_: valid[k_][1])
    return fits_dict, best

for ic in ('tubes', 'wound'):
    key_64 = (ic, 64)
    if key_64 not in results:
        print(f'\n  [{ic}]: 64³ data not found — skipping')
        continue
    h_64 = results[key_64]
    t_ax_64 = np.array(h_64['step'])*DT
    print(f'\n  [{ic}]')
    for inst in ('Sigma_u', 'Sigma_m'):
        s_ax = np.array(h_64[inst])
        fit_res = fit_three_models(t_ax_64, s_ax, t_min=1.0)
        if fit_res is None:
            print(f'    {inst}: fit failed')
            continue
        fits_d, best = fit_res
        deltas = {}
        for k_ in ('S', 'L', 'P'):
            if k_ in fits_d and fits_d[k_][0] is not None:
                deltas[k_] = fits_d[k_][1] - fits_d[best][1]
        ds = deltas.get('S', float('inf'))
        dl = deltas.get('L', float('inf'))
        dp = deltas.get('P', float('inf'))
        print(f'    {inst}: best = {best}  '
              f'(dAIC: S={ds:.0f}, L={dl:.0f}, P={dp:.0f})')
        if best == 'S' and fits_d['S'][0] is not None:
            B_val = fits_d['S'][0][0]
            print(f'      bound B = {B_val:.2f}')

