def dual_form_works(w, v, dx):
    wd = 0.0; wa = 0.0
    for i in range(3):
        wi = w[..., i]
        for j in range(3):
            vj = v[..., j]
            wd += float(np.sum(wi*np_dd(vj*wi, j, dx)))
            wa += float(np.sum(wi*vj*np_dd(wi, j, dx)))
    return 0.5*wd, 0.5*wa

