# =============================================================================
# JAX CORE (same operators as v26; projection parameterized + warm-start)
# =============================================================================
def jdd(f, axis, dx):
    return (jnp.roll(f, -1, axis=axis) - jnp.roll(f, 1, axis=axis)) \
        * (0.5/dx)

def jnth_jacobian(u, dx):
    gu = []
    for i in range(3):
        for j in range(3):
            gu.append(jdd(u[..., i], j + 1, dx))
    G = jnp.stack(gu, axis=-1).reshape(u.shape[0], u.shape[1],
                                       u.shape[1], u.shape[1], 3, 3)
    S = 0.5*(G + jnp.swapaxes(G, -1, -2))
    C1 = jnp.sqrt(jnp.sum(S*S, axis=(-2, -1)))
    A_ = 0.5*(G - jnp.swapaxes(G, -1, -2))
    C2 = jnp.sqrt(jnp.sum(A_*A_, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    return G, C1, C2, R, C1 + C2 + jnp.abs(R)

def jlap(u, dx):
    inv = 1.0/(dx*dx)
    out = -6.0*u
    for a in (1, 2, 3):
        out = out + jnp.roll(u, -1, axis=a) + jnp.roll(u, 1, axis=a)
    return out*inv

def jadvect(f, v, dx):
    parts = []
    for i in range(3):
        fi = f[..., i]
        acc = jnp.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc = acc + 0.5*(jdd(vj*fi, j + 1, dx) + vj*jdd(fi, j + 1, dx))
        parts.append(acc)
    return jnp.stack(parts, axis=-1)

def jaxis_dominant(C1, C2, G, dx):
    rot_dom = C2 > C1
    w0 = G[..., 2, 1] - G[..., 1, 2]
    w1 = G[..., 0, 2] - G[..., 2, 0]
    w2 = G[..., 1, 0] - G[..., 0, 1]
    wn = jnp.sqrt(w0*w0 + w1*w1 + w2*w2)
    gs0 = jdd(C1, 1, dx); gs1 = jdd(C1, 2, dx); gs2 = jdd(C1, 3, dx)
    gn = jnp.sqrt(gs0*gs0 + gs1*gs1 + gs2*gs2)
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    ax_v = jnp.stack([w0, w1, w2], axis=-1)/jnp.maximum(wn, 1e-30)[..., None]
    ax_g = jnp.stack([gs0, gs1, gs2], axis=-1)/jnp.maximum(gn, 1e-30)[..., None]
    return jnp.where(use_v[..., None], ax_v,
                     jnp.where(use_g[..., None], ax_g,
                               jnp.zeros_like(ax_v)))

def jomega_transfer(u, p, G, C1, C2, R, tension, dx, threshold, gain):
    excess = jnp.maximum(tension - threshold[:, None, None, None], 0.0)
    g = gain*excess*dx
    t_ = g/(1.0 + g)
    c = (1.0 - t_*t_)/(1.0 + t_*t_)
    s = (2.0*t_)/(1.0 + t_*t_)
    m = u + p
    d = 0.5*(u - p)
    axis = jaxis_dominant(C1, C2, G, dx)
    Pd = jnp.cross(axis, d)
    d_ax = d + jnp.cross(axis, Pd)
    d_tr = d - d_ax
    d_new = d_ax + c[..., None]*d_tr + s[..., None]*jnp.cross(axis, d_tr)
    return 0.5*m + d_new, 0.5*m - d_new

def jrestrict(F):
    classes = []
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                classes.append(F[:, a::2, b::2, d_::2])
    return jnp.stack(classes, axis=1)

def jmerge(G8, n):
    out = jnp.zeros((G8.shape[0], n, n, n), dtype=G8.dtype)
    idx = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out = out.at[:, a::2, b::2, d_::2].set(G8[:, idx])
                idx += 1
    return out

def jrestrict_fw(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))

def j_interp1(F, axis):
    n = F.shape[axis]
    odd = 0.5*(F + jnp.roll(F, -1, axis=axis))
    out = jnp.stack([F, odd], axis=axis + 1)
    shp = list(F.shape); shp[axis] = 2*n
    return out.reshape(shp)

def jprolong(C):
    F = j_interp1(C, C.ndim - 3)
    F = j_interp1(F, F.ndim - 2)
    F = j_interp1(F, F.ndim - 1)
    return F

def jdiv_bundle(V, dx):
    return jdd(V[..., 0], 1, dx) + jdd(V[..., 1], 2, dx) \
        + jdd(V[..., 2], 3, dx)

def jgrad_bundle(phi, dx):
    return jnp.stack([jdd(phi, 1, dx), jdd(phi, 2, dx),
                      jdd(phi, 3, dx)], axis=-1)

def jlap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    nd = F.ndim
    for a in (nd - 3, nd - 2, nd - 1):
        s = s + jnp.roll(F, -1, axis=a) + jnp.roll(F, 1, axis=a)
    return s*inv

def jsmooth_gs(phi, f, dx, iters):
    c = dx*dx/6.0
    m = phi.shape[-1]
    idx = jnp.indices((m, m, m))
    parity = (idx[0] + idx[1] + idx[2]) % 2
    red = (parity == 0); black = (parity == 1)
    def body(i, phi_):
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - c*jnp.where(red, r, 0.0)
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - c*jnp.where(black, r, 0.0)
        return phi_
    return lax.fori_loop(0, iters, body, phi)

def jv_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - jnp.mean(f, axis=(-3, -2, -1), keepdims=True)
        return jsmooth_gs(phi, f, dx, 40)
    phi = jsmooth_gs(phi, f, dx, 2)
    r = f - jlap_apply(phi, dx)
    rc = jrestrict_fw(r)
    ec = jv_cycle(jnp.zeros_like(rc), rc, 2.0*dx)
    phi = phi + jprolong(ec)
    return jsmooth_gs(phi, f, dx, 2)

def _project_warm(Vch, psic0, dx, cycles):
    """Class-decomposed whole-term projection with WARM START.
    Vch: (B, n, n, n, 3) any batch B (2C for the fused u,p solve).
    Returns (V + grad phi, psi, relative residual). Cold start =
    psic0 = zeros (v26-faithful)."""
    f = -jdiv_bundle(Vch, dx)
    fc = jrestrict(f)
    H = 2.0*dx
    fc = fc - jnp.mean(fc, axis=(-3, -2, -1), keepdims=True)
    psic = psic0 - jnp.mean(psic0, axis=(-3, -2, -1), keepdims=True)
    def cycle_body(i, psi):
        return jv_cycle(psi, fc, H)
    psic = lax.fori_loop(0, cycles, cycle_body, psic)
    psic = psic - jnp.mean(psic, axis=(-3, -2, -1), keepdims=True)
    resid = jnp.max(jnp.abs(fc - jlap_apply(psic, H))) \
        / (jnp.max(jnp.abs(fc)) + 1e-30)
    phi_full = jmerge(psic, Vch.shape[1])
    return Vch + jgrad_bundle(phi_full, dx), psic, resid

def _Es_md(a, b, vol):
    s = a + b; d = a - b
    return (0.25*vol*jnp.sum(s*s, axis=(1, 2, 3, 4)),
            0.25*vol*jnp.sum(d*d, axis=(1, 2, 3, 4)))

# =============================================================================
# FAST STEP + SCAN  (warm-started, batched (2C) projection, m/d ledger)
# =============================================================================
def jstep_fast(u, p, psic, nu, thr, dx, gain, cycles):
    C = u.shape[0]; vol = dx**3
    G_u, C1_u, C2_u, R_u, tension_u = jnth_jacobian(u, dx)
    Mk_u = jnp.max(tension_u.reshape(C, -1), axis=1)
    m = u + p
    _, _, _, _, tension_m = jnth_jacobian(m, dx)
    Mk_m = jnp.max(tension_m.reshape(C, -1), axis=1)
    Em_pre, Ed_pre = _Es_md(u, p, vol)
    au1 = jadvect(u, m, dx); ap1 = jadvect(p, m, dx)
    Lu = jlap(u, dx); Lp = jlap(p, dx)
    nu_ = nu[:, None, None, None, None]
    u_star = u + DT*(-au1 + nu_*Lu)
    p_star = p + DT*(-ap1 + nu_*Lp)
    m_star = u_star + p_star
    au2 = jadvect(u_star, m_star, dx)
    ap2 = jadvect(p_star, m_star, dx)
    u_s = u + 0.5*DT*(-(au1 + au2) + nu_*(Lu + jlap(u_star, dx)))
    p_s = p + 0.5*DT*(-(ap1 + ap2) + nu_*(Lp + jlap(p_star, dx)))
    Em_heun, Ed_heun = _Es_md(u_s, p_s, vol)
    u_s, p_s = jomega_transfer(u_s, p_s, G_u, C1_u, C2_u, R_u,
                                tension_u, dx, thr, gain)
    u_pre, p_pre = u_s, p_s
    Us = jnp.concatenate([u_s, p_s], axis=0)     # ONE batched cascade
    Unew, psic_n, resid = _project_warm(Us, psic, dx, cycles)
    u_new = Unew[:C]; p_new = Unew[C:]
    gu = u_new - u_pre; gp = p_new - p_pre
    toll_m = 0.25*vol*jnp.sum(2.0*(u_pre + p_pre)*(gu + gp)
                              + (gu + gp)*(gu + gp), axis=(1, 2, 3, 4))
    toll_d = 0.25*vol*jnp.sum(2.0*(u_pre - p_pre)*(gu - gp)
                              + (gu - gp)*(gu - gp), axis=(1, 2, 3, 4))
    Em, Ed = _Es_md(u_new, p_new, vol)
    return (u_new, p_new, psic_n, Mk_u, Mk_m, toll_m, toll_d,
            Em_heun - Em_pre, Ed_heun - Ed_pre, resid, Em, Ed)

def make_scan_body(nu, thr, dx, gain, cycles, warm):
    def body(carry, _):
        u, p, psic, Su, Sm, tm, td, hm, hd = carry
        psi_in = psic if warm else jnp.zeros_like(psic)
        (u, p, psic, Mk_u, Mk_m, t_m, t_d, h_m, h_d,
         resid, Em, Ed) = jstep_fast(u, p, psi_in, nu, thr, dx,
                                     gain, cycles)
        return (u, p, psic, Su + Mk_u*DT, Sm + Mk_m*DT,
                tm + t_m, td + t_d, hm + h_m, hd + h_d), \
               (Mk_u, Mk_m, resid, Em, Ed)
    return body

def setup_initial(ics_dict, ic_names, n, dx, thresh_frac):
    C = len(ic_names)
    U0 = np.stack([ics_dict[ic] for ic in ic_names])
    Us = jnp.asarray(np.concatenate([U0, np.zeros_like(U0)], axis=0))
    psic0 = jnp.zeros((2*C, 8, n//2, n//2, n//2))
    Us, psic0, _ = _project_warm(Us, psic0, dx, PROJ_INIT_CYCLES)
    U0j, P0j = Us[:C], Us[C:]
    _, _, _, _, t0_ = jnth_jacobian(U0j, dx)
    M0 = jnp.max(t0_.reshape(C, -1), axis=1)
    Em0, Ed0 = _Es_md(U0j, P0j, dx**3)
    return (U0j, P0j, psic0, jnp.asarray(np.full(C, NU_TEST)),
            thresh_frac*M0, np.asarray(Em0), np.asarray(Ed0),
            np.asarray(M0))

def run_variant(tag, ic_names, ics_dict, n, dx, steps, cycles, warm,
                thresh_frac=0.5, gain=10.0):
    U0j, P0j, psic0, nu, thr, Em0, Ed0, M0 = setup_initial(
        ics_dict, ic_names, n, dx, thresh_frac)
    body = make_scan_body(nu, thr, dx, gain, cycles, warm)
    C = len(ic_names); zed = jnp.zeros(C)
    def carry0():
        return (U0j, P0j, psic0, zed, zed, zed, zed, zed, zed)
    lax.scan(body, carry0(), xs=None, length=3)      # compile warmup
    jax.block_until_ready(jnp.asarray(0.0))
    t0 = time.perf_counter()
    carryF, out = lax.scan(body, carry0(), xs=None, length=steps)
    jax.block_until_ready(out[0])
    wall = time.perf_counter() - t0
    Mku, Mkm, resid, Em, Ed = [np.asarray(x) for x in out]
    uF = np.asarray(carryF[0]); pF = np.asarray(carryF[1])
    divfin = np.asarray(jdiv_bundle(jnp.asarray(uF), dx))
    maxdiv = divfin.reshape(C, -1).max(axis=1)
    Su = np.asarray(carryF[3]); Sm = np.asarray(carryF[4])
    tm = np.asarray(carryF[5]); td = np.asarray(carryF[6])
    hm = np.asarray(carryF[7]); hd = np.asarray(carryF[8])
    ledger = np.abs((Em[-1] + Ed[-1]) - (Em0 + Ed0)
                    - (tm + td + hm + hd))/np.maximum(Em0 + Ed0, 1e-30)
    print(f'  [{tag:9s}] {wall:6.1f}s total  {wall/steps*1000:7.1f} '
          f'ms/step  proj-resid worst {resid.max():.1e}  '
          f'median {np.median(resid):.1e}  ledger {ledger.max():.1e}')
    for ci, ic in enumerate(ic_names):
        print(f'      {ic:6s} final max|div_u| = {maxdiv[ci]:.1e}  '
              f'E_m retained {Em[-1, ci]/Em0[ci]*100:5.1f}%')
    return dict(tag=tag, wall=wall, ms=wall/steps*1000, resid=resid,
                Mku=Mku, Mkm=Mkm, Su=Su, Sm=Sm, Em=Em, Ed=Ed,
                Em0=Em0, Ed0=Ed0, tm=tm, td=td, hm=hm, hd=hd,
                uF=uF, pF=pF, M0=M0, ic_names=list(ic_names))

