def load_run(ic, steps):
    hits = sorted(glob.glob(os.path.join(SAVE, f'v263_{ic}_*_s{steps}_*.npz')))
    if not hits:
        return None
    z = np.load(hits[0])
    return {k: np.asarray(z[k]) for k in z.files}

