    hm = float(h['heun_m_cum'][-1]); hd = float(h['heun_d_cum'][-1])
    audm = abs((EmF - Em0) - (hm + tm))/Em0
    audd = abs((EdF - Em0) - (hd + td))/Em0
    tot = abs(tm) + abs(td)
    print(f'\n  [{ic}]')
    print(f'    E_m: {Em0:8.1f} -> {EmF:8.1f} ({EmF/Em0*100:5.1f}%)   '
          f'E_d: {Em0:8.1f} -> {EdF:8.1f} ({EdF/Em0*100:5.1f}%)')
    print(f'    ledger audit: m = {audm:.2e}   d = {audd:.2e}   '
          f'(expect <= ~1e-12; omega adds ~1e-13 FP drift)')
