import os
import time
import numpy as np
import matplotlib.pyplot as plt

import jax
jax.config.update("jax_enable_x64", True)
import jax.numpy as jnp
from jax import lax

print('JAX version:', jax.__version__)
print('backend devices:', jax.devices())
IS_GPU = 'gpu' in str(jax.devices()[0]).lower()
print('backend: CUDA GPU' if IS_GPU else 'backend: CPU')

np.set_printoptions(precision=6, suppress=True)
L_dom = 2.0*np.pi; L_half = L_dom/2.0
NU_TEST = 0.0001
WARM_CYCLES = 8; COLD_CYCLES = 20; INIT_CYCLES = 20
RUN_64 = True
A_SWIRL = 6.0; PHI = 0.5*(1.0 + np.sqrt(5.0)); W_GOLD = 12.0/PHI
SIGMA = 1.0; A_WIND = 0.35
ICS = ['tubes', 'wound']

# ---- ICs ----
def np_mesh(n):
    x = np.linspace(0.0, L_dom, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), L_dom/n

def ic_tubes(axes, strength=8.0, sigma=0.8, sep=1.6, tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt); st = np.sin(tilt)
    def tube(cx, sign):
        dx_ = (x - cx + L_half) % L_dom - L_half
        dy_ = (y - np.pi + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        r2 = dx_t*dx_t + dy_*dy_
        f = np.exp(-r2/(2.0*sigma*sigma))
        return np.stack([-sign*strength*dy_*f,
                         sign*strength*dx_t*f, np.zeros_like(x)], axis=-1)
    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)

def ic_wound(axes):
    x, y, z = axes
    xc = np.pi + A_WIND*np.sin(z)
    yc = np.pi + A_WIND*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA*SIGMA))
    return np.stack([-A_SWIRL*ry*f, A_SWIRL*rx*f, W_GOLD*f], axis=-1)

def build_ics_np(n):
    axes, dx = np_mesh(n)
    return {'tubes': ic_tubes(axes), 'wound': ic_wound(axes)}, dx

# ---- numpy reference cascade (initial projection; proven) ----
def np_dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis))*(0.5/dx)
def np_restrict(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))
def np_interp1(F, axis):
    n = F.shape[axis]
    shp = list(F.shape); shp[axis] = 2*n
    G = np.empty(shp, dtype=F.dtype)
    se = [slice(None)]*F.ndim; se[axis] = slice(0, 2*n, 2)
    G[tuple(se)] = F
    so = [slice(None)]*F.ndim; so[axis] = slice(1, 2*n, 2)
    G[tuple(so)] = 0.5*(F + np.roll(F, -1, axis=axis))
    return G
def np_prolong(C):
    F = np_interp1(C, C.ndim - 3)
    F = np_interp1(F, F.ndim - 2)
    F = np_interp1(F, F.ndim - 1)
    return F
def np_lap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    for a in (F.ndim - 3, F.ndim - 2, F.ndim - 1):
        s = s + np.roll(F, -1, axis=a) + np.roll(F, 1, axis=a)
    return s*inv
_RBGS = {}
def np_rb_mask(m):
    if m not in _RBGS:
        idx = np.indices((m, m, m))
        parity = (idx[0] + idx[1] + idx[2]) % 2
        _RBGS[m] = (parity == 0, parity == 1)
    return _RBGS[m]
def np_smooth_gs(phi, f, dx, iters):
    c = dx*dx/6.0
    red, black = np_rb_mask(phi.shape[-1])
    for _ in range(iters):
        r = f - np_lap_apply(phi, dx)
        phi = phi - c*np.where(red, r, 0.0)
        r = f - np_lap_apply(phi, dx)
        phi = phi - c*np.where(black, r, 0.0)
    return phi
def np_v_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - f.mean(axis=(-3, -2, -1), keepdims=True)
        return np_smooth_gs(phi, f, dx, 40)
    phi = np_smooth_gs(phi, f, dx, 2)
    r = f - np_lap_apply(phi, dx)
    rc = np_restrict(r)
    ec = np_v_cycle(np.zeros_like(rc), rc, 2.0*dx)
    phi = phi + np_prolong(ec)
    return np_smooth_gs(phi, f, dx, 2)
def np_split_classes(f):
    N = f.shape[-1]; M = N//2
    out = np.empty(f.shape[:-3] + (8, M, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out[..., c, :, :, :] = f[..., a::2, b::2, d_::2]
                c += 1
    return out
def np_merge_classes(g, N):
    f = np.empty(g.shape[:-4] + (N, N, N), dtype=g.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                f[..., a::2, b::2, d_::2] = g[..., c, :, :, :]
                c += 1
    return f
def np_div_bundle(V, dx):
    out = np.zeros(V.shape[:-1])
    for j in range(3):
        out += np_dd(V[..., j], V.ndim - 4 + j, dx)
    return out
def np_grad_bundle(phi, dx):
    return np.stack([np_dd(phi, phi.ndim - 3 + j, dx)
                     for j in range(3)], axis=-1)
def np_project_channels(V, dx, max_cycles=20):
    f = -np_div_bundle(V, dx)
    fc = np_split_classes(f)
    H = 2.0*dx
    fc = fc - fc.mean(axis=(-3, -2, -1), keepdims=True)
    psic = np.zeros_like(fc)
    psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
    for _ in range(max_cycles):
        psic = np_v_cycle(psic, fc, H)
        psic = psic - psic.mean(axis=(-3, -2, -1), keepdims=True)
    phi_out = np_merge_classes(psic, V.shape[-3])
    return V + np_grad_bundle(phi_out, dx)

# ---- JAX core (proven operators; identical to v26 lineage) ----
def jdd(f, axis, dx):
    return (jnp.roll(f, -1, axis=axis) - jnp.roll(f, 1, axis=axis))*(0.5/dx)
def jnth_jacobian(u, dx):
    gu = []
    for i in range(3):
        for j in range(3):
            gu.append(jdd(u[..., i], j + 1, dx))
    G = jnp.stack(gu, axis=-1).reshape(u.shape[0], u.shape[1],
                                       u.shape[1], u.shape[1], 3, 3)
    S = 0.5*(G + jnp.swapaxes(G, -1, -2))
    C1 = jnp.sqrt(jnp.sum(S*S, axis=(-2, -1)))
    A_ = 0.5*(G - jnp.swapaxes(G, -1, -2))
    C2 = jnp.sqrt(jnp.sum(A_*A_, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    return G, C1, C2, R, C1 + C2 + jnp.abs(R)
def jlap(u, dx):
    inv = 1.0/(dx*dx)
    out = -6.0*u
    for a in (1, 2, 3):
        out = out + jnp.roll(u, -1, axis=a) + jnp.roll(u, 1, axis=a)
    return out*inv
def jadvect(f, v, dx):
    parts = []
    for i in range(3):
        fi = f[..., i]
        acc = jnp.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc = acc + 0.5*(jdd(vj*fi, j + 1, dx) + vj*jdd(fi, j + 1, dx))
        parts.append(acc)
    return jnp.stack(parts, axis=-1)
def jrestrict(F):
    classes = []
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                classes.append(F[:, a::2, b::2, d_::2])
    return jnp.stack(classes, axis=1)
def jmerge(G8, n):
    out = jnp.zeros((G8.shape[0], n, n, n), dtype=G8.dtype)
    idx = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out = out.at[:, a::2, b::2, d_::2].set(G8[:, idx])
                idx += 1
    return out
def jrestrict_fw(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))
def j_interp1(F, axis):
    n = F.shape[axis]
    odd = 0.5*(F + jnp.roll(F, -1, axis=axis))
    out = jnp.stack([F, odd], axis=axis + 1)
    shp = list(F.shape); shp[axis] = 2*n
    return out.reshape(shp)
def jprolong(C):
    F = j_interp1(C, C.ndim - 3)
    F = j_interp1(F, F.ndim - 2)
    F = j_interp1(F, F.ndim - 1)
    return F
def jdiv_bundle(V, dx):
    return jdd(V[..., 0], 1, dx) + jdd(V[..., 1], 2, dx) \
        + jdd(V[..., 2], 3, dx)
def jgrad_bundle(phi, dx):
    return jnp.stack([jdd(phi, 1, dx), jdd(phi, 2, dx),
                      jdd(phi, 3, dx)], axis=-1)
def jlap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    nd = F.ndim
    for a in (nd - 3, nd - 2, nd - 1):
        s = s + jnp.roll(F, -1, axis=a) + jnp.roll(F, 1, axis=a)
    return s*inv
def jsmooth_gs(phi, f, dx, iters):
    cc = dx*dx/6.0
    m = phi.shape[-1]
    idx = jnp.indices((m, m, m))
    parity = (idx[0] + idx[1] + idx[2]) % 2
    red = (parity == 0); black = (parity == 1)
    def body(i, phi_):
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(red, r, 0.0)
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(black, r, 0.0)
        return phi_
    return lax.fori_loop(0, iters, body, phi)
def jv_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - jnp.mean(f, axis=(-3, -2, -1), keepdims=True)
        return jsmooth_gs(phi, f, dx, 40)
    phi = jsmooth_gs(phi, f, dx, 2)
    r = f - jlap_apply(phi, dx)
    rc = jrestrict_fw(r)
    ec = jv_cycle(jnp.zeros_like(rc), rc, 2.0*dx)
    phi = phi + jprolong(ec)
    return jsmooth_gs(phi, f, dx, 2)
def _project_warm(Vch, psic0, dx, cycles):
    f = -jdiv_bundle(Vch, dx)
    fc = jrestrict(f)
    H = 2.0*dx
    fc = fc - jnp.mean(fc, axis=(-3, -2, -1), keepdims=True)
    psic = psic0 - jnp.mean(psic0, axis=(-3, -2, -1), keepdims=True)
    def cycle_body(i, psi):
        return jv_cycle(psi, fc, H)
    psic = lax.fori_loop(0, cycles, cycle_body, psic)
    psic = psic - jnp.mean(psic, axis=(-3, -2, -1), keepdims=True)
    resid = jnp.max(jnp.abs(fc - jlap_apply(psic, H))) \
        / (jnp.max(jnp.abs(fc)) + 1e-30)
    phi_full = jmerge(psic, Vch.shape[1])
    return Vch + jgrad_bundle(phi_full, dx), psic, resid

# ---- gates-lite (fresh kernel insurance; proven patterns) ----
print('\n' + '='*79)
print('V27 GATES (minimal, tolerance-based)')
print('='*79)
axes_g, dx_g = np_mesh(16)
rng_g = np.random.default_rng(7)
Vg = rng_g.standard_normal((1, 16, 16, 16, 3))
for _ in range(6):
    for a in (1, 2, 3):
        Vg = 0.5*Vg + 0.25*(np.roll(Vg, -1, axis=a) + np.roll(Vg, 1, axis=a))
Vg_j, _, _ = _project_warm(jnp.asarray(Vg),
                           jnp.zeros((1, 8, 8, 8, 8)), dx_g, COLD_CYCLES)
E0g = float(np.sum(Vg**2)); E1g = float(np.sum(np.asarray(Vg_j)**2))
ok = np.isfinite(E1g) and E1g <= E0g*(1.0 + 1e-5)
print(f'  [G1] projection non-expansiveness: {E1g/max(E0g,1e-30):.8f} '
      f'({"PASS" if ok else "FAIL"})')
assert ok
wg = jadvect(jnp.asarray(Vg), jnp.asarray(Vg), dx_g)
wk = float(np.sum(np.asarray(Vg)*np.asarray(wg))) \
    / max(float(np.sum(np.asarray(Vg)**2)), 1e-30)
print(f'  [G2] fused advection zero-work: {wk:.2e}')
assert abs(wk) < 1e-12
print('  GATES PASS.\n')

# ---- classical step + scan (dt a closure parameter: one compile/config) ----
def make_classical_scan(n, dt, cycles):
    ics, dx = build_ics_np(n)
    C = len(ICS)
    U0 = np.stack([ics[nm] for nm in ICS])
    for ci in range(C):
        U0[ci] = np_project_channels(U0[ci][None], dx, INIT_CYCLES)[0]
    U0j = jnp.asarray(U0)
    vol = dx**3
    E0 = np.asarray(0.5*vol*jnp.sum(U0j*U0j, axis=(1, 2, 3, 4)))
    nu = jnp.asarray(np.full(C, NU_TEST))
    nu_ = nu[:, None, None, None, None]

    def step(u, psic):
        Cb = u.shape[0]
        _, _, _, _, tension = jnth_jacobian(u, dx)
        Mk = jnp.max(tension.reshape(Cb, -1), axis=1)
        au1 = jadvect(u, u, dx)
        Lu = jlap(u, dx)
        u_star = u + dt*(-au1 + nu_*Lu)
        au2 = jadvect(u_star, u_star, dx)
        u_s = u + 0.5*dt*(-(au1 + au2) + nu_*(Lu + jlap(u_star, dx)))
        Epre = 0.5*vol*jnp.sum(u*u, axis=(1, 2, 3, 4))
        Eheun = 0.5*vol*jnp.sum(u_s*u_s, axis=(1, 2, 3, 4))
        divb = jnp.max(jnp.abs(jdiv_bundle(u_s, dx)).reshape(Cb, -1), axis=1)
        u_new, psic_n, resid = _project_warm(u_s, psic, dx, cycles)
        Epost = 0.5*vol*jnp.sum(u_new*u_new, axis=(1, 2, 3, 4))
        return (u_new, psic_n), (Mk, Epost, Epost - Eheun, Eheun - Epre,
                                 divb, resid)

    def body(carry, _):
        u, psic, tc, hc = carry
        (u, psic), (Mk, E, toll, heun, divb, resid) = step(u, psic)
        return (u, psic, tc + toll, hc + heun), \
               (Mk, E, toll, heun, divb, resid)

    psic0 = jnp.zeros((C, 8, n//2, n//2, n//2))
    carry0 = (U0j, psic0, jnp.zeros(C), jnp.zeros(C))
    return body, carry0, dx, E0, C

def run_config(tag, n, dt, steps, cycles, chunk=100):
    body, carry0, dx, E0, C = make_classical_scan(n, dt, cycles)
    print(f'  [{tag}] n={n}^3  dt={dt}  steps={steps}  t={steps*dt}  '
          f'cycles={cycles}  dx={dx:.4f}')
    parts = []; t0 = time.time(); done = 0
    n_ch = int(np.ceil(steps/chunk))
    while done < steps:
        ln = min(chunk, steps - done)
        carry, out = lax.scan(body, carry0 if done == 0 else carry,
                              xs=None, length=ln)
        parts.append([np.asarray(x) for x in out])
        done += ln
        tc = np.asarray(carry[2])
        print(f'    t={done*dt:5.2f}  ({time.time()-t0:6.0f}s)  '
              f'toll-rate so far: '
              + '  '.join(f'{nm}={abs(tc[ci])/max(E0[ci]*done*dt, 1e-30):.4f}'
                          for ci, nm in enumerate(ICS)))
    cols = [np.concatenate([p[i] for p in parts], axis=0)
            for i in range(len(parts[0]))]
    Mk, E, toll, heun, divb, resid = cols
    uF = np.asarray(carry[0])
    T = steps*dt
    r = dict(tag=tag, n=n, dt=dt, steps=steps, cycles=cycles, dx=dx,
             E0=E0, T=T, Mk=Mk, E=E, toll=toll, heun=heun, divb=divb,
             resid=resid, uF=uF, wall=time.time() - t0)
    for ci, nm in enumerate(ICS):
        aud = abs((E[-1, ci] - E0[ci])
                  - (np.cumsum(toll[:, ci])[-1]
                     + np.cumsum(heun[:, ci])[-1]))/max(E0[ci], 1e-30)
        assert aud < 1e-10, f'ledger broken {tag}/{nm}: {aud:.2e}'
        assert np.all(np.isfinite(E[:, ci])), f'non-finite {tag}/{nm}'
    print(f'    done: wall={r["wall"]:.0f}s  ledger audit < 1e-10  '
          f'worst solver resid={resid.max():.1e}')
    return r

print('#'*79)
print('V27 — REFINEMENT LADDER (classical arms, nu=1e-4, both ICs)')
print('#'*79)
rA = run_config('A', 32, 0.004, 400, WARM_CYCLES)
rAc = run_config('A*', 32, 0.004, 400, COLD_CYCLES)
rB = run_config('B', 32, 0.002, 800, WARM_CYCLES)
rC = run_config('C', 64, 0.002, 800, WARM_CYCLES) if RUN_64 else None

# ---- analysis ----
print('\n' + '='*79)
