print('='*79)
def rates(r):
    out = {}
    for ci, nm in enumerate(ICS):
        tc = abs(float(np.cumsum(r['toll'][:, ci])[-1]))
        hc = abs(float(np.cumsum(r['heun'][:, ci])[-1]))
