# ---- dual step: batched warm projection + exact m/d ledger ----
def make_dual_scan(n, dt, cycles):
    ics, dx = build_ics_np(n)
    C = len(ICS)
    U0 = np.stack([ics[nm] for nm in ICS])
    Us0 = jnp.asarray(np.concatenate([U0, np.zeros_like(U0)], axis=0))
    psic0 = jnp.zeros((2*C, 8, n//2, n//2, n//2))
    Us0, psic0, _ = _project_warm(Us0, psic0, dx, INIT_CYCLES)
    U0j, P0j = Us0[:C], Us0[C:]
    _, _, _, _, t0_ = jnth_jacobian(U0j, dx)
    M0 = np.asarray(jnp.max(t0_.reshape(C, -1), axis=1))
    THR = THRESH_FRAC*M0
    nu = jnp.asarray(np.full(C, NU_TEST))
    nu_ = nu[:, None, None, None, None]
    thr = jnp.asarray(THR)
    vol = dx**3
    Em0 = np.asarray(0.25*vol*jnp.sum((U0j + P0j)**2, axis=(1, 2, 3, 4)))
    Ed0 = np.asarray(0.25*vol*jnp.sum((U0j - P0j)**2, axis=(1, 2, 3, 4)))

    def step(u, p, psic):
        Cb = u.shape[0]
        G_u, C1_u, C2_u, R_u, tension_u = jnth_jacobian(u, dx)
        Mk_u = jnp.max(tension_u.reshape(Cb, -1), axis=1)
        m = u + p
        _, _, _, _, tension_m = jnth_jacobian(m, dx)
        Mk_m = jnp.max(tension_m.reshape(Cb, -1), axis=1)
        Em_pre, Ed_pre = _Es_md(u, p, vol)
        au1 = jadvect(u, m, dx); ap1 = jadvect(p, m, dx)
        Lu = jlap(u, dx); Lp = jlap(p, dx)
        u_star = u + dt*(-au1 + nu_*Lu)
        p_star = p + dt*(-ap1 + nu_*Lp)
        m_star = u_star + p_star
        au2 = jadvect(u_star, m_star, dx)
        ap2 = jadvect(p_star, m_star, dx)
        u_s = u + 0.5*dt*(-(au1 + au2) + nu_*(Lu + jlap(u_star, dx)))
        p_s = p + 0.5*dt*(-(ap1 + ap2) + nu_*(Lp + jlap(p_star, dx)))
        Ehm, Ehd = _Es_md(u_s, p_s, vol)
        u_t, p_t = jomega_transfer(u_s, p_s, G_u, C1_u, C2_u, R_u,
                                    tension_u, dx, thr, GAIN)
        Us = jnp.concatenate([u_t, p_t], axis=0)
        Unew, psic_n, resid = _project_warm(Us, psic, dx, cycles)
        u_new = Unew[:Cb]; p_new = Unew[Cb:]
        gm = u_new - u_t; gp = p_new - p_t
        tm = 0.25*vol*jnp.sum(2.0*(u_t + p_t)*(gm + gp)
                              + (gm + gp)*(gm + gp), axis=(1, 2, 3, 4))
        td = 0.25*vol*jnp.sum(2.0*(u_t - p_t)*(gm - gp)
                              + (gm - gp)*(gm - gp), axis=(1, 2, 3, 4))
        Em, Ed = _Es_md(u_new, p_new, vol)
        return (u_new, p_new, psic_n), \
            (Mk_u, Mk_m, tm, td, Ehm - Em_pre, Ehd - Ed_pre, Em, Ed, resid)

    def body(carry, _):
        u, p, psic, Su, Sm, tmc, tdc, hmc, hdc = carry
        (u, p, psic), (Mk_u, Mk_m, tm, td, hm, hd, Em, Ed, resid) = \
            step(u, p, psic)
        return (u, p, psic, Su + Mk_u*dt, Sm + Mk_m*dt,
                tmc + tm, tdc + td, hmc + hm, hdc + hd), \
               (Mk_u, Mk_m, tm, td, hm, hd, Em, Ed, resid)

    carry0 = (U0j, P0j, psic0, jnp.zeros(C), jnp.zeros(C),
              jnp.zeros(C), jnp.zeros(C), jnp.zeros(C), jnp.zeros(C))
    return body, carry0, dx, Em0, Ed0, M0, C

def run_dual(tag, n, dt, cycles, T):
    steps = int(round(T/dt))
    body, carry0, dx, Em0, Ed0, M0, C = make_dual_scan(n, dt, cycles)
    print(f'  [{tag}] n={n}^3  dt={dt}  steps={steps}  T={steps*dt}  '
          f'omega=ON  gain={GAIN}  nu={NU_TEST:g}')
    parts = []; t0 = time.time(); done = 0
    while done < steps:
        ln = min(CHUNK, steps - done)
        carry, out = lax.scan(body, carry0 if done == 0 else carry,
                              xs=None, length=ln)
        parts.append([np.asarray(x) for x in out])
        done += ln
        Em_now = np.asarray(carry[6] if False else parts[-1][6])[-1] \
            if False else None
        tc = np.asarray(carry[5]); tdc = np.asarray(carry[6])
        Su = np.asarray(carry[3]); Sm = np.asarray(carry[4])
        msg = '  '.join(f'{nm}:Sm={Sm[ci]:.0f},Ed%={100*float(np.asarray(parts[-1][7])[-1, ci])/max(Ed0[ci], 1e-30):.0f}'
                        for ci, nm in enumerate(ICS))
        print(f'    t={done*dt:5.2f}  ({time.time()-t0:6.0f}s)  {msg}')
    cols = [np.concatenate([p_[i] for p_ in parts], axis=0)
            for i in range(len(parts[0]))]
    Mku, Mkm, tm, td, hm, hd, Em, Ed, resid = cols
    r = dict(tag=tag, dt=dt, steps=steps, T=steps*dt, Em0=Em0, Ed0=Ed0,
             M0=M0, Mku=Mku, Mkm=Mkm, tm=tm, td=td, hm=hm, hd=hd,
             Em=Em, Ed=Ed, resid=resid, wall=time.time() - t0)
    for ci, nm in enumerate(ICS):
        audm = abs((Em[-1, ci] - Em0[ci])
                   - (np.cumsum(hm[:, ci])[-1]
                      + np.cumsum(tm[:, ci])[-1]))/max(Em0[ci], 1e-30)
        audd = abs((Ed[-1, ci] - Ed0[ci])
                   - (np.cumsum(hd[:, ci])[-1]
                      + np.cumsum(td[:, ci])[-1]))/max(Ed0[ci], 1e-30)
        assert audm < 1e-10 and audd < 1e-10, \
            f'ledger broken {tag}/{nm}: {audm:.2e} {audd:.2e}'
        assert np.all(np.isfinite(Em[:, ci])), f'non-finite {tag}/{nm}'
    print(f'    done: wall={r["wall"]:.0f}s  ledger < 1e-10 (m and d)  '
          f'worst resid={resid.max():.1e}')
    return r

