def model_saturating(t, B, A, k):
    return B - A*np.exp(-k*t)
def model_linear(t, rate, c):
    return rate*t + c
def model_power(t, a, p, c):
    return a*np.power(t, p) + c
def fit_three_models(t_data, s_data, t_min=1.0):
    msk = t_data >= t_min
    t_fit, s_fit = t_data[msk], s_data[msk]
    n = len(t_fit)
    if n < 20:
        return None
    fits_dict = {}
    for name, model, p0, nparams in (
        ('S', model_saturating,
         [s_fit[-1] + 0.5*max(s_fit[-1]-s_fit[0], 1e-9),
          max(s_fit[-1]-s_fit[0], 1e-9), 0.5], 3),
        ('L', model_linear,
         [(s_fit[-1]-s_fit[0])/max(t_fit[-1]-t_fit[0], 1e-9),
          s_fit[0]], 2),
        ('P', model_power, None, 3)):
        try:
            if p0 is None:
                lt = np.log(np.maximum(t_fit, 1e-9))
                ls = np.log(np.maximum(s_fit, 1e-9))
                p_est = max(float(np.polyfit(lt, ls, 1)[0]), 1.05)
                p0 = [s_fit[-1]/max(t_fit[-1]**p_est, 1e-9), p_est, 0.0]
            popt, _ = optimize_curve_fit(model, t_fit, s_fit, p0)
            if name == 'P' and popt[1] <= 1.0:
                popt = (popt[0], 1.001, popt[2])
            ss = float(np.sum((s_fit - model(t_fit, *popt))**2))
            fits_dict[name] = (popt, n*np.log(max(ss/n, 1e-30)) + 2*nparams)
        except Exception:
            fits_dict[name] = (None, np.inf)
    valid = {k: v for k, v in fits_dict.items()
             if v[0] is not None and np.isfinite(v[1])}
    if not valid:
        return None
    return fits_dict, min(valid, key=lambda k: valid[k][1])
from scipy import optimize as _opt
def optimize_curve_fit(model, t, s, p0):
    return _opt.curve_fit(model, t, s, p0=p0, maxfev=10000)
