#        axis 1 as components; caller passed single scalar components
#        (B,n,n,n) -> Vch[:,2] became 3D -> jdd axis 3 out of bounds).
#        FIX: _project_warm RESTORED VERBATIM from the v26.3-v28 lineage
#        (vector bundles (B,n,n,n,3), components LAST; warm psi
#        (B,8,n/2,n/2,n/2) class-first). The rewritten layer is DELETED.
#        Per-IC residuals ([14]'s actual requirement) are computed post-hoc
#        from the projected state: per-IC max|div| — no core changes.
#   DISCIPLINE (standing): proven cores are never rewritten; new
#        instrumentation attaches at the periphery only. Every crash in
#        the V28.1 series came from rewriting the projection core, which
#        had zero failures across all prior runs.
#   Standing fixes carried: [11] C from U0.shape[0]; [12] per-IC fsd;
#   [13] named series + asserted contracts; [P1] corrector-bundle
#   reconstruction (m_s). REF is EXACTLY the V27.3 construction.
# =============================================================================
import time
import numpy as np
import matplotlib.pyplot as plt

import jax
jax.config.update("jax_enable_x64", True)
import jax.numpy as jnp
from jax import lax

print('JAX version:', jax.__version__)
print('backend devices:', jax.devices())
IS_GPU = 'gpu' in str(jax.devices()[0]).lower()
print('backend: CUDA GPU' if IS_GPU else 'backend: CPU')

np.set_printoptions(precision=6, suppress=True)
L_dom = 2.0*np.pi; L_half = L_dom/2.0
NU_TEST = 0.0001
WARM_CYCLES = 8; INIT_CYCLES = 20
DT_RUN = 0.004
QUICK = False
T_H = 1.5 if QUICK else 3.0
CHUNK = 125 if QUICK else 150
A_SWIRL = 6.0; PHI = 0.5*(1.0 + np.sqrt(5.0)); W_GOLD = 12.0/PHI
SIGMA_IC = 1.0; A_WIND = 0.35
ICS = ['tubes', 'wound']
GAIN = 10.0; THRESH_FRAC = 0.5

# ---- ICs (numpy) ----
def np_mesh(n):
    x = np.linspace(0.0, L_dom, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), L_dom/n

def ic_tubes(axes, strength=8.0, sigma=0.8, sep=1.6, tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt); st = np.sin(tilt)
    def tube(cx, sign):
        dx_ = (x - cx + L_half) % L_dom - L_half
        dy_ = (y - np.pi + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        r2 = dx_t*dx_t + dy_*dy_
        f = np.exp(-r2/(2.0*sigma*sigma))
        return np.stack([-sign*strength*dy_*f,
                         sign*strength*dx_t*f, np.zeros_like(x)], axis=-1)
    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)

def ic_wound(axes):
    x, y, z = axes
    xc = np.pi + A_WIND*np.sin(z)
    yc = np.pi + A_WIND*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA_IC*SIGMA_IC))
    return np.stack([-A_SWIRL*ry*f, A_SWIRL*rx*f, W_GOLD*f], axis=-1)

def build_ics_np(n):
    axes, dx = np_mesh(n)
    return {'tubes': ic_tubes(axes), 'wound': ic_wound(axes)}, dx

def np_split_classes(f):
    """Axiom 2.6.1 parity decomposition, class axis FIRST, for a pure
    spatial field (n,n,n) -> (8, M, M, M)."""
    N = f.shape[-1]; M = N//2
    out = np.empty((8, M, M, M), dtype=f.dtype)
    c = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out[c] = f[a::2, b::2, d_::2]
                c += 1
    return out

# ---- JAX core (proven operators) ----
def jdd(f, axis, dx):
    return (jnp.roll(f, -1, axis=axis) - jnp.roll(f, 1, axis=axis))*(0.5/dx)
def jnth_jacobian(u, dx):
    gu = []
    for i in range(3):
        for j in range(3):
            gu.append(jdd(u[..., i], j + 1, dx))
    G = jnp.stack(gu, axis=-1).reshape(u.shape[0], u.shape[1],
                                       u.shape[1], u.shape[1], 3, 3)
    S = 0.5*(G + jnp.swapaxes(G, -1, -2))
    C1 = jnp.sqrt(jnp.sum(S*S, axis=(-2, -1)))
    A_ = 0.5*(G - jnp.swapaxes(G, -1, -2))
    C2 = jnp.sqrt(jnp.sum(A_*A_, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    return G, C1, C2, R, C1 + C2 + jnp.abs(R)
def jlap(u, dx):
    inv = 1.0/(dx*dx)
    out = -6.0*u
    for a in (1, 2, 3):
        out = out + jnp.roll(u, -1, axis=a) + jnp.roll(u, 1, axis=a)
    return out*inv
def jadvect(f, v, dx):
    parts = []
    for i in range(3):
        fi = f[..., i]
        acc = jnp.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc = acc + 0.5*(jdd(vj*fi, j + 1, dx) + vj*jdd(fi, j + 1, dx))
        parts.append(acc)
    return jnp.stack(parts, axis=-1)
def jaxis_dominant(C1, C2, G, dx):
    rot_dom = C2 > C1
    w0 = G[..., 2, 1] - G[..., 1, 2]
    w1 = G[..., 0, 2] - G[..., 2, 0]
    w2 = G[..., 1, 0] - G[..., 0, 1]
    wn = jnp.sqrt(w0*w0 + w1*w1 + w2*w2)
    gs0 = jdd(C1, 1, dx); gs1 = jdd(C1, 2, dx); gs2 = jdd(C1, 3, dx)
    gn = jnp.sqrt(gs0*gs0 + gs1*gs1 + gs2*gs2)
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    ax_v = jnp.stack([w0, w1, w2], axis=-1) \
        / jnp.maximum(wn, 1e-30)[..., None]
    ax_g = jnp.stack([gs0, gs1, gs2], axis=-1) \
        / jnp.maximum(gn, 1e-30)[..., None]
    return jnp.where(use_v[..., None], ax_v,
                     jnp.where(use_g[..., None], ax_g,
                               jnp.zeros_like(ax_v)))
def jrestrict(F):
    classes = []
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                classes.append(F[:, a::2, b::2, d_::2])
    return jnp.stack(classes, axis=1)
def jmerge(G8, n):
    out = jnp.zeros((G8.shape[0], n, n, n), dtype=G8.dtype)
    idx = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out = out.at[:, a::2, b::2, d_::2].set(G8[:, idx])
                idx += 1
    return out
def jrestrict_fw(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))
def j_interp1(F, axis):
    n = F.shape[axis]
    odd = 0.5*(F + jnp.roll(F, -1, axis=axis))
    out = jnp.stack([F, odd], axis=axis + 1)
    shp = list(F.shape); shp[axis] = 2*n
    return out.reshape(shp)
def jprolong(C):
    F = j_interp1(C, C.ndim - 3)
    F = j_interp1(F, F.ndim - 2)
    F = j_interp1(F, F.ndim - 1)
    return F
def jdiv_bundle(V, dx):
    return jdd(V[..., 0], 1, dx) + jdd(V[..., 1], 2, dx) \
        + jdd(V[..., 2], 3, dx)
def jgrad_bundle(phi, dx):
    return jnp.stack([jdd(phi, 1, dx), jdd(phi, 2, dx),
                      jdd(phi, 3, dx)], axis=-1)
def jlap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    nd = F.ndim
    for a in (nd - 3, nd - 2, nd - 1):
        s = s + jnp.roll(F, -1, axis=a) + jnp.roll(F, 1, axis=a)
    return s*inv
def jsmooth_gs(phi, f, dx, iters):
    cc = dx*dx/6.0
    m = phi.shape[-1]
    idx = jnp.indices((m, m, m))
    parity = (idx[0] + idx[1] + idx[2]) % 2
    red = (parity == 0); black = (parity == 1)
    def body(i, phi_):
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(red, r, 0.0)
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(black, r, 0.0)
        return phi_
    return lax.fori_loop(0, iters, body, phi)
def jv_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - jnp.mean(f, axis=(-3, -2, -1), keepdims=True)
        return jsmooth_gs(phi, f, dx, 40)
    phi = jsmooth_gs(phi, f, dx, 2)
    r = f - jlap_apply(phi, dx)
    rc = jrestrict_fw(r)
    ec = jv_cycle(jnp.zeros_like(rc), rc, 2.0*dx)
    phi = phi + jprolong(ec)
    return jsmooth_gs(phi, f, dx, 2)

def _project_warm(Vch, psic0, dx, cycles):
    """RESTORED VERBATIM from the v26.3-v28 lineage (zero failures in
    every executed run). CONTRACT: Vch (B,n,n,n,3) vector bundle,
    components on the LAST axis; psic0 (B,8,n/2,n/2,n/2) class-first warm
    state. Returns (projected (B,n,n,n,3), warm psi, SCALAR residual).
    Per-IC diagnostics are computed by callers from the projected state."""
    f = -jdiv_bundle(Vch, dx)
    fc = jrestrict(f)
    H = 2.0*dx
    fc = fc - jnp.mean(fc, axis=(-3, -2, -1), keepdims=True)
    psic = psic0 - jnp.mean(psic0, axis=(-3, -2, -1), keepdims=True)
    def cycle_body(i, psi):
        return jv_cycle(psi, fc, H)
    psic = lax.fori_loop(0, cycles, cycle_body, psic)
    psic = psic - jnp.mean(psic, axis=(-3, -2, -1), keepdims=True)
    resid = jnp.max(jnp.abs(fc - jlap_apply(psic, H))) \
        / (jnp.max(jnp.abs(fc)) + 1e-30)
    phi_full = jmerge(psic, Vch.shape[1])
    return Vch + jgrad_bundle(phi_full, dx), psic, resid

def _Es_md(a, b, vol):
    s = a + b; d = a - b
    return (0.25*vol*jnp.sum(s*s, axis=(1, 2, 3, 4)),
            0.25*vol*jnp.sum(d*d, axis=(1, 2, 3, 4)))

def _rotate_d(u_s, p_s, G, C1, C2, tension, dx, thr, gain, sigma):
    """Omega rotation of the split channel with channel-order sign sigma
    (+1: C1-leading, axis x d; -1: C2-leading). Exact isometry on |d|;
    m untouched (returns d_rot only)."""
    excess = jnp.maximum(tension - thr[:, None, None, None], 0.0)
    g = gain*excess*dx
    t_ = g/(1.0 + g)
    c_ = (1.0 - t_*t_)/(1.0 + t_*t_)
    s_ = (2.0*t_)/(1.0 + t_*t_)
    d = 0.5*(u_s - p_s)
    axis = jaxis_dominant(C1, C2, G, dx)
    Pd = jnp.cross(axis, d)
    d_ax = d + jnp.cross(axis, Pd)
    d_tr = d - d_ax
    d_rot = d_ax + c_[..., None]*d_tr \
        + sigma*s_[..., None]*jnp.cross(axis, d_tr)
    route = tension > thr[:, None, None, None]
    srot = jnp.sum(jnp.where(route, s_, 0.0), axis=(1, 2, 3)) \
        / jnp.maximum(jnp.sum(route, axis=(1, 2, 3)), 1.0)
    return d_rot, srot

# ---- shared initialization ----
def _shared_init(n, U0=None):
    ics, dx = build_ics_np(n)
    if U0 is None:
        U0 = np.stack([ics[nm] for nm in ICS])
    U0 = np.asarray(U0, dtype=np.float64)
    assert U0.ndim == 5 and U0.shape[1:] == (n, n, n, 3), \
        f'U0 shape {U0.shape} incompatible with grid {n}^3'
    C = U0.shape[0]
    Us0 = jnp.asarray(np.concatenate([U0, np.zeros_like(U0)], axis=0))
    psic0 = jnp.zeros((2*C, 8, n//2, n//2, n//2))
    Us0, psic0, _ = _project_warm(Us0, psic0, dx, INIT_CYCLES)
    U0j, P0j = Us0[:C], Us0[C:]
    _, _, _, _, t0_ = jnth_jacobian(U0j, dx)
    M0 = np.asarray(jnp.max(t0_.reshape(C, -1), axis=1))
    vol = dx**3
    Em0 = np.asarray(0.25*vol*jnp.sum((U0j + P0j)**2, axis=(1, 2, 3, 4)))
    Ed0 = np.asarray(0.25*vol*jnp.sum((U0j - P0j)**2, axis=(1, 2, 3, 4)))
    return U0j, P0j, psic0, dx, Em0, Ed0, M0, C

# ---- PERSIST factory: bundle projection, symmetric distribution ----
def make_persist_factory(n, dt, cycles, U0=None):
    U0j, P0j, psic0, dx, Em0, Ed0, M0, C = _shared_init(n, U0)
    THR = jnp.asarray(THRESH_FRAC*M0)
    nu = jnp.asarray(np.full(C, NU_TEST))
    nu_ = nu[:, None, None, None, None]
    vol = dx**3

    def step(u, p, psic_m, sigma):
        Cb = u.shape[0]
        G_u, C1_u, C2_u, R_u, tension_u = jnth_jacobian(u, dx)
        Mk_u = jnp.max(tension_u.reshape(Cb, -1), axis=1)
        m = u + p
        _, _, _, _, tension_m = jnth_jacobian(m, dx)
        Mk_m = jnp.max(tension_m.reshape(Cb, -1), axis=1)
        Em_pre, Ed_pre = _Es_md(u, p, vol)
        au1 = jadvect(u, m, dx); ap1 = jadvect(p, m, dx)
        Lu = jlap(u, dx); Lp = jlap(p, dx)
        u_star = u + dt*(-au1 + nu_*Lu)
        p_star = p + dt*(-ap1 + nu_*Lp)
        m_star = u_star + p_star
        au2 = jadvect(u_star, m_star, dx)
        ap2 = jadvect(p_star, m_star, dx)
        u_s = u + 0.5*dt*(-(au1 + au2) + nu_*(Lu + jlap(u_star, dx)))
        p_s = p + 0.5*dt*(-(ap1 + ap2) + nu_*(Lp + jlap(p_star, dx)))
        m_s = u_s + p_s                     # corrector bundle (FIX P1)
        Ehm, Ehd = _Es_md(u_s, p_s, vol)
        d_rot, srot = _rotate_d(u_s, p_s, G_u, C1_u, C2_u, tension_u,
                                dx, THR, GAIN, sigma)
        u_t = 0.5*m_s + d_rot
        p_t = 0.5*m_s - d_rot
        Ed_t = _Es_md(u_t, p_t, vol)[1]
        iso = Ed_t - Ehd                    # isometry residual (~FP)
        m_new, psic_m2, _ = _project_warm(m_s, psic_m, dx, cycles)
        gcor = m_new - m_s
        u_new = u_t + 0.5*gcor
        p_new = p_t + 0.5*gcor
        Em, Ed = _Es_md(u_new, p_new, vol)
        d_new = 0.5*(u_new - p_new)
        maxd = jnp.max(jnp.sqrt(jnp.sum(d_new*d_new, axis=-1)),
                       axis=(1, 2, 3))
        divd = jnp.max(jnp.abs(jdiv_bundle(d_new, dx))
                       .reshape(Cb, -1), axis=1)
        divm = jnp.max(jnp.abs(jdiv_bundle(m_new, dx))
                       .reshape(Cb, -1), axis=1)
        return (u_new, p_new, psic_m2), \
            (Mk_u, Mk_m, Ehm - Em_pre, Ehd - Ed_pre, Em - Ehm,
             iso, Ed - Ed_t, Em, Ed, maxd, divd, srot, divm)

    def body(carry, sigma):
        u, p, psic_m, Su, Sm = carry
        (u, p, psic_m), out = step(u, p, psic_m, sigma)
        return (u, p, psic_m, Su + out[0]*dt, Sm + out[1]*dt), out

    carry0 = (U0j, P0j, psic0[:C], jnp.zeros(C), jnp.zeros(C))
    return dict(step=step, body=body, carry0=carry0, dx=dx, Em0=Em0,
                Ed0=Ed0, M0=M0, C=C, n=n, dt=dt, U0j=U0j, P0j=P0j,
                psic_m0=psic0[:C])

# ---- REF factory: per-channel construction (draining control; EXACTLY
#      the V27.3 lineage construction with FIX P1) ----
def make_ref_factory(n, dt, cycles, U0=None):
    U0j, P0j, psic0, dx, Em0, Ed0, M0, C = _shared_init(n, U0)
    THR = jnp.asarray(THRESH_FRAC*M0)
    nu = jnp.asarray(np.full(C, NU_TEST))
    nu_ = nu[:, None, None, None, None]
    vol = dx**3

    def step(u, p, psic):
        Cb = u.shape[0]
        G_u, C1_u, C2_u, R_u, tension_u = jnth_jacobian(u, dx)
        Mk_u = jnp.max(tension_u.reshape(Cb, -1), axis=1)
        m = u + p
        _, _, _, _, tension_m = jnth_jacobian(m, dx)
        Mk_m = jnp.max(tension_m.reshape(Cb, -1), axis=1)
        Em_pre, Ed_pre = _Es_md(u, p, vol)
        au1 = jadvect(u, m, dx); ap1 = jadvect(p, m, dx)
        Lu = jlap(u, dx); Lp = jlap(p, dx)
        u_star = u + dt*(-au1 + nu_*Lu)
        p_star = p + dt*(-ap1 + nu_*Lp)
        m_star = u_star + p_star
        au2 = jadvect(u_star, m_star, dx)
        ap2 = jadvect(p_star, m_star, dx)
        u_s = u + 0.5*dt*(-(au1 + au2) + nu_*(Lu + jlap(u_star, dx)))
        p_s = p + 0.5*dt*(-(ap1 + ap2) + nu_*(Lp + jlap(p_star, dx)))
        m_s = u_s + p_s                     # corrector bundle (FIX P1)
        Ehm, Ehd = _Es_md(u_s, p_s, vol)
        d_rot, _ = _rotate_d(u_s, p_s, G_u, C1_u, C2_u, tension_u,
                             dx, THR, GAIN, 1.0)
        u_t = 0.5*m_s + d_rot
        p_t = 0.5*m_s - d_rot
        Us = jnp.concatenate([u_t, p_t], axis=0)
        Unew, psic_n, _ = _project_warm(Us, psic, dx, cycles)
        u_new = Unew[:Cb]; p_new = Unew[Cb:]
        gm = u_new - u_t; gp = p_new - p_t
        toll_m = 0.25*vol*jnp.sum(2.0*(u_t + p_t)*(gm + gp)
                                  + (gm + gp)*(gm + gp), axis=(1, 2, 3, 4))
        toll_d = 0.25*vol*jnp.sum(2.0*(u_t - p_t)*(gm - gp)
                                  + (gm - gp)*(gm - gp), axis=(1, 2, 3, 4))
        Em, Ed = _Es_md(u_new, p_new, vol)
        divu = jnp.max(jnp.abs(jdiv_bundle(u_new, dx))
                       .reshape(Cb, -1), axis=1)
        return (u_new, p_new, psic_n), \
            (Mk_u, Mk_m, Ehm - Em_pre, Ehd - Ed_pre, toll_m, toll_d,
             Em, Ed, divu)

    def body(carry, _):
        u, p, psic, Su, Sm = carry
        (u, p, psic), out = step(u, p, psic)
        return (u, p, psic, Su + out[0]*dt, Sm + out[1]*dt), out

    carry0 = (U0j, P0j, psic0, jnp.zeros(C), jnp.zeros(C))
    return dict(step=step, body=body, carry0=carry0, dx=dx, Em0=Em0,
                Ed0=Ed0, M0=M0, C=C, n=n, dt=dt)

# ---- instruments (per-IC) ----
def finest_share_d(d_np):
    C = d_np.shape[0]
    out = np.empty(C)
    for ci in range(C):
        num = 0.0; den = 0.0
        for j in range(3):
            f = d_np[ci, ..., j]
            g = np_split_classes(f)
            blk = g.mean(axis=0, keepdims=True)
            num += float(np.sum((g - blk)**2))
            den += float(np.sum((f - f.mean())**2))
        out[ci] = num/(den + 1e-300)
    return out

def chunk_stats(carry, dx):
    u = np.asarray(carry[0]); p = np.asarray(carry[1])
    vol = dx**3
    Em = 0.25*vol*np.sum((u + p)**2, axis=(1, 2, 3, 4))
    Ed = 0.25*vol*np.sum((u - p)**2, axis=(1, 2, 3, 4))
    d = 0.5*(u - p)
    fsd = finest_share_d(d)
    maxd = np.max(np.sqrt(np.sum(d*d, axis=-1)), axis=(1, 2, 3))
    return Em, Ed, fsd, maxd

# =============================================================================
# GATES
# =============================================================================
print('\n' + '='*79)
print('V28.1d GATES')
print('='*79)
axes_g, dx_g = np_mesh(16)
rng_g = np.random.default_rng(7)
Vg = rng_g.standard_normal((1, 16, 16, 16, 3))
for _ in range(6):
    for a in (1, 2, 3):
        Vg = 0.5*Vg + 0.25*(np.roll(Vg, -1, axis=a) + np.roll(Vg, 1, axis=a))
Vg_j = jnp.asarray(Vg)
E0g = float(np.sum(Vg**2))
Vp, _, _ = _project_warm(Vg_j, jnp.zeros((1, 8, 8, 8, 8)), dx_g, 20)
E1g = float(np.sum(np.asarray(Vp)**2))
ok = np.isfinite(E1g) and E1g <= E0g*(1.0 + 1e-5)
print(f'  [G1] projection non-expansiveness: {E1g/max(E0g,1e-30):.8f} '
      f'({"PASS" if ok else "FAIL"})')
assert ok
wg = jadvect(Vg_j, Vg_j, dx_g)
wk = float(np.sum(np.asarray(Vg_j)*np.asarray(wg))) \
    / max(float(np.sum(np.asarray(Vg_j)**2)), 1e-30)
print(f'  [G2] fused advection zero-work: {wk:.2e}')
assert abs(wk) < 1e-12

a3 = jnp.asarray(rng_g.standard_normal((1, 16, 16, 16, 3)))
for _ in range(6):
    for a in (1, 2, 3):
        a3 = 0.5*a3 + 0.25*(jnp.roll(a3, -1, axis=a) + jnp.roll(a3, 1, axis=a))
b3 = jnp.asarray(rng_g.standard_normal((1, 16, 16, 16, 3)))
for _ in range(6):
    for a in (1, 2, 3):
        b3 = 0.5*b3 + 0.25*(jnp.roll(b3, -1, axis=a) + jnp.roll(b3, 1, axis=a))
m3 = a3 + b3
m3n, _, _ = _project_warm(m3, jnp.zeros((1, 8, 8, 8, 8)), dx_g, 20)
g3 = m3n - m3
d_before = 0.5*(a3 - b3)
d_after = 0.5*((a3 + 0.5*g3) - (b3 + 0.5*g3))
err3 = float(jnp.max(jnp.abs(d_after - d_before))) \
    / max(float(jnp.max(jnp.abs(d_before))), 1e-30)
print(f'  [G3] symmetric m-projection d-invariance: {err3:.2e} '
      f'(the closure never touches the split)')
