def run_arm(tag, factory, steps, sigma=None):
    body = factory['body']; carry = factory['carry0']
    dx = factory['dx']; C = factory['C']
    print(f'  [{tag}] n={factory["n"]}^3  dt={factory["dt"]}  '
          f'steps={steps}  T={steps*factory["dt"]:.2f}'
          + ('' if sigma is None else f'  sigma={sigma:+.0f}'))
    parts = []; fsd_ser = []; t0 = time.time(); done = 0
    while done < steps:
        ln = min(CHUNK, steps - done)
        if sigma is None:
            carry, out = lax.scan(body, carry, xs=None, length=ln)
        else:
            xs = jnp.asarray(np.full(ln, sigma, dtype=np.float64))
            carry, out = lax.scan(body, carry, xs=xs)
        parts.append([np.asarray(x) for x in out])
        done += ln
        Em_c, Ed_c, fsd_c, _ = chunk_stats(carry, dx)
        fsd_ser.append(fsd_c)
        msg = '  '.join(
            f'{nm}:Em%={100*Em_c[ci]/factory["Em0"][ci]:.0f}'
            f',Ed%={100*Ed_c[ci]/factory["Ed0"][ci]:.0f}'
            f',fsd={fsd_c[ci]:.2f}'
            for ci, nm in enumerate(ICS))
        print(f'    t={done*factory["dt"]:5.2f}  '
              f'({time.time()-t0:6.0f}s)  {msg}')
    cols = [np.concatenate([p_[i] for p_ in parts], axis=0)
            for i in range(len(parts[0]))]
    if sigma is None:      # REF: 9-slot tuple
        (Mk_u, Mk_m, hm, hd, toll_m, toll_d, Em, Ed, divu) = cols
        series = dict(Mk_u=Mk_u, Mk_m=Mk_m, hm=hm, hd=hd, tm=toll_m,
                      td=toll_d, Em=Em, Ed=Ed, divu=divu)
    else:                  # PERSIST: 13-slot tuple
        (Mk_u, Mk_m, hm, hd, tm, iso, pd, Em, Ed, maxd, divd, srot,
         divm) = cols
        series = dict(Mk_u=Mk_u, Mk_m=Mk_m, hm=hm, hd=hd, tm=tm,
                      iso=iso, pd=pd, Em=Em, Ed=Ed, maxd=maxd,
                      divd=divd, srot=srot, divm=divm)
    for k, v in series.items():     # asserted contracts
        assert v.ndim == 2 and v.shape == (steps, C) \
            and np.all(np.isfinite(v)), \
            f'series {k} malformed: {v.shape}'
    return dict(tag=tag, sigma=sigma, dx=dx, dt=factory['dt'],
                steps=steps, Em0=factory['Em0'], Ed0=factory['Ed0'],
                M0=factory['M0'], fsd=np.asarray(fsd_ser), series=series,
                wall=time.time() - t0)

def assert_ledgers(r):
    s = r['series']
    for ci, nm in enumerate(ICS):
        e_m = abs((s['Em'][-1, ci] - r['Em0'][ci])
                  - (float(np.cumsum(s['hm'][:, ci])[-1])
                     + float(np.cumsum(s['tm'][:, ci])[-1]))) / r['Em0'][ci]
        if 'td' in s:      # REF mode
            d_terms = (float(np.cumsum(s['hd'][:, ci])[-1])
                       + float(np.cumsum(s['td'][:, ci])[-1]))
            extra = ''
        else:               # persist mode
            d_terms = (float(np.cumsum(s['hd'][:, ci])[-1])
                       + float(np.cumsum(s['iso'][:, ci])[-1])
                       + float(np.cumsum(s['pd'][:, ci])[-1]))
            extra = (f'  [iso sum '
                     f'{float(np.cumsum(s["iso"][:, ci])[-1]):.1e}'
                     f'  pd sum '
                     f'{float(np.cumsum(s["pd"][:, ci])[-1]):.1e}]')
        e_d = abs((s['Ed'][-1, ci] - r['Ed0'][ci]) - d_terms) / r['Ed0'][ci]
        print(f'    ledger [{nm}]: m {e_m:.2e}  d {e_d:.2e}{extra}')
        assert e_m < 1e-10 and e_d < 1e-10, \
            f'ledger broken {r["tag"]}/{nm}: {e_m:.2e} {e_d:.2e}'

