def valid_checkpoints():
    out = []
    for fn in sorted(glob.glob(os.path.join(
            SAVE_DIR, 'v295*_fields_t*.npz'))):
        try:
            z = np.load(fn)
            u = z['u']; p = z['p']; M0 = z['M0']; dx = float(z['dx'])
            if (u.ndim == 5 and u.shape[0] == len(ICS)
                    and u.shape[1] == 32 and u.shape[-1] == 3
                    and np.all(np.isfinite(u)) and np.all(np.isfinite(p))):
                t_ck = float(os.path.basename(fn).split('_t')[1][:-4])
                out.append((t_ck, u, p, M0, dx))
        except Exception:
            pass
    out.sort(key=lambda f_: f_[0])
    return out

fields = valid_checkpoints()
if len(fields) >= 3:
    print(f'using {len(fields)} validated persisted checkpoint(s)')
else:
    print(f'{len(fields)} valid checkpoint(s) — running the PERSIST arm '
          f'in-cell (32^3, dt={DT_RUN}, T={T_H})...')
    STEPS = int(round(T_H/DT_RUN))
    fac = make_persist_factory(32, DT_RUN, WARM_CYCLES)
    body = fac['body']; carry = fac['carry0']
    xs = jnp.asarray(np.full(STEPS, 1.0, dtype=np.float64))
    t0 = time.time(); done = 0; fields = []
    while done < STEPS:
        ln = min(CHUNK, STEPS - done)
        carry, out = lax.scan(body, carry, xs=xs[done:done + ln])
        done += ln
        if done in CKPTS or done == STEPS:
            u_ck = np.array(carry[0], dtype=np.float64)
            p_ck = np.array(carry[1], dtype=np.float64)
            fields.append((done*DT_RUN, u_ck, p_ck, fac['M0'], fac['dx']))
            np.savez(os.path.join(SAVE_DIR,
                                  f'v295f_fields_t{done*DT_RUN:.1f}.npz'),
                     u=u_ck, p=p_ck, M0=fac['M0'], dx=fac['dx'])
            Em_ck = 0.25*fac['dx']**3*np.sum((u_ck + p_ck)**2,
                                             axis=(1, 2, 3, 4))
            Ed_ck = 0.25*fac['dx']**3*np.sum((u_ck - p_ck)**2,
                                             axis=(1, 2, 3, 4))
            msg = '  '.join(
                f'{nm}:Em%={100*Em_ck[ci]/fac["Em0"][ci]:.0f}'
                f',Ed%={100*Ed_ck[ci]/fac["Ed0"][ci]:.0f}'
                for ci, nm in enumerate(ICS))
            print(f'    checkpoint t={done*DT_RUN:.2f}  '
                  f'({time.time()-t0:6.0f}s)  {msg}')
    print(f'  run complete: {time.time()-t0:.0f}s\n')

