CLUSTER = {'1/phi^2': 0.38197, 'K41': 0.39685, 'eps^(1/3)': 0.40142}

def block_avg(F, k):
    if k == 0:
        return F
    C, n = F.shape[0], F.shape[1]; b = 2**k
    return F.reshape(C, n//b, b, n//b, b, n//b, b, 3).mean(axis=(2, 4, 6))

def band_rms(F):
    lv = [F] + [block_avg(F, k) for k in range(1, 5)]
    L = [np.sum(l**2, axis=(1, 2, 3, 4)) for l in lv]
    S = np.stack([8.0**(k-1)*L[k-1] - 8.0**k*L[k] for k in range(1, 5)])
    Sres = 8.0**4*L[4]
    n = F.shape[1]
    return np.concatenate([np.sqrt(np.maximum(S, 0))/n**1.5,
                           np.sqrt(np.maximum(Sres, 0))[None]/n**1.5],
                          axis=0)          # (5, C) band rms per rung

files = sorted(glob.glob(os.path.join(SAVE_DIR, 'v295f_fields_t*.npz')))
assert files, 'run V29.5f first (it persists the checkpoint fields)'
fields = []
for fn in files:
    z = np.load(fn)
    fields.append((float(os.path.basename(fn).split('_t')[1][:-4]),
                   z['u'], z['p']))
fields.sort(key=lambda f: f[0])
NU = 1e-4; dx = 2*np.pi/32
