print('     boundary rungs excluded: finest = small-sample/debris,')
print('     last = scale-label defect, content pi labeled 2pi)\n')
chains_t = {}
for (t_ck, u, p) in fields:
    for chan, F in (('m', u + p), ('d', 0.5*(u - p))):
        u_l = band_rms(F)
        Re = u_l*np.array([2.0, 4.0, 8.0, 16.0, 16.0])[:, None]*dx/NU
        chain = Re[:-1, :]/np.maximum(Re[1:, :], 1e-30)
        chains_t.setdefault((chan, t_ck), chain)
        for ci, nm in enumerate(ICS):
            print(f'  t={t_ck:.1f} [{chan} {nm:6s}] interior: '
                  f'{chain[1, ci]:.3f} {chain[2, ci]:.3f}   '
                  f'(boundary, corrected last: {2*chain[3, ci]:.3f})')
