import os
import time
import numpy as np
import matplotlib.pyplot as plt

import jax
jax.config.update("jax_enable_x64", True)
import jax.numpy as jnp
from jax import lax

print('JAX version:', jax.__version__)
print('backend devices:', jax.devices())
IS_GPU = 'gpu' in str(jax.devices()[0]).lower()
print('backend: CUDA GPU' if IS_GPU else 'backend: CPU')

np.set_printoptions(precision=6, suppress=True)
L_dom = 2.0*np.pi; L_half = L_dom/2.0
NU_TEST = 0.0001
WARM_CYCLES = 8; INIT_CYCLES = 20
DT_RUN = 0.004
T_H = 3.0
CHUNK = 150
A_SWIRL = 6.0; PHI = 0.5*(1.0 + np.sqrt(5.0)); W_GOLD = 12.0/PHI
SIGMA_IC = 1.0; A_WIND = 0.35
ICS = ['tubes', 'wound']
GAIN = 10.0; THRESH_FRAC = 0.5
GAMMA_CONTRACT = 0.5
SAVE_DIR = '/content/v30_results'; os.makedirs(SAVE_DIR, exist_ok=True)
CKPTS = [150, 300, 450, 600, 750]
THETA_N = 11221.0/8214.0            # 78.27 deg — the LOCK quantum

# ---- ICs (proven) ----
def np_mesh(n):
    x = np.linspace(0.0, L_dom, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), L_dom/n
def np_dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis))*(0.5/dx)
def ic_tubes(axes, strength=8.0, sigma=0.8, sep=1.6, tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt); st = np.sin(tilt)
    def tube(cx, sign):
        dx_ = (x - cx + L_half) % L_dom - L_half
        dy_ = (y - np.pi + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        r2 = dx_t*dx_t + dy_*dy_
        f = np.exp(-r2/(2.0*sigma*sigma))
        return np.stack([-sign*strength*dy_*f,
                         sign*strength*dx_t*f, np.zeros_like(x)], axis=-1)
    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)
def ic_wound(axes):
    x, y, z = axes
    xc = np.pi + A_WIND*np.sin(z)
    yc = np.pi + A_WIND*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA_IC*SIGMA_IC))
    return np.stack([-A_SWIRL*ry*f, A_SWIRL*rx*f, W_GOLD*f], axis=-1)
def build_ics_np(n):
    axes, dx = np_mesh(n)
    return {'tubes': ic_tubes(axes), 'wound': ic_wound(axes)}, dx

# ---- JAX core (proven, verbatim) ----
def jdd(f, axis, dx):
    return (jnp.roll(f, -1, axis=axis) - jnp.roll(f, 1, axis=axis))*(0.5/dx)
def jnth_jacobian(u, dx):
    gu = []
    for i in range(3):
        for j in range(3):
            gu.append(jdd(u[..., i], j + 1, dx))
    G = jnp.stack(gu, axis=-1).reshape(u.shape[0], u.shape[1],
                                       u.shape[1], u.shape[1], 3, 3)
    S = 0.5*(G + jnp.swapaxes(G, -1, -2))
    C1 = jnp.sqrt(jnp.sum(S*S, axis=(-2, -1)))
    A_ = 0.5*(G - jnp.swapaxes(G, -1, -2))
    C2 = jnp.sqrt(jnp.sum(A_*A_, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    return G, C1, C2, R, C1 + C2 + jnp.abs(R)
def jlap(u, dx):
    inv = 1.0/(dx*dx)
    out = -6.0*u
    for a in (1, 2, 3):
        out = out + jnp.roll(u, -1, axis=a) + jnp.roll(u, 1, axis=a)
    return out*inv
def jadvect(f, v, dx):
    parts = []
    for i in range(3):
        fi = f[..., i]
        acc = jnp.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc = acc + 0.5*(jdd(vj*fi, j + 1, dx) + vj*jdd(fi, j + 1, dx))
        parts.append(acc)
    return jnp.stack(parts, axis=-1)
def jaxis_dominant(C1, C2, G, dx):
    rot_dom = C2 > C1
    w0 = G[..., 2, 1] - G[..., 1, 2]
    w1 = G[..., 0, 2] - G[..., 2, 0]
    w2 = G[..., 1, 0] - G[..., 0, 1]
    wn = jnp.sqrt(w0*w0 + w1*w1 + w2*w2)
    gs0 = jdd(C1, 1, dx); gs1 = jdd(C1, 2, dx); gs2 = jdd(C1, 3, dx)
    gn = jnp.sqrt(gs0*gs0 + gs1*gs1 + gs2*gs2)
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    ax_v = jnp.stack([w0, w1, w2], axis=-1) \
        / jnp.maximum(wn, 1e-30)[..., None]
    ax_g = jnp.stack([gs0, gs1, gs2], axis=-1) \
        / jnp.maximum(gn, 1e-30)[..., None]
    return jnp.where(use_v[..., None], ax_v,
                     jnp.where(use_g[..., None], ax_g,
                               jnp.zeros_like(ax_v)))
def jrestrict(F):
    classes = []
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                classes.append(F[:, a::2, b::2, d_::2])
    return jnp.stack(classes, axis=1)
def jmerge(G8, n):
    out = jnp.zeros((G8.shape[0], n, n, n), dtype=G8.dtype)
    idx = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out = out.at[:, a::2, b::2, d_::2].set(G8[:, idx])
                idx += 1
    return out
def jrestrict_fw(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))
def j_interp1(F, axis):
    n = F.shape[axis]
    odd = 0.5*(F + jnp.roll(F, -1, axis=axis))
    out = jnp.stack([F, odd], axis=axis + 1)
    shp = list(F.shape); shp[axis] = 2*n
    return out.reshape(shp)
def jprolong(C):
    F = j_interp1(C, C.ndim - 3)
    F = j_interp1(F, F.ndim - 2)
    F = j_interp1(F, F.ndim - 1)
    return F
def jdiv_bundle(V, dx):
    return jdd(V[..., 0], 1, dx) + jdd(V[..., 1], 2, dx) \
        + jdd(V[..., 2], 3, dx)
def jgrad_bundle(phi, dx):
    return jnp.stack([jdd(phi, 1, dx), jdd(phi, 2, dx),
                      jdd(phi, 3, dx)], axis=-1)
def jlap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    nd = F.ndim
    for a in (nd - 3, nd - 2, nd - 1):
        s = s + jnp.roll(F, -1, axis=a) + jnp.roll(F, 1, axis=a)
    return s*inv
def jsmooth_gs(phi, f, dx, iters):
    cc = dx*dx/6.0
    m = phi.shape[-1]
    idx = jnp.indices((m, m, m))
    parity = (idx[0] + idx[1] + idx[2]) % 2
    red = (parity == 0); black = (parity == 1)
    def body(i, phi_):
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(red, r, 0.0)
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(black, r, 0.0)
        return phi_
    return lax.fori_loop(0, iters, body, phi)
def jv_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - jnp.mean(f, axis=(-3, -2, -1), keepdims=True)
        return jsmooth_gs(phi, f, dx, 40)
    phi = jsmooth_gs(phi, f, dx, 2)
    r = f - jlap_apply(phi, dx)
    rc = jrestrict_fw(r)
    ec = jv_cycle(jnp.zeros_like(rc), rc, 2.0*dx)
    phi = phi + jprolong(ec)
    return jsmooth_gs(phi, f, dx, 2)
def _project_warm(Vch, psic0, dx, cycles):
    f = -jdiv_bundle(Vch, dx)
    fc = jrestrict(f)
    H = 2.0*dx
    fc = fc - jnp.mean(fc, axis=(-3, -2, -1), keepdims=True)
    psic = psic0 - jnp.mean(psic0, axis=(-3, -2, -1), keepdims=True)
    def cycle_body(i, psi):
        return jv_cycle(psi, fc, H)
    psic = lax.fori_loop(0, cycles, cycle_body, psic)
    psic = psic - jnp.mean(psic, axis=(-3, -2, -1), keepdims=True)
    resid = jnp.max(jnp.abs(fc - jlap_apply(psic, H))) \
        / (jnp.max(jnp.abs(fc)) + 1e-30)
    phi_full = jmerge(psic, Vch.shape[1])
    return Vch + jgrad_bundle(phi_full, dx), psic, resid

# =============================================================================
# THE ARM OPERATOR ([30]-redesigned): §3's two arms — magnitude decay +
# phase orbit. EXACT identity at unrouted points (selectivity measurable).
# =============================================================================
def _arm(u_s, p_s, G, C1, C2, tension, dx, thr, mode):
    """mode: 'gain' (tension-driven Cayley angle), 'lock' (theta_n cap),
    'rho' (Gaussian resonance gate on the routed population)."""
    Cb = u_s.shape[0]
    thr_ = thr[:, None, None, None]
    base = tension > thr_
    if mode == 'rho':
        cnt = jnp.sum(base, axis=(1, 2, 3))
        tsum = jnp.sum(jnp.where(base, tension, 0.0), axis=(1, 2, 3))
        tmean = tsum/jnp.maximum(cnt, 1.0)
        dev = tension - tmean[:, None, None, None]
        dev2 = jnp.sum(jnp.where(base, dev*dev, 0.0), axis=(1, 2, 3))
        sig = jnp.sqrt(dev2/jnp.maximum(cnt, 1.0))
        rho = jnp.exp(-dev**2
                      / (2.0*jnp.maximum(sig, 1e-30)[:, None, None,
                                                     None]**2))
        routed = base & (rho > 0.5)
    else:
        routed = base
    m = u_s + p_s
    d = 0.5*(u_s - p_s)
    axis = jaxis_dominant(C1, C2, G, dx)
    dpar = jnp.sum(axis*d, axis=-1)[..., None]*axis
    d_tr = d - dpar
    gam = jnp.where(routed, GAMMA_CONTRACT, 1.0)
    if mode == 'lock':
        t_par = jnp.where(routed, jnp.tan(0.5*THETA_N), 0.0)
    else:
        excess = jnp.maximum(tension - thr_, 0.0)
        g = GAIN*excess*dx
        t_par = jnp.where(routed, g/(1.0 + g), 0.0)
    c_ = (1.0 - t_par*t_par)/(1.0 + t_par*t_par)
    s_ = (2.0*t_par)/(1.0 + t_par*t_par)
    rot = c_[..., None]*d_tr + s_[..., None]*jnp.cross(axis, d_tr)
    d_new = dpar + gam[..., None]*rot
    u_t = 0.5*m + d_new
    p_t = 0.5*m - d_new
    ncells = float(np.prod(tension.shape[1:]))
    frac = jnp.sum(routed, axis=(1, 2, 3))/ncells
    return u_t, p_t, frac

# =============================================================================
# ARM FACTORY ([35]: carrier = m — the attribution theorem restored)
# =============================================================================
def make_arm_factory(n, dt, cycles, mode, nu_val=NU_TEST):
    ics, dx = build_ics_np(n)
    C = len(ICS)
    U0 = np.stack([ics[nm] for nm in ICS])
    Us0 = jnp.asarray(np.concatenate([U0, np.zeros_like(U0)], axis=0))
    psic0 = jnp.zeros((2*C, 8, n//2, n//2, n//2))
    Us0, psic0, _ = _project_warm(Us0, psic0, dx, INIT_CYCLES)
    U0j, P0j = Us0[:C], Us0[C:]
    _, _, _, _, t0_ = jnth_jacobian(U0j, dx)
    M0 = np.asarray(jnp.max(t0_.reshape(C, -1), axis=1))
    THR = jnp.asarray(THRESH_FRAC*M0)
    nu = jnp.asarray(np.broadcast_to(np.asarray(nu_val, dtype=np.float64),
                                     (C,)))
    nu_ = nu[:, None, None, None, None]
    vol = dx**3
    Eu0 = np.asarray(0.5*vol*jnp.sum(U0j*U0j, axis=(1, 2, 3, 4)))
    Ep0 = np.asarray(0.5*vol*jnp.sum(P0j*P0j, axis=(1, 2, 3, 4)))

    def step(u, p, psic):
        Cb = u.shape[0]
        G_u, C1_u, C2_u, R_u, tension_u = jnth_jacobian(u, dx)
        Mk_u = jnp.max(tension_u.reshape(Cb, -1), axis=1)
        m = u + p
        Eu_start = 0.5*vol*jnp.sum(u*u, axis=(1, 2, 3, 4))
        Ep_start = 0.5*vol*jnp.sum(p*p, axis=(1, 2, 3, 4))
        au1 = jadvect(u, m, dx); ap1 = jadvect(p, m, dx)
        Lu = jlap(u, dx); Lp = jlap(p, dx)
        u_star = u + dt*(-au1 + nu_*Lu)
        p_star = p + dt*(-ap1 + nu_*Lp)
        m_star = u_star + p_star
        au2 = jadvect(u_star, m_star, dx)
        ap2 = jadvect(p_star, m_star, dx)
        u_s = u + 0.5*dt*(-(au1 + au2) + nu_*(Lu + jlap(u_star, dx)))
        p_s = p + 0.5*dt*(-(ap1 + ap2) + nu_*(Lp + jlap(p_star, dx)))
        Eu_pre = 0.5*vol*jnp.sum(u_s*u_s, axis=(1, 2, 3, 4))
        Ep_pre = 0.5*vol*jnp.sum(p_s*p_s, axis=(1, 2, 3, 4))
        if mode == 'classical':
            u_t, p_t = u_s, p_s
            frac = jnp.zeros(Cb)
        else:
            u_t, p_t, frac = _arm(u_s, p_s, G_u, C1_u, C2_u, tension_u,
                                   dx, THR, mode)
        Eu_post = 0.5*vol*jnp.sum(u_t*u_t, axis=(1, 2, 3, 4))
        Ep_post = 0.5*vol*jnp.sum(p_t*p_t, axis=(1, 2, 3, 4))
        Usp = jnp.concatenate([u_t, p_t], axis=0)
        Unew, psic_n, _ = _project_warm(Usp, psic, dx, cycles)
        u_new = Unew[:Cb]; p_new = Unew[Cb:]
        Eu_new = 0.5*vol*jnp.sum(u_new*u_new, axis=(1, 2, 3, 4))
        Ep_new = 0.5*vol*jnp.sum(p_new*p_new, axis=(1, 2, 3, 4))
        w0 = jdd(u_new[..., 2], 2, dx) - jdd(u_new[..., 1], 3, dx)
        w1 = jdd(u_new[..., 0], 3, dx) - jdd(u_new[..., 2], 1, dx)
        w2 = jdd(u_new[..., 1], 1, dx) - jdd(u_new[..., 0], 2, dx)
        maxw = jnp.max(jnp.sqrt(w0*w0 + w1*w1 + w2*w2), axis=(1, 2, 3))
        maxu = jnp.max(jnp.sqrt(jnp.sum(u_new*u_new, axis=-1)),
                       axis=(1, 2, 3))
        return (u_new, p_new, psic_n), \
            (Mk_u, Eu_new, Ep_new,
             Eu_pre - Eu_start, Eu_post - Eu_pre, Eu_new - Eu_post,
             Ep_pre - Ep_start, Ep_post - Ep_pre, Ep_new - Ep_post,
             maxu, maxw, frac)

    def body(carry, _):
        u, p, psic, Su = carry
        (u, p, psic), out = step(u, p, psic)
        return (u, p, psic, Su + out[0]*dt), out

    carry0 = (U0j, P0j, psic0, jnp.zeros(C))
    return dict(body=body, carry0=carry0, dx=dx, Eu0=Eu0, Ep0=Ep0,
                M0=M0, THR=np.asarray(THR), C=C, n=n, dt=dt)

SERIES = ['Mk_u', 'Eu', 'Ep', 'h_u', 'a_u', 't_u',
          'h_p', 'a_p', 't_p', 'maxu', 'maxw', 'frac']

def run_arm(tag, mode, nu_val=NU_TEST):
    fac = make_arm_factory(32, DT_RUN, WARM_CYCLES, mode, nu_val)
    body = fac['body']; carry = fac['carry0']
    dx = fac['dx']; C = fac['C']
    STEPS = int(round(T_H/DT_RUN))
    print(f'  [{tag:12s}] mode={mode:9s} steps={STEPS}  T={STEPS*DT_RUN}')
    parts = []; t0 = time.time(); done = 0; ck = []
    while done < STEPS:
        ln = min(CHUNK, STEPS - done)
        carry, out = lax.scan(body, carry, xs=None, length=ln)
        parts.append([np.asarray(x) for x in out])
        done += ln
        if done in CKPTS or done == STEPS:
            ck.append((done*DT_RUN, np.array(carry[0]),
                       np.array(carry[1])))
            Eu_ck = 0.5*dx**3*np.sum(ck[-1][1]**2, axis=(1, 2, 3, 4))
            Ep_ck = 0.5*dx**3*np.sum(ck[-1][2]**2, axis=(1, 2, 3, 4))
            msg = '  '.join(
                f'{nm}:Eu%={100*Eu_ck[ci]/fac["Eu0"][ci]:.0f}'
                f',Ep%={100*Ep_ck[ci]/max(fac["Ep0"][ci], 1e-30):.0f}'
                for ci, nm in enumerate(ICS))
            print(f'    t={done*DT_RUN:5.2f}  ({time.time()-t0:6.0f}s)  '
                  f'{msg}')
    cols = [np.concatenate([p_[i] for p_ in parts], axis=0)
            for i in range(len(SERIES))]
    series = dict(zip(SERIES, cols))
    for k, v in series.items():
        assert v.ndim == 2 and v.shape == (STEPS, C) \
            and np.all(np.isfinite(v)), f'series {k}: {v.shape}'
    # [31] exact ledger: Eu(T)-Eu0 = cum(h_u)+cum(a_u)+cum(t_u)
    for ci, nm in enumerate(ICS):
        su = (np.cumsum(series['h_u'][:, ci])
              + np.cumsum(series['a_u'][:, ci])
              + np.cumsum(series['t_u'][:, ci]))[-1]
        sp = (np.cumsum(series['h_p'][:, ci])
              + np.cumsum(series['a_p'][:, ci])
              + np.cumsum(series['t_p'][:, ci]))[-1]
        e_u = abs((series['Eu'][-1, ci] - fac['Eu0'][ci]) - su) \
            / max(abs(fac['Eu0'][ci]), 1e-30)
        dpn = max(abs(fac['Ep0'][ci]),
                  1e-30) if fac['Ep0'][ci] > 1e-9*fac['Eu0'][ci] \
            else max(abs(fac['Eu0'][ci]), 1e-30)
        e_p = abs((series['Ep'][-1, ci] - fac['Ep0'][ci]) - sp)/dpn
        print(f'    ledger [{nm}]: u {e_u:.2e}  p {e_p:.2e}')
        assert e_u < 1e-10 and e_p < 1e-10, \
            f'ledger broken {tag}/{nm}: {e_u:.2e} {e_p:.2e}'
    save = {k: v for k, v in series.items()}
    save.update({'Eu0': fac['Eu0'], 'Ep0': fac['Ep0'], 'M0': fac['M0']})
    for (t_ck, u_ck, p_ck) in ck:
        ti = int(round(t_ck*10))
        save[f'u_t{ti}'] = u_ck
        save[f'p_t{ti}'] = p_ck
    np.savez(os.path.join(SAVE_DIR, f'v301_{tag}.npz'), **save)
    return dict(tag=tag, mode=mode, dx=dx, dt=DT_RUN, steps=STEPS,
                Eu0=fac['Eu0'], Ep0=fac['Ep0'], M0=fac['M0'],
                THR=fac['THR'], series=series, ck=ck,
                wall=time.time() - t0)

