# unchanged after this cell (it reads TR/DT_TR only).
# =============================================================================
import os
import time
import numpy as np
import matplotlib.pyplot as plt

import jax
jax.config.update("jax_enable_x64", True)
import jax.numpy as jnp
from jax import lax

print('JAX version:', jax.__version__)
print('backend devices:', jax.devices())
IS_GPU = 'gpu' in str(jax.devices()[0]).lower()
print('backend: CUDA GPU' if IS_GPU else 'backend: CPU')

np.set_printoptions(precision=6, suppress=True)
L_dom = 2.0*np.pi; L_half = L_dom/2.0
NU_TEST = 0.0001
WARM_CYCLES = 8; INIT_CYCLES = 20
DT_RUN = 0.004
T_H = 3.0
SAVE_EVERY = 15
CHUNK = 150
A_SWIRL = 6.0; PHI = 0.5*(1.0 + np.sqrt(5.0)); W_GOLD = 12.0/PHI
SIGMA_IC = 1.0; A_WIND = 0.35
ICS = ['tubes', 'wound']
GAIN = 10.0; THRESH_FRAC = 0.5
GAMMA_CONTRACT = 0.5
SAVE_DIR = '/content/v31l_results'; os.makedirs(SAVE_DIR, exist_ok=True)

# ---- ICs (proven) ----
def np_mesh(n):
    x = np.linspace(0.0, L_dom, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), L_dom/n
def np_dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis))*(0.5/dx)
def ic_tubes(axes, strength=8.0, sigma=0.8, sep=1.6, tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt); st = np.sin(tilt)
    def tube(cx, sign):
        dx_ = (x - cx + L_half) % L_dom - L_half
        dy_ = (y - np.pi + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        r2 = dx_t*dx_t + dy_*dy_
        f = np.exp(-r2/(2.0*sigma*sigma))
        return np.stack([-sign*strength*dy_*f,
                         sign*strength*dx_t*f, np.zeros_like(x)], axis=-1)
    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)
def ic_wound(axes):
    x, y, z = axes
    xc = np.pi + A_WIND*np.sin(z)
    yc = np.pi + A_WIND*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA_IC*SIGMA_IC))
    return np.stack([-A_SWIRL*ry*f, A_SWIRL*rx*f, W_GOLD*f], axis=-1)
def build_ics_np(n):
    axes, dx = np_mesh(n)
    return {'tubes': ic_tubes(axes), 'wound': ic_wound(axes)}, dx

# ---- JAX core (proven, verbatim) ----
def jdd(f, axis, dx):
    return (jnp.roll(f, -1, axis=axis) - jnp.roll(f, 1, axis=axis))*(0.5/dx)
def jnth_jacobian(u, dx):
    gu = []
    for i in range(3):
        for j in range(3):
            gu.append(jdd(u[..., i], j + 1, dx))
    G = jnp.stack(gu, axis=-1).reshape(u.shape[0], u.shape[1],
                                       u.shape[1], u.shape[1], 3, 3)
    S = 0.5*(G + jnp.swapaxes(G, -1, -2))
    C1 = jnp.sqrt(jnp.sum(S*S, axis=(-2, -1)))
    A_ = 0.5*(G - jnp.swapaxes(G, -1, -2))
    C2 = jnp.sqrt(jnp.sum(A_*A_, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    return G, C1, C2, R, C1 + C2 + jnp.abs(R)
def jlap(u, dx):
    inv = 1.0/(dx*dx)
    out = -6.0*u
    for a in (1, 2, 3):
        out = out + jnp.roll(u, -1, axis=a) + jnp.roll(u, 1, axis=a)
    return out*inv
def jadvect(f, v, dx):
    parts = []
    for i in range(3):
        fi = f[..., i]
        acc = jnp.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc = acc + 0.5*(jdd(vj*fi, j + 1, dx) + vj*jdd(fi, j + 1, dx))
        parts.append(acc)
    return jnp.stack(parts, axis=-1)
def jaxis_dominant(C1, C2, G, dx):
    rot_dom = C2 > C1
    w0 = G[..., 2, 1] - G[..., 1, 2]
    w1 = G[..., 0, 2] - G[..., 2, 0]
    w2 = G[..., 1, 0] - G[..., 0, 1]
    wn = jnp.sqrt(w0*w0 + w1*w1 + w2*w2)
    gs0 = jdd(C1, 1, dx); gs1 = jdd(C1, 2, dx); gs2 = jdd(C1, 3, dx)
    gn = jnp.sqrt(gs0*gs0 + gs1*gs1 + gs2*gs2)
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    ax_v = jnp.stack([w0, w1, w2], axis=-1) \
        / jnp.maximum(wn, 1e-30)[..., None]
    ax_g = jnp.stack([gs0, gs1, gs2], axis=-1) \
        / jnp.maximum(gn, 1e-30)[..., None]
    return jnp.where(use_v[..., None], ax_v,
                     jnp.where(use_g[..., None], ax_g,
                               jnp.zeros_like(ax_v)))
def jrestrict(F):
    classes = []
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                classes.append(F[:, a::2, b::2, d_::2])
    return jnp.stack(classes, axis=1)
def jmerge(G8, n):
    out = jnp.zeros((G8.shape[0], n, n, n), dtype=G8.dtype)
    idx = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out = out.at[:, a::2, b::2, d_::2].set(G8[:, idx])
                idx += 1
    return out
def jrestrict_fw(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))
def j_interp1(F, axis):
    n = F.shape[axis]
    odd = 0.5*(F + jnp.roll(F, -1, axis=axis))
    out = jnp.stack([F, odd], axis=axis + 1)
    shp = list(F.shape); shp[axis] = 2*n
    return out.reshape(shp)
def jprolong(C):
    F = j_interp1(C, C.ndim - 3)
    F = j_interp1(F, F.ndim - 2)
    F = j_interp1(F, F.ndim - 1)
    return F
def jdiv_bundle(V, dx):
    return jdd(V[..., 0], 1, dx) + jdd(V[..., 1], 2, dx) \
        + jdd(V[..., 2], 3, dx)
def jgrad_bundle(phi, dx):
    return jnp.stack([jdd(phi, 1, dx), jdd(phi, 2, dx),
                      jdd(phi, 3, dx)], axis=-1)
def jlap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    nd = F.ndim
    for a in (nd - 3, nd - 2, nd - 1):
        s = s + jnp.roll(F, -1, axis=a) + jnp.roll(F, 1, axis=a)
    return s*inv
def jsmooth_gs(phi, f, dx, iters):
    cc = dx*dx/6.0
    m = phi.shape[-1]
    idx = jnp.indices((m, m, m))
    parity = (idx[0] + idx[1] + idx[2]) % 2
    red = (parity == 0); black = (parity == 1)
    def body(i, phi_):
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(red, r, 0.0)
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(black, r, 0.0)
        return phi_
    return lax.fori_loop(0, iters, body, phi)
def jv_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - jnp.mean(f, axis=(-3, -2, -1), keepdims=True)
        return jsmooth_gs(phi, f, dx, 40)
    phi = jsmooth_gs(phi, f, dx, 2)
    r = f - jlap_apply(phi, dx)
    rc = jrestrict_fw(r)
    ec = jv_cycle(jnp.zeros_like(rc), rc, 2.0*dx)
    phi = phi + jprolong(ec)
    return jsmooth_gs(phi, f, dx, 2)
def _project_warm(Vch, psic0, dx, cycles):
    f = -jdiv_bundle(Vch, dx)
    fc = jrestrict(f)
    H = 2.0*dx
    fc = fc - jnp.mean(fc, axis=(-3, -2, -1), keepdims=True)
    psic = psic0 - jnp.mean(psic0, axis=(-3, -2, -1), keepdims=True)
    def cycle_body(i, psi):
        return jv_cycle(psi, fc, H)
    psic = lax.fori_loop(0, cycles, cycle_body, psic)
    psic = psic - jnp.mean(psic, axis=(-3, -2, -1), keepdims=True)
    resid = jnp.max(jnp.abs(fc - jlap_apply(psic, H))) \
        / (jnp.max(jnp.abs(fc)) + 1e-30)
    phi_full = jmerge(psic, Vch.shape[1])
    return Vch + jgrad_bundle(phi_full, dx), psic, resid

def _arm(u_s, p_s, G, C1, C2, tension, dx, thr):
    thr_ = thr[:, None, None, None]
    routed = tension > thr_
    m = u_s + p_s
    d = 0.5*(u_s - p_s)
    axis = jaxis_dominant(C1, C2, G, dx)
    dpar = jnp.sum(axis*d, axis=-1)[..., None]*axis
    d_tr = d - dpar
    gam = jnp.where(routed, GAMMA_CONTRACT, 1.0)
    excess = jnp.maximum(tension - thr_, 0.0)
    g = GAIN*excess*dx
    t_par = jnp.where(routed, g/(1.0 + g), 0.0)
    c_ = (1.0 - t_par*t_par)/(1.0 + t_par*t_par)
    s_ = (2.0*t_par)/(1.0 + t_par*t_par)
    rot = c_[..., None]*d_tr + s_[..., None]*jnp.cross(axis, d_tr)
    d_new = dpar + gam[..., None]*rot
    return 0.5*m + d_new, 0.5*m - d_new

def make_arm_factory(n, dt, cycles, mode):
    ics, dx = build_ics_np(n)
    C = len(ICS)
    U0 = np.stack([ics[nm] for nm in ICS])
    Us0 = jnp.asarray(np.concatenate([U0, np.zeros_like(U0)], axis=0))
    psic0 = jnp.zeros((2*C, 8, n//2, n//2, n//2))
    Us0, psic0, _ = _project_warm(Us0, psic0, dx, INIT_CYCLES)
    U0j, P0j = Us0[:C], Us0[C:]
    _, _, _, _, t0_ = jnth_jacobian(U0j, dx)
    M0 = np.asarray(jnp.max(t0_.reshape(C, -1), axis=1))
    THR = jnp.asarray(THRESH_FRAC*M0)
    nu = jnp.asarray(np.full(C, NU_TEST, dtype=np.float64))
    nu_ = nu[:, None, None, None, None]

    def step(u, p, psic):
        Cb = u.shape[0]
        G_u, C1_u, C2_u, R_u, tension_u = jnth_jacobian(u, dx)
        m = u + p
        au1 = jadvect(u, m, dx); ap1 = jadvect(p, m, dx)
        Lu = jlap(u, dx); Lp = jlap(p, dx)
        u_star = u + dt*(-au1 + nu_*Lu)
        p_star = p + dt*(-ap1 + nu_*Lp)
        m_star = u_star + p_star
        au2 = jadvect(u_star, m_star, dx)
        ap2 = jadvect(p_star, m_star, dx)
        u_s = u + 0.5*dt*(-(au1 + au2) + nu_*(Lu + jlap(u_star, dx)))
        p_s = p + 0.5*dt*(-(ap1 + ap2) + nu_*(Lp + jlap(p_star, dx)))
        if mode == 'classical':
            u_t, p_t = u_s, p_s
        else:
            u_t, p_t = _arm(u_s, p_s, G_u, C1_u, C2_u, tension_u,
                            dx, THR)
        Usp = jnp.concatenate([u_t, p_t], axis=0)
        Unew, psic_n, _ = _project_warm(Usp, psic, dx, cycles)
        return (Unew[:Cb], Unew[Cb:], psic_n)

    def body(carry, _):
        u, p, psic = carry
        u, p, psic = step(u, p, psic)
        return (u, p, psic), None

    return dict(body=body, carry0=(U0j, P0j, psic0), dx=dx, M0=M0,
                THR=np.asarray(THR), C=C, n=n, dt=dt)

def run_dense(tag, mode):
    fac = make_arm_factory(32, DT_RUN, WARM_CYCLES, mode)
    body = fac['body']; carry = fac['carry0']
    STEPS = int(round(T_H/DT_RUN))
    n_blocks = STEPS//SAVE_EVERY
    print(f'  [{tag}] dense-save run: steps={STEPS}, save every '
          f'{SAVE_EVERY} ({n_blocks} snapshots)')
    snaps = [np.array(fac['carry0'][0])]
    times = [0.0]
    t0 = time.time()
    for b_ in range(n_blocks):
        carry, _ = lax.scan(body, carry, xs=None, length=SAVE_EVERY)
        snaps.append(np.array(carry[0]))
        times.append((b_ + 1)*SAVE_EVERY*DT_RUN)
        if (b_ + 1) % 50 == 0:
            print(f'    t={times[-1]:5.2f}  ({time.time()-t0:5.0f}s)')
    print(f'    done: {len(snaps)} snapshots, {time.time()-t0:.0f}s')
    np.savez(os.path.join(SAVE_DIR, f'v31lc_{tag}.npz'),
             **{f'u_{i_}': s_ for i_, s_ in enumerate(snaps)},
             times=np.array(times), M0=fac['M0'], THR=fac['THR'],
             dx=fac['dx'])
    return dict(tag=tag, mode=mode, snaps=snaps, times=np.array(times),
                dx=fac['dx'], M0=fac['M0'], THR=fac['THR'], C=fac['C'])

# =============================================================================
# TRACER MACHINERY ([49]-fixed: ci channel slicing; asserted contracts)
# =============================================================================
def cell_index(pos, dx, n):
    """Boundary-safe cell index for positions in [0, L_dom)."""
    c = (pos/dx).astype(int)
    return np.clip((c % n), 0, n - 1)

def interp_field(F, pos_grid, n):
    """Trilinear periodic interpolation. CONTRACT: F is UNBATCHED
    (n,n,n,3); pos_grid (M,3) in grid units. All corner indices wrapped
    mod n. ([49]: callers slice the IC channel BEFORE calling.)"""
    assert F.ndim == 4 and F.shape[:3] == (n, n, n), \
        f'interp_field contract: got {F.shape}, want (n,n,n,3)'
    p = pos_grid % n
    i0 = np.floor(p).astype(int)
    f = p - i0
    out = np.zeros((p.shape[0], 3))
    for dx_, fx in ((0, 1 - f[:, 0]), (1, f[:, 0])):
        for dy_, fy in ((0, 1 - f[:, 1]), (1, f[:, 1])):
            for dz_, fz in ((0, 1 - f[:, 2]), (1, f[:, 2])):
                w = fx*fy*fz
                ii = (i0[:, 0] + dx_) % n
                jj = (i0[:, 1] + dy_) % n
                kk = (i0[:, 2] + dz_) % n
                out += w[:, None]*F[ii, jj, kk, :]
    return out

def velocity_at(run, t, pos, ci):
    """Velocity at global time t, IC channel ci. Snapshots are BATCHED
    (C,n,n,n,3); the channel is sliced before interpolation ([49])."""
    ts = run['times']; n = run['snaps'][0].shape[1]
    k = int(np.searchsorted(ts, t, side='right')) - 1
    k = max(0, min(k, len(ts) - 2))
    a = (t - ts[k])/max(ts[k + 1] - ts[k], 1e-30)
    a = max(0.0, min(1.0, a))
    grid_pos = pos/(2.0*np.pi/n)
    v0 = interp_field(run['snaps'][k][ci], grid_pos, n)
    v1 = interp_field(run['snaps'][k + 1][ci], grid_pos, n)
    return (1 - a)*v0 + a*v1

def tension_at_grid(u, dx):
    C, n = u.shape[0], u.shape[1]
    G = np.empty((C, n, n, n, 3, 3))
    for i in range(3):
        for j in range(3):
            G[..., i, j] = np_dd(u[..., i], j + 1, dx)
    S = 0.5*(G + np.swapaxes(G, -1, -2))
    A_ = 0.5*(G - np.swapaxes(G, -1, -2))
    C1 = np.sqrt(np.sum(S*S, axis=(-2, -1)))
    C2 = np.sqrt(np.sum(A_*A_, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    return C1 + C2 + np.abs(R)

def seed_tracers(ic_name, n_core=1500, n_far=500, seed=0):
    axes, dx = np_mesh(32)
    x, y, z = axes
    if ic_name == 'wound':
        xc = np.pi + A_WIND*np.sin(z)
        yc = np.pi + A_WIND*np.sin(2.0*z)
        rx = (x - xc + L_half) % L_dom - L_half
        ry = (y - yc + L_half) % L_dom - L_half
        f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA_IC**2))
    else:
        ct = np.cos(0.35); st = np.sin(0.35)
        dxA = (x - (np.pi - 0.8) + L_half) % L_dom - L_half
        dxB = (x - (np.pi + 0.8) + L_half) % L_dom - L_half
        dyA = (y - np.pi + L_half) % L_dom - L_half
        tA = ct*dxA + st*z; tB = ct*dxB + st*z
        fA = np.exp(-(tA*tA + dyA*dyA)/(2.0*0.8**2))
        fB = np.exp(-(tB*tB + dyA*dyA)/(2.0*0.8**2))
        f = np.maximum(fA, fB)
    rng = np.random.default_rng(seed)
    pos_all = rng.uniform(0, L_dom, (40000, 3))
    cells = cell_index(pos_all, dx, 32)
    fvals = f[cells[:, 0], cells[:, 1], cells[:, 2]]
    core = pos_all[fvals > 0.35][:n_core]
    far = pos_all[fvals < 0.02][:n_far]
    return core, far

def advect_tracers(run, pos0, ci, dt_tr=0.01):
    """RK2 through the time-interpolated saved field, IC channel ci."""
    T_end = float(run['times'][-1])
    S = int(round(T_end/dt_tr))
    M = pos0.shape[0]
    traj = np.empty((M, S + 1, 3))
    spd = np.empty((M, S + 1))
    traj[:, 0] = pos0
    spd[:, 0] = np.linalg.norm(velocity_at(run, 0.0, pos0, ci), axis=-1)
    pos = pos0.copy()
    for s_ in range(S):
        t = s_*dt_tr
        v1 = velocity_at(run, t, pos, ci)
        mid = (pos + 0.5*dt_tr*v1) % L_dom
        v2 = velocity_at(run, t + 0.5*dt_tr, mid, ci)
        pos = (pos + dt_tr*v2) % L_dom
        traj[:, s_ + 1] = pos
        spd[:, s_ + 1] = np.linalg.norm(
            velocity_at(run, (s_ + 1)*dt_tr, pos, ci), axis=-1)
    return traj, spd

# =============================================================================
# GATES
# =============================================================================
print('\n' + '='*79)
print('V31-Lc GATES')
print('='*79)
rng_g = np.random.default_rng(7)
# [G11] interpolation exactness at grid nodes (incl. the wrap corner)
Fg = rng_g.standard_normal((16, 16, 16, 3))
nodes = np.stack(np.meshgrid(np.arange(16), np.arange(16),
                             np.arange(16), indexing='ij'),
                 axis=-1).reshape(-1, 3)
val = interp_field(Fg, nodes, 16)
err11 = float(np.max(np.abs(val - Fg.reshape(-1, 3))))
print(f'  [G11] trilinear exactness at nodes (incl. wrap): {err11:.2e}')
assert err11 < 1e-12

# [G12] SEAM-FREE SOLID-BODY ([50]): rotation about the DOMAIN CENTER,
#   interior tracers (radius <= 0.15, advance 0.6 rad -> they never
#   leave the seam-free interior). Trilinear reproduces the linear
#   field exactly there, so this is a pure RK2-accuracy gate. Batched
#   snapshot with ci=0 also exercises the [49] slicing path.
n_sb = 32; dx_sb = L_dom/n_sb
th_ = np.arange(n_sb)*dx_sb
X, Y, Z = np.meshgrid(th_, th_, th_, indexing='ij')
Om = 1.0
Vsb = np.stack([-Om*(Y - np.pi), Om*(X - np.pi),
                np.zeros_like(X)], axis=-1)      # (32,32,32,3)
run_sb = dict(times=np.array([0.0, 10.0]),
              snaps=[Vsb[None], Vsb[None]])      # batched, C=1
r0 = np.array([[np.pi + 0.10, np.pi + 0.10, 1.5],
               [np.pi - 0.12, np.pi + 0.08, 2.0],
               [np.pi + 0.05, np.pi - 0.14, 0.7]])
ang0 = np.arctan2(r0[:, 1] - np.pi, r0[:, 0] - np.pi)
pos_sb = r0.copy()
for s_ in range(60):                              # t to 0.6, dt 0.01
    t = s_*0.01
    v1 = velocity_at(run_sb, t, pos_sb, 0)
    mid = (pos_sb + 0.5*0.01*v1) % L_dom
    v2 = velocity_at(run_sb, t + 0.005, mid, 0)
    pos_sb = (pos_sb + 0.01*v2) % L_dom
r_i = np.linalg.norm(r0[:, :2] - np.pi, axis=-1)
r_f = np.linalg.norm(pos_sb[:, :2] - np.pi, axis=-1)
err12r = float(np.max(np.abs(r_f - r_i))/max(float(np.max(r_i)), 1e-30))
angf = np.arctan2(pos_sb[:, 1] - np.pi, pos_sb[:, 0] - np.pi)
err12a = float(np.max(np.abs(np.unwrap(angf - ang0) - Om*0.6)))
print(f'  [G12] seam-free solid-body: radius err {err12r:.2e}   '
      f'angular err {err12a:.2e} rad (RK2-only; expect <1e-4)')
assert err12r < 1e-3 and err12a < 1e-3
print('  GATES PASS.\n')

