# V31-Ld — LOCAL-CLOCK RE-PARAMETERIZATION (post-hoc, paired tracers;
# answers: orbit decay vs clock differentiation, per tracer)
import numpy as np
L = 2*np.pi; LH = np.pi
Z = np.load('/content/v31l_results/v31lc_tracers.npz')

def geo(traj, A_WIND=0.35):
    d = np.diff(traj, axis=1)
    d = (d + LH) % L - LH                      # shortest-step
    ang = np.arctan2(d[..., 1], d[..., 0])
    dang = np.diff(np.unwrap(ang, axis=1), axis=1)
    rev = np.sum(dang, axis=1)/(2*np.pi)       # per tracer
    arc = np.sum(np.linalg.norm(d, axis=-1), axis=1)  # local time accrued
    # radius about the wound center line (center wanders with z)
    z = traj[:, :-1, 2]
    cx = np.pi + A_WIND*np.sin(z); cy = np.pi + A_WIND*np.sin(2*z)
    r = np.sqrt((traj[:, :-1, 0] - cx)**2 + (traj[:, :-1, 1] - cy)**2)
    return rev, arc, np.median(r, axis=1), np.std(r, axis=1)

for ic in ('wound', 'tubes'):
    revC, arcC, rCm, rCs = geo(Z[f'trajc_{ic}_CLASSICAL'])
    revT, arcT, rTm, rTs = geo(Z[f'trajc_{ic}_TRANSMUTE'])
    ok = revC > 0.3                            # orbital tracers only
    print(f'\n[{ic}] paired orbital tracers: {ok.sum()}/{len(revC)}')
    rr = revT[ok]/revC[ok]; ar = arcT[ok]/arcC[ok]
    rpa_T = revT[ok]/arcT[ok]; rpa_C = revC[ok]/arcC[ok]
    print(f'  rev ratio  T/C: median {np.median(rr):.3f}   '
          f'arc ratio T/C: median {np.median(ar):.3f}')
    print(f'  rev per unit LOCAL time: C {np.median(rpa_C):.4f}  '
          f'T {np.median(rpa_T):.4f}   '
          f'ratio {np.median(rpa_T)/np.median(rpa_C):.3f}')
    print(f'  orbit radius: C {np.median(rCm[ok]):.3f}+-{np.median(rCs[ok]):.3f}'
          f'  T {np.median(rTm[ok]):.3f}+-{np.median(rTs[ok]):.3f}')
    print('  CLOCK DIFFERENTIATION: rev/arc ratio ~1 AND radii match;')
    print('  ORBITAL DECAY: rev/arc ratio < 1 AND/OR T radii drift.')

# V31-Le — the degeneracy-breaking controls (post-hoc, persisted data)
import numpy as np
L = 2*np.pi; LH = np.pi
Z = np.load('/content/v31l_results/v31lc_tracers.npz')

def per_center(traj, cx, cy):
    d = np.diff(traj, axis=1); d = (d + LH) % L - LH
    rx = traj[:, :-1, 0] - cx; ry = traj[:, :-1, 1] - cy
    ang = np.arctan2(ry, rx)
    dang = np.diff(np.unwrap(ang, axis=1), axis=1)
    rev = np.sum(dang, axis=1)/(2*np.pi)
    arc = np.sum(np.linalg.norm(d, axis=-1), axis=1)
    return rev, arc

# [E1] tubes per-TUBE centers (pi-0.8, pi) and (pi+0.8, pi):
#   does the clock signature appear once the center is right?
for arm in ('CLASSICAL', 'TRANSMUTE'):
    tr = Z[f'trajc_tubes_{arm}']
    for cx, tag in ((np.pi - 0.8, 'tubeA'), (np.pi + 0.8, 'tubeB')):
        rev, arc = per_center(tr, cx, np.pi)
        orb = rev > 0.3
        print(f'[E1] tubes {arm:10s} {tag}: orbital {orb.sum():4d}/1500  '
              f'median rev {np.median(rev[orb]) if orb.any() else 0:.2f}')
revC, arcC = per_center(Z['trajc_tubes_CLASSICAL'], np.pi - 0.8, np.pi)
revT, arcT = per_center(Z['trajc_tubes_TRANSMUTE'], np.pi - 0.8, np.pi)
orb = (revC > 0.3)
if orb.sum() > 50:
    rpa = np.median(revT[orb]/arcT[orb]) / np.median(revC[orb]/arcC[orb])
    print(f'   tubeA rev/local-time ratio T/C: {rpa:.3f}  '
          f'({"CLOCK branch" if 0.9 < rpa < 1.1 else "DECAY branch"})')

# [E2] wound per-tracer SPREAD of the rate (structure vs uniform damping):
revW, arcW = per_center(Z['trajc_wound_CLASSICAL'], np.pi, np.pi)
revWT, arcWT = per_center(Z['trajc_wound_TRANSMUTE'], np.pi, np.pi)
rate = (arcWT/np.maximum(arcW, 1e-12))   # per-tracer local-time rate
orbW = revW > 0.3
print(f'\n[E2] wound per-tracer rate: median {np.median(rate[orbW]):.3f}  '
      f'IQR {np.percentile(rate[orbW], 25):.3f}-'
      f'{np.percentile(rate[orbW], 75):.3f}  '
      f'tail(10%) {np.percentile(rate[orbW], 10):.3f}')
print('   structured rate field (broad IQR, low tail) = differentiation'
      ' with structure;\n   tight ~0.59 for all = uniform damping.')

