nodes = np.stack(np.meshgrid(np.arange(16), np.arange(16),
                             np.arange(16), indexing='ij'),
                 axis=-1).reshape(-1, 3)
val = interp_field(Fg, nodes, 16)
err11 = float(np.max(np.abs(val - Fg.reshape(-1, 3))))
