"""### Time Scale Ratio Confirmation: Unified Temporal & Lagrangian Audit
This cell verifies the clock-differentiation and orbital decay metrics. It loads the persisted Lagrangian data and evaluates the local-time ratios, the structural coordinate spread, and the exactness of the $m$-invariance theorem under local clock shear.
"""

import os
import numpy as np

SAVE_DIR = '/content/v31l_results'
tracer_file = os.path.join(SAVE_DIR, 'v31lc_tracers.npz')

if os.path.exists(tracer_file):
    Z = np.load(tracer_file)
    L = 2*np.pi
    LH = np.pi

    def analyze_chiral_orbits(traj):
        d = np.diff(traj, axis=1)
        d = (d + LH) % L - LH
        ang = np.arctan2(d[..., 1], d[..., 0])
        dang = np.diff(np.unwrap(ang, axis=1), axis=1)
        rev = np.sum(dang, axis=1)/(2*np.pi)
        arc = np.sum(np.linalg.norm(d, axis=-1), axis=1)
        return rev, arc

    print('='*79)
    print('UNIFIED TEMPORAL AUDIT: CLOCK DIFFERENTIATION VS DECAY')
    print('='*79)
    for ic in ('wound', 'tubes'):
        revC, arcC = analyze_chiral_orbits(Z[f'trajc_{ic}_CLASSICAL'])
        revT, arcT = analyze_chiral_orbits(Z[f'trajc_{ic}_TRANSMUTE'])
        ok = revC > 0.3

        ratio_rev = np.median(revT[ok]/revC[ok])
        ratio_arc = np.median(arcT[ok]/arcC[ok])
        ratio_local = np.median((revT[ok]/arcT[ok])/(revC[ok]/arcC[ok]))

        print(f'  [{ic:6s}] matched orbital tracers: {ok.sum()}/{len(revC)}')
        print(f'         global rev ratio T/C: {ratio_rev:.3f}')
        print(f'         local arc ratio T/C:  {ratio_arc:.3f}')
        print(f'         local orbital rate ratio: {ratio_local:.3f} (expect ~1.0 for pure clock diff)')
    print('='*79)
else:
    print(f'Tracer file not found at {tracer_file}. Please run V31-Lc first.')

