rng_g = np.random.default_rng(7)
Fg = rng_g.standard_normal((2, 16, 16, 16, 3))
S_g, Sres_g, ident_g = octave_energies(Fg)
ref_g = max(float(np.sum(Fg[0]**2)), float(np.sum(Fg[1]**2)))
err_g = float(np.max(np.abs(ident_g)))/max(ref_g, 1e-30)
print(f'  [G8] Haar telescoping identity (batched): {err_g:.2e}')
assert err_g < 1e-10
axes_32, dx_32 = np_mesh(32)
xg, yg, zg = axes_32
u_syn = np.zeros((1, 32, 32, 32, 3))
u_syn[..., 0] = np.sin(2*np.pi*2*xg/L_dom)*np.cos(2*np.pi*2*yg/L_dom)
u_syn[..., 1] = np.sin(2*np.pi*2*yg/L_dom)
S_syn, Sres_syn, _ = octave_energies(u_syn)
tot_syn = float(np.sum(S_syn[:, 0]) + Sres_syn[0])
share_syn = S_syn[:, 0]/tot_syn
print('  [G14] mode-2 Haar shares: '
      + ' '.join(f'{s_:.3f}' for s_ in share_syn))
assert share_syn[0] < 0.20 and int(np.argmax(share_syn)) >= 2
u_wn = rng_g.standard_normal((1, 32, 32, 32, 3))
S_wn, Sres_wn, _ = octave_energies(u_wn)
tot_wn = float(np.sum(S_wn[:, 0]) + Sres_wn[0])
share_wn = S_wn[:, 0]/tot_wn
print('  [G14b] white-noise Haar shares: '
      + ' '.join(f'{s_:.3f}' for s_ in share_wn))
assert share_wn[0] > 0.70 and share_wn[0] > 2.5*share_wn[1]
# [G15] the [63] fix verified: mask broadcast path through the instrument
fp_test = (rng_g.random((32, 32, 32)) > 0.5).astype(float)
fp3 = np.repeat(fp_test[:, :, :, None], 3, axis=-1)[None, ...]
S_t, Sres_t, ident_t = octave_energies(fp3)
ref_t = float(np.sum(fp3**2))
err_t = float(abs(ident_t[0]))/max(ref_t, 1e-30)
print(f'  [G15] mask-octave path (broadcast fix): identity {err_t:.2e}')
assert err_t < 1e-10
print('  GATES PASS.\n')

