# =============================================================================
# [A] gamma=1 CONTROL: the routing footprint on the classical field
# =============================================================================
print('\n' + '='*79)
print('[A] gamma=1 CONTROL — the routing footprint (where routing WOULD')
print('    fire on the classical evolution; no arm ever acts)')
print('='*79)
foot_stats = {}
foot_frac = {}
for ki in CK_IDX:
    snap = RUN['snaps'][ki]
    t_lab = float(RUN['times'][ki])
    tens = tension_at_grid(snap, dx_)
    for ci, nm in enumerate(ICS):
        fp = tens[ci] > THR_[ci]
        foot_stats[(ki, nm)] = fp
        foot_frac[(ki, nm)] = float(fp.mean())
        print(f'  t={t_lab:.2f} [{nm:6s}] footprint fraction: '
              f'{foot_frac[(ki, nm)]*100:5.2f}%')

print('\n  DENSITY CONTRAST (footprint fraction wound/tubes):')
for ki in CK_IDX:
    t_lab = float(RUN['times'][ki])
    fw = foot_frac[(ki, 'wound')]
    ft = foot_frac[(ki, 'tubes')]
    ratio_now = fw/max(ft, 1e-30)
    print(f'  t={t_lab:.2f}: wound {fw*100:5.2f}% / tubes {ft*100:5.2f}%'
          f'  -> ratio {ratio_now:.2f}')

print('\n  FOOTPRINT GEOMETRY (wound): centroid winding of the routed set')
for ki in CK_IDX:
    t_lab = float(RUN['times'][ki])
    fp = foot_stats[(ki, 'wound')]
    n_ = 32
    cz = []; cx_ = []; cy_ = []
    for z_ in range(n_):
        sl = fp[:, :, z_]
        if sl.sum() < 3:
            cz.append(z_); cx_.append(np.nan); cy_.append(np.nan)
            continue
        ii, jj = np.where(sl)
        wts = sl[ii, jj].astype(float)
        cz.append(z_)
        cx_.append(np.average(ii, weights=wts))
        cy_.append(np.average(jj, weights=wts))
    cx_ = np.array(cx_); cy_ = np.array(cy_); cz = np.array(cz) + 0.5
    okm = np.isfinite(cx_)
    if okm.sum() > 8:
        angc = np.unwrap(np.arctan2(cy_[okm] - 16.0, cx_[okm] - 16.0))
        z_ok = cz[okm]*dx_
        dpitch = float(np.polyfit(z_ok, angc, 1)[0])
        print(f'  t={t_lab:.2f}: centroid winding rate {dpitch:+.3f} rad/z')
        print(f'    (compactification helix reference: A_WIND-driven, '
              f'scale ~{A_WIND*2.0:.2f} rad/z; W_GOLD {W_GOLD:.1f} is the '
              f'tracer pitch, not the centroid pitch)')
    else:
        print(f'  t={t_lab:.2f}: routed set too sparse for centroid fit')

fw3 = foot_frac[(CK_IDX[-1], 'wound')]
ft3 = foot_frac[(CK_IDX[-1], 'tubes')]
ratio_fp = fw3/max(ft3, 1e-30)
print('\n  [A] VERDICT BRANCHES:')
print(f'  final footprint ratio wound/tubes = {ratio_fp:.2f}')
if ratio_fp > 1.8:
    print('  -> footprint density contrast ~ the routing contrast (2.4x):')
    print('     the footprint is CONCENTRATED in the compactified object.')
    print('     If the pitch block shows helical structure -> [A](a):')
