oct_hist = {}
for ki in CK_IDX:
    t_lab = float(RUN['times'][ki])
    snap = RUN['snaps'][ki]
    S_u, Sres_u, ident_u = octave_energies(snap)
    for ci, nm in enumerate(ICS):
        tot = float(np.sum(S_u[:, ci]) + Sres_u[ci])
        shares = S_u[:, ci]/max(tot, 1e-30)
        oct_hist[(ki, nm)] = shares
        idr = float(abs(ident_u[ci]))/max(tot, 1e-30)
        share_str = ' '.join(f'{s_:.3f}' for s_ in shares)
        coarse_str = f'{Sres_u[ci]/max(tot, 1e-30):.3f}'
        print(f'  t={t_lab:.2f} [{nm:6s}] u-shares: {share_str}'
              f'  coarse {coarse_str}  identity {idr:.1e}')
        assert idr < 1e-10

print('\n  SHARE STATIONARITY (first checkpoint -> last):')
drifts = {}
for nm in ICS:
    s1 = oct_hist[(CK_IDX[0], nm)]
    s3 = oct_hist[(CK_IDX[-1], nm)]
    drifts[nm] = float(np.max(np.abs(s3 - s1)))
    label = 'STATIONARY' if drifts[nm] < 0.10 else 'EVOLVING'
    print(f'  [{nm:6s}] max share drift: {drifts[nm]:.3f} ({label})')

print('\n  FOOTPRINT-OCTAVE CORRELATION (which scales carry the mask):')
fp_shares = {}
for nm in ICS:
    fp = foot_stats[(CK_IDX[-1], nm)].astype(float)
    fp3 = np.repeat(fp[:, :, :, None], 3, axis=-1)[None, ...]
    S_fp, Sres_fp, _ = octave_energies(fp3)
    tot_fp = float(np.sum(S_fp[:, 0]) + Sres_fp[0])
    fp_shares[nm] = S_fp[:, 0]/max(tot_fp, 1e-30)
    share_str = ' '.join(f'{s_:.3f}' for s_ in fp_shares[nm])
    print(f'  [{nm:6s}] footprint octave shares: {share_str}')

print('\n' + '='*79)
print('[B] VERDICT')
print('='*79)
stat = all(d < 0.10 for d in drifts.values())
w_sh = oct_hist[(CK_IDX[-1], 'wound')]
core_dom = bool(w_sh[0] > 0.5 or w_sh[1] > 0.4)
