def load_run(tag):
    z = np.load(os.path.join(SAVE_DIR, f'v33b_{tag}.npz'))
    times = np.asarray(z['times'])
    snaps = [np.asarray(z[f'u_{i_}']) for i_ in range(len(times))]
    return dict(times=times, snaps=snaps,
                M0=np.asarray(z['M0']), THR=np.asarray(z['THR']),
                dx=float(z['dx']))

Q1 = load_run('Q1_LONGT')
