#   Scale-consistent armed evolution at 32/64/128^3; per-resolution Haar
#   depth (kmax 4/5/6) so ALL residuals sit at the same physical scale
#   (L/2); PHYSICAL-SCALE-MATCHED octave comparison:
#       32^3 octave k  <->  64^3 octave k+1  <->  128^3 octave k+2
#       (matched wavelengths L/16, L/8, L/4, L/2)
#   SUPERSEDES V33e [Q3] (same-k alignment was scale-misaligned).
# Single self-contained cell. GPU ~10-15 min. Requires CUDA.
# =============================================================================
# FIX LOG (V34c -> V34d):
#   [83] THE GATE'S SCALE FORMULA WAS INVERTED: physical wavelength of
#        octave k on n=2^m grid is 2^k*dx = L/2^(m-k) (octave 1 is
#        FINEST). The gate wrote (n/2^k)*dx = L/2^k — the scale of octave
#        (m-k), counting from the COARSE end — so the three expressions
#        computed L/2^k, L/2^(k+1), L/2^(k+2): never equal, at ANY
#        tolerance. Diagnoses [81]/[82] ("float tolerance") were
#        misreads of a correctly-failing gate; the diagnostic print
#        exposed deviations HALVING with k (1.6, 0.79, 0.39, 0.20) —
#        the structural signature. ALSO: the Fraction reference used pi
#        while the domain is 2*pi (factor-2 error). Both fixed; the
#        load-bearing INDEX ALIGNMENT (k/k+1/k+2) and the analysis
#        slices were correct all along.
#   RETROACTIVE: V33e [Q3] compared same-k octaves across resolutions
#        (different physical scales) with a hardcoded kmax=4 (residuals
#        at L/2 for 32^3 but L/4 for 64^3) — its L1s and its
#        coarse-anchoring-amplifies reading are RETIRED. This cell
#        supersedes them. Within-resolution results are unaffected.
#   META-LESSON (logged): when a gate fails, PRINT THE VALUES before
#        theorizing about tolerance. Halving deviations = wrong formula,
#        not numerical noise.
#   Carried: memory-audited saves (75-step at 128^3); [G19] traced-
#   boundary gate; [G20] telescoping at two depths; zero new traced
#   code (V33e verbatim scan path); dot-free keys; [74]-class alphas.
# =============================================================================
import os
import time
from fractions import Fraction
import numpy as np
import matplotlib.pyplot as plt

import jax
jax.config.update("jax_enable_x64", True)
import jax.numpy as jnp
from jax import lax

print('JAX version:', jax.__version__)
DEVICES = jax.devices()
PLATFORM = DEVICES[0].platform
IS_GPU = (PLATFORM == 'gpu')
print('backend devices:', DEVICES)
if not IS_GPU:
    raise SystemExit('V34d requires CUDA (128^3 evolution).')
print('backend platform: gpu — V34d ACTIVE')

np.set_printoptions(precision=6, suppress=True)
L_dom = 2.0*np.pi; L_half = L_dom/2.0
NU_TEST = 0.0001
WARM_CYCLES = 8; INIT_CYCLES = 20
DT_RUN = 0.004
T_H = 3.0
A_SWIRL = 6.0; PHI = 0.5*(1.0 + np.sqrt(5.0)); W_GOLD = 12.0/PHI
SIGMA_IC = 1.0; A_WIND = 0.35
ICS = ['tubes', 'wound']
GAIN = 10.0; THRESH_FRAC = 0.5
GAMMA_CONTRACT = 0.5
SAVE_DIR = '/content/v34_results'; os.makedirs(SAVE_DIR, exist_ok=True)
SAVE_128 = 75
CK_IDX = [0, 3, 7, 10]        # snapshot indices: t = 0.0, 0.9, 2.1, 3.0
KMAX = {32: 4, 64: 5, 128: 6}  # residuals all at 16/32/64-cell = L/2

# ---- ICs (proven, host-side, verbatim) ----
def np_mesh(n):
    x = np.linspace(0.0, L_dom, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), L_dom/n
def np_dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis))*(0.5/dx)
def ic_tubes(axes, strength=8.0, sigma=0.8, sep=1.6, tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt); st = np.sin(tilt)
    def tube(cx, sign):
        dx_ = (x - cx + L_half) % L_dom - L_half
        dy_ = (y - np.pi + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        r2 = dx_t*dx_t + dy_*dy_
        f = np.exp(-r2/(2.0*sigma*sigma))
        return np.stack([-sign*strength*dy_*f,
                         sign*strength*dx_t*f,
                         np.zeros_like(x)], axis=-1)
    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)
def ic_wound(axes):
    x, y, z = axes
    xc = np.pi + A_WIND*np.sin(z)
    yc = np.pi + A_WIND*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA_IC*SIGMA_IC))
    return np.stack([-A_SWIRL*ry*f, A_SWIRL*rx*f, W_GOLD*f], axis=-1)
def build_ics_np(n):
    axes, dx = np_mesh(n)
    return {'tubes': ic_tubes(axes), 'wound': ic_wound(axes)}, dx

# ---- JAX core (V33e verbatim — [G19]-gated traced-boundary lineage) ----
def jdd(f, axis, dx):
    return (jnp.roll(f, -1, axis=axis) - jnp.roll(f, 1, axis=axis))*(0.5/dx)
def jnth_jacobian(u, dx):
    gu = []
    for i in range(3):
        for j in range(3):
            gu.append(jdd(u[..., i], j + 1, dx))
    G = jnp.stack(gu, axis=-1).reshape(u.shape[0], u.shape[1],
                                       u.shape[1], u.shape[1], 3, 3)
    S = 0.5*(G + jnp.swapaxes(G, -1, -2))
    A_ = 0.5*(G - jnp.swapaxes(G, -1, -2))
    C1 = jnp.sqrt(jnp.sum(S*S, axis=(-2, -1)))
    C2 = jnp.sqrt(jnp.sum(A_*A_, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    return G, C1, C2, R, C1 + C2 + jnp.abs(R)
def jlap(u, dx):
    inv = 1.0/(dx*dx)
    out = -6.0*u
    for a in (1, 2, 3):
        out = out + jnp.roll(u, -1, axis=a) + jnp.roll(u, 1, axis=a)
    return out*inv
def jadvect(f, v, dx):
    parts = []
    for i in range(3):
        fi = f[..., i]
        acc = jnp.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc = acc + 0.5*(jdd(vj*fi, j + 1, dx) + vj*jdd(fi, j + 1, dx))
        parts.append(acc)
    return jnp.stack(parts, axis=-1)
def jaxis_dominant(C1, C2, G, dx):
    rot_dom = C2 > C1
    w0 = G[..., 2, 1] - G[..., 1, 2]
    w1 = G[..., 0, 2] - G[..., 2, 0]
    w2 = G[..., 1, 0] - G[..., 0, 1]
    wn = jnp.sqrt(w0*w0 + w1*w1 + w2*w2)
    gs0 = jdd(C1, 1, dx); gs1 = jdd(C1, 2, dx); gs2 = jdd(C1, 3, dx)
    gn = jnp.sqrt(gs0*gs0 + gs1*gs1 + gs2*gs2)
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    ax_v = jnp.stack([w0, w1, w2], axis=-1) \
        / jnp.maximum(wn, 1e-30)[..., None]
    ax_g = jnp.stack([gs0, gs1, gs2], axis=-1) \
        / jnp.maximum(gn, 1e-30)[..., None]
    return jnp.where(use_v[..., None], ax_v,
                     jnp.where(use_g[..., None], ax_g,
                               jnp.zeros_like(ax_v)))
def jrestrict(F):
    classes = []
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                classes.append(F[:, a::2, b::2, d_::2])
    return jnp.stack(classes, axis=1)
def jmerge(G8, n):
    out = jnp.zeros((G8.shape[0], n, n, n), dtype=G8.dtype)
    idx = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out = out.at[:, a::2, b::2, d_::2].set(G8[:, idx])
                idx += 1
    return out
def jrestrict_fw(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))
def j_interp1(F, axis):
    n = F.shape[axis]
    odd = 0.5*(F + jnp.roll(F, -1, axis=axis))
    out = jnp.stack([F, odd], axis=axis + 1)
    shp = list(F.shape); shp[axis] = 2*n
    return out.reshape(shp)
def jprolong(C):
    F = j_interp1(C, C.ndim - 3)
    F = j_interp1(F, F.ndim - 2)
    F = j_interp1(F, F.ndim - 1)
    return F
def jdiv_bundle(V, dx):
    return jdd(V[..., 0], 1, dx) + jdd(V[..., 1], 2, dx) \
        + jdd(V[..., 2], 3, dx)
def jgrad_bundle(phi, dx):
    return jnp.stack([jdd(phi, 1, dx), jdd(phi, 2, dx),
                      jdd(phi, 3, dx)], axis=-1)
def jlap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    nd = F.ndim
    for a in (nd - 3, nd - 2, nd - 1):
        s = s + jnp.roll(F, -1, axis=a) + jnp.roll(F, 1, axis=a)
    return s*inv
def jsmooth_gs(phi, f, dx, iters):
    cc = dx*dx/6.0
    m = phi.shape[-1]
    idx = jnp.indices((m, m, m))
    parity = (idx[0] + idx[1] + idx[2]) % 2
    red = (parity == 0); black = (parity == 1)
    def body(i, phi_):
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(red, r, 0.0)
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(black, r, 0.0)
        return phi_
    return lax.fori_loop(0, iters, body, phi)
def jv_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - jnp.mean(f, axis=(-3, -2, -1), keepdims=True)
        return jsmooth_gs(phi, f, dx, 40)
    phi = jsmooth_gs(phi, f, dx, 2)
    r = f - jlap_apply(phi, dx)
    rc = jrestrict_fw(r)
    ec = jv_cycle(jnp.zeros_like(rc), rc, 2.0*dx)
    phi = phi + jprolong(ec)
    return jsmooth_gs(phi, f, dx, 2)
def _project_warm(Vch, psic0, dx, cycles):
    f = -jdiv_bundle(Vch, dx)
    fc = jrestrict(f)
    H = 2.0*dx
    fc = fc - jnp.mean(fc, axis=(-3, -2, -1), keepdims=True)
    psic = psic0 - jnp.mean(psic0, axis=(-3, -2, -1), keepdims=True)
    def cycle_body(i, psi):
        return jv_cycle(psi, fc, H)
    psic = lax.fori_loop(0, cycles, cycle_body, psic)
    psic = psic - jnp.mean(psic, axis=(-3, -2, -1), keepdims=True)
    resid = jnp.max(jnp.abs(fc - jlap_apply(psic, H))) \
        / (jnp.max(jnp.abs(fc)) + 1e-30)
    phi_full = jmerge(psic, Vch.shape[1])
    return Vch + jgrad_bundle(phi_full, dx), psic, resid
def _arm_scaled(u_s, p_s, G, C1, C2, tension, dx, thr):
    thr_ = thr[:, None, None, None]
    routed = tension > thr_
    m = u_s + p_s
    d = 0.5*(u_s - p_s)
    axis = jaxis_dominant(C1, C2, G, dx)
    dpar = jnp.sum(axis*d, axis=-1)[..., None]*axis
    d_tr = d - dpar
    gam = jnp.where(routed, GAMMA_CONTRACT, 1.0)
    excess = jnp.maximum(tension - thr_, 0.0)
    g = GAIN*excess/jnp.maximum(thr_, 1e-30)
    t_par = jnp.where(routed, g/(1.0 + g), 0.0)
    c_ = (1.0 - t_par*t_par)/(1.0 + t_par*t_par)
    s_ = (2.0*t_par)/(1.0 + t_par*t_par)
    rot = c_[..., None]*d_tr + s_[..., None]*jnp.cross(axis, d_tr)
    d_new = dpar + gam[..., None]*rot
    return 0.5*m + d_new, 0.5*m - d_new

def make_factory(n, dt, cycles, mode, nu_val=NU_TEST):
    ics, dx = build_ics_np(n)
    C = len(ICS)
    U0 = np.stack([ics[nm] for nm in ICS])
    Us0 = jnp.asarray(np.concatenate([U0, np.zeros_like(U0)], axis=0))
    psic0 = jnp.zeros((2*C, 8, n//2, n//2, n//2))
    Us0, psic0, _ = _project_warm(Us0, psic0, dx, INIT_CYCLES)
    U0j, P0j = Us0[:C], Us0[C:]
    _, _, _, _, t0_ = jnth_jacobian(U0j, dx)
    M0 = np.asarray(jnp.max(t0_.reshape(C, -1), axis=1))
    THR = jnp.asarray(THRESH_FRAC*M0)
    nu = jnp.asarray(np.full(C, nu_val, dtype=np.float64))
    nu_ = nu[:, None, None, None, None]
    dx_j = dx
    def step(u, p, psic):
        Cb = u.shape[0]
        G_u, C1_u, C2_u, R_u, tension_u = jnth_jacobian(u, dx_j)
        m = u + p
        au1 = jadvect(u, m, dx_j); ap1 = jadvect(p, m, dx_j)
        Lu = jlap(u, dx_j); Lp = jlap(p, dx_j)
        u_star = u + dt*(-au1 + nu_*Lu)
        p_star = p + dt*(-ap1 + nu_*Lp)
        m_star = u_star + p_star
        au2 = jadvect(u_star, m_star, dx_j)
        ap2 = jadvect(p_star, m_star, dx_j)
        u_s = u + 0.5*dt*(-(au1 + au2) + nu_*(Lu + jlap(u_star, dx_j)))
        p_s = p + 0.5*dt*(-(ap1 + ap2) + nu_*(Lp + jlap(p_star, dx_j)))
        if mode == 'classical':
            u_t, p_t = u_s, p_s
        else:
            u_t, p_t = _arm_scaled(u_s, p_s, G_u, C1_u, C2_u,
                                    tension_u, dx_j, THR)
        Usp = jnp.concatenate([u_t, p_t], axis=0)
        Unew, psic_n, _ = _project_warm(Usp, psic, dx_j, cycles)
        return (Unew[:Cb], Unew[Cb:], psic_n)
    def body(carry, _):
        u, p, psic = carry
        u, p, psic = step(u, p, psic)
        return (u, p, psic), None
    return dict(body=body, carry0=(U0j, P0j, psic0), dx=dx,
                M0=np.asarray(M0), THR=np.asarray(THR), C=C, n=n, dt=dt)

def run_dense(tag, mode, n, T, save_every):
    fac = make_factory(n, DT_RUN, WARM_CYCLES, mode)
    body = fac['body']; carry = fac['carry0']
    STEPS = int(round(T/DT_RUN))
    n_blocks = STEPS//save_every
    est_mb = 2*n*n*n*3*8/1e6
    print(f'  [{tag}] n={n}^3 mode={mode} steps={STEPS} '
          f'save_every={save_every} ({est_mb:.0f} MB/snapshot)')
    snaps = [np.array(fac['carry0'][0])]
    times = [0.0]
    t0 = time.time()
    for b_ in range(n_blocks):
        carry, _ = lax.scan(body, carry, xs=None, length=save_every)
        snaps.append(np.array(carry[0]))
        times.append((b_ + 1)*save_every*DT_RUN)
    print(f'    done: {len(snaps)} snapshots, {time.time()-t0:.0f}s')
    np.savez(os.path.join(SAVE_DIR, f'v34d_{tag}.npz'),
             **{f'u_{i_}': s_ for i_, s_ in enumerate(snaps)},
             times=np.array(times), M0=fac['M0'], THR=fac['THR'],
             dx=fac['dx'])
    return dict(tag=tag, mode=mode, snaps=snaps, times=np.array(times),
                dx=fac['dx'], M0=fac['M0'], THR=fac['THR'], C=fac['C'])

# ---- host-side instruments ----
def block_avg(F, k):
    if k == 0:
        return F
    C, n = F.shape[0], F.shape[1]
    b = 2**k
    return F.reshape(C, n//b, b, n//b, b, n//b, b, 3).mean(axis=(2, 4, 6))

def octave_energies_k(F, kmax):
    lv = [F] + [block_avg(F, k) for k in range(1, kmax + 1)]
    L = [np.sum(l**2, axis=(1, 2, 3, 4)) for l in lv]
    S = np.stack([8.0**(k - 1)*L[k - 1] - 8.0**k*L[k]
                  for k in range(1, kmax + 1)], axis=0)
    Sres = (8.0**kmax)*L[kmax]
    ident = np.sum(S, axis=0) + Sres - L[0]
    return S, Sres, ident

# =============================================================================
# GATES
# =============================================================================
print('\n' + '='*79)
print('V34d GATES')
print('='*79)
rng_g = np.random.default_rng(7)
for n_g, kmax_g in ((16, 4), (32, 5)):
    Fg = rng_g.standard_normal((2, n_g, n_g, n_g, 3))
    S_g, Sres_g, ident_g = octave_energies_k(Fg, kmax_g)
    ref_g = max(float(np.sum(Fg[0]**2)), float(np.sum(Fg[1]**2)))
    err_g = float(np.max(np.abs(ident_g)))/max(ref_g, 1e-30)
    print(f'  [G20] telescoping kmax={kmax_g} at {n_g}^3: {err_g:.2e}')
    assert err_g < 1e-10

# [G21] ([83]-corrected): octave k on n=2^m grid has wavelength
#   2^k*dx = L/2^(m-k). Matched alignment: 32^3 octave k, 64^3 octave
#   k+1, 128^3 octave k+2 all have wavelength 2^k*L/32.
#   Fraction-exact reference from the float L_dom itself.
L_exact = Fraction(L_dom)      # exact binary value of the float 2*pi
dx32 = L_dom/32.0
dx64 = L_dom/64.0
dx128 = L_dom/128.0
rel_devs = []
for k in range(1, 5):
    s32 = (2.0**k)*dx32            # wavelength of 32^3 octave k
    s64 = (2.0**(k + 1))*dx64      # wavelength of 64^3 octave k+1
    s128 = (2.0**(k + 2))*dx128    # wavelength of 128^3 octave k+2
    s_exact = float(L_exact*Fraction(2**k, 32))
    dev = max(abs(s32 - s_exact), abs(s64 - s_exact),
              abs(s128 - s_exact))
    rel = dev/max(s_exact, 1e-30)
    rel_devs.append(rel)
    print(f'    k={k}: exact {s_exact:.15f}  32:{s32:.15f}  '
          f'64:{s64:.15f}  128:{s128:.15f}  maxrel {rel:.1e}')
assert max(rel_devs) < 1e-12, 'scale matching failed beyond ULP noise'
print('  [G21] matched wavelengths verified (32^3 oct k = 64^3 oct '
      f'k+1 = 128^3 oct k+2; max rel dev {max(rel_devs):.1e}):')
print('       ladder covers L/16, L/8, L/4, L/2; residuals (kmax '
      '4/5/6) all at L/2 — cross-resolution comparable.')

for n_g in (16, 32):
    fac_g = make_factory(n_g, 0.004, 8, 'transmute')
    try:
        carry_g, _ = lax.scan(fac_g['body'], fac_g['carry0'],
                              xs=None, length=2)
        jax.block_until_ready(carry_g[0])
        print(f'  [G19] traced path at {n_g}^3: PASS')
    except Exception as e_g:
        print(f'  [G19] traced path at {n_g}^3 FAILED: '
              f'{type(e_g).__name__}')
        raise
print('  GATES PASS.\n')

# =============================================================================
# THE RUNS
# =============================================================================
print('#'*79)
print('V34d — THE 128^3 RUNG (three resolutions, scale-consistent arm,')
print('       scale-matched analysis — supersedes V33e [Q3])')
print('#'*79)
R32 = run_dense('R32', 'transmute', 32, T_H, 15)
try: jax.clear_caches()
except Exception: pass
R64 = run_dense('R64', 'transmute', 64, T_H, 15)
try: jax.clear_caches()
except Exception: pass
R128 = run_dense('R128', 'transmute', 128, T_H, SAVE_128)

# =============================================================================
# ANALYSIS
# =============================================================================
print('\n' + '='*79)
print('[V34a] OCTAVE SHARES at each resolution (own indices; kmax 4/5/6')
print('     — residuals all at the L/2 physical scale)')
print('='*79)
OCT = {32: {}, 64: {}, 128: {}}
for res, RUN in ((32, R32), (64, R64), (128, R128)):
    kmax_r = KMAX[res]
    for ki in CK_IDX:
        k_ok = min(ki, len(RUN['times']) - 1)
        t_lab = float(RUN['times'][k_ok])
        snap = RUN['snaps'][k_ok]
        S_u, Sres_u, ident_u = octave_energies_k(snap, kmax_r)
        for ci, nm in enumerate(ICS):
            tot = float(np.sum(S_u[:, ci]) + Sres_u[ci])
            shares = S_u[:, ci]/max(tot, 1e-30)
            coarse = float(Sres_u[ci]/max(tot, 1e-30))
            OCT[res][(ki, nm)] = (shares, coarse)
            idr = float(abs(ident_u[ci]))/max(tot, 1e-30)
            assert idr < 1e-10
            sh_str = ' '.join(f'{s_:.3f}' for s_ in shares)
            print(f'  {res}^3 t={t_lab:.2f} [{nm:6s}] k1..{kmax_r}: '
                  f'{sh_str}  coarse {coarse:.3f}')

print('\n  COARSE-RESIDUAL COMPARISON (now scale-aligned at L/2 for all')
print('  three resolutions — the V33e misalignment is corrected here):')
for ki in CK_IDX:
    k32 = min(ki, len(R32['times']) - 1)
    t_lab = float(R32['times'][k32])
    for nm in ICS:
        c32 = OCT[32][(ki, nm)][1]
        c64 = OCT[64][(ki, nm)][1]
