L_dom = 2.0*np.pi; L_half = L_dom/2.0
NU_TEST = 0.0001
WARM_CYCLES = 8; INIT_CYCLES = 20
T_H = 3.0
A_SWIRL = 6.0; PHI = 0.5*(1.0 + np.sqrt(5.0)); W_GOLD = 12.0/PHI
SIGMA_IC = 1.0; A_WIND = 0.35
ICS = ['tubes', 'wound']
GAIN = 10.0; THRESH_FRAC = 0.5
GAMMA_CONTRACT = 0.5
SAVE_DIR = '/content/v34_results'; os.makedirs(SAVE_DIR, exist_ok=True)
# [86]: CFL-consistent ladder — dt proportional to dx; block saves land
# t = 0.3k identically at every rung; T_CK hit exactly by construction.
DT_N = {32: 0.004, 64: 0.002, 128: 0.001}
SAVE_N = {32: 75, 64: 150, 128: 300}
