# ---- ICs (proven, host-side, verbatim) ----
def np_mesh(n):
    x = np.linspace(0.0, L_dom, n, endpoint=False)
    return np.meshgrid(x, x, x, indexing='ij'), L_dom/n
def np_dd(f, axis, dx):
    return (np.roll(f, -1, axis=axis) - np.roll(f, 1, axis=axis))*(0.5/dx)
def ic_tubes(axes, strength=8.0, sigma=0.8, sep=1.6, tilt=0.35):
    x, y, z = axes
    ct = np.cos(tilt); st = np.sin(tilt)
    def tube(cx, sign):
        dx_ = (x - cx + L_half) % L_dom - L_half
        dy_ = (y - np.pi + L_half) % L_dom - L_half
        dx_t = ct*dx_ + st*z
        r2 = dx_t*dx_t + dy_*dy_
        f = np.exp(-r2/(2.0*sigma*sigma))
        return np.stack([-sign*strength*dy_*f,
                         sign*strength*dx_t*f,
                         np.zeros_like(x)], axis=-1)
    return tube(np.pi - sep/2, +1.0) + tube(np.pi + sep/2, -1.0)
def ic_wound(axes):
    x, y, z = axes
    xc = np.pi + A_WIND*np.sin(z)
    yc = np.pi + A_WIND*np.sin(2.0*z)
    rx = (x - xc + L_half) % L_dom - L_half
    ry = (y - yc + L_half) % L_dom - L_half
    f = np.exp(-(rx*rx + ry*ry)/(2.0*SIGMA_IC*SIGMA_IC))
    return np.stack([-A_SWIRL*ry*f, A_SWIRL*rx*f, W_GOLD*f], axis=-1)
def build_ics_np(n):
    axes, dx = np_mesh(n)
    return {'tubes': ic_tubes(axes), 'wound': ic_wound(axes)}, dx

# ---- JAX core (V33e verbatim) ----
def jdd(f, axis, dx):
    return (jnp.roll(f, -1, axis=axis) - jnp.roll(f, 1, axis=axis))*(0.5/dx)
def jnth_jacobian(u, dx):
    gu = []
    for i in range(3):
        for j in range(3):
            gu.append(jdd(u[..., i], j + 1, dx))
    G = jnp.stack(gu, axis=-1).reshape(u.shape[0], u.shape[1],
                                       u.shape[1], u.shape[1], 3, 3)
    S = 0.5*(G + jnp.swapaxes(G, -1, -2))
    A_ = 0.5*(G - jnp.swapaxes(G, -1, -2))
    C1 = jnp.sqrt(jnp.sum(S*S, axis=(-2, -1)))
    C2 = jnp.sqrt(jnp.sum(A_*A_, axis=(-2, -1)))
    a = G[..., 0, 0]; b = G[..., 0, 1]; c = G[..., 0, 2]
    d = G[..., 1, 0]; e = G[..., 1, 1]; f_ = G[..., 1, 2]
    g_ = G[..., 2, 0]; h = G[..., 2, 1]; i_ = G[..., 2, 2]
    R = a*(e*i_ - f_*h) - b*(d*i_ - f_*g_) + c*(d*h - e*g_)
    return G, C1, C2, R, C1 + C2 + jnp.abs(R)
def jlap(u, dx):
    inv = 1.0/(dx*dx)
    out = -6.0*u
    for a in (1, 2, 3):
        out = out + jnp.roll(u, -1, axis=a) + jnp.roll(u, 1, axis=a)
    return out*inv
def jadvect(f, v, dx):
    parts = []
    for i in range(3):
        fi = f[..., i]
        acc = jnp.zeros_like(fi)
        for j in range(3):
            vj = v[..., j]
            acc = acc + 0.5*(jdd(vj*fi, j + 1, dx) + vj*jdd(fi, j + 1, dx))
        parts.append(acc)
    return jnp.stack(parts, axis=-1)
def jaxis_dominant(C1, C2, G, dx):
    rot_dom = C2 > C1
    w0 = G[..., 2, 1] - G[..., 1, 2]
    w1 = G[..., 0, 2] - G[..., 2, 0]
    w2 = G[..., 1, 0] - G[..., 0, 1]
    wn = jnp.sqrt(w0*w0 + w1*w1 + w2*w2)
    gs0 = jdd(C1, 1, dx); gs1 = jdd(C1, 2, dx); gs2 = jdd(C1, 3, dx)
    gn = jnp.sqrt(gs0*gs0 + gs1*gs1 + gs2*gs2)
    use_v = rot_dom & (wn > 1e-14)
    use_g = (~rot_dom) & (gn > 1e-14)
    ax_v = jnp.stack([w0, w1, w2], axis=-1) \
        / jnp.maximum(wn, 1e-30)[..., None]
    ax_g = jnp.stack([gs0, gs1, gs2], axis=-1) \
        / jnp.maximum(gn, 1e-30)[..., None]
    return jnp.where(use_v[..., None], ax_v,
                     jnp.where(use_g[..., None], ax_g,
                               jnp.zeros_like(ax_v)))
def jrestrict(F):
    classes = []
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                classes.append(F[:, a::2, b::2, d_::2])
    return jnp.stack(classes, axis=1)
def jmerge(G8, n):
    out = jnp.zeros((G8.shape[0], n, n, n), dtype=G8.dtype)
    idx = 0
    for a in (0, 1):
        for b in (0, 1):
            for d_ in (0, 1):
                out = out.at[:, a::2, b::2, d_::2].set(G8[:, idx])
                idx += 1
    return out
def jrestrict_fw(F):
    ra, rb, rc = F.shape[-3], F.shape[-2], F.shape[-1]
    return F.reshape(F.shape[:-3] + (ra//2, 2, rb//2, 2, rc//2, 2)
                     ).mean(axis=(-5, -3, -1))
def j_interp1(F, axis):
    n = F.shape[axis]
    odd = 0.5*(F + jnp.roll(F, -1, axis=axis))
    out = jnp.stack([F, odd], axis=axis + 1)
    shp = list(F.shape); shp[axis] = 2*n
    return out.reshape(shp)
def jprolong(C):
    F = j_interp1(C, C.ndim - 3)
    F = j_interp1(F, F.ndim - 2)
    F = j_interp1(F, F.ndim - 1)
    return F
def jdiv_bundle(V, dx):
    return jdd(V[..., 0], 1, dx) + jdd(V[..., 1], 2, dx) \
        + jdd(V[..., 2], 3, dx)
def jgrad_bundle(phi, dx):
    return jnp.stack([jdd(phi, 1, dx), jdd(phi, 2, dx),
                      jdd(phi, 3, dx)], axis=-1)
def jlap_apply(F, dx):
    inv = 1.0/(dx*dx)
    s = -6.0*F
    nd = F.ndim
    for a in (nd - 3, nd - 2, nd - 1):
        s = s + jnp.roll(F, -1, axis=a) + jnp.roll(F, 1, axis=a)
    return s*inv
def jsmooth_gs(phi, f, dx, iters):
    cc = dx*dx/6.0
    m = phi.shape[-1]
    idx = jnp.indices((m, m, m))
    parity = (idx[0] + idx[1] + idx[2]) % 2
    red = (parity == 0); black = (parity == 1)
    def body(i, phi_):
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(red, r, 0.0)
        r = f - jlap_apply(phi_, dx)
        phi_ = phi_ - cc*jnp.where(black, r, 0.0)
        return phi_
    return lax.fori_loop(0, iters, body, phi)
def jv_cycle(phi, f, dx):
    if f.shape[-1] <= 4:
        f = f - jnp.mean(f, axis=(-3, -2, -1), keepdims=True)
        return jsmooth_gs(phi, f, dx, 40)
    phi = jsmooth_gs(phi, f, dx, 2)
    r = f - jlap_apply(phi, dx)
    rc = jrestrict_fw(r)
    ec = jv_cycle(jnp.zeros_like(rc), rc, 2.0*dx)
    phi = phi + jprolong(ec)
    return jsmooth_gs(phi, f, dx, 2)
def _project_warm(Vch, psic0, dx, cycles):
    f = -jdiv_bundle(Vch, dx)
    fc = jrestrict(f)
    H = 2.0*dx
    fc = fc - jnp.mean(fc, axis=(-3, -2, -1), keepdims=True)
    psic = psic0 - jnp.mean(psic0, axis=(-3, -2, -1), keepdims=True)
    def cycle_body(i, psi):
        return jv_cycle(psi, fc, H)
    psic = lax.fori_loop(0, cycles, cycle_body, psic)
    psic = psic - jnp.mean(psic, axis=(-3, -2, -1), keepdims=True)
    resid = jnp.max(jnp.abs(fc - jlap_apply(psic, H))) \
        / (jnp.max(jnp.abs(fc)) + 1e-30)
    phi_full = jmerge(psic, Vch.shape[1])
    return Vch + jgrad_bundle(phi_full, dx), psic, resid
def _arm_scaled(u_s, p_s, G, C1, C2, tension, dx, thr):
    thr_ = thr[:, None, None, None]
    routed = tension > thr_
    m = u_s + p_s
    d = 0.5*(u_s - p_s)
    axis = jaxis_dominant(C1, C2, G, dx)
    dpar = jnp.sum(axis*d, axis=-1)[..., None]*axis
    d_tr = d - dpar
    gam = jnp.where(routed, GAMMA_CONTRACT, 1.0)
    excess = jnp.maximum(tension - thr_, 0.0)
    g = GAIN*excess/jnp.maximum(thr_, 1e-30)
    t_par = jnp.where(routed, g/(1.0 + g), 0.0)
    c_ = (1.0 - t_par*t_par)/(1.0 + t_par*t_par)
    s_ = (2.0*t_par)/(1.0 + t_par*t_par)
    rot = c_[..., None]*d_tr + s_[..., None]*jnp.cross(axis, d_tr)
    d_new = dpar + gam[..., None]*rot
    return 0.5*m + d_new, 0.5*m - d_new

def make_factory(n, dt, cycles, mode, nu_val=NU_TEST):
    ics, dx = build_ics_np(n)
    C = len(ICS)
    U0 = np.stack([ics[nm] for nm in ICS])
    Us0 = jnp.asarray(np.concatenate([U0, np.zeros_like(U0)], axis=0))
    psic0 = jnp.zeros((2*C, 8, n//2, n//2, n//2))
    Us0, psic0, _ = _project_warm(Us0, psic0, dx, INIT_CYCLES)
    U0j, P0j = Us0[:C], Us0[C:]
    _, _, _, _, t0_ = jnth_jacobian(U0j, dx)
    M0 = np.asarray(jnp.max(t0_.reshape(C, -1), axis=1))
    THR = jnp.asarray(THRESH_FRAC*M0)
    nu = jnp.asarray(np.full(C, nu_val, dtype=np.float64))
    nu_ = nu[:, None, None, None, None]
    dx_j = dx
    def step(u, p, psic):
        Cb = u.shape[0]
        G_u, C1_u, C2_u, R_u, tension_u = jnth_jacobian(u, dx_j)
        m = u + p
        au1 = jadvect(u, m, dx_j); ap1 = jadvect(p, m, dx_j)
        Lu = jlap(u, dx_j); Lp = jlap(p, dx_j)
        u_star = u + dt*(-au1 + nu_*Lu)
        p_star = p + dt*(-ap1 + nu_*Lp)
        m_star = u_star + p_star
        au2 = jadvect(u_star, m_star, dx_j)
        ap2 = jadvect(p_star, m_star, dx_j)
        u_s = u + 0.5*dt*(-(au1 + au2) + nu_*(Lu + jlap(u_star, dx_j)))
        p_s = p + 0.5*dt*(-(ap1 + ap2) + nu_*(Lp + jlap(p_star, dx_j)))
        if mode == 'classical':
            u_t, p_t = u_s, p_s
        else:
            u_t, p_t = _arm_scaled(u_s, p_s, G_u, C1_u, C2_u,
                                    tension_u, dx_j, THR)
        Usp = jnp.concatenate([u_t, p_t], axis=0)
        Unew, psic_n, _ = _project_warm(Usp, psic, dx_j, cycles)
        return (Unew[:Cb], Unew[Cb:], psic_n)
    def body(carry, _):
        u, p, psic = carry
        u, p, psic = step(u, p, psic)
        return (u, p, psic), None
    return dict(body=body, carry0=(U0j, P0j, psic0), dx=dx,
                M0=np.asarray(M0), THR=np.asarray(THR), C=C, n=n, dt=dt)

# ---- host-side instruments ----
def block_avg(F, k):
    if k == 0:
        return F
    C, n = F.shape[0], F.shape[1]
    b = 2**k
    return F.reshape(C, n//b, b, n//b, b, n//b, b, 3).mean(axis=(2, 4, 6))

def octave_energies_k(F, kmax):
    lv = [F] + [block_avg(F, k) for k in range(1, kmax + 1)]
    L = [np.sum(l**2, axis=(1, 2, 3, 4)) for l in lv]
    S = np.stack([8.0**(k - 1)*L[k - 1] - 8.0**k*L[k]
                  for k in range(1, kmax + 1)], axis=0)
    Sres = (8.0**kmax)*L[kmax]
    ident = np.sum(S, axis=0) + Sres - L[0]
    return S, Sres, ident

def maxu_per_ic(snap):
    C = snap.shape[0]
    out = []
    for ci in range(C):
        out.append(float(np.max(np.sqrt(np.sum(snap[ci]**2, axis=-1)))))
    return out

def temporal_haar_1d(x):
    """Hand-derived temporal Haar. PROVEN on n=8 linear trend:
    E = [E_finest, ..., E_coarsest] built by the formula
    E_k = 2^(k-1)*L[k-1] - 2^k*L[k], then REVERSED to return
    [coarsest, ..., finest].
    For the n=8 linear trend (demeaned):
    L = [42, 20, 8, 0], E = [2, 8, 32], reversed = [32, 8, 2],
    shares = [0.762, 0.190, 0.048]. Coarsest-dominant. CORRECT.
    Returns (shares_coarsest_to_finest, identity_residual)."""
    n = len(x)
    assert n >= 8 and (n & (n - 1)) == 0, \
        f'temporal_haar_1d: length {n} not power of 2 >= 8'
    y = x - np.mean(x)
    # Build averaging pyramid
    levels = [y]
    while len(levels[-1]) > 1:
        z = levels[-1]
        h = z[:2*(len(z)//2)].reshape(-1, 2)
        levels.append(0.5*(h[:, 0] + h[:, 1]))
    K = len(levels) - 1
    Ls = [float(np.sum(l**2)) for l in levels]
    # Level energies: E_k = 2^(k-1)*L[k-1] - 2^k*L[k] for k=1..K
    # E[0] = finest (between y and a_1), E[K-1] = coarsest (between
    # a_{K-1} and a_K)
    Ev = [2.0**k * Ls[k] - 2.0**(k+1) * Ls[k+1] for k in range(K)]
    # Coarse residual: 2^K * ||a_K||^2 = 0 (demeaned)
    Sres = 2.0**K * Ls[K]
    ident = sum(Ev) + Sres - Ls[0]
    total = Ls[0]
    if total < 1e-30:
        return np.zeros(K), 0.0
    # Reverse to coarsest-to-finest
    shares = np.array([e/total for e in Ev[::-1]])
    return shares, ident

