# =============================================================================
# THE LONG-T RUN (in-loop share computation)
# =============================================================================
def run_longt(tag, mode, n):
    dt_n = DT_N[n]
    steps = int(round(T_H/dt_n))
    save_every = SAVE_N[n]
    n_blocks = steps // save_every
    kmax_r = KMAX[n]
    fac = make_factory(n, dt_n, WARM_CYCLES, mode)
    body = fac['body']; carry = fac['carry0']
    print(f'  [{tag}] n={n}^3 mode={mode} steps={steps} dt={dt_n} '
          f'blocks={n_blocks}')

    times_l = [0.0]
    shares_l = []
    coarse_l = []
    maxu_l = []

    snap0 = np.array(fac['carry0'][0])
    S0, Sres0, ident0 = octave_energies_k(snap0, kmax_r)
    tot0 = np.sum(S0, axis=0) + Sres0
    sh0 = S0 / np.maximum(tot0[None, :], 1e-30)
    co0 = Sres0 / np.maximum(tot0, 1e-30)
    shares_l.append(sh0)
    coarse_l.append(co0)
    maxu_l.append(maxu_per_ic(snap0))
    id_check = float(np.max(np.abs(ident0))) / max(float(np.max(tot0)), 1e-30)
    assert id_check < 1e-10, 'initial octave identity failed'
    del snap0, S0, Sres0

    t0 = time.time()
    failed = False
    fail_t = -1.0
    for b_ in range(n_blocks):
        carry, _ = lax.scan(body, carry, xs=None, length=save_every)
        snap_u = np.array(carry[0])
        snap_p = np.array(carry[1])
        if not (np.all(np.isfinite(snap_u))
                and np.all(np.isfinite(snap_p))):
            failed = True
            fail_t = (b_ + 1)*save_every*dt_n
            print(f'    block {b_+1} (t={fail_t:.2f}): NON-FINITE -> '
                  f'HALTED')
            break
        t_now = (b_ + 1)*save_every*dt_n
        times_l.append(t_now)
        S_now, Sres_now, ident_now = octave_energies_k(snap_u, kmax_r)
        tot_now = np.sum(S_now, axis=0) + Sres_now
        sh_now = S_now / np.maximum(tot_now[None, :], 1e-30)
        co_now = Sres_now / np.maximum(tot_now, 1e-30)
        shares_l.append(sh_now)
        coarse_l.append(co_now)
        maxu_l.append(maxu_per_ic(snap_u))
        idr = float(np.max(np.abs(ident_now))) \
            / max(float(np.max(tot_now)), 1e-30)
        assert idr < 1e-10, f'octave identity failed at t={t_now}'
        del snap_u, snap_p, S_now, Sres_now
        if (b_ + 1) % 5 == 0:
            print(f'    t={t_now:.2f}  ({time.time()-t0:.0f}s)  '
                  f'coarse: '
                  + ' '.join(f'{nm}={co_now[ci]:.3f}'
                              for ci, nm in enumerate(ICS)))

    if not failed:
        print(f'    done: {len(times_l)} checkpoints, '
              f'{time.time()-t0:.0f}s')
    times = np.array(times_l)
    shares = np.stack(shares_l)
    coarse = np.stack(coarse_l)
    maxu = np.array(maxu_l)
    np.savez(os.path.join(SAVE_DIR, f'v35c_{tag}.npz'),
             times=times, shares=shares, coarse=coarse, maxu=maxu,
             finite=np.array(not failed), fail_t=np.array(fail_t),
             kmax=np.array(kmax_r), n=np.array(n))
    return dict(tag=tag, mode=mode, n=n, kmax=kmax_r, times=times,
                shares=shares, coarse=coarse, maxu=maxu,
                finite=not failed, fail_t=fail_t)

