print('\n' + '='*79)
print('[F1] SHARE TRAJECTORIES (coarse share, both ICs, all runs)')
print('='*79)
for tag, RUN in (('R128A', R128A), ('R64A', R64A), ('R64C', R64C),
                 ('R32A', R32A), ('R32C', R32C)):
    if not RUN['finite']:
        print(f'  [{tag}] FAILED at t={RUN["fail_t"]:.2f} — skipped')
        continue
    for ci, nm in enumerate(ICS):
        traj = RUN['coarse'][:, ci]
        n_show = min(12, len(traj))
        step_show = max(1, len(traj)//n_show)
        vals = [f'{traj[i]:.3f}' for i in range(0, len(traj), step_show)]
        print(f'  [{tag:5s} {nm:6s}] coarse: '
              + ' -> '.join(vals))

print('\n' + '='*79)
print(f'[F2] STATIONARITY (CV over last {T_STAT} checkpoints)')
print('     CV < 0.05 = quasi-stationary; CV < 0.01 = stationary')
print('='*79)
stat_results = {}
for tag, RUN in (('R128A', R128A), ('R64A', R64A), ('R64C', R64C),
                 ('R32A', R32A), ('R32C', R32C)):
    if not RUN['finite']:
        continue
    for ci, nm in enumerate(ICS):
        for oi in range(RUN['kmax']):
            traj = RUN['shares'][:, oi, ci]
            last = traj[-T_STAT:]
            mean_v = float(np.mean(last))
            std_v = float(np.std(last))
            cv = std_v / max(abs(mean_v), 1e-30)
            stat_results[(tag, nm, oi)] = cv
        traj_c = RUN['coarse'][:, ci]
        last_c = traj_c[-T_STAT:]
        mean_c = float(np.mean(last_c))
        std_c = float(np.std(last_c))
        cv_c = std_c / max(abs(mean_c), 1e-30)
        stat_results[(tag, nm, 'coarse')] = cv_c
        label = 'STATIONARY' if cv_c < 0.01 else \
            'QUASI-STAT' if cv_c < 0.05 else 'EVOLVING'
        print(f'  [{tag:5s} {nm:6s}] coarse CV = {cv_c:.4f} ({label})'
              f'   mean = {mean_c:.3f}')
