# Recompute the temporal Haar on the persisted trajectories
def temporal_haar_1d(x):
    n = len(x)
    y = x - np.mean(x)
    levels = [y]
    while len(levels[-1]) > 1:
        z = levels[-1]
        h = z[:2*(len(z)//2)].reshape(-1, 2)
        levels.append(0.5*(h[:, 0] + h[:, 1]))
    K = len(levels) - 1
    Ls = [float(np.sum(l**2)) for l in levels]
    Ev = [2.0**k * Ls[k] - 2.0**(k+1) * Ls[k+1] for k in range(K)]
    total = Ls[0]
    if total < 1e-30:
        return np.zeros(K), 0.0
    shares = np.array([e/total for e in Ev[::-1]])
    return shares, sum(Ev) - total

for tag in ('R64A', 'R64C'):
    D = load(tag)
    shares_spatial = D['shares']
    coarse = D['coarse']
    kmax = int(D['kmax']) if hasattr(D['kmax'], 'item') else int(D['kmax'])
    times = D['times']
    n_haar = 16
    if len(times) < n_haar:
        continue
    for ci, nm in enumerate(ICS):
        series_c = coarse[-n_haar:, ci]
        S_hc, _ = temporal_haar_1d(series_c)
        # Power-law fit: log(S) vs level index
        levels_idx = np.arange(len(S_hc))
        valid = S_hc > 1e-10
        if valid.sum() >= 3:
            log_S = np.log(S_hc[valid])
            lv = levels_idx[valid].astype(float)
            slope, intercept = np.polyfit(lv, log_S, 1)
            print(f'  [{tag} {nm}] temporal Haar levels: '
                  + ' '.join(f'{s:.3f}' for s in S_hc)
                  + f'  -> decay slope = {slope:+.2f} '
                  f'({"power-law decay (smooth)" if slope < -0.5 else "flat/bumpy (oscillatory)"})')
        else:
            print(f'  [{tag} {nm}] insufficient energy for decay fit')

