def run_study(tag, mode, w_gold):
    fac = make_factory(N_RUN, DT_RUN, WARM_CYCLES, mode, w_gold)
    body = fac['body']; carry = fac['carry0']
    steps = int(round(T_H/DT_RUN))
    n_blocks = steps // SAVE_EVERY
    print(f'  [{tag}] mode={mode} W_GOLD={w_gold:.3f} '
          f'steps={steps}')
    times_l = [0.0]
    shares_l = []
    coarse_l = []
    maxu_l = []
    snap0 = np.array(fac['carry0'][0])
    S0, Sres0, ident0 = octave_energies_k(snap0, KMAX_RUN)
    tot0 = np.sum(S0, axis=0) + Sres0
    shares_l.append(S0 / np.maximum(tot0[None, :], 1e-30))
    coarse_l.append(Sres0 / np.maximum(tot0, 1e-30))
    maxu_l.append(maxu_per_ic(snap0))
    del snap0, S0, Sres0
    t0 = time.time()
    failed = False
    fail_t = -1.0
    for b_ in range(n_blocks):
        carry, _ = lax.scan(body, carry, xs=None, length=SAVE_EVERY)
        snap_u = np.array(carry[0])
        snap_p = np.array(carry[1])
        if not (np.all(np.isfinite(snap_u))
                and np.all(np.isfinite(snap_p))):
            failed = True
            fail_t = (b_ + 1)*SAVE_EVERY*DT_RUN
            print(f'    block {b_+1} (t={fail_t:.2f}): NON-FINITE -> HALTED')
            break
        t_now = (b_ + 1)*SAVE_EVERY*DT_RUN
        times_l.append(t_now)
        S_now, Sres_now, ident_now = octave_energies_k(snap_u, KMAX_RUN)
        tot_now = np.sum(S_now, axis=0) + Sres_now
        shares_l.append(S_now / np.maximum(tot_now[None, :], 1e-30))
        coarse_l.append(Sres_now / np.maximum(tot_now, 1e-30))
        maxu_l.append(maxu_per_ic(snap_u))
        del snap_u, snap_p, S_now, Sres_now
    if not failed:
        print(f'    done: {len(times_l)} ckpts, {time.time()-t0:.0f}s')
    times = np.array(times_l)
    shares = np.stack(shares_l)
    coarse = np.stack(coarse_l)
    maxu = np.array(maxu_l)
    np.savez(os.path.join(SAVE_DIR, f'v36_{tag}.npz'),
             times=times, shares=shares, coarse=coarse, maxu=maxu,
             finite=np.array(not failed), fail_t=np.array(fail_t),
             w_gold=np.array(w_gold), mode=np.array(mode))
    return dict(tag=tag, mode=mode, w_gold=w_gold, times=times,
                shares=shares, coarse=coarse, maxu=maxu,
                finite=not failed, fail_t=fail_t)

